async function createCharacterImageVariants({ name, summary, storyContext, styleAnalysis, userCharStyle, useModelScope = false, useBestModel = false, imageModel = null, maxRetries = 3, retryDelayMs = 2000 }) {
    const analysis = styleAnalysis || analyzeStoryStyle(`${name} ${summary} ${storyContext}`);
    const variants = [];

    // 🎯 根据用户风格选择不同的提示词模板
    const isRealistic = userCharStyle === 'realistic';
    const isAnime = userCharStyle === 'anime';
    const isChinese = userCharStyle === 'chinese';

    // 🎨 强调风格的前缀（确保风格一致性）
    const stylePrefix = isRealistic
        ? 'PHOTOREALISTIC, real human, live-action movie quality, NOT anime, NOT cartoon, NOT illustration, realistic skin texture, natural lighting'
        : isAnime
            ? 'ANIME STYLE, Japanese animation, 2D illustration, cel-shaded, vibrant anime colors, large expressive eyes'
            : isChinese
                ? 'CHINESE TRADITIONAL STYLE (国风), ink painting influence, hanfu clothing, oriental aesthetic'
                : analysis.artStyle;

    const posterPrompt = `${stylePrefix}

${analysis.title}: ${name}

CHARACTER: ${name}
DESCRIPTION: ${summary}
STORY CONTEXT: ${storyContext.substring(0, 300)}

LAYOUT DESIGN:
- LEFT SECTION "${analysis.labels.clothing}": Individual clothing/armor items with color swatches and material labels
- CENTER: Full body character in signature pose, detailed outfit, showing personality
- RIGHT SECTION "${analysis.labels.technical}": Equipment details, weapons, accessories, props blueprints
- BOTTOM LEFT "${analysis.labels.expression}": 3 facial expressions showing character personality
- Detail callouts for unique features mentioned in the story

ART STYLE: ${analysis.artStyle}
${isRealistic ? '- CRITICAL: Must be photorealistic, real human appearance, NOT anime or cartoon\n- Realistic skin pores, natural hair texture, real fabric materials\n- Professional photography lighting, cinematic quality' : ''}
${isAnime ? '- CRITICAL: Must be Japanese anime style, 2D illustration\n- Large expressive anime eyes, stylized hair, cel-shading\n- Vibrant anime color palette' : ''}
${isChinese ? '- CRITICAL: Must be Chinese traditional art style (国风)\n- Elegant ink painting influence, traditional patterns\n- Hanfu/traditional Chinese clothing aesthetic' : ''}
- Clean professional linework with vibrant colors
- Light neutral background (white/light gray gradient)
- ${analysis.labelNote}
- Each section clearly separated with headers
- High detail, production-ready quality

OUTPUT: 4K character design reference sheet, ${isRealistic ? 'PHOTOREALISTIC style' : analysis.styleKeywords || 'professional quality'}.`;

    const turnaroundPrompt = `${stylePrefix}

角色三视图设定海报 / Character Turnaround Poster

角色: ${name}
简介: ${summary}
剧本背景: ${storyContext.substring(0, 500)}

版式要求:
- 顶部标题区: 中英双语角色名称与设计主题
- 中央上方: 三视图模块 (Front / Side / Back) 16:9 宽幅，人物比例准确
- 中央下方: 半身/表情参考（至少3种情绪）+ 手部或动作特写
- 左下角: 比例尺、身高对比、头身比刻度
- 右下角: Outfit breakdown / 材质/关键配色
- 背景: 低饱和渐变或柔和网格，突出主体
- 标注: 关键服装/饰品/道具使用中英双语标注

视觉风格:
- ${analysis.artStyle}
${isRealistic ? '- 【重要】必须是真人写实风格，不是动漫/卡通\n- 真实的皮肤质感、自然的发丝、真实的服装材质\n- 电影级摄影光效，专业人像质感' : ''}
${isAnime ? '- 【重要】必须是日系动漫风格\n- 动漫大眼睛、动漫发型、赛璐璐上色\n- 明亮的动漫色彩' : ''}
${isChinese ? '- 【重要】必须是中国古典国风风格\n- 水墨画韵味、传统纹样\n- 汉服/古装美学' : ''}
- 干净、现代、具有工业设计感
- 可作为动画/游戏建模参考

注意事项:
- 人物必须全身且保持同一姿态（T Pose 或自然站姿）
- 三视图高度对齐，确保比例可用于建模
- 表情与动作参考紧扣人物性格
- 风格必须与用户设置一致: ${isRealistic ? '真人写实' : isAnime ? '日系动漫' : isChinese ? '国风古典' : userCharStyle || '默认'}`;

    function _isNodeUnavailableOrTransient(err) {
        const msg = String(err?.message || err || '');
        return (
            msg.includes('所有API节点均不可用') ||
            msg.includes('节点均不可用') ||
            msg.includes('Node') && msg.includes('unavailable') ||
            msg.includes('500') ||
            msg.includes('502') ||
            msg.includes('503') ||
            msg.includes('504') ||
            msg.toLowerCase().includes('timeout') ||
            msg.includes('429')
        );
    }

    function _trimPromptForFallback(p, maxLen = 1600) {
        const s = String(p || '');
        return s.length > maxLen ? s.slice(0, maxLen) : s;
    }

    async function generateVariant(prompt, type, label) {
        try {
            // 🎬 模型选择优先级：
            // 1) 任务指定 imageModel（可选：seedream / banana2 / banana2-4k / modelscope）
            // 2) 首次体验/免费：魔塔
            // 3) 付费默认：Banana2 4K
            let url;
            const m = (imageModel || '').toString().toLowerCase();
            const wantModelScope = m === 'modelscope' || m === 'motaverse' || m === 'zaomeng' || m.includes('modelscope') || m.includes('造梦');
            const wantSeedream = m === 'seedream' || m.includes('seedream') || m.includes('doubao');
            const wantBanana4k = m === 'banana2-4k' || m === 'banana2_4k' || m.includes('nano-banana-2-4k') || m.includes('4k');
            const wantBanana = m === 'banana2' || m.includes('nano-banana-2');

            // 🛟 Banana2 临时不可用窗口：直接跳过 Banana2，避免每张图都先 500 再降级拖慢整体
            const banana2Down = (() => {
                try {
                    const until = (typeof window !== 'undefined') ? window.__banana2DownUntil : 0;
                    return Number.isFinite(until) && until > Date.now();
                } catch (_) { return false; }
            })();

            if (wantModelScope) {
                url = await callModelScopeImageAPI(prompt, { aspectRatio: '16:9' });
            } else if (wantSeedream) {
                url = await callBanana2ImageAPI(prompt, { aspectRatio: '16:9', model: 'doubao-seedream-4-5-251128', maxRetries, retryDelayMs });
            } else if (wantBanana4k) {
                if (banana2Down) {
                    url = await callModelScopeImageAPI(_trimPromptForFallback(prompt, 1500), { aspectRatio: '16:9' });
                } else {
                    url = await callBanana2ImageAPI(prompt, { aspectRatio: '16:9', model: 'nano-banana-2-4k', maxRetries, retryDelayMs });
                }
            } else if (wantBanana) {
                if (banana2Down) {
                    url = await callModelScopeImageAPI(_trimPromptForFallback(prompt, 1500), { aspectRatio: '16:9' });
                } else {
                    url = await callBanana2ImageAPI(prompt, { aspectRatio: '16:9', model: 'nano-banana-2', maxRetries, retryDelayMs });
                }
            } else if (useModelScope) {
                console.log('🎁 首次体验：使用魔塔生成角色图');
                url = await callModelScopeImageAPI(prompt, { aspectRatio: '16:9' });
            } else if (useBestModel) {
                console.log('🎞️ 付费用户：使用Banana2 4K生成角色图');
                if (banana2Down) {
                    url = await callModelScopeImageAPI(_trimPromptForFallback(prompt, 1500), { aspectRatio: '16:9' });
                } else {
                    url = await callBanana2ImageAPI(prompt, { aspectRatio: '16:9', model: 'nano-banana-2-4k', maxRetries, retryDelayMs });
                }
            } else {
                // ✅ 默认策略：
                // - 非付费：优先用魔塔（更稳，避免 /api/banana2 上游抖动导致“角色图全挂”）
                // - 付费：默认仍用 Banana2 4K
                const paid = (typeof isPaidUser === 'function') ? !!isPaidUser() : false;
                if (!paid) {
                    url = await callModelScopeImageAPI(prompt, { aspectRatio: '16:9' });
                } else {
                    if (banana2Down) {
                        url = await callModelScopeImageAPI(_trimPromptForFallback(prompt, 1500), { aspectRatio: '16:9' });
                    } else {
                        url = await callBanana2ImageAPI(prompt, { aspectRatio: '16:9', model: 'nano-banana-2-4k', maxRetries, retryDelayMs });
                    }
                }
            }
            if (url) {
                variants.push({ type, label, url });
            }
        } catch (error) {
            console.error(`❌ ${name} - ${label} 生成失败:`, error);
            // 🛟 1) 422：参数/内容不可处理 → 用更短更稳的提示词重试一次
            if (error?.message && String(error.message).includes('422')) {
                // 简化后备提示词，但保持风格一致
                const styleTag = isRealistic ? 'photorealistic, real human, live action' : isAnime ? 'anime style, 2D illustration' : isChinese ? 'Chinese traditional style' : '';
                const fallbackPrompt = `${styleTag}, ${name} character reference sheet, ${type}, clean white background, include front/side/back views with labels, ${summary.substring(0, 120)}.`;
                try {
                    const url = await callBanana2ImageAPI(fallbackPrompt, { aspectRatio: '16:9', model: 'nano-banana-2-4k', maxRetries: 1, retryDelayMs: 800 });
                    if (url) {
                        variants.push({ type, label, url });
                    }
                } catch (fallbackError) {
                    console.error(`❌ ${name} - ${label} Fallback失败:`, fallbackError);
                }
                return;
            }

            // 🛟 2) 上游节点不可用/5xx/超时/限流：自动降级到魔塔，避免“视频角色图经常全挂”
            if (_isNodeUnavailableOrTransient(error)) {
                try {
                    const p = _trimPromptForFallback(prompt, 1500);
                    const url = await callModelScopeImageAPI(p, { aspectRatio: '16:9' });
                    if (url) {
                        // ✅ 不向用户暴露“降级/兜底”，仅在控制台保留（可接入调试面板）
                        console.debug?.(`(silent) ${name} - ${label}: switched generator path`);
                        variants.push({ type, label, url });
                    }
                } catch (fallbackError2) {
                    console.error(`❌ ${name} - ${label} 降级到魔塔也失败:`, fallbackError2);
                }
            }
        }
    }

    // 🚀 并行生成：同一角色的海报+三视图同时出，节省一半等待时间
    await Promise.all([
        generateVariant(posterPrompt, 'poster', '视觉设定图'),
        generateVariant(turnaroundPrompt, 'turnaround', '三视图设定')
    ]);

    return variants;
}

/**
 * AI视频批量创作工具 - 批量页脚本
 * @version 2.2.0
 * @date 2025-11-22
 * @description 角色生成优化 + 自动托管模式 + 全面Bug修复
 */

const APP_VERSION = 'V8.9.5'; // 欢迎页逻辑修复 + 写作页修复

// 🔒 简单转义，防止 XSS 注入
function escapeHtml(str = '') {
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

// 🔧 修复：添加缺失的getSetting函数
function getSetting(key) {
    try {
        const settings = JSON.parse(localStorage.getItem('nv_settings') || '{}');
        return settings[key];
    } catch (e) {
        console.warn('getSetting失败:', e);
        return undefined;
    }
}
window.getSetting = getSetting;

function loadSettings() {
    try {
        return JSON.parse(localStorage.getItem('nv_settings') || '{}');
    } catch (e) {
        return {};
    }
}

function saveSettings() {
    try {
        const s = loadSettings();
        const charSheetEl = document.getElementById('settingCharacterSheets');
        if (charSheetEl) s.characterSheetEnabled = charSheetEl.checked;
        const autoHostEl = document.getElementById('settingAutoHosting');
        if (autoHostEl) s.autoHostingEnabled = autoHostEl.checked;
        localStorage.setItem('nv_settings', JSON.stringify(s));
        console.log('✅ 全局设置已保存:', s);
    } catch (e) {
        console.warn('saveSettings失败:', e);
    }
    // 关闭弹窗
    const modal = document.getElementById('settingsModal');
    if (modal) modal.style.display = 'none';
}
window.saveSettings = saveSettings;

function openSettingsModal() {
    const s = loadSettings();
    const charSheetEl = document.getElementById('settingCharacterSheets');
    if (charSheetEl) charSheetEl.checked = s.characterSheetEnabled !== false; // 默认开启
    const autoHostEl = document.getElementById('settingAutoHosting');
    if (autoHostEl) autoHostEl.checked = !!s.autoHostingEnabled;
    // 显示配额信息
    const quotaEl = document.getElementById('quotaDetails');
    if (quotaEl && typeof updateQuotaDisplay === 'function') {
        try { updateQuotaDisplay(); } catch (e) { }
    }
    const modal = document.getElementById('settingsModal');
    if (modal) modal.style.display = 'flex';
}
window.openSettingsModal = openSettingsModal;

function closeSettingsModal() {
    saveSettings();
}
window.closeSettingsModal = closeSettingsModal;

/**
 * 轻量级 Toast 提示（不阻断用户操作）
 * @param {string} message - 提示消息
 * @param {string} type - 类型：success/warning/error/info
 * @param {number} duration - 显示时长（毫秒）
 */
function showToast(message, type = 'info', duration = 3000) {
    // 移除已有的 toast
    const existing = document.getElementById('globalToast');
    if (existing) existing.remove();

    const colors = {
        success: { bg: 'rgba(16, 185, 129, 0.95)', border: '#10b981' },
        warning: { bg: 'rgba(245, 158, 11, 0.95)', border: '#f59e0b' },
        error: { bg: 'rgba(239, 68, 68, 0.95)', border: '#ef4444' },
        info: { bg: 'rgba(59, 130, 246, 0.95)', border: '#3b82f6' }
    };

    const color = colors[type] || colors.info;

    const toast = document.createElement('div');
    toast.id = 'globalToast';
    toast.style.cssText = `
        position: fixed;
        top: 20px;
        left: 50%;
        transform: translateX(-50%);
        background: ${color.bg};
        border: 1px solid ${color.border};
        color: #fff;
        padding: 12px 24px;
        border-radius: 8px;
        font-size: 14px;
        z-index: 99999;
        box-shadow: 0 4px 20px rgba(0,0,0,0.3);
        animation: toastSlideIn 0.3s ease;
        max-width: 90%;
        text-align: center;
    `;
    const safeMsg = escapeHtml(message);
    toast.textContent = '';
    const wrapper = document.createElement('div');
    wrapper.style.display = 'flex';
    wrapper.style.alignItems = 'center';
    wrapper.style.gap = '8px';
    const iconSpan = document.createElement('span');
    iconSpan.textContent = (type === 'success' ? '✅' : type === 'warning' ? '⚠️' : type === 'error' ? '❌' : 'ℹ️');
    const msgSpan = document.createElement('span');
    msgSpan.style.flex = '1';
    msgSpan.textContent = safeMsg;
    wrapper.appendChild(iconSpan);
    wrapper.appendChild(msgSpan);
    toast.appendChild(wrapper);

    // 添加动画样式
    if (!document.getElementById('toastStyles')) {
        const style = document.createElement('style');
        style.id = 'toastStyles';
        style.textContent = `
            @keyframes toastSlideIn {
                from { opacity: 0; transform: translateX(-50%) translateY(-20px); }
                to { opacity: 1; transform: translateX(-50%) translateY(0); }
            }
            @keyframes toastSlideOut {
                from { opacity: 1; transform: translateX(-50%) translateY(0); }
                to { opacity: 0; transform: translateX(-50%) translateY(-20px); }
            }
        `;
        document.head.appendChild(style);
    }

    document.body.appendChild(toast);

    // 自动消失
    setTimeout(() => {
        toast.style.animation = 'toastSlideOut 0.3s ease';
        setTimeout(() => toast.remove(), 300);
    }, duration);
}

// 🛡️ 浏览器插件阻断检测
let pluginBlockDetected = false;
let pluginBypassConfirmed = localStorage.getItem('plugin_bypass_confirmed') === 'true';
let pluginDetectionIssues = [];
const PROXY_ENDPOINT = '/api/proxy';

const SUPABASE_FALLBACK_SRCS = [
    'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.js',
    'https://unpkg.com/@supabase/supabase-js@2/dist/umd/supabase.js'
];
let supabaseFallbackIndex = 0;
let supabaseFallbackLoading = false;

const MODELSCOPE_IMAGE_MODEL = 'Tongyi-MAI/Z-Image-Turbo';
const MODELSCOPE_TEXT_MODEL = 'ZhipuAI/GLM-4.6';
const MODELSCOPE_DAILY_QUOTA = 2000;

function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

function getFilmBalance() {
    const v = parseFloat(localStorage.getItem('film_balance') || '0');
    return Number.isFinite(v) ? v : 0;
}

// 🔄 云端余额同步状态
let __cloudBalanceSyncPending = false;
let __lastCloudBalanceSyncAt = 0;
const __CLOUD_BALANCE_SYNC_INTERVAL = 30000; // 30秒内不重复同步

/**
 * 🔄 从云端刷新胶片余额，确保本地与服务器一致
 * @param {boolean} force - 是否强制刷新（忽略防抖）
 * @returns {Promise<number|null>} 新余额或null
 */
async function refreshFilmBalanceFromCloud(force = false) {
    try {
        // 防抖：30秒内不重复同步（除非强制）
        const now = Date.now();
        if (!force && (now - __lastCloudBalanceSyncAt) < __CLOUD_BALANCE_SYNC_INTERVAL) {
            return null;
        }
        if (__cloudBalanceSyncPending) return null;

        __cloudBalanceSyncPending = true;

        if (typeof NVAuth === 'undefined') {
            __cloudBalanceSyncPending = false;
            return null;
        }
        const user = await NVAuth.getCurrentUser();
        if (!user?.id) {
            __cloudBalanceSyncPending = false;
            return null;
        }

        const res = await fetch('/api/supabase-proxy', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'getProfile', userId: user.id })
        });
        const data = await res.json().catch(() => ({}));

        __cloudBalanceSyncPending = false;
        __lastCloudBalanceSyncAt = now;

        if (res.ok && data.success && typeof data.quotaBalance === 'number') {
            const newBalance = data.quotaBalance;
            const oldBalance = getFilmBalance();

            // 更新本地缓存
            localStorage.setItem('film_balance', String(newBalance));
            localStorage.setItem('cloud_film_balance', String(newBalance));
            localStorage.setItem('cloud_balance_sync_at', String(now));

            // 同步会员类型
            if (data.membershipType) {
                localStorage.setItem('membership_type', data.membershipType);
            }

            if (oldBalance !== newBalance) {
                console.log(`🔄 [云端余额同步] ${oldBalance} → ${newBalance}`);
            }
            try { updateUsageDisplay(); } catch (e) { }
            return newBalance;
        }
        return null;
    } catch (e) {
        __cloudBalanceSyncPending = false;
        console.warn('⚠️ [云端余额同步失败]', e?.message);
        return null;
    }
}

// 🔄 页面可见性变化时自动同步余额
if (typeof document !== 'undefined') {
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') {
            // 页面变为可见时，强制同步余额
            refreshFilmBalanceFromCloud(true).catch(() => { });
        }
    });
}

/**
 * 🔄 登录后从云端同步用户数据（余额、会员状态等）
 * 该函数在登录成功后被调用，确保跨设备数据一致
 * 🔧 简化版本：只同步余额，避免重复调用
 */
async function syncDataFromCloud() {
    try {
        if (typeof NVAuth === 'undefined') return;
        const user = await NVAuth.getCurrentUser();
        if (!user?.id) return;

        console.log('🔄 [数据同步] 开始从云端同步数据...');

        // 🔧 只同步余额，refreshFilmBalanceFromCloud 已经包含了所有必要的数据
        // 不再调用 refreshGiftUnlockStatus，因为它会额外查询余额可能导致数据不一致
        const newBalance = await refreshFilmBalanceFromCloud(true);
        if (newBalance !== null) {
            console.log('✅ [数据同步] 余额同步完成:', newBalance);
        }

        // 更新UI显示
        try {
            if (typeof updateUsageDisplay === 'function') {
                updateUsageDisplay();
            }
        } catch (e) { }

        console.log('✅ [数据同步] 云端数据同步完成');
    } catch (e) {
        console.error('❌ [数据同步] 云端同步失败:', e?.message);
    }
}

// 暴露到全局，供 supabase-config.js 调用
if (typeof window !== 'undefined') {
    window.syncDataFromCloud = syncDataFromCloud;
}

function getLockedGiftClaimable() {
    const v = Number(localStorage.getItem('gift_unlock_can_unlock') || '0');
    // 🔧 修复：验证值的合理性，canUnlock 不应该超过单个等级的最大解锁限制（10000）
    // 如果值异常大（如10万），说明是旧数据，应该返回0并清除
    if (!Number.isFinite(v) || v > 10000) {
        try { localStorage.removeItem('gift_unlock_can_unlock'); } catch (e) { }
        return 0;
    }
    return Math.max(0, Math.round(v * 100) / 100);
}

async function refreshGiftUnlockCacheIfNeeded(force = false) {
    try {
        if (typeof NVAuth === 'undefined') return;
        const user = await NVAuth.getCurrentUser();
        if (!user) return;

        const ts = Number(localStorage.getItem('gift_unlock_ts') || '0');
        const now = Date.now();
        // 🔧 修复：缩短缓存时间到30秒，确保数据更及时
        const stale = !Number.isFinite(ts) || (now - ts) > 30 * 1000;
        if (!force && !stale) return;

        await refreshGiftUnlockStatus();
    } catch (e) {
    }
}

function updateUsageDisplay() {
    try {
        const bal = getFilmBalance();
        const available = Math.max(0, bal);
        const roundedAvailable = Math.round(available * 100) / 100;

        // 🔧 修复：从localStorage读取已验证的待解锁数据，并验证合理性
        let canUnlock = Number(localStorage.getItem('gift_unlock_can_unlock') || 0);
        // canUnlock 不应该超过单个等级的最大解锁限制（10000），如果超过说明是旧数据
        if (!Number.isFinite(canUnlock) || canUnlock > 10000) {
            canUnlock = 0;
            try { localStorage.removeItem('gift_unlock_can_unlock'); } catch (e) { }
        }
        const roundedCanUnlock = Math.round(Math.max(0, canUnlock) * 100) / 100;

        // 更新侧边栏底部的胶片显示：始终显示余额和待解锁
        const quotaEl = document.getElementById('quotaDisplay');
        if (quotaEl) {
            quotaEl.innerHTML = `<span>🎞️ ${roundedAvailable}</span> <span style="color:#888;font-size:11px;">| 🎁待解锁${roundedCanUnlock}</span>`;
            console.log('🎞️ 胶片显示已更新:', roundedAvailable, '待解锁:', roundedCanUnlock);
        }

        // 更新其他可能的胶片显示元素
        const el = document.getElementById('filmBalance');
        if (el) el.textContent = String(roundedAvailable);

        // 更新用户状态栏中的胶片显示（如果存在）
        const userQuotaBadge = document.querySelector('.user-quota-badge');
        if (userQuotaBadge) {
            userQuotaBadge.innerHTML = `<span>🎞️ ${roundedAvailable}</span> <span style="color:#888;font-size:11px;">| 🎁待解锁${roundedCanUnlock}</span>`;
        }
    } catch (e) {
        console.error('❌ updateUsageDisplay 失败:', e);
    }
}

function consumeQuota(count = 1) {
    try {
        const stats = (typeof getUsageStats === 'function') ? getUsageStats() : { limit: Infinity, count: 0 };
        if (stats.limit !== Infinity) {
            const next = Math.max(0, (parseInt(stats.count, 10) || 0) + (parseInt(count, 10) || 0));
            localStorage.setItem('usage_count', String(next));
        }
        try {
            if (typeof updateUsageDisplay === 'function') updateUsageDisplay();
        } catch (e) { }
        return true;
    } catch (e) {
        return false;
    }
}

function __rrEnsureMemberPurchaseMount() {
    const panel = document.getElementById('paymentMemberPanel');
    if (!panel) return null;
    let mount = document.getElementById('memberPurchaseMount');
    if (mount) return mount;
    mount = document.createElement('div');
    mount.id = 'memberPurchaseMount';
    mount.style.marginTop = '12px';
    // 插入到“打开会员中心/去输入激活码”按钮行之前
    const btnRow = Array.from(panel.querySelectorAll('div')).find((d) => {
        const s = (d && d.getAttribute && d.getAttribute('style')) ? d.getAttribute('style') : '';
        return String(s).includes('display:flex') && String(s).includes('margin-top: 12px');
    });
    if (btnRow && btnRow.parentNode) {
        btnRow.parentNode.insertBefore(mount, btnRow);
    } else {
        panel.appendChild(mount);
    }
    return mount;
}

function __rrBuildMembershipOrderNote(targetKey) {
    try {
        const profile = window.__nvLastProfile || null;
        const uid = profile?.id || localStorage.getItem('last_logged_user_id') || '';
        const email = profile?.email || '';
        const curType = String(profile?.membership_type || localStorage.getItem('membership_type') || 'free');
        const curLv = Number.isFinite(Number(window.currentMembershipLevel)) ? Number(window.currentMembershipLevel) : Number(localStorage.getItem('membership_level'));
        const keyStr = String(targetKey || '').trim();
        const lvMatch = keyStr.match(/^lv\s*(\d+)$/i);
        const lv = lvMatch ? Number(lvMatch[1]) : null;
        const unlockLimit = (lv !== null && Number.isFinite(lv))
            ? Number(GIFT_UNLOCK_LIMITS_BY_LEVEL?.[Math.max(0, Math.min(10, Math.floor(lv)))] || 0)
            : null;

        const plan = SUBSCRIPTION_PLANS?.[keyStr];
        const planName = (lv !== null && Number.isFinite(lv)) ? `LV${Math.max(0, Math.min(10, Math.floor(lv)))}` : (plan?.name || keyStr);
        const price = (lv !== null && Number.isFinite(lv))
            ? Number(MEMBERSHIP_LEVEL_PRICE_CNY?.[Math.max(0, Math.min(10, Math.floor(lv)))] || 0)
            : plan?.priceCNY;
        const now = new Date();
        const ts = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}-${String(now.getHours()).padStart(2, '0')}${String(now.getMinutes()).padStart(2, '0')}`;
        const priceLine = (price !== undefined && price !== null && price !== '') ? `\n金额: ¥${price}` : '';
        const unlockLine = (unlockLimit !== null) ? `\n解锁上限: ${unlockLimit}` : '';
        return `【会员开通】${planName}
用户ID: ${uid}
邮箱: ${email}
当前: ${curType} / LV${Number.isFinite(curLv) ? curLv : 0}
目标: ${planName}${unlockLine}${priceLine}
时间: ${ts}`;
    } catch (e) {
        return `【会员开通】${String(targetKey || '')}`;
    }
}

window.openMembershipPurchase = function (targetKey) {
    const key = String(targetKey || '').trim();
    const lvMatch = key.match(/^lv\s*(\d+)$/i);
    const isLv = !!lvMatch;
    const ok = isLv || !!SUBSCRIPTION_PLANS?.[key];
    if (!key || !ok) {
        alert('套餐不存在，请稍后重试');
        return;
    }
    const note = __rrBuildMembershipOrderNote(key);
    // 不依赖控制台复制：优先剪贴板，失败则 prompt
    try {
        navigator.clipboard.writeText(note).then(() => {
            alert('✅ 已复制付款备注（请粘贴给客服/闲鱼备注）');
        }).catch(() => {
            window.prompt('复制付款备注（长按全选复制）：', note);
        });
    } catch (e) {
        window.prompt('复制付款备注（长按全选复制）：', note);
    }

    // 引导到现有手动支付区（在充值Tab里）
    try {
        if (typeof window.setPaymentTab === 'function') window.setPaymentTab('recharge');
        const manual = document.getElementById('manualPayArea');
        if (manual && manual.style.display === 'none') {
            window.toggleManualPay?.();
        } else if (!manual) {
            window.toggleManualPay?.();
        }
    } catch (e) { }
};

function renderMembershipPurchaseOptions() {
    const mount = __rrEnsureMemberPurchaseMount();
    if (!mount) return;

    // ✅ LV1-LV10 会员包月价格表（如需调整只改这里）
    // 说明：会员等级为包月制，每月需续费，超过30天未消费自动降级
    // 若未来改成从服务端读取，可替换本表。
    //
    // 💰 包月定价逻辑（保证50%利润）：
    // - 成本约 ¥0.07/胶片（根据cost-analysis.md）
    // - 每月解锁胶片 = 解锁上限 × 10%（月度配额）
    // - 月费 = 月度配额 × ¥0.14（50%利润售价）
    // - 解锁上限: LV1=3000, LV2=6000, LV3=12000, LV4=22000, LV5=35000
    //            LV6=50000, LV7=68000, LV8=82000, LV9=93000, LV10=100000
    // - 月度配额: LV1=300, LV2=600, LV3=1200, LV4=2200, LV5=3500...
    window.MEMBERSHIP_LEVEL_PRICE_CNY = window.MEMBERSHIP_LEVEL_PRICE_CNY || {
        1: 42,     // 300 × 0.14 = 42/月
        2: 84,     // 600 × 0.14 = 84/月
        3: 168,    // 1200 × 0.14 = 168/月
        4: 308,    // 2200 × 0.14 = 308/月
        5: 490,    // 3500 × 0.14 = 490/月
        6: 700,    // 5000 × 0.14 = 700/月
        7: 952,    // 6800 × 0.14 = 952/月
        8: 1148,   // 8200 × 0.14 = 1148/月
        9: 1302,   // 9300 × 0.14 = 1302/月
        10: 1400   // 10000 × 0.14 = 1400/月
    };

    // 🎁 每月解锁胶片配额（按等级）
    window.MEMBERSHIP_MONTHLY_QUOTA = window.MEMBERSHIP_MONTHLY_QUOTA || {
        1: 300,    // LV1: 300胶片/月
        2: 600,    // LV2: 600胶片/月
        3: 1200,   // LV3: 1200胶片/月
        4: 2200,   // LV4: 2200胶片/月
        5: 3500,   // LV5: 3500胶片/月
        6: 5000,   // LV6: 5000胶片/月
        7: 6800,   // LV7: 6800胶片/月
        8: 8200,   // LV8: 8200胶片/月
        9: 9300,   // LV9: 9300胶片/月
        10: 10000  // LV10: 10000胶片/月
    };

    // ⏰ 会员降级规则：超过N天未消费自动降级
    window.MEMBERSHIP_INACTIVE_DAYS_TO_DOWNGRADE = 30;
    const MEMBERSHIP_LEVEL_PRICE_CNY = window.MEMBERSHIP_LEVEL_PRICE_CNY;

    const curLv = (() => {
        try {
            if (Number.isFinite(Number(window.currentMembershipLevel))) return Math.max(0, Math.min(10, Math.floor(Number(window.currentMembershipLevel))));
        } catch (e) { }
        try {
            const v = Number(localStorage.getItem('membership_level'));
            if (Number.isFinite(v)) return Math.max(0, Math.min(10, Math.floor(v)));
        } catch (e) { }
        return 0;
    })();

    const MEMBERSHIP_MONTHLY_QUOTA = window.MEMBERSHIP_MONTHLY_QUOTA || {};

    const cards = Array.from({ length: 10 }, (_, i) => i + 1).map((lv) => {
        const monthlyQuota = Number(MEMBERSHIP_MONTHLY_QUOTA?.[lv] || 0);
        const price = Number(MEMBERSHIP_LEVEL_PRICE_CNY?.[lv] || 0);
        const isCurrent = lv === curLv;
        const isLower = lv < curLv;
        const border = isCurrent ? '2px solid var(--accent-gold)' : '1px solid rgba(255,255,255,0.10)';
        const bg = isCurrent ? 'rgba(251,191,36,0.15)' : 'rgba(255,255,255,0.04)';
        const title = `LV${lv}`;
        const subtitle = `解锁 ${monthlyQuota} 胶片/月`;
        const btnText = isLower ? '已超过该等级' : (isCurrent ? '续费当前等级' : '立即开通');
        const btnDisabled = isLower;
        const btnStyle = btnDisabled
            ? 'background:rgba(255,255,255,0.1); color:#666; cursor:not-allowed;'
            : 'background:linear-gradient(135deg, #fbbf24 0%, #f59e0b 100%); color:#000; font-weight:900; cursor:pointer;';
        return `
            <div style="background: ${bg}; border: ${border}; border-radius: 12px; padding: 14px; display:flex; flex-direction:column; gap:8px;">
                <div style="display:flex; align-items:center; justify-content:space-between;">
                    <div style="font-weight: 1000; font-size: 16px; color: #fff;">${title}</div>
                    ${isCurrent ? '<div style="font-size: 10px; color: var(--accent-gold); font-weight: 900; background:rgba(251,191,36,0.2); padding:2px 6px; border-radius:4px;">当前</div>' : ''}
                </div>
                <div style="font-size: 11px; color: #999; line-height: 1.4;">🎁 ${subtitle}</div>
                <div style="font-size: 18px; color: var(--accent-gold); font-weight: 1000;">¥${price}<span style="font-size:12px; color:#888;">/月</span></div>
                <button onclick="openMembershipPurchase('lv${lv}')" style="width:100%; padding:10px; border:none; border-radius:8px; font-size:13px; ${btnStyle}" ${btnDisabled ? 'disabled' : ''}>${btnText}</button>
            </div>
        `;
    }).join('');

    // 获取会员到期时间
    const expiresAt = localStorage.getItem('membership_expires_at') || '';
    const expiresDate = expiresAt ? new Date(expiresAt) : null;
    const isExpired = expiresDate && expiresDate < new Date();
    const expiresText = expiresDate
        ? (isExpired ? `⚠️ 已于 ${expiresDate.toLocaleDateString()} 到期` : `📅 有效期至 ${expiresDate.toLocaleDateString()}`)
        : (curLv > 0 ? '📅 永久有效' : '');

    mount.innerHTML = `
        <div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px;">
            <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom: 12px;">
                <div style="color: #ddd; font-size: 14px; font-weight: 900;">💳 会员包月开通 / 续费</div>
                ${expiresText ? `<div style="font-size: 11px; color: ${isExpired ? '#ef4444' : '#10b981'};">${expiresText}</div>` : ''}
            </div>
            <div style="display:grid; grid-template-columns: repeat(2, 1fr); gap: 12px;">${cards}</div>
            <div style="margin-top: 14px; padding: 12px; background: rgba(251,191,36,0.1); border: 1px solid rgba(251,191,36,0.2); border-radius: 8px;">
                <div style="font-size: 12px; color: #fbbf24; font-weight: 800; margin-bottom: 6px;">💡 会员说明</div>
                <div style="font-size: 11px; color: #999; line-height: 1.6;">
                    1. 开通会员后解锁对应等级的胶片配额上限<br>
                    2. 点击"立即开通"按钮，系统会自动复制付款备注<br>
                    3. 前往下方"手动充值"区域完成支付<br>
                    4. ⚠️ 超过30天未消费将自动降级，请保持活跃
                </div>
            </div>
        </div>
    `;
}

async function refreshGiftUnlockStatus() {
    const summaryEl = document.getElementById('giftUnlockSummary');
    const detailEl = document.getElementById('giftUnlockDetails');
    const btn = document.getElementById('giftUnlockClaimBtn');

    if (summaryEl) summaryEl.textContent = '加载中...';
    if (detailEl) detailEl.textContent = '';
    if (btn) btn.disabled = true;

    try {
        if (typeof NVAuth === 'undefined') throw new Error('未登录');
        const user = await NVAuth.getCurrentUser();
        if (!user) throw new Error('未登录');

        const res = await fetch('/api/supabase-proxy', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'giftUnlockStatus', userId: user.id })
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok || !data.success) throw new Error(data.message || data.error || `获取失败: ${res.status}`);

        const totalGift = Number(data.totalGift || 0);
        const unlocked = Number(data.unlocked || 0);
        const limit = Number(data.unlockLimit || 0);
        const canUnlock = Number(data.canUnlock || 0);
        const memberType = String(data.membershipType || 'free');
        const memberLevelRaw = Number(data.membershipLevel);
        const hasMemberLevel = Number.isFinite(memberLevelRaw) && memberLevelRaw > 0;
        const memberLabel = hasMemberLevel ? `Lv${memberLevelRaw}` : memberType;

        if (summaryEl) {
            summaryEl.textContent = `总额：${totalGift} ｜ 当前等级(${memberLabel})可解锁：${limit} ｜ 已解锁：${unlocked}`;
        }
        if (detailEl) {
            const imgCost = (typeof QUOTA_COSTS === 'object' && QUOTA_COSTS && Number(QUOTA_COSTS.image_generation)) ? Number(QUOTA_COSTS.image_generation) : 1;
            const img4kCost = (typeof QUOTA_COSTS === 'object' && QUOTA_COSTS && Number(QUOTA_COSTS.image_4k)) ? Number(QUOTA_COSTS.image_4k) : 1;
            const videoCost = (typeof QUOTA_COSTS === 'object' && QUOTA_COSTS && Number(QUOTA_COSTS.video_sora2_15s)) ? Number(QUOTA_COSTS.video_sora2_15s) : 1;
            const base = Math.max(0, canUnlock > 0 ? canUnlock : Math.max(0, limit - unlocked));
            const estImg = imgCost > 0 ? Math.floor(base / imgCost) : 0;
            const est4k = img4kCost > 0 ? Math.floor(base / img4kCost) : 0;
            const estVideo = videoCost > 0 ? Math.floor(base / videoCost) : 0;
            const estLine = `约等于：普通图${estImg}张 / 4K图${est4k}张 / 15s视频${estVideo}个`;

            detailEl.textContent = canUnlock > 0
                ? `本次可领取：${canUnlock}（升级会员后可继续解锁剩余额度）\n${estLine}`
                : `当前等级暂无可领取额度（可升级会员提高可解锁上限）\n${estLine}`;
        }
        if (btn) {
            btn.disabled = !(canUnlock > 0);
            btn.textContent = canUnlock > 0 ? `领取 ${canUnlock}` : '暂无可领取';
        }

        // ✅ 全局缓存：用于侧边栏/状态栏显示“锁定/待领取”额度
        // 🔧 待解锁 = 总额 - 已解锁（不是canUnlock，那是"当前可领取"）
        const pendingUnlock = Math.max(0, totalGift - unlocked);
        try {
            localStorage.setItem('gift_unlock_can_unlock', String(Math.max(0, canUnlock))); // 修复：显示当前可领取数量
            localStorage.setItem('gift_unlock_claimable', String(Math.max(0, canUnlock)));
            localStorage.setItem('gift_unlock_unlocked', String(Math.max(0, unlocked)));
            localStorage.setItem('gift_unlock_limit', String(Math.max(0, limit)));
            localStorage.setItem('gift_unlock_total', String(Math.max(0, totalGift)));
            localStorage.setItem('gift_unlock_ts', String(Date.now()));
        } catch (e) { }
        try { updateUsageDisplay(); } catch (e) { }
        return data;
    } catch (e) {
        if (summaryEl) summaryEl.textContent = '解锁状态获取失败';
        if (detailEl) detailEl.textContent = String(e && e.message ? e.message : e);
        if (btn) {
            btn.disabled = true;
            btn.textContent = '领取可解锁额度';
        }
        try {
            localStorage.setItem('gift_unlock_can_unlock', '0');
            localStorage.setItem('gift_unlock_ts', String(Date.now()));
        } catch (err) { }
        try { updateUsageDisplay(); } catch (err) { }
        return null;
    }
}

async function claimGiftUnlock() {
    const btn = document.getElementById('giftUnlockClaimBtn');
    if (btn) {
        btn.disabled = true;
        btn.textContent = '领取中...';
    }
    try {
        if (typeof NVAuth === 'undefined') throw new Error('未登录');
        const user = await NVAuth.getCurrentUser();
        if (!user) throw new Error('未登录');

        const res = await fetch('/api/supabase-proxy', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'claimGiftUnlock', userId: user.id })
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok || !data.success) throw new Error(data.message || data.error || `领取失败: ${res.status}`);

        const delta = Number(data.delta || 0);
        const newBalance = Number(data.newBalance ?? data.quotaBalance ?? 0);

        if (Number.isFinite(newBalance)) {
            try {
                localStorage.setItem('film_balance', String(newBalance));
                localStorage.setItem('cloud_film_balance', String(newBalance));
            } catch (e) { }
            try {
                const profile = JSON.parse(localStorage.getItem('nv_user_profile') || '{}');
                if (profile && typeof profile === 'object') {
                    profile.quota_balance = newBalance;
                    localStorage.setItem('nv_user_profile', JSON.stringify(profile));
                }
            } catch (e) { }
        }

        try { if (typeof updateUsageDisplay === 'function') updateUsageDisplay(); } catch (e) { }
        try { if (typeof updateMemberInfo === 'function') updateMemberInfo(); } catch (e) { }

        if (delta > 0) {
            alert(`🎁 已解锁 ${delta} 胶片\n\n当前余额：${newBalance}`);
        } else {
            alert(data.message || '当前等级暂无可解锁额度');
        }
    } catch (e) {
        alert('❌ 领取失败：' + (e && e.message ? e.message : e));
    } finally {
        await refreshGiftUnlockStatus();
    }
}

window.refreshGiftUnlockStatus = refreshGiftUnlockStatus;
window.claimGiftUnlock = claimGiftUnlock;

// 🔐 获取当前用户ID（用于API调用时传递userId）
async function getCurrentUserId() {
    if (typeof NVAuth === 'undefined') return null;
    try {
        const user = await NVAuth.getCurrentUser();
        return user?.id || null;
    } catch (e) {
        console.warn('[getCurrentUserId] 获取用户ID失败:', e);
        return null;
    }
}

/**
 * 🆕 获取当前用户ID（带Session刷新重试）
 * 用于API调用前确保用户已登录
 * @param {boolean} throwOnFail - 失败时是否抛出异常（默认true）
 * @returns {Promise<string|null>} 用户ID
 */
async function requireUserId(throwOnFail = true) {
    if (typeof NVAuth === 'undefined') {
        if (throwOnFail) throw new Error('请先登录后再使用此功能');
        return null;
    }

    // 第一次尝试
    let user = await NVAuth.getCurrentUser();
    if (user?.id) return user.id;

    // Session可能过期，尝试刷新
    console.log('🔄 [Auth] 用户为空，尝试刷新Session...');
    if (typeof NVAuth.refreshSession === 'function') {
        const refreshed = await NVAuth.refreshSession();
        if (refreshed) {
            user = await NVAuth.getCurrentUser();
            if (user?.id) {
                console.log('✅ [Auth] Session刷新成功，用户已恢复');
                return user.id;
            }
        }
    }

    // 确实未登录或登录已过期
    console.warn('⚠️ [Auth] 用户未登录或登录已过期');
    if (throwOnFail) {
        // 🆕 提示用户重新登录
        const shouldRelogin = confirm('登录已过期，是否重新登录？');
        if (shouldRelogin && typeof showLoginModal === 'function') {
            showLoginModal();
        }
        throw new Error('登录已过期，请重新登录');
    }
    return null;
}

window.requireUserId = requireUserId;

async function retryableAPICall(fn, optionsOrMaxRetries = {}, legacyRetryDelayMs) {
    const options = (typeof optionsOrMaxRetries === 'number')
        ? { maxRetries: optionsOrMaxRetries, retryDelayMs: legacyRetryDelayMs }
        : (optionsOrMaxRetries || {});
    const maxRetries = Number.isFinite(options.maxRetries) ? options.maxRetries : 3;
    const retryDelayMs = Number.isFinite(options.retryDelayMs) ? options.retryDelayMs : 3000;
    let lastErr = null;
    for (let attempt = 1; attempt <= maxRetries; attempt++) {
        try {
            return await fn(attempt);
        } catch (e) {
            lastErr = e;
            if (e && e.name === 'AbortError') break;
            if (attempt >= maxRetries) break;
            await new Promise(r => setTimeout(r, retryDelayMs * attempt));
        }
    }
    throw lastErr || new Error('API调用失败');
}

async function callZhenzhenTextAPI(prompt, options = {}) {
    const model = options.model || 'gemini-3.1-pro-preview';
    const temperature = (typeof options.temperature === 'number') ? options.temperature : 0.7;
    const max_tokens = (typeof options.max_tokens === 'number') ? options.max_tokens : 4096;
    const speed = (typeof options.speed === 'number') ? options.speed : 1;

    if (!prompt) throw new Error('提示词为空');

    const paid = (typeof isPaidUser === 'function' && isPaidUser());
    if (!paid) {
        const access = (typeof checkFreeUserTextProvider === 'function')
            ? checkFreeUserTextProvider('gemini3')
            : { allowed: false, message: 'Gemini3 为付费用户专属功能' };
        if (!access || !access.allowed) {
            throw new Error((access && access.message) ? access.message : 'Gemini3 为付费用户专属功能');
        }
    }

    // 🔐 获取当前用户ID（yunwu API 必须提供 userId）
    let userId = null;
    try {
        if (typeof NVAuth !== 'undefined' && NVAuth.getCurrentUser) {
            const user = await NVAuth.getCurrentUser();
            userId = user?.id || null;
        }
    } catch (e) {
        console.warn('[callZhenzhenTextAPI] 获取用户ID失败:', e?.message);
    }
    if (!userId) {
        throw new Error('请先登录后再使用此功能');
    }

    const res = await fetch('/api/yunwu', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            action: 'text',
            prompt,
            model,
            temperature,
            max_tokens,
            speed,
            userId  // 🔐 传递用户ID
        })
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || !data.success) {
        throw new Error(data.message || data.error || `文本生成失败: ${res.status}`);
    }
    const content = String(data.content || data.text || '').trim();
    if (!content) throw new Error('文本生成返回为空');

    if (paid) {
        try {
            await consumeRealtime('text_gemini3', 1, false);
        } catch (e) {
            console.error('❌ [文本扣费失败]', e && e.message ? e.message : e);
        }
    }
    return content;
}

async function callScriptGenerator(idea, prompt) {
    const s = (idea && idea.settings) ? idea.settings : {};
    const provider = String(s.scriptProvider || 'gemini3').trim().toLowerCase();
    const paid = (typeof isPaidUser === 'function') ? !!isPaidUser() : false;

    // 🆓 免费用户：默认走“魔塔/智能文本”通道（避免 Gemini3 拦截导致第一步不可用）
    const wantFreeText = (provider === 'motaverse') || (!paid && provider === 'gemini3');
    if (wantFreeText) {
        // 配额检查（魔塔文本）
        if (!paid && typeof checkFreeUserAccess === 'function') {
            const access = checkFreeUserAccess('modelscope_text');
            if (access && access.blocked) {
                throw new Error(access.message || '今日免费文本额度已用完');
            }
        }

        // 1) 优先：ModelScope 文本（魔塔）
        try {
            const out = await retryableAPICall(() => callModelScopeTextAPI(prompt), 2, 2000);
            if (out) {
                if (!paid && typeof consumeModelScopeQuota === 'function') {
                    try { consumeModelScopeQuota('text'); } catch (e) { }
                }
                return out;
            }
        } catch (e) {
            // 继续兜底
        }

        // 2) 兜底：writer-llm（如果后端配置了 WRITER_MIMO_API_KEY）
        try {
            const msg = [
                { role: 'system', content: '你是中文短视频剧本/故事写作助手。请直接输出连贯的故事正文，不要解释。' },
                { role: 'user', content: String(prompt || '') }
            ];
            const out = await retryableAPICall(() => callWriterLLM(msg, { temperature: 0.8, max_tokens: 4096 }), 2, 2000);
            if (out) return out;
        } catch (e) { }

        throw new Error('文本生成失败：免费通道不可用');
    }

    // 💎 付费用户 / Gemini3 高级通道
    const model = s.scriptModel || s.textModel || 'gemini-3.1-pro-preview';
    const temperature = (typeof s.scriptTemperature === 'number') ? s.scriptTemperature : 0.8;
    const max_tokens = (typeof s.scriptMaxTokens === 'number') ? s.scriptMaxTokens : 4096;
    const speed = (typeof s.scriptSpeed === 'number') ? s.scriptSpeed : 1;
    return await retryableAPICall(() => callZhenzhenTextAPI(prompt, { model, temperature, max_tokens, speed }), 2, 2500);
}

async function callModelScopeImageAPI(prompt, options = {}) {
    const aspectRatio = options.aspectRatio || '1:1';
    const refImage = options.refImage;
    const refImages = options.refImages;  // 🌟 多图参考支持 (1-3张)
    const skipDeduct = options.skipDeduct || false;  // 允许调用方跳过扣费（避免重复扣费）

    // 获取当前用户ID
    let userId = null;
    try {
        if (typeof NVAuth !== 'undefined') {
            const user = await NVAuth.getCurrentUser();
            userId = user?.id;
        }
    } catch (e) {
        console.warn('[ModelScope] 获取用户ID失败:', e);
    }

    // 🔐 必须登录才能使用
    if (!userId) {
        throw new Error('请先登录后再使用此功能');
    }

    // 🌟 确定图片 URL 数组
    let imageUrls = undefined;
    let action = 'image';

    // 多图参考模式 (1-3张)
    if (refImages && Array.isArray(refImages) && refImages.length >= 2) {
        // Qwen-Image-Edit 最多支持3张参考图
        imageUrls = refImages.slice(0, 3);
        action = 'image2image';
        console.log(`🎭 [万象Max] 多图编辑模式: ${imageUrls.length}张参考图`);
    }
    // 单图参考模式
    else if (refImage) {
        imageUrls = [refImage];
        action = 'image2image';
    }

    const res = await fetch('/api/modelscope', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            action,
            prompt,
            aspectRatio,
            imageUrls,
            userId
        })
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || !data.success) {
        throw new Error(data.message || data.error || `ModelScope失败: ${res.status}`);
    }
    const img = (data.images && data.images[0]) ? data.images[0] : null;
    if (!img) throw new Error('ModelScope 未返回图片');

    // 🎞️ 有胶片的用户使用ModelScope也要扣费（成本较低，扣0.5胶片）
    if (!skipDeduct) {
        try {
            const filmBalance = parseFloat(localStorage.getItem('film_balance') || '0');
            if (filmBalance > 0) {
                const result = await consumeFilmFromCloud(0.5);
                console.log(`🎞️ [ModelScope扣费] 余额=${filmBalance}, 扣费0.5胶片, 结果:`, result?.success ? '成功' : result?.message);
            }
        } catch (e) {
            console.error('❌ [ModelScope扣费失败]', e?.message || e);
        }
    }

    return img;
}

