/**
 * 🛡️ 本地快速检测提示词是否违规
 * @param {string} text - 要检测的文本
 * @returns {object} { safe, level, category, message }
 */
function checkContentLocal(text) {
    if (!text || typeof text !== 'string') {
        return { safe: true, level: 0, category: null, message: '' };
    }

    const lowerText = text.toLowerCase();
    let maxLevel = 0;
    let category = null;
    let matchedCount = 0;

    // 检查极端违规
    for (const keyword of CONTENT_MODERATION.extreme) {
        if (lowerText.includes(keyword.toLowerCase())) {
            maxLevel = 3;
            category = 'extreme';
            matchedCount++;
            break; // 极端违规直接返回
        }
    }

    // 检查严重违规
    if (maxLevel < 3) {
        for (const keyword of CONTENT_MODERATION.severe) {
            if (lowerText.includes(keyword.toLowerCase())) {
                maxLevel = Math.max(maxLevel, 2);
                category = category || 'severe';
                matchedCount++;
            }
        }
    }

    // 检查警告级别
    if (maxLevel < 2) {
        for (const keyword of CONTENT_MODERATION.warning) {
            if (lowerText.includes(keyword.toLowerCase())) {
                maxLevel = Math.max(maxLevel, 1);
                category = category || 'warning';
                matchedCount++;
            }
        }
    }

    const messages = {
        3: '⛔ 检测到极端违规内容，已记录。继续违规将导致账号永久封禁！',
        2: '🚫 检测到违规内容，禁止生成。请修改提示词后重试。',
        1: '⚠️ 检测到敏感内容，建议修改后再生成。',
        0: ''
    };

    return {
        safe: maxLevel === 0,
        level: maxLevel,
        category,
        message: messages[maxLevel],
        matchedCount
    };
}

/**
 * 🔒 用户违规记录管理（本地存储 + 云端同步）
 */
const ViolationManager = {
    STORAGE_KEY: 'nv_user_violations',
    BAN_STORAGE_KEY: 'nv_user_ban_status',

    // 获取当前用户ID
    getUserId() {
        if (typeof NVAuth !== 'undefined' && NVAuth.user) {
            return NVAuth.user.id;
        }
        // 匿名用户使用设备指纹
        let anonId = localStorage.getItem('nv_anon_user_id');
        if (!anonId) {
            anonId = 'anon_' + Date.now() + '_' + Math.random().toString(36).slice(2);
            localStorage.setItem('nv_anon_user_id', anonId);
        }
        return anonId;
    },

    // 获取本地违规记录
    getLocalViolations() {
        try {
            const data = localStorage.getItem(this.STORAGE_KEY);
            return data ? JSON.parse(data) : [];
        } catch (e) {
            return [];
        }
    },

    // 记录违规
    async recordViolation(content, contentType, level, category) {
        const userId = this.getUserId();
        const violation = {
            userId,
            content: content.substring(0, 500), // 限制长度
            contentType,
            level,
            category,
            timestamp: Date.now(),
            date: new Date().toISOString()
        };

        // 本地存储
        const violations = this.getLocalViolations();
        violations.push(violation);
        // 只保留最近100条
        if (violations.length > 100) {
            violations.splice(0, violations.length - 100);
        }
        localStorage.setItem(this.STORAGE_KEY, JSON.stringify(violations));

        // 云端同步（如果已登录）
        if (typeof NVAuth !== 'undefined' && NVAuth.user) {
            try {
                await fetch('/api/content-moderation', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        action: 'record_violation',
                        userId,
                        content: violation.content,
                        contentType,
                        level,
                        category
                    })
                });
            } catch (e) {
                console.warn('云端违规记录同步失败:', e);
            }
        }

        // 检查是否需要自动封禁
        await this.checkAndAutoBan();

        return violation;
    },

    // 检查并自动封禁
    async checkAndAutoBan() {
        const violations = this.getLocalViolations();
        const userId = this.getUserId();
        const now = Date.now();
        const thirtyDaysAgo = now - 30 * 24 * 60 * 60 * 1000;

        // 只统计30天内的违规
        const recentViolations = violations.filter(v => v.timestamp > thirtyDaysAgo);
        const extremeCount = recentViolations.filter(v => v.level >= 3).length;
        const severeCount = recentViolations.filter(v => v.level >= 2).length;

        let banInfo = null;

        // 封禁规则
        if (extremeCount >= 1) {
            // 极端违规1次，永久封禁
            banInfo = {
                banned: true,
                reason: '发布极端违规内容',
                permanent: true,
                bannedAt: new Date().toISOString()
            };
        } else if (severeCount >= 5) {
            // 严重违规5次，永久封禁
            banInfo = {
                banned: true,
                reason: '多次发布严重违规内容',
                permanent: true,
                bannedAt: new Date().toISOString()
            };
        } else if (severeCount >= 3) {
            // 严重违规3次，封禁7天
            banInfo = {
                banned: true,
                reason: '多次发布违规内容',
                permanent: false,
                expiresAt: new Date(now + 7 * 24 * 60 * 60 * 1000).toISOString(),
                bannedAt: new Date().toISOString()
            };
        }

        if (banInfo) {
            localStorage.setItem(this.BAN_STORAGE_KEY, JSON.stringify(banInfo));

            // 云端同步封禁状态
            if (typeof NVAuth !== 'undefined' && NVAuth.user) {
                try {
                    await fetch('/api/content-moderation', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            action: 'ban_user',
                            userId,
                            reason: banInfo.reason,
                            duration: banInfo.permanent ? null : 7
                        })
                    });
                } catch (e) {
                    console.warn('云端封禁同步失败:', e);
                }
            }
        }

        return banInfo;
    },

    // 检查用户是否被封禁
    checkBanStatus() {
        try {
            const data = localStorage.getItem(this.BAN_STORAGE_KEY);
            if (!data) return { banned: false };

            const banInfo = JSON.parse(data);
            if (!banInfo.banned) return { banned: false };

            // 检查临时封禁是否过期
            if (!banInfo.permanent && banInfo.expiresAt) {
                if (new Date(banInfo.expiresAt) < new Date()) {
                    // 封禁已过期
                    localStorage.removeItem(this.BAN_STORAGE_KEY);
                    return { banned: false };
                }
            }

            return banInfo;
        } catch (e) {
            return { banned: false };
        }
    },

    // 获取违规统计
    getViolationStats() {
        const violations = this.getLocalViolations();
        const now = Date.now();
        const thirtyDaysAgo = now - 30 * 24 * 60 * 60 * 1000;
        const recentViolations = violations.filter(v => v.timestamp > thirtyDaysAgo);

        return {
            total: violations.length,
            recent: recentViolations.length,
            extreme: recentViolations.filter(v => v.level >= 3).length,
            severe: recentViolations.filter(v => v.level >= 2).length,
            warning: recentViolations.filter(v => v.level === 1).length
        };
    }
};

// 暴露到全局
window.ViolationManager = ViolationManager;
window.checkContentLocal = checkContentLocal;

/**
 * 🛡️ 内容审核入口函数 - 在生成前调用
 * @param {string} prompt - 提示词
 * @param {string} contentType - 内容类型 ('prompt' | 'image')
 * @returns {object} { allowed, message, level }
 */
async function moderateContent(prompt, contentType = 'prompt') {
    // 1. 检查用户是否被封禁
    const banStatus = ViolationManager.checkBanStatus();
    if (banStatus.banned) {
        const msg = banStatus.permanent
            ? `⛔ 您的账号已被永久封禁\n原因：${banStatus.reason}\n如有异议请联系客服申诉`
            : `⛔ 您的账号已被临时封禁\n原因：${banStatus.reason}\n解封时间：${new Date(banStatus.expiresAt).toLocaleString()}`;
        return { allowed: false, message: msg, level: 99, banned: true };
    }

    // 2. 本地快速检测
    const localResult = checkContentLocal(prompt);

    if (localResult.level >= 2) {
        // 严重违规，记录并拒绝
        await ViolationManager.recordViolation(prompt, contentType, localResult.level, localResult.category);
        return {
            allowed: false,
            message: localResult.message,
            level: localResult.level,
            category: localResult.category
        };
    }

    if (localResult.level === 1) {
        // 警告级别，允许但提示
        console.warn('⚠️ 内容审核警告:', localResult.message);
        // 不记录警告级别，只提示
    }

    return {
        allowed: true,
        message: localResult.message,
        level: localResult.level,
        category: localResult.category
    };
}

// 暴露到全局
window.moderateContent = moderateContent;

