function getPluginDetectionIssues() {
    const issues = [];
    if (typeof supabase === 'undefined') {
        const note = supabaseFallbackLoading ? '（正在尝试备用线路...）' : '';
        issues.push(`Supabase SDK 未加载，可能被浏览器插件或网络阻止${note}`);
    }
    if (typeof NVAuth === 'undefined') {
        issues.push('NVAuth 模块未初始化，云端同步功能不可用。');
    }
    if (typeof callBanana2ImageAPI !== 'function') {
        issues.push('核心脚本未成功执行（callBanana2ImageAPI 不可用）。');
    }
    return issues;
}

function updatePluginWarningUI() {
    const warningEl = document.getElementById('pluginWarning');
    const listEl = document.getElementById('pluginWarningList');
    const checkbox = document.getElementById('pluginConfirmCheckbox');

    if (!warningEl || !listEl) return;

    if (pluginDetectionIssues.length > 0) {
        listEl.innerHTML = pluginDetectionIssues.map(item => `<li>${escapeHtml(item)}</li>`).join('');
        if (checkbox) checkbox.checked = pluginBypassConfirmed;
        warningEl.style.display = 'flex';
    } else {
        warningEl.style.display = 'none';
    }
}

function hidePluginWarning() {
    const warningEl = document.getElementById('pluginWarning');
    if (warningEl) warningEl.style.display = 'none';
}

function runPluginDetection(forceShow = false) {
    pluginDetectionIssues = getPluginDetectionIssues();
    pluginBlockDetected = pluginDetectionIssues.length > 0;

    if (pluginDetectionIssues.some(msg => msg.includes('Supabase SDK')) && typeof supabase === 'undefined') {
        tryLoadSupabaseFallback();
    }

    if (pluginBlockDetected) {
        if (!pluginBypassConfirmed || forceShow) {
            updatePluginWarningUI();
        }
        return pluginBypassConfirmed;
    }

    hidePluginWarning();
    return true;
}

window.retryPluginDetection = function () {
    pluginBypassConfirmed = false;
    localStorage.removeItem('plugin_bypass_confirmed');
    runPluginDetection(true);
};

window.confirmPluginBypass = function () {
    const checkbox = document.getElementById('pluginConfirmCheckbox');
    if (checkbox && !checkbox.checked) {
        alert('请先勾选确认后再继续。');
        return;
    }
    pluginBypassConfirmed = true;
    localStorage.setItem('plugin_bypass_confirmed', 'true');
    hidePluginWarning();
};

function tryLoadSupabaseFallback() {
    if (supabaseFallbackLoading || typeof supabase !== 'undefined') return;
    if (supabaseFallbackIndex >= SUPABASE_FALLBACK_SRCS.length) return;

    const src = SUPABASE_FALLBACK_SRCS[supabaseFallbackIndex++];
    supabaseFallbackLoading = true;
    console.log('尝试加载 Supabase 备用线路:', src);

    const script = document.createElement('script');
    script.src = `${src}?cache=${Date.now()}`;
    script.onload = () => {
        supabaseFallbackLoading = false;
        console.log('✅ Supabase 备用线路加载成功');
        setTimeout(() => runPluginDetection(true), 200);
    };
    script.onerror = () => {
        supabaseFallbackLoading = false;
        console.warn('⚠️ Supabase 备用线路加载失败');
        tryLoadSupabaseFallback();
    };
    document.head.appendChild(script);
}

// ==================== 全局缩放函数（提前定义） ====================
/**
 * 获取当前画布缩放比例
 * @returns {number} 缩放比例
 */
window.getCurrentScale = function () {
    const canvas = document.getElementById('taskCanvas');
    if (!canvas) return 1;
    const st = canvas.style.transform;
    const m = st.match(/scale\(([\d.]+)\)/);
    return m ? parseFloat(m[1]) : 1;
};

/**
 * 获取当前画布平移
 * @returns {{x: number, y: number}} 平移坐标
 */
window.getCanvasTranslate = function () {
    const canvas = document.getElementById('taskCanvas');
    if (!canvas) return { x: 0, y: 0 };
    const st = canvas.style.transform;
    const m = st.match(/translate\(([-\d.]+)px,\s*([-\d.]+)px\)/);
    return m ? { x: parseFloat(m[1]), y: parseFloat(m[2]) } : { x: 0, y: 0 };
};

