// ==================== API 日志系统 ====================

// 保存原始 fetch
const originalFetch = window.fetch;

// 拦截 fetch 请求
window.fetch = async function (url, options = {}) {
    const startTime = Date.now();
    const method = options.method || 'GET';
    const urlStr = typeof url === 'string' ? url : url.toString();

    // 简化 URL 显示
    let shortUrl = urlStr;
    try {
        const u = new URL(urlStr, window.location.origin);
        shortUrl = u.pathname + (u.search ? '?' + u.search.substring(0, 50) : '');
        if (shortUrl.length > 80) shortUrl = shortUrl.substring(0, 80) + '...';
    } catch (e) {
        if (shortUrl.length > 80) shortUrl = shortUrl.substring(0, 80) + '...';
    }

    // 记录请求
    if (typeof window.addApiLog === 'function') {
        let reqDetails = null;
        if (options.body) {
            try {
                reqDetails = typeof options.body === 'string' ? JSON.parse(options.body) : options.body;
            } catch (e) {
                reqDetails = options.body.toString().substring(0, 500);
            }
        }
        window.addApiLog('REQUEST', `${method} ${shortUrl}`, reqDetails);
    }

    try {
        const response = await originalFetch.call(window, url, options);
        const duration = Date.now() - startTime;

        // 克隆响应以便读取内容
        const clonedResponse = response.clone();

        // 记录响应
        if (typeof window.addApiLog === 'function') {
            const statusColor = response.ok ? 'SUCCESS' : 'ERROR';
            let resDetails = null;

            try {
                const contentType = response.headers.get('content-type') || '';
                if (contentType.includes('application/json')) {
                    resDetails = await clonedResponse.json();
                } else if (contentType.includes('text/')) {
                    const text = await clonedResponse.text();
                    resDetails = text.substring(0, 1000);
                } else {
                    resDetails = `[${contentType || 'binary'}] ${response.status}`;
                }
            } catch (e) {
                resDetails = `[无法解析响应]`;
            }

            window.addApiLog(statusColor, `${response.status} ${shortUrl} (${duration}ms)`, resDetails);
        }

        return response;
    } catch (error) {
        const duration = Date.now() - startTime;

        if (typeof window.addApiLog === 'function') {
            window.addApiLog('ERROR', `${method} ${shortUrl} 失败 (${duration}ms)`, error.message);
        }

        throw error;
    }
};

// 辅助函数：手动添加日志
window.logApi = function (type, message, details) {
    if (typeof window.addApiLog === 'function') {
        window.addApiLog(type, message, details);
    }
    console.log(`[API ${type}]`, message, details || '');
};

