/**
 * 更新影院式遮罩的步骤状态
 * @param {string} text - 步骤描述文本
 * @param {string} status - 状态: 'processing', 'completed', 'error', 'warning'
 * @param {number} ideaId - 任务ID（可选）
 */
function updateCinematicOverlaySteps(text, status, ideaId) {
    // 更新主状态文本
    const st = document.getElementById('cineStatus');
    if (st) {
        st.textContent = text;
        // 根据状态设置颜色
        if (status === 'completed') {
            st.style.color = '#34d399';
        } else if (status === 'error') {
            st.style.color = '#ef4444';
        } else if (status === 'warning') {
            st.style.color = '#fbbf24';
        } else {
            st.style.color = '#fff';
        }
    }

    // 同时更新步骤日志（如果有ideaId）
    if (ideaId) {
        const idea = ideas.find(i => i.id === ideaId);
        if (idea) {
            // 可以在这里添加更多的UI更新逻辑
            console.log(`📋 [${idea.theme.substring(0, 20)}...] ${text}`);
        }
    }
}

// ==================== 全局状态 & 配额 ====================

let ideas = [];
let deletedTaskIds = []; // 🔧 跟踪已删除的任务ID，用于云端同步
let currentEditingId = null;
let isGenerating = false;
let totalGenerated = 0;
let autoMode = 'sora-2'; // Note: This variable name is reused for radio group value in onModeChange
let maxConcurrentTasks = 3;

const __taskScheduler = {
    running: new Set(),
    queue: [],
    pumpTimer: null,
    getLimit() {
        try {
            const stats = getUsageStats();
            const lim = stats?.plan?.maxConcurrent;
            // 云雾上游可高并发，但浏览器/UI 仍需保护上限
            if (lim === Infinity) return 50;
            const n = parseInt(lim, 10);
            return Number.isFinite(n) && n > 0 ? n : 1;
        } catch (e) {
            return 1;
        }
    },
    isBusy() {
        return this.running.size > 0 || this.queue.length > 0;
    },
    enqueue(tasks) {
        const list = Array.isArray(tasks) ? tasks : [tasks];
        list.forEach(t => {
            if (!t) return;
            if (t.status === 'processing' || t.status === 'completed') return;
            if ([...this.running].some(x => x && x.id === t.id)) return;
            if (this.queue.some(x => x && x.id === t.id)) return;
            this.queue.push(t);
        });
        try {
            updateBatchButton();
            renderIdeasList();
        } catch (e) { }
        this.pump();
    },
    async _runTask(task) {
        try {
            // 💰 任务执行前强制从云端同步余额，确保扣费准确
            console.log('💰 [任务启动] 正在从云端同步余额...');
            if (typeof refreshFilmBalanceFromCloud === 'function') {
                await refreshFilmBalanceFromCloud(true); // 强制同步
            }

            // 💰 检查用户是否已登录且余额充足
            if (typeof NVAuth !== 'undefined') {
                const user = await NVAuth.getCurrentUser();
                if (!user) {
                    console.error('❌ [任务启动] 用户未登录');
                    task.status = 'error';
                    task.error = '请先登录后再执行任务';
                    alert('❌ 请先登录后再执行任务');
                    renderIdeasList();
                    return;
                }

                // 检查余额是否足够（预估最低消耗）
                const balance = getFilmBalance();
                const minCost = 2; // 最低消耗（一次视频生成）
                if (balance < minCost && typeof isPaidUser === 'function' && isPaidUser()) {
                    console.error(`❌ [任务启动] 余额不足: ${balance} < ${minCost}`);
                    task.status = 'error';
                    task.error = `余额不足（当前${balance}胶片）`;
                    alert(`❌ 胶片余额不足\n\n当前余额: ${balance} 胶片\n最低需要: ${minCost} 胶片\n\n请充值后重试`);
                    renderIdeasList();
                    return;
                }
            }

            console.log('✅ [任务启动] 余额检查通过，开始执行任务');

            if (task.type === 'comic') {
                await executeComicGeneration(task);
            } else if (task.type === 'continuity') {
                await executeContinuityVideoGeneration(task);
            } else if (task.type === 'writing') {
                // ✍️ 写作任务不走自动执行流程，需要用户手动操作
                console.log('✍️ 写作任务需要手动操作，请在写作面板中点击"一键生成章节"');
                task.status = 'writing';
                renderCanvas();
                renderIdeasList();
                // 打开写作任务设置面板
                if (typeof openWritingTaskSettings === 'function') {
                    openWritingTaskSettings(task.id);
                }
            } else {
                await processIdea(task);
            }
        } catch (e) {
            console.error('❌ [任务执行] 异常:', e);
        }
    },
    pump() {
        if (this.pumpTimer) return;
        this.pumpTimer = setTimeout(() => {
            this.pumpTimer = null;
            const limit = this.getLimit();
            while (this.running.size < limit && this.queue.length > 0) {
                const task = this.queue.shift();
                if (!task) continue;
                this.running.add(task);
                Promise.resolve()
                    .then(() => this._runTask(task))
                    .finally(() => {
                        this.running.delete(task);
                        try {
                            updateBatchButton();
                            renderIdeasList();
                        } catch (e) { }
                        this.pump();
                    });
            }
            try {
                updateBatchButton();
            } catch (e) { }
        }, 0);
    }
};

