function onGenModeChange(mode) {
    const hint = document.getElementById('continuityModeHint');

    // 🖼️ 图生视频模式：显示/隐藏角色图上传区域
    const refImageSection = document.getElementById('quickRefImageSection');
    if (refImageSection) {
        const isImageMode = mode === 'image-to-video' || mode === 'banana-image-to-video' || mode === 'grok-video-3' || mode === 'grok-video-3-10s' || mode === 'grok-video-3-15s';
        refImageSection.style.display = isImageMode ? 'block' : 'none';
    }

    // 💰 显示价格提示
    const priceHintArea = document.getElementById('priceHintArea');
    const priceHintContent = document.getElementById('priceHintContent');

    if (priceHintArea && priceHintContent) {
        const priceInfo = MODEL_PRICES[mode];

        if (priceInfo) {
            priceHintArea.style.display = 'block';

            let content = `<div style="font-weight: 700; font-size: 18px; color: #60a5fa;">${priceInfo.cost === 0 ? '🆓 免费' : '🎞️ ' + priceInfo.label}</div>`;

            if (priceInfo.warning) {
                content += `<div style="margin-top: 8px; padding: 8px; background: rgba(239,68,68,0.15); border: 1px solid rgba(239,68,68,0.4); border-radius: 6px; color: #fca5a5; font-size: 13px;">${priceInfo.warning}</div>`;
            }

            if (priceInfo.cost === 0) {
                content += `<div style="margin-top: 8px; color: #888; font-size: 12px;">• 新用户有3次免费机会<br>• VIP用户无限制</div>`;
            }

            priceHintContent.innerHTML = content;
        } else {
            priceHintArea.style.display = 'none';
        }
    }

    if (!hint) return;

    if (mode === 'video-continuity') {
        hint.style.display = 'block';
        // 连续性视频模式下，禁用时长和分镜输入（由AI自动分镜）
        const durInput = document.getElementById('quickDuration');
        const scInput = document.getElementById('quickScenes');
        if (durInput) {
            durInput.value = '';
            durInput.placeholder = 'AI自动分镜';
            durInput.disabled = true;
        }
        if (scInput) {
            scInput.value = '';
            scInput.placeholder = 'AI自动分镜';
            scInput.disabled = true;
        }
    } else {
        hint.style.display = 'none';
        // 恢复时长和分镜输入
        const durInput = document.getElementById('quickDuration');
        const scInput = document.getElementById('quickScenes');
        if (durInput) {
            durInput.placeholder = '自动分析';
            durInput.disabled = false;
        }
        if (scInput) {
            scInput.placeholder = '自动分析';
            scInput.disabled = false;
        }
    }
}
window.onGenModeChange = onGenModeChange;

function adjustTaskCount(delta) {
    maxConcurrentTasks += delta;
    if (maxConcurrentTasks < 1) maxConcurrentTasks = 1;
    if (maxConcurrentTasks > 10) maxConcurrentTasks = 10;
    document.getElementById('taskCountDisplay').textContent = maxConcurrentTasks;
}

window.onModeChange = onModeChange;
window.adjustTaskCount = adjustTaskCount;

// ==================== 🆕 自动托管模式函数 ====================

/**
 * 启用/禁用自动托管模式
 * 用户可以批量添加任务，系统会自动按顺序处理
 */
async function toggleAutoHosting() {
    // 🔐 【紧急】强制登录验证
    try {
        if (typeof NVAuth !== 'undefined') {
            const currentUser = await NVAuth.getCurrentUser();
            if (!currentUser) {
                alert('🔒 请先登录后再使用自动托管功能\n\n点击右上角"登录/注册"按钮');
                if (typeof window.showAuthModal === 'function') {
                    window.showAuthModal();
                }
                return;
            }
        }
    } catch (e) {
        console.error('登录验证失败:', e);
        alert('❌ 请先登录后再使用');
        return;
    }

    autoHostingMode = !autoHostingMode;
    console.log(`🤖 自动托管模式: ${autoHostingMode ? '已启用' : '已禁用'}`);

    if (autoHostingMode) {
        // 启用时，检查是否有待处理任务
        checkAndStartAutoHosting();
    } else {
        // 禁用时，停止处理（当前任务会完成）
        autoHostingRunning = false;
    }

    // 更新UI状态（可选，不改变UI结构）
    localStorage.setItem('auto_hosting_enabled', autoHostingMode ? 'true' : 'false');
}

/**
 * 添加任务到自动托管队列
 * @param {Object} idea - 任务对象
 */
function addToAutoHostingQueue(idea) {
    if (!autoHostingQueue.find(i => i.id === idea.id)) {
        autoHostingQueue.push(idea);
        console.log(`📥 任务已加入托管队列: ${idea.theme || idea.id}`);

        // 如果托管模式启用且未运行，则启动
        if (autoHostingMode && !autoHostingRunning) {
            startAutoHosting();
        }
    }
}

/**
 * 从托管队列中移除任务
 * @param {string} ideaId - 任务ID
 */
function removeFromAutoHostingQueue(ideaId) {
    const index = autoHostingQueue.findIndex(i => i.id === ideaId);
    if (index !== -1) {
        autoHostingQueue.splice(index, 1);
        console.log(`🗑️ 任务已从托管队列移除: ${ideaId}`);
    }
}

/**
 * 检查并启动自动托管
 */
function checkAndStartAutoHosting() {
    if (autoHostingMode && !autoHostingRunning && autoHostingQueue.length > 0) {
        startAutoHosting();
    }
}

/**
 * 启动自动托管处理
 * 自动按顺序处理队列中的所有任务
 */
async function startAutoHosting() {
    if (autoHostingRunning) {
        console.warn('⚠️ 自动托管已在运行中');
        return;
    }

    if (autoHostingQueue.length === 0) {
        console.log('📭 托管队列为空，无需处理');
        return;
    }

    autoHostingRunning = true;
    console.log(`🤖 自动托管开始，队列中有 ${autoHostingQueue.length} 个任务`);

    while (autoHostingQueue.length > 0 && autoHostingMode) {
        const idea = autoHostingQueue[0]; // 取第一个任务

        // 检查配额
        if (!checkQuota(1)) {
            console.warn('⚠️ 配额不足，自动托管暂停');
            alert('⚠️ 配额不足，自动托管已暂停。请分享获取额外额度或升级会员后，手动重新启动托管模式。');
            autoHostingMode = false;
            localStorage.setItem('auto_hosting_enabled', 'false');
            break;
        }

        // 检查任务状态
        if (idea.status === 'processing' || idea.status === 'completed') {
            // 任务已在处理或已完成，跳过
            autoHostingQueue.shift();
            continue;
        }

        // 处理任务
        console.log(`🎬 自动托管处理: ${idea.theme || idea.id}`);
        try {
            await processIdea(idea);
            console.log(`✅ 任务完成: ${idea.theme || idea.id}`);
            // 🔓 不再限制全自动次数，仅用胶片消耗控制
        } catch (error) {
            console.error(`❌ 任务失败: ${idea.theme || idea.id}`, error);
            // 失败的任务标记为失败，继续处理下一个
            if (idea.status !== 'cancelled') {
                idea.status = 'failed';
                addStepLog(idea, `❌ 任务失败: ${error.message}`, 'error');
            }
        }

        // 从队列移除已处理的任务
        autoHostingQueue.shift();

        // 保存状态
        saveIdeasToHistory();
        renderCanvas();

        // 短暂延迟，避免过快调用API
        await new Promise(resolve => setTimeout(resolve, 1000));
    }

    autoHostingRunning = false;
    console.log('🤖 自动托管结束');

    // 如果队列还有任务且托管模式仍启用，继续处理
    if (autoHostingQueue.length > 0 && autoHostingMode) {
        setTimeout(() => startAutoHosting(), 2000);
    }
}

/**
 * 批量添加任务到托管队列
 * @param {Array} ideas - 任务数组
 */
function batchAddToAutoHosting(ideas) {
    ideas.forEach(idea => addToAutoHostingQueue(idea));
    console.log(`📥 批量添加 ${ideas.length} 个任务到托管队列`);
}

/**
 * 获取托管队列状态
 */
function getAutoHostingStatus() {
    return {
        enabled: autoHostingMode,
        running: autoHostingRunning,
        queueLength: autoHostingQueue.length,
        queue: autoHostingQueue.map(i => ({
            id: i.id,
            theme: i.theme,
            status: i.status
        }))
    };
}

/**
 * 设置自动托管模式（从设置面板调用）
 * @param {boolean} enabled - 是否启用
 */
window.toggleAutoHostingMode = function (enabled) {
    // 🔓 全自动模式对所有用户开放，仅用胶片控制
    // 免费用户只要有胶片就可以使用，不再限制次数

    autoHostingMode = enabled;
    console.log(`🤖 自动托管模式: ${autoHostingMode ? '已启用' : '已禁用'}`);

    // 保存到localStorage
    localStorage.setItem('autoHostingEnabled', enabled ? '1' : '0');

    if (autoHostingMode && autoHostingQueue.length > 0) {
        checkAndStartAutoHosting();
    }

    // 🔧 静默启用，不显示提示
    if (enabled) {
        console.log('🤖 全自动托管模式已启用');
    }
};

// 暴露给window，方便调试和外部调用
window.toggleAutoHosting = toggleAutoHosting;
window.addToAutoHostingQueue = addToAutoHostingQueue;
window.removeFromAutoHostingQueue = removeFromAutoHostingQueue;
window.startAutoHosting = startAutoHosting;
window.batchAddToAutoHosting = batchAddToAutoHosting;
window.getAutoHostingStatus = getAutoHostingStatus;

