const FILM_UNIT_PRICE = 0.3;

/**
 * 📊 真实API成本（官方1折，仅用于成本追踪，不对外显示）
 */
const REAL_API_COSTS = {
    gemini3: 0.026,    // ¥0.026/次
    banana2: 0.17,     // ¥0.17/张
    seedream: 0.22,    // ¥0.22/张（豆包 doubao-seedream-4-5-251128）
    jimeng: 0.18,      // ¥0.18/张（即梦4.5）
    sora2: 1.08,       // ¥1.08/15秒
};

/**
 * 📈 记录API调用成本到数据库（管理员可见）
 * @param {Object} params - 参数
 * @param {string} params.apiType - API类型：gemini3, banana2, sora2
 * @param {string} params.action - 具体操作：text_story, image_character等
 * @param {number} params.count - 调用次数
 * @param {number} params.filmConsumed - 消耗胶片数
 * @param {string} params.taskId - 任务ID
 * @param {boolean} params.success - 是否成功
 * @param {string} params.errorMessage - 错误信息
 * @param {number} params.responseTime - 响应时间(ms)
 */
async function trackApiCost(params) {
    const {
        apiType,
        action = '',
        count = 1,
        filmConsumed = 0,
        taskId = '',
        success = true,
        errorMessage = '',
        responseTime = 0
    } = params;

    // 计算实际成本
    const actualCost = (REAL_API_COSTS[apiType] || 0) * count;
    // 计算预估收入
    const revenue = filmConsumed * FILM_UNIT_PRICE;

    // 本地缓存（用于离线或数据库不可用时）
    const localLog = {
        time: new Date().toISOString(),
        apiType,
        action,
        count,
        actualCost,
        filmConsumed,
        revenue,
        profit: revenue - actualCost,
        taskId,
        success,
        errorMessage,
        responseTime
    };

    // 存入localStorage备份
    const localLogs = JSON.parse(localStorage.getItem('api_cost_logs') || '[]');
    localLogs.push(localLog);
    // 只保留最近1000条
    if (localLogs.length > 1000) localLogs.shift();
    localStorage.setItem('api_cost_logs', JSON.stringify(localLogs));

    // 尝试写入数据库（优先NVAuth，降级supabase）
    try {
        let client = null;
        let userId = null;

        // 方式1: NVAuth
        if (typeof NVAuth !== 'undefined') {
            client = NVAuth.getSupabase();
            const user = await NVAuth.getCurrentUser();
            userId = user?.id || null;
        }

        // 方式2: 全局supabase
        if (!client && typeof supabase !== 'undefined') {
            client = supabase;
            const { data: { user } } = await supabase.auth.getUser();
            userId = user?.id || null;
        }

        if (client) {
            const { error } = await client.from('api_cost_logs').insert({
                user_id: userId,
                api_type: apiType,
                api_action: action,
                call_count: count,
                actual_cost: actualCost,
                film_consumed: filmConsumed,
                revenue: revenue,
                task_id: taskId || null,
                success: success,
                error_message: errorMessage || null,
                response_time_ms: responseTime || 0
            });

            if (error) {
                console.warn('📊 成本追踪写入失败:', error.message);
            } else {
                console.log(`📊 [成本追踪] ${apiType} × ${count} = ¥${actualCost.toFixed(3)} 已记录到数据库`);
            }
        } else {
            console.warn('📊 成本追踪：无可用的数据库连接，仅本地保存');
        }
    } catch (e) {
        // 数据库写入失败，本地已有备份
        console.warn('📊 成本追踪异常:', e.message);
    }

    return localLog;
}

/**
 * 📊 获取成本统计摘要（管理员用）
 */
async function getCostSummary() {
    try {
        if (typeof NVAuth !== 'undefined') {
            const client = NVAuth.getSupabase();
            if (client) {
                const { data, error } = await client
                    .from('cost_summary')
                    .select('*')
                    .order('date', { ascending: false })
                    .limit(30);

                if (!error && data) {
                    return data;
                }
            }
        }
    } catch (e) {
        console.warn('获取成本摘要失败:', e.message);
    }

    // 降级：从本地获取
    const localLogs = JSON.parse(localStorage.getItem('api_cost_logs') || '[]');
    return localLogs;
}

