/**
 * 🔐 生成设备指纹（软件级，用于防刷）
 * @returns {string} 64位哈希指纹
 */
function generateDeviceFingerprint() {
    const components = [
        navigator.userAgent,
        navigator.language,
        screen.width + 'x' + screen.height,
        screen.colorDepth,
        new Date().getTimezoneOffset(),
        navigator.hardwareConcurrency || 'unknown',
        navigator.platform,
        // Canvas指纹（简化版）
        (() => {
            try {
                const canvas = document.createElement('canvas');
                const ctx = canvas.getContext('2d');
                ctx.textBaseline = 'top';
                ctx.font = '14px Arial';
                ctx.fillText('RollRoll', 2, 2);
                return canvas.toDataURL().slice(-50);
            } catch (e) {
                return 'canvas-error';
            }
        })()
    ];

    // 简单哈希
    const str = components.join('|');
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        const char = str.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash = hash & hash;
    }

    // 转为64位十六进制
    const hash1 = Math.abs(hash).toString(16).padStart(8, '0');
    const hash2 = Math.abs(hash * 31).toString(16).padStart(8, '0');
    const hash3 = Math.abs(hash * 17).toString(16).padStart(8, '0');
    const hash4 = Math.abs(hash * 13).toString(16).padStart(8, '0');

    return (hash1 + hash2 + hash3 + hash4).substring(0, 64);
}

/**
 * 🔐 检查用户是否有首次全自动体验资格
 * @returns {Promise<{eligible: boolean, reason: string, message: string}>}
 */
async function checkFirstAutoEligibility() {
    if (!FIRST_AUTO_CONFIG.enabled) {
        return { eligible: false, reason: 'disabled', message: '首次体验功能已关闭' };
    }

    // 付费用户不需要首次体验（直接有全自动权限）
    if (isPaidUser()) {
        return { eligible: false, reason: 'paid_user', message: '付费用户已有全自动权限' };
    }

    try {
        if (typeof NVAuth === 'undefined') {
            return { eligible: false, reason: 'no_auth', message: '请先登录' };
        }

        const user = await NVAuth.getCurrentUser();
        if (!user) {
            return { eligible: false, reason: 'not_logged_in', message: '请先登录' };
        }

        const fingerprint = generateDeviceFingerprint();
        const client = NVAuth.getSupabase();

        if (!client) {
            // 降级：使用本地存储检查
            const localUsed = localStorage.getItem('first_auto_used');
            if (localUsed === 'true') {
                return { eligible: false, reason: 'already_used', message: '您已使用过首次全自动体验' };
            }
            return { eligible: true, reason: 'ok', message: '可以使用首次体验（本地模式）' };
        }

        // 调用云端函数检查
        const { data, error } = await client.rpc('check_first_auto_eligibility', {
            p_user_id: user.id,
            p_device_fingerprint: fingerprint
        });

        if (error) {
            console.warn('首次体验检查失败，使用本地模式:', error);
            const localUsed = localStorage.getItem('first_auto_used');
            if (localUsed === 'true') {
                return { eligible: false, reason: 'already_used', message: '您已使用过首次全自动体验' };
            }
            return { eligible: true, reason: 'ok', message: '可以使用首次体验' };
        }

        return data;
    } catch (e) {
        console.error('首次体验检查异常:', e);
        // 降级到本地检查
        const localUsed = localStorage.getItem('first_auto_used');
        if (localUsed === 'true') {
            return { eligible: false, reason: 'already_used', message: '您已使用过首次全自动体验' };
        }
        return { eligible: true, reason: 'ok', message: '可以使用首次体验' };
    }
}

/**
 * 🔐 标记首次全自动体验已使用
 * @param {boolean} success - 是否成功完成
 * @returns {Promise<boolean>}
 */
async function markFirstAutoUsed(success = true) {
    // 只有成功时才标记
    if (!success) {
        console.log('💡 生成失败，保留首次体验重试机会');
        return false;
    }

    // 本地标记
    localStorage.setItem('first_auto_used', 'true');
    localStorage.setItem('first_auto_used_at', new Date().toISOString());

    try {
        if (typeof NVAuth === 'undefined') return true;

        const user = await NVAuth.getCurrentUser();
        if (!user) return true;

        const fingerprint = generateDeviceFingerprint();
        const client = NVAuth.getSupabase();

        if (!client) return true;

        // 调用云端函数标记
        const { error } = await client.rpc('mark_first_auto_used', {
            p_user_id: user.id,
            p_device_fingerprint: fingerprint,
            p_success: success
        });

        if (error) {
            console.warn('云端标记失败:', error);
        } else {
            console.log('✅ 首次体验已标记完成（云端+本地）');
        }

        return true;
    } catch (e) {
        console.error('标记首次体验异常:', e);
        return true; // 本地已标记，返回成功
    }
}

