/**
 * 📅 检查每日免费额度
 * @param {string} type - 'text' | 'image'
 * @returns {{remaining: number, used: number, limit: number}}
 */
function getDailyFreeQuota(type) {
    const today = new Date().toDateString();
    const storageKey = `daily_free_${type}_${today}`;
    const used = parseInt(localStorage.getItem(storageKey) || '0');

    const limit = type === 'text'
        ? NEW_USER_EXPERIENCE.daily_free.text_calls
        : NEW_USER_EXPERIENCE.daily_free.image_calls;

    return {
        remaining: Math.max(0, limit - used),
        used: used,
        limit: limit
    };
}

/**
 * 📅 消耗每日免费额度
 * @param {string} type - 'text' | 'image'
 * @returns {boolean} 是否成功消耗
 */
function consumeDailyFreeQuota(type) {
    const quota = getDailyFreeQuota(type);
    if (quota.remaining <= 0) {
        return false;
    }

    const today = new Date().toDateString();
    const storageKey = `daily_free_${type}_${today}`;
    localStorage.setItem(storageKey, String(quota.used + 1));

    console.log(`📅 消耗每日${type === 'text' ? '文本' : '图片'}免费额度: ${quota.used + 1}/${quota.limit}`);
    return true;
}

