/**
 * 🚀 开始首次全自动体验
 */
async function startFirstAutoExperience() {
    // 再次检查资格
    const eligibility = await checkFirstAutoEligibility();
    if (!eligibility.eligible) {
        alert(`❌ ${eligibility.message}`);
        return;
    }

    // 获取用户输入
    const input = document.getElementById('quickIdeaInput');
    const theme = input?.value?.trim();

    if (!theme || theme.length < 5) {
        alert('📝 请先在输入框中描述您想要创作的视频主题\n\n例如：一只可爱的小猫在花园里玩耍');
        input?.focus();
        return;
    }

    // 创建首次体验任务
    const pos = calculateNewTaskPosition();
    const idea = {
        id: Date.now(),
        theme: theme,
        status: 'pending',
        automationLevel: 'full-auto',
        scenes: FIRST_AUTO_CONFIG.max_scenes,
        clipDuration: FIRST_AUTO_CONFIG.scene_duration,
        _isFirstAutoExperience: true,  // 标记为首次体验
        _firstAutoConfig: { ...FIRST_AUTO_CONFIG },  // 保存配置
        generatedScript: '',
        characterSheets: [],
        normalStoryboards: [],
        generatedVideoPrompts: [],
        videoResults: [],
        createdAt: new Date().toISOString(),
        x: pos.x,
        y: pos.y
    };
    // 🎨 初始化 settings，从全局设置读取角色设定图开关
    idea.settings = {
        automationLevel: 'full-auto',
        enableCharSheet: loadSettings().characterSheetEnabled !== false
    };

    ideas.push(idea);
    saveIdeasToHistory();
    renderIdeasList();
    renderCanvas();

    // 清空输入框
    if (input) input.value = '';

    // 开始处理
    console.log('🎬 开始首次全自动体验:', idea.id);
    await processIdea(idea);
}

window.startFirstAutoExperience = startFirstAutoExperience;
