/**
 * 🔍 检查用户是否为付费用户
 * 付费用户 = 有胶片余额 或 VIP会员
 */
function isPaidUser() {
    // 🔧 检查胶片余额（使用正确的键）
    const filmBalance = parseFloat(localStorage.getItem('film_balance') || '0');

    // 🔧 优先检查云端同步的会员类型
    const memberType = localStorage.getItem('membership_type');
    if (memberType && memberType !== 'free') {
        return true;
    }

    // 🔧 兼容旧的vip_info格式
    const vipInfo = localStorage.getItem('vip_info');
    if (vipInfo) {
        try {
            const parsed = JSON.parse(vipInfo);
            if (parsed.expiry && new Date(parsed.expiry) > new Date()) {
                return true;
            }
        } catch (e) {
            // 兼容旧的字符串格式
            if (vipInfo.includes('pro') || vipInfo.includes('mid') || vipInfo.includes('basic') || vipInfo.includes('vip')) {
                return true;
            }
        }
    }

    return filmBalance > 0;
}

/**
 * 🎖️ 获取会员折扣比例（方案B）
 * @returns {number} 折扣比例 (0.85 = 85折, 1.0 = 无折扣)
 */
function getMemberDiscount() {
    const userLevel = window.currentUserLevel || 'free';
    // 优先从 MEMBER_PLANS 获取折扣
    const plan = MEMBER_PLANS[userLevel];
    if (plan && plan.discount) {
        return plan.discount;
    }
    // 兼容旧版本
    const discountMap = {
        'studio': 0.85,   // 85折
        'pro': 0.90,      // 9折
        'creator': 0.95,  // 95折
        'mid': 0.90,      // 9折（旧版兼容）
        'basic': 0.95,    // 95折（旧版兼容）
        'free': 1.0       // 无折扣
    };
    return discountMap[userLevel] || 1.0;
}

/**
 * 🎬 计算实际胶片消费（应用会员折扣）
 * @param {number} baseFilm - 基础胶片消费
 * @returns {number} 折扣后的胶片消费
 */
function calculateFilmCost(baseFilm) {
    const discount = getMemberDiscount();
    const actualCost = Math.ceil(baseFilm * discount); // 向上取整
    return Math.max(1, actualCost); // 最少消费1胶片
}

