/**
 * 🎞️ 计算视频胶片消耗（按时长）
 * @param {number} durationSeconds - 视频时长（秒）
 * @returns {number} 消耗胶片数
 */
function calculateVideoCost(durationSeconds) {
    return __estimateSoraVideoFilmCost('sora-2', durationSeconds, false);
}

/**
 * 🧮 智能计算任务胶片消耗
 * @param {object} task - 任务对象或配置
 * @returns {object} { total, breakdown, formula }
 */
function calculateTaskCost(task = {}) {
    // 从任务中提取信息
    const type = task.type || 'video';
    const scenes = task.scenes || task.normalStoryboards?.length || 5;
    const characters = task.characters?.length || task.characterSheets?.length || 2;
    const hasMotion = task.includeMotion !== false;
    const motionCount = Math.min(characters, 4); // 动效最多4个角色

    let breakdown = {};
    let total = 0;

    if (type === 'video') {
        // ========== 视频任务 ==========
        // 基础文本（固定）
        breakdown.storyAnalysis = { label: '故事分析', count: 1, unit: 1.69, cost: 1.69 };
        breakdown.characterDesign = { label: '角色设定', count: 1, unit: 1.69, cost: 1.69 };
        breakdown.sceneGeneration = { label: '分镜生成', count: 1, unit: 1.69, cost: 1.69 };

        // 角色图（2张）
        breakdown.characterImages = { label: '角色设计图', count: 2, unit: 4.5, cost: 9 };

        // 分镜相关（按分镜数）
        breakdown.scenePrompts = { label: '分镜提示词', count: scenes, unit: 1.69, cost: Math.round(scenes * 1.69 * 100) / 100 };
        breakdown.sceneImages = { label: '分镜图片', count: scenes, unit: 4.5, cost: scenes * 4.5 };
        breakdown.sceneVideos = { label: '分镜视频', count: scenes, unit: 5, cost: scenes * 5 };

        // 角色动效（可选）
        if (hasMotion && motionCount > 0) {
            breakdown.characterMotion = { label: '角色动效', count: motionCount, unit: 5, cost: motionCount * 5 };
        }

    } else if (type === 'comic') {
        // ========== 漫画任务 ==========
        const pages = task.pages || task.comicPages?.length || scenes;

        breakdown.storyAnalysis = { label: '故事分析', count: 1, unit: 1.69, cost: 1.69 };
        breakdown.characterDesign = { label: '角色设定', count: 1, unit: 1.69, cost: 1.69 };
        breakdown.panelPlanning = { label: '分镜规划', count: 1, unit: 1.69, cost: 1.69 };
        breakdown.characterImages = { label: '角色设计图', count: 2, unit: 4.5, cost: 9 };
        breakdown.comicPages = { label: '漫画页', count: pages, unit: 4.5, cost: pages * 4.5 };
    }

    // 计算总和
    total = Object.values(breakdown).reduce((sum, item) => sum + item.cost, 0);
    total = Math.round(total * 100) / 100; // 保留2位小数

    // 生成公式说明
    const formula = type === 'video'
        ? `基础(14) + 分镜×11.2 + 动效×5 ≈ ${total}`
        : `基础(14) + 页数×4.5 ≈ ${total}`;

    return {
        total,
        breakdown,
        formula,
        type,
        scenes,
        characters,
        hasMotion
    };
}

/**
 * 🏷️ 获取任务消耗标签（用于卡片显示）
 * @param {object} task - 任务对象
 * @returns {string} HTML标签
 */
function getTaskCostLabel(task) {
    const cost = calculateTaskCost(task);
    const filmBalance = getFilmBalance();
    const canAfford = filmBalance >= cost.total;

    const color = canAfford ? '#4ade80' : '#ef4444';
    const icon = task.type === 'comic' ? '📖' : '🎬';
    const countLabel = task.type === 'comic'
        ? `${cost.scenes}页`
        : `${cost.scenes}镜${cost.hasMotion ? '+动效' : ''}`;

    return `<span style="color:${color}; font-size:11px;" title="${cost.formula}">
        ${icon} ${countLabel} ≈ <b>${cost.total}</b>胶片
    </span>`;
}

/**
 * 🎞️ 计算任务胶片消耗（旧版兼容）
 */
function estimateTaskCost(taskConfig = {}) {
    const result = calculateTaskCost(taskConfig);
    return result.total;
}

