/**
 * 🎞️ 实时计费 - 每次API调用成功后立即扣费
 * @param {string} type - 消耗类型
 * @param {number} count - 数量（默认1）
 * @param {boolean} skipFreeUser - 是否跳过免费用户扣费（免费API不扣费）
 * @returns {object} { cost, success, message }
 */
async function consumeRealtime(type, count = 1, skipFreeUser = false) {
    // 获取消耗成本
    const costMap = {
        'text': QUOTA_COSTS.text_generation,
        'text_gemini3': QUOTA_COSTS.text_gemini3,
        'image': QUOTA_COSTS.image_generation,
        'image_2k': QUOTA_COSTS.image_2k,
        'image_4k': QUOTA_COSTS.image_4k,
        'image_qwen_max': QUOTA_COSTS.image_qwen_max,
        'video': QUOTA_COSTS.video_sora2_15s,
        'video_15s': QUOTA_COSTS.video_sora2_15s,
        'video_pro': QUOTA_COSTS.video_sora2_pro_15s,
        'character_image': QUOTA_COSTS.character_image,
        'character_motion': QUOTA_COSTS.character_motion,
        'character_motion_extra': 1,  // 角色动效额外费用（线稿转换成本分摊）
        'comic_text': QUOTA_COSTS.comic_text,
        'comic_page': QUOTA_COSTS.comic_page_hd,
        'comic_character': QUOTA_COSTS.comic_character,
    };

    const baseCost = (costMap[type] || 0) * count;

    // 免费操作不扣费
    if (baseCost === 0) {
        console.log(`✅ [实时计费] ${type} × ${count} = 免费`);
        return { cost: 0, success: true, message: '免费' };
    }

    // 免费用户使用免费API不扣费
    if (skipFreeUser && !isPaidUser()) {
        console.log(`✅ [实时计费] ${type} × ${count} = 免费用户免费`);
        return { cost: 0, success: true, message: '免费用户' };
    }

    // 应用会员折扣
    const discount = 1.0;
    const actualCost = Math.round(baseCost * discount * 100) / 100; // 保留2位小数

    // 🔧 直接在云端扣费（云端是权威数据源）
    const result = await consumeFilmFromCloud(actualCost);

    if (result.success) {
        const levelInfo = getMemberLevelInfo();
        const discountText = discount < 1 ? ` (${levelInfo.discount})` : '';
        console.log(`🎞️ [实时计费] ${type} × ${count} = -${actualCost}胶片${discountText} [余额: ${result.newBalance}]`);

        // 🔧 追踪到当前任务
        if (_currentExecutingIdea && typeof _currentExecutingIdea.filmConsumed === 'number') {
            _currentExecutingIdea.filmConsumed += actualCost;
            console.log(`📊 任务累计消耗: ${_currentExecutingIdea.filmConsumed}胶片`);
        }

        updateUsageDisplay();
    } else {
        console.error(`❌ [实时计费失败] ${result.message}`);
        // 🔧 扣费失败时不静默，需要让调用方知道
    }

    return { cost: actualCost, success: result.success, message: result.message, newBalance: result.newBalance };
}

/**
 * 🎞️ 直接在云端执行扣费（云端必须成功才算成功）
 * 🔧 增加重试机制，确保扣费成功
 * @param {number} amount - 扣除数量
 * @returns {Promise<{success: boolean, newBalance: number, message: string}>}
 */
async function consumeFilmFromCloud(amount) {
    // 检查登录状态
    if (typeof NVAuth === 'undefined') {
        console.error('❌ 扣费失败: NVAuth未定义');
        return { success: false, newBalance: 0, message: '系统未初始化' };
    }

    const user = await NVAuth.getCurrentUser();

    if (!user) {
        console.error('❌ 扣费失败: 用户未登录');
        return { success: false, newBalance: 0, message: '请先登录' };
    }

    // 🔧 重试机制：最多重试3次
    const maxRetries = 3;
    let lastError = null;

    for (let attempt = 1; attempt <= maxRetries; attempt++) {
        try {
            console.log(`☁️ 云端扣费尝试 ${attempt}/${maxRetries}: -${amount}胶片`);

            // 🔧 通过服务端代理扣费（绕过CORS和RLS）
            const response = await fetch('/api/supabase-proxy', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    action: 'consume',
                    userId: user.id,
                    amount: amount,
                    description: '任务消耗'
                })
            });

            const data = await response.json().catch(() => ({}));

            // 🔧 修复：正确处理 HTTP 状态码和响应数据
            if (!response.ok) {
                lastError = data.message || data.error || `服务器错误: ${response.status}`;
                console.warn(`⚠️ 扣费尝试 ${attempt} 失败:`, lastError);

                // 余额不足不需要重试
                if (response.status === 400 && data.error === 'INSUFFICIENT_BALANCE') {
                    return { success: false, newBalance: data.quotaBalance || 0, message: '余额不足' };
                }

                if (attempt < maxRetries) {
                    await new Promise(r => setTimeout(r, 1000 * attempt)); // 递增延迟
                    continue;
                }
                return { success: false, newBalance: data.newBalance || 0, message: lastError };
            }

            // 🔧 修复：兼容多种成功响应格式
            if (!data.success && data.newBalance === undefined) {
                lastError = data.message || data.error || '扣费失败';
                console.warn(`⚠️ 扣费尝试 ${attempt} 失败:`, lastError);

                if (attempt < maxRetries) {
                    await new Promise(r => setTimeout(r, 1000 * attempt));
                    continue;
                }
                return { success: false, newBalance: data.newBalance || 0, message: lastError };
            }

            // ✅ 云端成功后，同步到本地缓存
            localStorage.setItem('film_balance', String(data.newBalance));
            localStorage.setItem('cloud_film_balance', String(data.newBalance));
            // 🔧 同步已用额度
            if (data.newUsed !== undefined) {
                localStorage.setItem('quota_used', String(data.newUsed));
            }
            // 🔧 同步会员类型
            if (data.membershipType) {
                localStorage.setItem('membership_type', data.membershipType);
            }

            // 更新UI显示
            updateUsageDisplay();

            console.log(`✅ 云端扣费成功: -${amount} → 新余额: ${data.newBalance}, 已用: ${data.newUsed || 0}`);
            return { success: true, newBalance: data.newBalance, message: `扣除${amount}胶片` };

        } catch (e) {
            lastError = e.message;
            console.error(`❌ 扣费尝试 ${attempt} 异常:`, e);

            if (attempt < maxRetries) {
                await new Promise(r => setTimeout(r, 1000 * attempt));
                continue;
            }
        }
    }

    console.error(`❌ 云端扣费最终失败（重试${maxRetries}次）:`, lastError);
    return { success: false, newBalance: 0, message: '扣费异常: ' + lastError };
}

/**
 * 🎞️ 直接在云端执行充值（云端必须成功才算成功）
 * @param {number} amount - 充值数量
 * @returns {Promise<number>} 充值后的新余额
 * @throws {Error} 云端操作失败时抛出错误
 */
async function rechargeFilmToCloud(amount) {
    console.log('🔄 开始云端充值流程（服务端代理）...');

    // 获取用户ID
    let userId;
    try {
        if (typeof NVAuth !== 'undefined') {
            const user = await NVAuth.getCurrentUser();
            userId = user?.id;
        }
    } catch (e) {
        console.error('❌ 获取用户失败:', e);
    }

    if (!userId) {
        throw new Error('请先登录后再充值');
    }

    console.log('✅ 用户验证通过:', userId.substring(0, 8) + '...');

    // 🔧 通过服务端代理执行充值（绑过 CORS）
    try {
        const response = await fetch('/api/supabase-proxy', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'recharge',
                userId: userId,
                amount: amount,
                description: '激活码充值'
            })
        });

        const data = await response.json();

        if (!response.ok || !data.success) {
            console.error('❌ 服务端充值失败:', data);
            throw new Error(data.message || '充值失败');
        }

        const newBalance = data.newBalance;

        // 同步到本地缓存
        localStorage.setItem('film_balance', String(newBalance));
        localStorage.setItem('cloud_film_balance', String(newBalance));

        console.log(`✅ 云端充值成功: +${amount} → 新余额: ${newBalance}`);
        return newBalance;

    } catch (e) {
        console.error('❌ 充值请求失败:', e);
        if (e.message.includes('fetch') || e.message.includes('network')) {
            throw new Error('网络连接失败，请检查网络后重试');
        }
        throw e;
    }
}

/**
 * 🔄 同步胶片余额到云端（强化版 - 即时同步）
 */
async function syncFilmToCloud(balance) {
    try {
        // 优先使用 NVAuth
        if (typeof NVAuth !== 'undefined') {
            const client = NVAuth.getSupabase();
            const user = await NVAuth.getCurrentUser();
            if (client && user) {
                const { error } = await client
                    .from('user_profiles')
                    .update({ quota_balance: Math.round(balance * 100) / 100 })
                    .eq('id', user.id);

                if (error) {
                    console.error('☁️ 云端同步失败:', error.message);
                } else {
                    console.log(`☁️ 云端同步成功: ${balance}胶片`);
                }
                return;
            }
        }

        // 降级：使用全局supabase
        if (typeof supabase !== 'undefined') {
            const { data: { user } } = await supabase.auth.getUser();
            if (user) {
                await supabase
                    .from('user_profiles')
                    .update({ quota_balance: Math.round(balance * 100) / 100 })
                    .eq('id', user.id);
                console.log(`☁️ 云端同步成功(降级): ${balance}胶片`);
            }
        }
    } catch (e) {
        console.error('☁️ 云端同步异常:', e.message);
    }
}

