function getUsageStats() {
    const today = new Date().toISOString().split('T')[0];
    const lastDate = localStorage.getItem('usage_date');
    if (lastDate !== today) {
        localStorage.setItem('usage_date', today);
        localStorage.setItem('usage_count', '0');
    }

    const usageCount = parseInt(localStorage.getItem('usage_count') || '0', 10);

    // 优先使用云端同步的 membership_type
    const memberType = localStorage.getItem('membership_type');
    let vipType = 'free';
    if (memberType && memberType !== 'free') {
        vipType = memberType;
    } else {
        // 兼容旧 vip_info
        let vipInfo = {};
        try {
            vipInfo = JSON.parse(localStorage.getItem('vip_info') || '{}');
        } catch (_) {
            vipInfo = {};
        }
        if (vipInfo.expiry && new Date(vipInfo.expiry) > new Date()) {
            vipType = vipInfo.type || 'basic';
        }
    }

    const plan = MEMBER_PLANS[vipType] || MEMBER_PLANS.free;
    const limit = plan.dailyLimit;
    const remaining = (limit === Infinity) ? Infinity : Math.max(0, (limit || 0) - usageCount);

    return {
        count: usageCount,
        limit,
        remaining,
        plan
    };
}

function checkQuota(count = 1) {
    // 付费用户：不走“次数制”，走胶片扣费（由 consumeRealtime 兜底）
    if (typeof isPaidUser === 'function' && isPaidUser()) return true;

    const stats = getUsageStats();
    if (stats.limit === Infinity) return true;

    if (stats.remaining < count) {
        alert(`⚠️ 今日免费额度不足

剩余：${stats.remaining}次
需要：${count}次

🎬 充值胶片可解锁无限使用`);
        return false;
    }

    const next = Math.max(0, stats.count + count);
    localStorage.setItem('usage_count', String(next));
    return true;
}

function refundQuota(count = 1) {
    try {
        const used = parseInt(localStorage.getItem('usage_count') || '0', 10);
        const next = Math.max(0, used - (parseInt(count, 10) || 0));
        localStorage.setItem('usage_count', String(next));
        return true;
    } catch (_) {
        return false;
    }
}

/**
 * 🔄 轮询Sora2任务状态（健壮版）
 * 兼容多种状态和URL提取格式
 * @param {string} taskId - 任务ID
 * @param {object} options - 可选参数 { _source, _endpoint } 用于指定API来源
 */
async function pollSora2Task(taskId, options = {}) {
    const maxAttempts = 300; // 最多轮询300次（约15分钟）- Sora2高峰期可能需要更长时间
    const { _source, _endpoint } = options;

    // 🔧 2026-02-17 优化：记录连续失败次数，避免单次失败就放弃
    let consecutiveFailures = 0;
    const MAX_CONSECUTIVE_FAILURES = 10; // 连续10次失败才考虑放弃

    for (let i = 0; i < maxAttempts; i++) {
        await sleep(3000); // 每3秒轮询一次

        try {
            // 🔐 使用服务器端代理轮询（传递来源信息以使用正确的API路径）
            const res = await fetch('/api/sora2', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    action: 'poll',
                    task_id: taskId,
                    _source,    // 🆕 来源：yunwu 或 zhenzhen
                    _endpoint   // 🆕 云雾节点地址
                })
            });

            if (!res.ok) {
                console.warn(`⚠️ 轮询请求失败: ${res.status} (${i + 1}/${maxAttempts})`);
                consecutiveFailures++;

                // 🔧 只有连续失败超过阈值才继续
                if (consecutiveFailures >= MAX_CONSECUTIVE_FAILURES) {
                    console.error(`❌ 轮询连续失败${consecutiveFailures}次，但仍然继续等待...`);
                    // 不抛出错误，继续等待，可能后端只是暂时不可用
                }
                continue;
            }

            // 轮询成功，重置连续失败计数
            consecutiveFailures = 0;

            const data = await res.json();

            // 🔧 健壮的状态检查（兼容多种格式）
            const status = (data.status || data.state || data.task_status || '').toUpperCase();

            // ✅ 成功状态
            if (status === 'SUCCESS' || status === 'COMPLETED' || status === 'DONE') {
                console.log(`✅ Sora2任务完成: ${taskId}`);

                // 🔧 健壮的URL提取（尝试多种路径）
                const videoUrl =
                    data.video_url ||
                    data.videoUrl ||
                    data.url ||
                    data.data?.output ||
                    data.data?.video_url ||
                    data.data?.url ||
                    (Array.isArray(data.data) && data.data[0]?.url) ||
                    (Array.isArray(data.data) && data.data[0]?.video_url) ||
                    data.result?.url ||
                    data.result?.video_url;

                if (videoUrl) {
                    return videoUrl;
                } else {
                    console.error('❌ 任务完成但未找到视频URL:', data);
                    throw new Error('任务完成但未找到视频URL');
                }
            }

            // ❌ 失败状态（兼容更多格式）
            if (status === 'FAILURE' || status === 'FAILED' || status === 'ERROR' || status === 'FAIL' || status === 'CANCELLED' || status === 'CANCELED') {
                // 🔧 2026-02-17 优化：即使状态显示失败，也要检查是否有视频URL！
                // 有时候上游会返回失败状态但实际有视频
                const videoUrl =
                    data.video_url ||
                    data.videoUrl ||
                    data.url ||
                    data.data?.output ||
                    data.data?.video_url ||
                    data.data?.url ||
                    data.result?.url ||
                    data.result?.video_url;

                if (videoUrl) {
                    console.warn(`⚠️ 任务状态显示${status}，但发现视频URL，视为成功:`, videoUrl);
                    return videoUrl;
                }

                const errorMsg = data.fail_reason || data.error || data.message || data.error_message || data.detail || '未知错误';
                console.error(`❌ Sora2任务失败: ${errorMsg}`, data);
                throw new Error(`视频生成失败: ${errorMsg}`);
            }

            // 🔧 检查data内部的失败状态
            if (data.data?.status && ['FAILURE', 'FAILED', 'ERROR', 'FAIL'].includes(String(data.data.status).toUpperCase())) {
                // 同样检查是否有视频URL
                const videoUrl = data.data?.video_url || data.data?.url;
                if (videoUrl) {
                    console.warn(`⚠️ 任务内部状态显示失败，但发现视频URL，视为成功:`, videoUrl);
                    return videoUrl;
                }

                const errorMsg = data.data.fail_reason || data.data.error || data.data.message || '任务执行失败';
                console.error(`❌ Sora2任务内部失败: ${errorMsg}`, data);
                throw new Error(`视频生成失败: ${errorMsg}`);
            }

            // ⏳ 进行中（避免刷屏：每10次打印一次）
            if (i === 0 || ((i + 1) % 10 === 0)) {
                console.log(`⏳ Sora2任务进行中... (${i + 1}/${maxAttempts}), status=${status}`);
            }

        } catch (pollError) {
            consecutiveFailures++;

            // 🔧 只有明确的"视频生成失败"错误才抛出
            if (pollError.message && pollError.message.includes('视频生成失败')) {
                throw pollError; // 重新抛出失败错误
            }

            console.warn(`⚠️ 轮询异常: ${pollError.message} (连续失败:${consecutiveFailures}/${MAX_CONSECUTIVE_FAILURES})`);

            // 🔧 连续失败过多时，给用户一个提示，但不要直接放弃
            if (consecutiveFailures >= MAX_CONSECUTIVE_FAILURES && (i + 1) % 20 === 0) {
                console.warn(`⚠️ 轮询已连续失败${consecutiveFailures}次，但继续等待...`);
            }
        }
    }

    throw new Error('视频生成超时（已等待15分钟），服务器可能繁忙，请稍后重试');
}

// ==================== Sora Characters（无需 PID 的自动锁角色） ====================
/**
 * 🧬 从视频URL创建Sora角色
 * @param {string} videoUrl - 包含角色的视频URL
 * @param {Object} options - 配置选项
 * @param {string} options.timestamps - 时间戳范围，如 '1,3'（1-3秒）
 * @param {string} options.from_task - 可选，使用任务ID替代URL
 * @returns {Promise<Object>} - 角色信息 { id, username, permalink, profile_picture_url, ... }
 */
async function createSoraCharacterFromVideoUrl(videoUrl, options = {}) {
    const url = String(videoUrl || '').trim();
    const { timestamps = '1,3', from_task } = options;

    // url 和 from_task 二选一
    if (!url && !from_task) {
        throw new Error('需要提供 videoUrl 或 from_task');
    }

    // 🔐 获取用户ID（后端需要用于认证）
    const userId = await getCurrentUserId();
    if (!userId) {
        throw new Error('请先登录后再使用此功能');
    }

    const requestBody = {
        action: 'create-character',
        timestamps,
        userId
    };

    if (from_task) {
        requestBody.from_task = String(from_task);
    } else {
        requestBody.url = url;
    }

    console.log('[sora-character] 创建角色:', { hasUrl: !!url, hasTask: !!from_task, timestamps });

    const res = await fetch('/api/sora2', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(requestBody)
    });

    if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.message || `创建角色失败: ${res.status}`);
    }

    const data = await res.json();
    const ch = data?.character || data?.data?.character || data;

    // 🔧 按照 OpenAPI 规范提取字段
    const id = ch?.id || '';
    const username = ch?.username ? String(ch.username).trim() : '';
    const permalink = ch?.permalink || '';
    const profile_picture_url = ch?.profile_picture_url || '';

    if (!username) {
        throw new Error('创建角色成功但未返回 username');
    }

    console.log('[sora-character] ✅ 角色创建成功:', { id, username });

    return {
        id,
        username,
        permalink,
        profile_picture_url,
        createdAt: new Date().toISOString(),
        raw: ch
    };
}

function _pickCharactersForSoraLock(idea, maxN = 3) {
    const n = Math.min(Math.max(parseInt(maxN || 3, 10) || 3, 1), 6);
    const script = String(idea?.generatedScript || idea?.theme || '');
    const chars = (Array.isArray(idea?.characterSheets) && idea.characterSheets.length > 0)
        ? idea.characterSheets.map(c => ({ name: c?.name, summary: c?.summary, sheet: c }))
        : (Array.isArray(idea?.characterDescriptions) ? idea.characterDescriptions.map(c => ({ name: c?.name, summary: c?.summary, sheet: null })) : []);

    const bad = /系统VO|旁白|VO|系统|解说|字幕|音效/i;
    const cleaned = chars
        .map(c => ({ ...c, name: String(c?.name || '').trim(), summary: String(c?.summary || '').trim() }))
        .filter(c => c.name && !bad.test(c.name));

    const score = (name) => {
        if (!name) return 0;
        const re = new RegExp(name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
        const m = script.match(re);
        return (m ? m.length : 0);
    };

    cleaned.sort((a, b) => (score(b.name) - score(a.name)));
    return cleaned.slice(0, n);
}

function _getCharacterRefImageForSoraLock(idea, charObj) {
    const c = charObj?.sheet;
    const v = c?.variants || {};
    return v.turnaround || v.poster || c?.imageUrl || c?.standingImageUrl || '';
}

function _buildSoraLockAnchorPrompt(idea, charName, charSummary) {
    const s = idea?.settings || {};
    const videoStyle = (s.videoStyle || idea?.videoStyle || '').toString().toLowerCase();
    const styleHint = (videoStyle === 'anime')
        ? 'ANIME STYLE, 2D animation, NOT live-action, NOT photorealistic.'
        : (videoStyle === 'realistic' || videoStyle === 'cinematic')
            ? 'PHOTOREALISTIC, live-action movie quality, NOT anime, NOT cartoon.'
            : '';
    const summary = String(charSummary || '').trim();
    // 🆕 优化锚定视频提示词：确保角色清晰可见且动作自然，便于OpenAI提取角色特征
    // 根据官方文档：角色功能通过保存录制的视频作为参考点来在未来的Sora视频中插入形象
    return `${styleHint}
SINGLE CHARACTER SHOWCASE VIDEO for character registration.
Character: ${charName}${summary ? ` - ${summary}` : ''}.

SHOT REQUIREMENTS (optimized for OpenAI Character extraction):
- Clean, neutral background (solid color or simple gradient)
- Full body visible, well-lit from multiple angles
- Character stands centered, facing camera
- Slow 360-degree turntable rotation showing all angles
- Clear facial features visible during 1-3 second mark
- Natural idle animation (breathing, slight movement)
- No other characters, objects, or distractions

IMPORTANT: The 1-3 second segment will be used to create the character reference. Ensure the character's face and body are clearly visible and stable during this time.`;
}

async function ensureAutoSoraCharacterLocks(idea, promptsForGen) {
    // 🔧 修复：检查新的 enableSoraCharacterLock 选项，而不是视频模型
    // 角色设定图（Banana2）和角色锁定（Sora-2 Characters）现在是分开的功能
    const enableSoraLock = idea?.settings?.enableSoraCharacterLock === true;

    // 如果没有启用 Sora-2 角色一致性，直接返回
    if (!enableSoraLock) {
        console.log('📢 未启用 Sora-2 角色一致性，跳过角色锁定流程');
        return null;
    }

    // 检查是否有角色数据需要准备
    const hasCharacterData = (idea.characterSheets && idea.characterSheets.length > 0) ||
        (idea.characterDescriptions && idea.characterDescriptions.length > 0);
    if (!hasCharacterData) {
        console.log('⚠️ 没有角色数据，跳过角色锁定');
        return null;
    }

    if (!idea.settings) idea.settings = {};
    // 🔧 修复：只有当所有角色都有有效的username时才返回缓存，否则重新创建
    if (Array.isArray(idea.settings.soraCharacters) &&
        idea.settings.soraCharacters.length > 0 &&
        idea.settings.soraCharacters.every(x => x?.username && x?.id)) {
        return idea.settings.soraCharacters;
    }

    const aspectRatio = idea.settings?.aspectRatio || idea.aspectRatio || '16:9';
    const clipDur = 15; // 固定：Sora2 15s
    const lockCount = Number.isFinite(Number(idea.settings?.soraCharacterLockCount))
        ? Number(idea.settings.soraCharacterLockCount)
        : 3;

    const picked = _pickCharactersForSoraLock(idea, lockCount);
    if (!picked.length) return null;

    addStepLog(idea, `🧬 正在并发准备 ${picked.length} 个角色一致性...`, 'processing');
    saveIdeasToHistory();
    renderCanvas();

    // 🚀 LV10用户云雾API无限并发：同时生成所有角色锁定视频
    const memberLevel = window.currentMembershipLevel || Number(localStorage.getItem('membership_level')) || 0;
    const isLV10 = memberLevel >= 10;
    console.log(`🧬 角色锁定并发: ${isLV10 ? '无限(LV10)' : picked.length}, 会员等级: LV${memberLevel}`);

    // 🚀 并发生成所有角色的锁定视频
    const resultsArr = await Promise.all(picked.map(async (ch, i) => {
        const name = String(ch.name || '').trim();
        if (!name) return null;

        try {
            const refImg = _getCharacterRefImageForSoraLock(idea, ch);
            const anchorPrompt = _buildSoraLockAnchorPrompt(idea, name, ch.summary);
            let anchorUrl = '';

            if (refImg) {
                // 强制将参考图转为线稿，再用于生成锚定视频
                let sketchImg = refImg;
                try {
                    if (typeof convertRealisticToSketch === 'function') {
                        sketchImg = await convertRealisticToSketch(refImg, { chargeUser: false });
                        console.log('[sora-characters] 参考图已转线稿');
                    }
                } catch (e) {
                    console.warn('[sora-characters] 线稿转换失败，使用原图:', e?.message || e);
                }
                anchorUrl = await callSora2ImageToVideoAPI(sketchImg, anchorPrompt, {
                    model: 'sora-2',
                    duration: clipDur,
                    aspectRatio
                });
            } else {
                // 兆底：没有角色图时，用文字生成"单角色锚定片段"
                anchorUrl = await callSora2TextToVideoAPI(anchorPrompt, {
                    model: 'sora-2',
                    duration: clipDur,
                    aspectRatio
                });
            }

            const character = await createSoraCharacterFromVideoUrl(anchorUrl, { timestamps: '1,3' });
            console.log(`✅ 角色锁定 ${i + 1}/${picked.length} 完成: ${name}`);
            return {
                name,
                id: character.id,
                username: character.username,
                anchorUrl,
                createdAt: new Date().toISOString()
            };
        } catch (e) {
            console.warn('[sora-characters] create lock failed:', name, e?.message || e);
            return null;
        }
    }));

    const results = resultsArr.filter(r => r !== null);

    if (!results.length) return null;

    idea.settings.soraCharacters = results;
    // 兼容旧字段：保留第一个为 soraCharacter
    idea.settings.soraCharacter = { id: results[0].id, username: results[0].username, createdAt: results[0].createdAt };

    addStepLog(idea, `✅ ${results.length} 个角色一致性已就绪`, 'completed');
    saveIdeasToHistory();
    renderCanvas();
    return results;
}

