/**
 * 处理快速脚本上传
 */
function handleQuickScriptUpload(input) {
    const file = input.files[0];
    if (!file) return;

    // 检查文件类型（虽然 accept 限制了，但最好再检查一下）
    if (file.size > 1024 * 1024 * 5) { // 5MB limit
        alert('文件太大，请上传小于 5MB 的文本文件');
        input.value = ''; // Clear input
        return;
    }

    const reader = new FileReader();
    reader.onload = function (e) {
        const content = e.target.result;
        const textArea = document.getElementById('quickIdeaInput');
        if (textArea) {
            // 如果已有内容，询问是覆盖还是追加
            if (textArea.value.trim()) {
                if (confirm('输入框中已有内容，是否覆盖？\n\n点击“确定”覆盖，点击“取消”追加到末尾。')) {
                    textArea.value = content;
                } else {
                    textArea.value += '\n\n' + content;
                }
            } else {
                textArea.value = content;
            }
            // 触发 auto params 分析（如果文本够长）
            if (content.length > 10) {
                // 模拟输入事件以触发可能的监听器（虽然当前没有实时监听，但保持一致性好）
                textArea.dispatchEvent(new Event('input'));
            }
        }
        input.value = ''; // Reset file input so same file can be selected again
    };
    reader.onerror = function (e) {
        console.error('File read error:', e);
        alert('读取文件失败，请重试');
        input.value = '';
    };

    reader.readAsText(file);
}

/**
 * 🧠 智能提示词解析器 - Agent模式（学习自豆包/Coze）
 * 
 * 核心能力：
 * 1. 意图识别：识别用户想要生成图片/视频/文本
 * 2. 参数提取：从自然语言中提取数量、风格、比例等参数
 * 3. 提示词优化：自动补充风格描述词
 * 
 * 支持的自然语言表达：
 * - "生成30张猫咪图" / "画5张动漫风格的头像"
 * - "帮我做3张16:9的风景海报"
 * - "创建10张水墨风格的山水画"
 * - "生成5个短视频" / "做3段动画"
 * 
 * @param {string} text - 用户输入的文本
 * @returns {object} { type, count, prompt, style, aspectRatio, model }
 */
function parseSmartPrompt(text) {
    if (!text || typeof text !== 'string') return { type: null, count: 1, prompt: text || '', style: null, aspectRatio: null, model: null };

    const trimmed = text.trim();

    // 🆕 多主题独立任务检测：识别"一张图画猫，一张图画狗"这种模式
    // 更灵活的模式匹配，支持多种表达方式
    const multiTaskPatterns = [
        /一张.*?[，,、；;\n].*?一张/,           // "一张...，一张..."
        /第一张.*?[，,、；;\n].*?第二张/,       // "第一张...，第二张..."
        /画.*?[，,、；;\n].*?画/,               // "画...，画..."
        /生成.*?[，,、；;\n].*?生成/,           // "生成...，生成..."
        /一[只个条匹头].*?[，,、；;\n].*?一[只个条匹头]/, // "一只...，一只..."
    ];
    const hasMultiTaskIntent = multiTaskPatterns.some(p => p.test(trimmed));

    if (hasMultiTaskIntent) {
        // 按分隔符拆分任务
        const separatorRegex = /[，,、；;\n]/g;
        const parts = trimmed.split(separatorRegex).map(s => s.trim()).filter(s => s.length > 0);

        // 提取每个部分的核心主题
        const tasks = [];
        for (const part of parts) {
            // 更智能的主题提取：移除前缀词，保留核心内容
            let subject = part
                .replace(/^(?:一张|第[一二三四五六七八九十\d]+张)?/, '')  // 移除"一张"、"第X张"
                .replace(/^(?:图画?|画图?|生成|做|创建|制作)?/, '')       // 移除动词
                .replace(/^(?:一[只个条匹头张幅])?/, '')                  // 移除量词
                .replace(/(?:的?图片?|的?照片?|的?图像?)$/, '')           // 移除后缀
                .trim();

            // 如果提取结果太短，使用更宽松的方式
            if (subject.length < 1) {
                subject = part
                    .replace(/^一张图?画?/, '')
                    .replace(/的?图片?$/, '')
                    .trim();
            }

            if (subject.length > 0) {
                tasks.push(subject);
            }
        }

        // 如果成功识别到多个不同主题
        if (tasks.length >= 2) {
            console.log(`🧠 识别到多主题独立任务: ${tasks.length}个主题`, tasks);
            return {
                type: 'multi_image',
                count: tasks.length,
                prompts: tasks, // 多个不同的提示词
                prompt: tasks[0], // 兼容单提示词字段
                style: null,
                aspectRatio: null,
                model: null
            };
        }
    }

    // 🔢 中文数字转阿拉伯数字（支持十一到九十九）
    const chineseNumMap = { '零': 0, '一': 1, '二': 2, '两': 2, '三': 3, '四': 4, '五': 5, '六': 6, '七': 7, '八': 8, '九': 9, '十': 10 };
    const convertChineseNum = (str) => {
        // 先尝试直接匹配阿拉伯数字
        const arabicMatch = str.match(/\d+/);
        if (arabicMatch) return parseInt(arabicMatch[0]);
        // 处理十一到九十九
        if (str.includes('十')) {
            const parts = str.split('十');
            const tens = parts[0] ? (chineseNumMap[parts[0]] || 1) : 1;
            const ones = parts[1] ? (chineseNumMap[parts[1]] || 0) : 0;
            return tens * 10 + ones;
        }
        // 再尝试匹配单个中文数字
        for (const [cn, num] of Object.entries(chineseNumMap)) {
            if (str.includes(cn)) return num;
        }
        return null;
    };

    // 🎨 风格识别映射表（学习自豆包提示词技巧）
    const styleMap = {
        // 动漫/插画风格
        '动漫': 'anime style, 2D illustration',
        '二次元': 'anime style, 2D illustration',
        '卡通': 'cartoon style, colorful',
        '插画': 'illustration style, artistic',
        '绘本': 'picture book style, warm colors',
        // 中国风
        '水墨': 'Chinese ink painting style, traditional',
        '国风': 'Chinese traditional style, elegant',
        '中国风': 'Chinese traditional style, elegant',
        '仙侠': 'Chinese fantasy style, mystical',
        '古风': 'ancient Chinese style, classical',
        // 暗黑武侠AI国风
        '暗黑武侠': 'dark wuxia martial arts style, AI-generated cinematic realism, dramatic side lighting, desaturated colors with high contrast, gritty texture, ancient Chinese architecture, blood and steel atmosphere, 2.5D anime-realism fusion',
        '武侠': 'wuxia martial arts style, Chinese martial arts, ancient Jianghu atmosphere, traditional kung fu',
        // 写实风格
        '写实': 'photorealistic, highly detailed',
        '真实': 'photorealistic, real',
        '摄影': 'photography style, professional',
        '纪实': 'documentary photography style',
        '胶片': 'film photography, Kodak film',
        // 艺术风格
        '油画': 'oil painting style, artistic',
        '水彩': 'watercolor painting style',
        '素描': 'pencil sketch style',
        '剪纸': 'paper-cut art style, Chinese',
        // 现代风格
        '赛博朋克': 'cyberpunk style, neon lights',
        '科幻': 'sci-fi style, futuristic',
        '极简': 'minimalist style, clean',
        '扁平': 'flat design style',
        // 特殊风格
        '复古': 'vintage style, retro',
        '文艺复兴': 'Renaissance style, classical art',
        '港风': 'Hong Kong style, nostalgic',
        '日系': 'Japanese style, aesthetic'
    };

    // 📐 比例识别
    const aspectRatioMap = {
        '16:9': '16:9', '16比9': '16:9', '横屏': '16:9', '宽屏': '16:9',
        '9:16': '9:16', '9比16': '9:16', '竖屏': '9:16', '手机屏': '9:16',
        '1:1': '1:1', '1比1': '1:1', '正方形': '1:1', '方形': '1:1',
        '4:3': '4:3', '4比3': '4:3',
        '3:4': '3:4', '3比4': '3:4',
        '3:2': '3:2', '3比2': '3:2',
        '2:3': '2:3', '2比3': '2:3'
    };

    // 🤖 模型识别
    const modelMap = {
        '高清': 'nano-banana-2-2k',
        '2k': 'nano-banana-2-2k',
        '2K': 'nano-banana-2-2k',
        '超清': 'nano-banana-2-4k',
        '4k': 'nano-banana-2-4k',
        '4K': 'nano-banana-2-4k',
        '星梦': 'doubao-seedream-4-5-251128',
        '豆包': 'doubao-seedream-4-5-251128',
        '即梦': 'jimeng-4.5',
        '免费': 'modelscope',
        '智能': 'modelscope'
    };

    // 🔍 提取风格
    let detectedStyle = null;
    let styleTag = '';
    for (const [keyword, style] of Object.entries(styleMap)) {
        if (trimmed.includes(keyword)) {
            detectedStyle = keyword;
            styleTag = style;
            break;
        }
    }

    // 🔍 提取比例
    let detectedRatio = null;
    for (const [keyword, ratio] of Object.entries(aspectRatioMap)) {
        if (trimmed.includes(keyword)) {
            detectedRatio = ratio;
            break;
        }
    }

    // 🔍 提取模型
    let detectedModel = null;
    for (const [keyword, model] of Object.entries(modelMap)) {
        if (trimmed.includes(keyword)) {
            detectedModel = model;
            break;
        }
    }

    // 🖼️ 图片数量匹配模式（支持中文数字）
    const imagePatterns = [
        /(?:生成|画|做|创建|制作|帮我生成|帮我画|帮我做|来|给我)\s*([零一二两三四五六七八九十百\d]+)\s*张?\s*(?:张|幅|个)?\s*(?:图|图片|图像|画|照片|头像|插画|海报|壁纸|封面)/i,
        /([零一二两三四五六七八九十百\d]+)\s*张?\s*(?:张|幅|个)?\s*(?:图|图片|图像|画|照片|头像|插画|海报|壁纸|封面)/i,
        /(?:图|图片|图像|画|照片|头像|插画|海报|壁纸|封面)\s*([零一二两三四五六七八九十百\d]+)\s*(?:张|幅|个)/i,
    ];

    // 🎬 视频数量匹配模式（支持中文数字）
    const videoPatterns = [
        /(?:生成|做|创建|制作|帮我生成|帮我做|来|给我)\s*([零一二两三四五六七八九十百\d]+)\s*(?:个|段|条)?\s*(?:视频|短视频|动画|片段|影片)/i,
        /([零一二两三四五六七八九十百\d]+)\s*(?:个|段|条)?\s*(?:视频|短视频|动画|片段|影片)/i,
        /(?:视频|短视频|动画|片段|影片)\s*([零一二两三四五六七八九十百\d]+)\s*(?:个|段|条)/i,
    ];

    // 尝试匹配图片
    for (const pattern of imagePatterns) {
        const match = trimmed.match(pattern);
        if (match && match[1]) {
            const count = convertChineseNum(match[1]);
            if (count && count > 0 && count <= 100) {
                // 提取核心提示词（去掉数量、风格、比例等描述词）
                let prompt = trimmed
                    .replace(/(?:生成|画|做|创建|制作|帮我生成|帮我画|帮我做|来|给我)\s*[零一二两三四五六七八九十百\d]+\s*(?:张|幅|个)?\s*(?:张|幅|个)?/gi, '')
                    .replace(/[零一二两三四五六七八九十百\d]+\s*(?:张|幅|个)\s*(?:图|图片|图像|画|照片|头像|插画|海报|壁纸|封面)/gi, '')
                    .replace(/(?:图|图片|图像|画|照片|头像|插画|海报|壁纸|封面)\s*[零一二两三四五六七八九十百\d]+\s*(?:张|幅|个)/gi, '')
                    .replace(/(?:16:9|9:16|1:1|4:3|3:4|16比9|9比16|1比1|横屏|竖屏|正方形|方形|宽屏|手机屏)/gi, '')
                    .replace(/(?:高清|超清|2k|4k|星梦|豆包|即梦|免费|智能)(?:模式|模型|版)?/gi, '')
                    .trim();

                // 🎨 如果检测到风格，自动补充英文风格标签
                if (styleTag && !prompt.toLowerCase().includes('style')) {
                    prompt = `${prompt}, ${styleTag}`;
                }

                if (!prompt) prompt = trimmed;

                console.log(`🧠 Agent解析结果: type=image, count=${count}, style=${detectedStyle}, ratio=${detectedRatio}, model=${detectedModel}`);
                console.log(`🧠 优化后提示词: "${prompt}"`);

                return {
                    type: 'image',
                    count,
                    prompt,
                    style: detectedStyle,
                    aspectRatio: detectedRatio,
                    model: detectedModel
                };
            }
        }
    }

    // 尝试匹配视频
    for (const pattern of videoPatterns) {
        const match = trimmed.match(pattern);
        if (match && match[1]) {
            const count = convertChineseNum(match[1]);
            if (count && count > 0 && count <= 50) {
                let prompt = trimmed
                    .replace(/(?:生成|做|创建|制作|帮我生成|帮我做|来|给我)\s*[零一二两三四五六七八九十百\d]+\s*(?:个|段|条)?\s*(?:个|段|条)?/gi, '')
                    .replace(/[零一二两三四五六七八九十百\d]+\s*(?:个|段|条)\s*(?:视频|短视频|动画|片段|影片)/gi, '')
                    .replace(/(?:视频|短视频|动画|片段|影片)\s*[零一二两三四五六七八九十百\d]+\s*(?:个|段|条)/gi, '')
                    .trim();
                if (!prompt) prompt = trimmed;

                console.log(`🧠 Agent解析结果: type=video, count=${count}`);
                return {
                    type: 'video',
                    count,
                    prompt,
                    style: detectedStyle,
                    aspectRatio: detectedRatio,
                    model: detectedModel
                };
            }
        }
    }

    // 未匹配到批量意图，检查是否是单张图片请求
    const singleImageKeywords = ['画', '生成', '做', '创建', '帮我画', '帮我生成'];
    const imageContentKeywords = ['图', '图片', '照片', '头像', '插画', '海报', '壁纸'];
    const hasSingleIntent = singleImageKeywords.some(k => trimmed.startsWith(k));
    const hasImageContent = imageContentKeywords.some(k => trimmed.includes(k));

    if (hasSingleIntent || hasImageContent) {
        let prompt = trimmed;
        if (styleTag && !prompt.toLowerCase().includes('style')) {
            prompt = `${prompt}, ${styleTag}`;
        }
        console.log(`🧠 Agent解析结果: 单张图片请求`);
        return {
            type: 'image',
            count: 1,
            prompt,
            style: detectedStyle,
            aspectRatio: detectedRatio,
            model: detectedModel
        };
    }

    // 完全未识别
    console.log(`🧠 Agent: 未识别明确意图，作为通用提示词处理: "${trimmed}"`);
    return { type: null, count: 1, prompt: trimmed, style: null, aspectRatio: null, model: null };
}

/**
 * 🤖 Agent快捷指令列表（学习自豆包/Coze）
 * 用于引导用户快速上手
 */
const AGENT_QUICK_COMMANDS = [
    // 🎨 图片生成示例（每次1张，节省成本）
    { label: '🐱 猫咪', command: '生成1张可爱的猫咪图片' },
    { label: '🎭 头像', command: '画1张动漫风格的头像' },
    { label: '🏔️ 山水', command: '生成1张水墨风格的山水画' },
    { label: '📱 壁纸', command: '做1张9:16竖屏的风景壁纸' },
    { label: '🌆 赛博', command: '画1张赛博朋克风格的城市夜景' },
    { label: '🌸 日系', command: '生成1张日系治愈风格的插画' },
    { label: '🎮 角色', command: '画1张游戏角色立绘' },
    { label: '🎬 视频', command: '生成1个短视频' }
];

window.AGENT_QUICK_COMMANDS = AGENT_QUICK_COMMANDS;

/**
 * 🎨 批量创建图片节点（思维导图流式布局 + 自动连接）
 * @param {number} count - 要创建的节点数量
 * @param {string} prompt - 提示词
 * @param {object} options - 配置选项（支持Agent解析的参数）
 *   - autoRun: 是否自动运行生成
 *   - model: 指定模型
 *   - aspectRatio: 图片比例（Agent从用户输入中解析）
 *   - connectNodes: 是否自动连接节点
 *   - refImage: 参考图（base64）
 *   - refVideo: 参考视频（base64）
 */
async function batchCreateImageNodes(count, prompt, options = {}) {
    // 🎯 根据用户等级智能选择默认模型（仅当用户未指定模型时使用）
    const userLevel = window.currentUserLevel || 'free';
    // 🔧 默认使用 Banana 标准版（modelscope 可能不稳定）
    let defaultModel = 'nano-banana-2';

    // 付费用户可以使用更好的模型作为默认
    if (userLevel === 'pro') {
        defaultModel = 'nano-banana-2-4k'; // 高级会员默认4K
    } else if (userLevel === 'mid') {
        defaultModel = 'nano-banana-2-2k'; // 中级会员默认2K
    }

    console.log(`🎯 用户等级: ${userLevel}, 默认模型: ${defaultModel}`);

    // 🤖 Agent模式：支持从用户输入中解析的参数
    // ⚠️ 重要：用户明确选择的模型优先级最高，不被默认模型覆盖
    const { autoRun = true, connectNodes = true, aspectRatio = '1:1', refImage = null, refVideo = null } = options;
    // 🎯 用户选择的模型 > 默认模型
    const model = options.model || defaultModel;
    console.log(`🤖 Agent参数: model=${model}, aspectRatio=${aspectRatio}, hasRefImage=${!!refImage}, hasRefVideo=${!!refVideo}`);

    if (count <= 0 || count > 100) {
        alert('批量生成数量需要在1-100之间');
        return;
    }

    console.log(`🎨 批量创建 ${count} 个图片节点，提示词: ${prompt}`);

    // 计算起始位置（在画布中心）
    const canvas = document.getElementById('canvasContent');
    const canvasRect = canvas?.getBoundingClientRect() || { width: 1200, height: 800 };

    // 🌳 思维导图布局：中心节点 + 放射状子节点
    const nodeWidth = 280;
    const nodeHeight = 200;

    // 中心节点位置
    const centerX = Math.max(400, (canvasRect.width / 2) - nodeWidth / 2);
    const centerY = 80;

    const createdNodes = [];
    const statusEl = document.querySelector('.voice-status');

    // 🎯 创建中心主节点（使用banana-draw图片生成节点）
    const mainNodeId = 'batch_main_' + Date.now();
    const mainNode = {
        id: mainNodeId,
        type: 'banana-draw',  // 图片生成节点，带生成功能
        x: centerX,
        y: centerY,
        locked: false,
        data: {
            mode: 'auto',
            model: model,    // 🔧 同时设置 model 确保兼容
            backend: model,
            aspectRatio: aspectRatio,  // 🤖 Agent解析的比例
            characterId: '',
            customPrompt: prompt,
            referenceImage: refImage || '',  // 📎 参考图
            refVideo: refVideo || '',        // 📎 参考视频
            sheetUrl: '',
            sheetDataUrl: '',
            slices: [],
            refImages: refImage ? [{ url: refImage, name: '命令上传参考图' }] : [],  // 📎 参考图数组（对象格式）
            status: 'idle',
            error: '',
            isMainNode: true,
            batchTotal: count,
            batchChildIds: []  // 存储子节点ID，用于批量操作
        }
    };
    flowNodes.push(mainNode);
    createdNodes.push(mainNode);

    if (statusEl) {
        statusEl.textContent = `🎨 创建主节点...`;
        statusEl.style.color = '#60a5fa';
    }

    // 🌿 创建子节点（放射状布局）
    const childCount = count - 1; // 减去主节点
    if (childCount > 0) {
        // 计算子节点布局（分层放射）
        const layerGap = nodeHeight + 60; // 层间距
        const nodeGap = nodeWidth + 40;   // 节点间距

        let nodeIndex = 0;
        let currentY = centerY + layerGap;

        while (nodeIndex < childCount) {
            // 计算当前层可容纳的节点数
            const layer = Math.floor(nodeIndex / 5) + 1;
            const nodesInLayer = Math.min(5, childCount - nodeIndex);
            const layerWidth = nodesInLayer * nodeGap;
            const layerStartX = centerX + nodeWidth / 2 - layerWidth / 2;

            for (let i = 0; i < nodesInLayer && nodeIndex < childCount; i++) {
                const x = layerStartX + i * nodeGap;
                const y = currentY;

                const nodeId = 'batch_' + Date.now() + '_' + (nodeIndex + 1);
                // 🎨 生成更丰富的变体描述，确保每个节点生成不同内容
                const variantStyles = [
                    '不同角度视角',
                    '不同光影效果',
                    '不同色调氛围',
                    '不同构图方式',
                    '不同艺术风格',
                    '不同表情神态',
                    '不同背景环境',
                    '不同细节特征'
                ];
                const variantStyle = variantStyles[nodeIndex % variantStyles.length];
                const randomSeed = Math.floor(Math.random() * 10000);
                const node = {
                    id: nodeId,
                    type: 'banana-draw',
                    x: x,
                    y: y,
                    locked: false,
                    data: {
                        mode: 'auto',
                        model: model,    // 🔧 同时设置 model 确保兼容
                        backend: model,
                        aspectRatio: aspectRatio,  // 🤖 Agent解析的比例
                        characterId: '',
                        customPrompt: prompt + `, ${variantStyle}, 创意变体#${randomSeed}`,
                        referenceImage: '',
                        sheetUrl: '',
                        sheetDataUrl: '',
                        slices: [],
                        refImages: [],
                        status: 'idle',
                        error: '',
                        batchIndex: nodeIndex + 2,
                        batchTotal: count
                    }
                };

                flowNodes.push(node);
                createdNodes.push(node);

                // 将子节点ID存储到主节点
                mainNode.data.batchChildIds.push(nodeId);

                // 🔗 创建从主节点到子节点的连接
                if (connectNodes) {
                    connections.push({
                        id: 'conn_batch_' + Date.now() + '_' + nodeIndex,
                        source: mainNodeId,
                        target: nodeId
                    });
                }

                nodeIndex++;

                if (statusEl) {
                    statusEl.textContent = `🎨 创建节点 ${nodeIndex + 1}/${count}...`;
                    statusEl.style.color = '#60a5fa';
                }

                // 小延迟避免ID冲突
                await new Promise(r => setTimeout(r, 5));
            }

            currentY += layerGap;
        }
    }

    // 保存并渲染
    saveIdeasToHistory();
    renderCanvas();

    // 聚焦到第一个节点
    if (createdNodes.length > 0) {
        try {
            window.__rrFocusCanvasOnNode && window.__rrFocusCanvasOnNode(createdNodes[0], { animate: true });
        } catch (e) { }
    }

    if (statusEl) {
        statusEl.textContent = `✅ 已创建 ${count} 个图片节点`;
        statusEl.style.color = '#10b981';
    }

    // 自动运行生成
    if (autoRun) {
        // 🔧 增加延迟，确保节点完全渲染到 DOM 后再开始生成
        setTimeout(async () => {
            if (statusEl) {
                statusEl.textContent = `🚀 开始并行生成 ${count} 张图片...`;
                statusEl.style.color = '#f59e0b';
            }

            // 🚀 并行生成所有节点的图片（同时发起所有请求）
            let completedCount = 0;
            const generatePromises = createdNodes.map(async (node, i) => {
                // 🔧 确保节点 DOM 元素存在
                const nodeEl = document.getElementById(`node-${node.id}`);
                if (!nodeEl) {
                    console.warn(`⚠️ 节点 ${node.id} 的 DOM 元素不存在，触发重新渲染`);
                    renderCanvas();
                    await new Promise(r => setTimeout(r, 200));
                }

                try {
                    await generateNodeImage(node.id);
                    completedCount++;
                    if (statusEl) {
                        statusEl.textContent = `🎨 已完成 ${completedCount}/${count}...`;
                    }
                } catch (e) {
                    console.error(`节点 ${node.id} 生成失败:`, e);
                    completedCount++;
                    if (statusEl) {
                        statusEl.textContent = `🎨 已完成 ${completedCount}/${count}...`;
                    }
                }
            });

            // 等待所有生成任务完成
            await Promise.all(generatePromises);

            if (statusEl) {
                statusEl.textContent = `✅ 批量生成完成！共 ${count} 张图片`;
                statusEl.style.color = '#10b981';
                setTimeout(() => {
                    statusEl.textContent = '支持连续对话，试试说出创意...';
                    statusEl.style.color = '#9ca3af';
                }, 5000);
            }
        }, 500);  // 🔧 减少延迟，更快开始并行生成
    }

    return createdNodes;
}

/**
 * 🎬 批量创建视频任务（思维导图流式布局 + 自动连接）
 * @param {number} count - 要创建的任务数量
 * @param {string} prompt - 提示词
 * @param {object} options - 配置选项
 */
async function batchCreateVideoTasks(count, prompt, options = {}) {
    const { autoRun = false, videoModel = 'sora-2', connectTasks = true } = options;

    if (count <= 0 || count > 50) {
        alert('批量生成数量需要在1-50之间');
        return;
    }

    console.log(`🎬 批量创建 ${count} 个视频任务，提示词: ${prompt}`);

    const statusEl = document.querySelector('.voice-status');
    const createdTasks = [];

    // 🌳 思维导图布局：主任务 + 放射状子任务
    const canvas = document.getElementById('canvasContent');
    const canvasRect = canvas?.getBoundingClientRect() || { width: 1200, height: 800 };

    const taskWidth = 320;
    const taskHeight = 180;
    const centerX = Math.max(400, (canvasRect.width / 2) - taskWidth / 2);
    const centerY = 80;

    // 🎯 创建主任务
    const mainId = Date.now() + Math.floor(Math.random() * 10000);
    const clipDuration = __getFixedClipDurationByModel(videoModel, undefined);

    const mainTask = {
        id: mainId,
        theme: prompt,
        type: 'video',
        status: 'pending',
        automationLevel: globalAutomationLevel,
        progress: 0,
        logs: [],
        stepLogs: [],
        videoResults: [],
        characterSheets: [],
        characterDescriptions: [],
        generatedScript: null,
        normalStoryboards: [],
        generatedVideoPrompts: [],
        generationMode: 'video',
        videoModel: videoModel,
        clipDuration: clipDuration,
        duration: clipDuration,
        totalDuration: clipDuration,
        scenes: 1,
        selected: false,
        forceRestart: true,
        x: centerX,
        y: centerY,
        batchIndex: 1,
        batchTotal: count,
        isMainTask: true
    };
    mainTask.settings = {
        automationLevel: mainTask.automationLevel,
        videoModel: mainTask.videoModel,
        clipDuration: mainTask.clipDuration,
        sceneCount: mainTask.scenes,
        totalDuration: mainTask.totalDuration,
        generationMode: mainTask.generationMode,
        enableCharSheet: loadSettings().characterSheetEnabled !== false
    };
    ideas.push(mainTask);
    createdTasks.push(mainTask);

    if (statusEl) {
        statusEl.textContent = `🎬 创建主任务...`;
        statusEl.style.color = '#60a5fa';
    }

    // 🌿 创建子任务（放射状布局）
    const childCount = count - 1;
    if (childCount > 0) {
        const layerGap = taskHeight + 50;
        const taskGap = taskWidth + 30;

        let taskIndex = 0;
        let currentY = centerY + layerGap;

        while (taskIndex < childCount) {
            const nodesInLayer = Math.min(4, childCount - taskIndex);
            const layerWidth = nodesInLayer * taskGap;
            const layerStartX = centerX + taskWidth / 2 - layerWidth / 2;

            for (let i = 0; i < nodesInLayer && taskIndex < childCount; i++) {
                const x = layerStartX + i * taskGap;
                const y = currentY;

                const uniqueId = Date.now() + Math.floor(Math.random() * 10000) + taskIndex + 1;

                const newIdea = {
                    id: uniqueId,
                    theme: prompt + ` (变体${taskIndex + 2})`,
                    type: 'video',
                    status: 'pending',
                    automationLevel: globalAutomationLevel,
                    progress: 0,
                    logs: [],
                    stepLogs: [],
                    videoResults: [],
                    characterSheets: [],
                    characterDescriptions: [],
                    generatedScript: null,
                    normalStoryboards: [],
                    generatedVideoPrompts: [],
                    generationMode: 'video',
                    videoModel: videoModel,
                    clipDuration: clipDuration,
                    duration: clipDuration,
                    totalDuration: clipDuration,
                    scenes: 1,
                    selected: false,
                    forceRestart: true,
                    x: x,
                    y: y,
                    batchIndex: taskIndex + 2,
                    batchTotal: count,
                    parentTaskId: mainId
                };

                newIdea.settings = {
                    automationLevel: newIdea.automationLevel,
                    videoModel: newIdea.videoModel,
                    clipDuration: newIdea.clipDuration,
                    sceneCount: newIdea.scenes,
                    totalDuration: newIdea.totalDuration,
                    generationMode: newIdea.generationMode,
                    enableCharSheet: loadSettings().characterSheetEnabled !== false
                };

                ideas.push(newIdea);
                createdTasks.push(newIdea);

                // 🔗 创建任务连接（用于画布显示）
                if (connectTasks) {
                    connections.push({
                        id: 'conn_task_' + Date.now() + '_' + taskIndex,
                        source: String(mainId),
                        target: String(uniqueId)
                    });
                }

                taskIndex++;

                if (statusEl) {
                    statusEl.textContent = `🎬 创建任务 ${taskIndex + 1}/${count}...`;
                    statusEl.style.color = '#60a5fa';
                }

                await new Promise(r => setTimeout(r, 5));
            }

            currentY += layerGap;
        }
    }

    saveIdeasToHistory();
    renderIdeasList();
    renderCanvas();

    if (statusEl) {
        statusEl.textContent = `✅ 已创建 ${count} 个视频任务（已连接）`;
        statusEl.style.color = '#10b981';
        setTimeout(() => {
            statusEl.textContent = '支持连续对话，试试说出创意...';
            statusEl.style.color = '#9ca3af';
        }, 3000);
    }

    return createdTasks;
}

// 导出批量生成函数
window.parseSmartPrompt = parseSmartPrompt;
window.batchCreateImageNodes = batchCreateImageNodes;
window.batchCreateVideoTasks = batchCreateVideoTasks;

/**
 * 🛠️ 检测用户输入是否触发左侧工具栏功能
 * @param {string} command - 用户输入的命令
 * @returns {Object|null} - 返回匹配的工具栏动作，或null
 */
function detectToolbarAction(command) {
    const cmd = command.toLowerCase();

    // ========== 产品类型切换 ==========

    // 🎬 AI视频模式
    const videoKeywords = ['视频模式', 'ai视频', '切换视频', '做视频', '生成视频', '视频生成', '文生视频', '图生视频'];
    for (const kw of videoKeywords) {
        if (cmd.includes(kw)) {
            return {
                name: 'AI视频模式',
                action: () => window.switchProductType && window.switchProductType('video')
            };
        }
    }

    // 📚 AI漫画模式
    const comicKeywords = ['漫画模式', 'ai漫画', '切换漫画', '做漫画', '生成漫画', '漫画生成', '画漫画'];
    for (const kw of comicKeywords) {
        if (cmd.includes(kw)) {
            return {
                name: 'AI漫画模式',
                action: () => window.switchProductType && window.switchProductType('comic')
            };
        }
    }

    // ✍️ AI写作模式
    const writingKeywords = ['写作模式', 'ai写作', '切换写作', '写文章', '写小说', '写剧本', '文案'];
    for (const kw of writingKeywords) {
        if (cmd.includes(kw)) {
            return {
                name: 'AI写作模式',
                action: () => window.switchProductType && window.switchProductType('writing')
            };
        }
    }

    // ========== 工作模式切换 ==========

    // 🚀 全自动模式
    const fullAutoKeywords = ['全自动', '全自动模式', '自动模式', '一键生成', '自动运行'];
    for (const kw of fullAutoKeywords) {
        if (cmd.includes(kw)) {
            return {
                name: '全自动模式',
                action: () => {
                    const radio = document.querySelector('input[name="autoMode"][value="full-auto"]');
                    if (radio) { radio.checked = true; window.onModeChange && window.onModeChange('full-auto'); }
                }
            };
        }
    }

    // ⚡ 半自动模式
    const semiAutoKeywords = ['半自动', '半自动模式', '审核模式'];
    for (const kw of semiAutoKeywords) {
        if (cmd.includes(kw)) {
            return {
                name: '半自动模式',
                action: () => {
                    const radio = document.querySelector('input[name="autoMode"][value="semi-auto"]');
                    if (radio) { radio.checked = true; window.onModeChange && window.onModeChange('semi-auto'); }
                }
            };
        }
    }

    // 🎛️ 手动模式
    const manualKeywords = ['手动模式', '手动', '手工模式'];
    for (const kw of manualKeywords) {
        if (cmd.includes(kw)) {
            return {
                name: '手动模式',
                action: () => {
                    const radio = document.querySelector('input[name="autoMode"][value="manual"]');
                    if (radio) { radio.checked = true; window.onModeChange && window.onModeChange('manual'); }
                }
            };
        }
    }

    return null;
}

/**
 * ⚡ 执行画布命令
 * 从画布底部命令输入框获取命令并执行
 */
window.executeCanvasCommand = async function () {
    const input = document.getElementById('canvasCommandInput');
    const statusEl = document.getElementById('commandStatus');
    const modelSelect = document.getElementById('commandModelSelect');
    const sizeSelect = document.getElementById('commandSizeSelect');

    if (!input) return;

    const command = input.value.trim();
    if (!command) {
        if (statusEl) {
            statusEl.textContent = '请输入命令';
            statusEl.className = 'command-status error';
            setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'command-status'; }, 2000);
        }
        return;
    }

    // 🎨 获取用户选择的模型和尺寸
    const userSelectedModelRaw = modelSelect?.value || 'auto';
    const userSelectedSize = sizeSelect?.value || 'auto';

    // 🎯 模型名称映射（选择器值 → 后端模型名）
    // 注意：图片模型和视频模型分开处理
    const IMAGE_MODEL_MAP = {
        'auto': null,  // 自动选择
        'banana': 'nano-banana-2',           // Banana 标准版
        'banana-2k': 'nano-banana-2-2k',     // Banana 2K 高清
        'banana-4k': 'nano-banana-2-4k',     // Banana 4K 超清
        'Qwen/Qwen-Image-2512': 'Qwen/Qwen-Image-2512',  // 通义万相Max
        'seedream': 'doubao-seedream-4-5-251128',  // 星梦画师
        'jimeng': 'jimeng-4.5',              // 即梦4.5
        'modelscope': 'modelscope'           // 智能绘图引擎（免费）
    };
    const VIDEO_MODEL_MAP = {
        'auto': null,
        'modelscope-video': 'modelscope-video',
        'sora-2-vip-all': 'sora-2-vip-all',
        'sora-2-all': 'sora-2-vip-all',
        'sora-2-pro-all': 'sora-2-vip-all',
        'veo': 'veo3.1',
        'grok': 'grok-video-3',
        // Vidu 系列 - 5秒
        'vidu-q2-5s-720p': 'vidu-q2-5s-720p',
        'vidu-q2-5s-1080p': 'vidu-q2-5s-1080p',
        'vidu-q2-pro-5s-720p': 'vidu-q2-pro-5s-720p',
        'vidu-q2-pro-5s-1080p': 'vidu-q2-pro-5s-1080p',
        'vidu-q2-turbo-5s-720p': 'vidu-q2-turbo-5s-720p',
        'vidu-q2-turbo-5s-1080p': 'vidu-q2-turbo-5s-1080p',
        // Vidu 系列 - 10秒
        'vidu-q2-10s-720p': 'vidu-q2-10s-720p',
        'vidu-q2-10s-1080p': 'vidu-q2-10s-1080p',
        'vidu-q2-pro-10s-720p': 'vidu-q2-pro-10s-720p',
        'vidu-q2-pro-10s-1080p': 'vidu-q2-pro-10s-1080p',
        'vidu-q2-turbo-10s-720p': 'vidu-q2-turbo-10s-720p',
        'vidu-q2-turbo-10s-1080p': 'vidu-q2-turbo-10s-1080p',
        // 兼容旧模型名称
        'vidu-q2-720p': 'vidu-q2-5s-720p',
        'vidu-q2-1080p': 'vidu-q2-5s-1080p',
        'vidu-q2-pro-720p': 'vidu-q2-pro-5s-720p',
        'vidu-q2-pro-1080p': 'vidu-q2-pro-5s-1080p',
        'vidu-q2-turbo-720p': 'vidu-q2-turbo-5s-720p',
        'vidu-q2-turbo-1080p': 'vidu-q2-turbo-5s-1080p'
    };
    // 兼容旧的映射
    const MODEL_MAP = { ...IMAGE_MODEL_MAP, ...VIDEO_MODEL_MAP };
    const userSelectedModel = MODEL_MAP[userSelectedModelRaw] || (userSelectedModelRaw !== 'auto' ? userSelectedModelRaw : null);

    // 🎬 判断用户是否选择了视频模型
    const isVideoModelSelected = VIDEO_MODEL_MAP.hasOwnProperty(userSelectedModelRaw) && userSelectedModelRaw !== 'auto';

    // 显示处理状态
    if (statusEl) {
        statusEl.textContent = '🤖 Agent 解析中...';
        statusEl.className = 'command-status processing';
    }

    try {
        // 🛠️ 首先检查是否触发左侧工具栏功能
        const toolbarAction = detectToolbarAction(command);
        if (toolbarAction) {
            if (statusEl) {
                statusEl.textContent = `🛠️ 启动 ${toolbarAction.name}...`;
                statusEl.className = 'command-status processing';
            }
            input.value = '';

            // 执行对应的工具栏功能
            toolbarAction.action();

            if (statusEl) {
                statusEl.textContent = `✅ 已切换到 ${toolbarAction.name}`;
                statusEl.className = 'command-status success';
                setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'command-status'; }, 3000);
            }
            return;
        }

        // 🧠 Agent模式：智能解析命令（提取意图、数量、风格、比例、模型）
        const smartResult = parseSmartPrompt(command);

        // 📎 获取参考图/视频数据
        let refData = window.getCommandRefData ? window.getCommandRefData() : null;

        // 🆕 处理多图合并
        if (refData && refData.type === 'multi-image' && refData.imageList && refData.imageList.length > 1) {
            const mergeMode = document.getElementById('refMergeMode')?.value || 'grid';
            if (statusEl) statusEl.textContent = '🖼️ 正在合并参考图...';
            const mergedBase64 = await window.mergeRefImages(refData.imageList, mergeMode);
            if (mergedBase64) {
                refData = { type: 'image', base64: mergedBase64 };
                console.log('[PC] 多图已合并为单图，模式:', mergeMode);
            }
        }

        // 🎯 用户选择的模型优先级高于Agent解析
        const finalModel = userSelectedModel !== 'auto' ? userSelectedModel : smartResult.model;
        // 🎯 用户选择的尺寸优先级高于Agent解析
        const finalAspectRatio = userSelectedSize !== 'auto' ? userSelectedSize : smartResult.aspectRatio;

        // 🎯 构建选项对象，传递Agent解析出的参数
        const agentOptions = {
            autoRun: true,
            // 模型：用户选择 > Agent解析
            ...(finalModel && { model: finalModel }),
            // 比例：用户选择 > Agent解析
            ...(finalAspectRatio && { aspectRatio: finalAspectRatio }),
            // 📎 如果有参考图，传递给节点
            ...(refData && refData.type === 'image' && { refImage: refData.base64 }),
            // 📎 如果有参考视频，传递给节点
            ...(refData && refData.type === 'video' && { refVideo: refData.base64 })
        };

        // 📊 显示Agent解析结果（包含用户选择）
        const agentInfo = [];
        if (smartResult.style) agentInfo.push(`风格:${smartResult.style}`);
        if (finalAspectRatio) agentInfo.push(`比例:${finalAspectRatio}`);
        if (finalModel) agentInfo.push(`模型:${finalModel}`);
        if (refData) agentInfo.push(`参考${refData.type === 'image' ? '图' : '视频'}`);
        const agentInfoStr = agentInfo.length > 0 ? ` (${agentInfo.join(', ')})` : '';

        // 🎬 用户选择视频模型时，强制创建视频任务
        if (isVideoModelSelected) {
            const videoCount = smartResult.count > 0 ? smartResult.count : 1;
            if (statusEl) {
                statusEl.textContent = `🎬 创建 ${videoCount} 个视频任务${agentInfoStr}...`;
            }
            input.value = '';
            if (refData) window.removeCommandRef();
            // 传递视频模型到 videoModel 参数
            await batchCreateVideoTasks(videoCount, smartResult.prompt || command, {
                autoRun: false,
                videoModel: finalModel,
                aspectRatio: finalAspectRatio,
                ...(refData && refData.type === 'image' && { refImage: refData.base64 }),
                ...(refData && refData.type === 'video' && { refVideo: refData.base64 })
            });
            if (statusEl) {
                statusEl.textContent = `✅ 已创建 ${videoCount} 个视频任务`;
                statusEl.className = 'command-status success';
                setTimeout(() => { statusEl.textContent = '支持连续对话，试试说出创意...'; statusEl.className = 'command-status'; }, 5000);
            }
            return;
        }

        if (smartResult.type === 'image' && smartResult.count > 0) {
            // 批量图片生成
            if (statusEl) {
                statusEl.textContent = `🎨 创建 ${smartResult.count} 个图片节点${agentInfoStr}...`;
            }
            input.value = '';
            // 清除参考图/视频（已使用）
            if (refData) window.removeCommandRef();
            await batchCreateImageNodes(smartResult.count, smartResult.prompt, agentOptions);
            if (statusEl) {
                statusEl.textContent = `✅ 已创建 ${smartResult.count} 个图片节点，正在生成...`;
                statusEl.className = 'command-status success';
                setTimeout(() => { statusEl.textContent = '支持连续对话，试试说出创意...'; statusEl.className = 'command-status'; }, 5000);
            }
            return;
        }

        if (smartResult.type === 'video' && smartResult.count > 0) {
            // 批量视频生成
            if (statusEl) {
                statusEl.textContent = `🎬 创建 ${smartResult.count} 个视频任务${agentInfoStr}...`;
            }
            input.value = '';
            // 清除参考图/视频（已使用）
            if (refData) window.removeCommandRef();
            await batchCreateVideoTasks(smartResult.count, smartResult.prompt, { autoRun: false, ...agentOptions });
            if (statusEl) {
                statusEl.textContent = `✅ 已创建 ${smartResult.count} 个视频任务`;
                statusEl.className = 'command-status success';
                setTimeout(() => { statusEl.textContent = '支持连续对话，试试说出创意...'; statusEl.className = 'command-status'; }, 5000);
            }
            return;
        }

        // 单个任务：创建单个节点
        if (statusEl) {
            statusEl.textContent = `🎨 创建图片节点${agentInfoStr}...`;
        }
        input.value = '';
        // 清除参考图/视频（已使用）
        if (refData) window.removeCommandRef();
        await batchCreateImageNodes(1, smartResult.prompt || command, agentOptions);
        if (statusEl) {
            statusEl.textContent = '✅ 已创建节点，正在生成...';
            statusEl.className = 'command-status success';
            setTimeout(() => { statusEl.textContent = '支持连续对话，试试说出创意...'; statusEl.className = 'command-status'; }, 5000);
        }

    } catch (e) {
        console.error('命令执行失败:', e);
        if (statusEl) {
            statusEl.textContent = '❌ 命令执行失败: ' + e.message;
            statusEl.className = 'command-status error';
            setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'command-status'; }, 5000);
        }
    }
};

/**
 * 🤖 填充快捷指令到输入框（不自动执行，等待用户确认）
 * @param {string} command - 要填充的命令
 * @param {string} forceModel - 可选，强制选择的模型（如 'sora-2-all' 表示视频模型）
 */
window.fillQuickCommand = function (command, forceModel) {
    const input = document.getElementById('canvasCommandInput');
    const modelSelect = document.getElementById('commandModelSelect');
    if (input) {
        input.value = command;
        input.focus();

        // 🎬 如果指定了强制模型，自动切换模型选择器
        if (forceModel && modelSelect) {
            modelSelect.value = forceModel;
            console.log('[QuickCommand] 自动切换模型:', forceModel);
        }

        // 🔧 修复：不自动执行，等待用户按回车确认
        // executeCanvasCommand(); // 已移除自动执行
        console.log('[QuickCommand] 已填充命令，按回车执行:', command);
    }
};

// ============================================================================
// 📎 命令输入框参考图/视频上传功能
// ============================================================================

// 存储当前上传的参考图/视频
window._commandRefData = null;
// 🆕 多图列表
window._commandRefImageList = [];

/**
 * 📎 处理参考图/视频上传（🆕 支持多图）
 */
window.handleCommandRefUpload = async function (input) {
    const files = input.files;
    if (!files || files.length === 0) return;

    const statusEl = document.getElementById('commandStatus');
    const previewEl = document.getElementById('commandRefPreview');
    const imgEl = document.getElementById('refPreviewImg');
    const videoEl = document.getElementById('refPreviewVideo');
    const uploadBtn = document.querySelector('.command-upload-btn');
    const multiPreviewEl = document.getElementById('multiRefPreviewContainer');
    const mergeOptionsEl = document.getElementById('refMergeOptions');
    const imageCountEl = document.getElementById('refImageCount');

    // 检查第一个文件类型
    const firstFile = files[0];
    const isVideo = firstFile.type.startsWith('video/');

    // 如果是视频，只处理单个文件
    if (isVideo) {
        if (firstFile.size > 50 * 1024 * 1024) {
            if (statusEl) {
                statusEl.textContent = '❌ 视频文件过大，最大50MB';
                statusEl.className = 'command-status error';
                setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'command-status'; }, 3000);
            }
            input.value = '';
            return;
        }

        if (statusEl) {
            statusEl.textContent = '📎 正在处理视频...';
            statusEl.className = 'command-status processing';
        }

        try {
            const base64 = await readFileAsDataURL(firstFile);
            window._commandRefData = { type: 'video', base64, file: firstFile, name: firstFile.name };
            window._commandRefImageList = [];

            videoEl.src = base64;
            videoEl.style.display = 'block';
            imgEl.style.display = 'none';
            if (multiPreviewEl) multiPreviewEl.style.display = 'none';
            if (mergeOptionsEl) mergeOptionsEl.style.display = 'none';
            previewEl.style.display = 'flex';
            if (uploadBtn) uploadBtn.classList.add('has-ref');

            if (statusEl) {
                statusEl.textContent = `✅ 已添加参考视频：${firstFile.name}`;
                statusEl.className = 'command-status success';
                setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'command-status'; }, 3000);
            }
        } catch (e) {
            console.error('视频处理失败:', e);
            if (statusEl) {
                statusEl.textContent = '❌ 视频处理失败';
                statusEl.className = 'command-status error';
                setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'command-status'; }, 3000);
            }
        }
        input.value = '';
        return;
    }

    // 🆕 处理多张图片
    if (statusEl) {
        statusEl.textContent = `📎 正在处理 ${files.length} 个文件...`;
        statusEl.className = 'command-status processing';
    }

    const imageFiles = Array.from(files).filter(f => f.type.startsWith('image/'));
    if (imageFiles.length === 0) {
        if (statusEl) {
            statusEl.textContent = '❌ 请上传图片或视频文件';
            statusEl.className = 'command-status error';
            setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'command-status'; }, 3000);
        }
        input.value = '';
        return;
    }

    // 检查文件大小
    for (const file of imageFiles) {
        if (file.size > 10 * 1024 * 1024) {
            if (statusEl) {
                statusEl.textContent = `❌ 图片 ${file.name} 过大，最大10MB`;
                statusEl.className = 'command-status error';
                setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'command-status'; }, 3000);
            }
            input.value = '';
            return;
        }
    }

    try {
        // 读取所有图片
        const newImages = await Promise.all(imageFiles.map(async file => {
            const base64 = await readFileAsDataURL(file);
            return { name: file.name, base64 };
        }));

        // 追加到列表
        window._commandRefImageList.push(...newImages.map(img => img.base64));

        // 更新UI
        const total = window._commandRefImageList.length;

        if (total === 1) {
            // 单图模式
            imgEl.src = window._commandRefImageList[0];
            imgEl.style.display = 'block';
            videoEl.style.display = 'none';
            if (multiPreviewEl) multiPreviewEl.style.display = 'none';
            if (mergeOptionsEl) mergeOptionsEl.style.display = 'none';
            previewEl.style.display = 'flex';

            window._commandRefData = { type: 'image', base64: window._commandRefImageList[0], name: newImages[0].name };
        } else {
            // 🆕 多图模式
            imgEl.style.display = 'none';
            videoEl.style.display = 'none';
            if (multiPreviewEl) {
                multiPreviewEl.style.display = 'flex';
                multiPreviewEl.innerHTML = window._commandRefImageList.map((data, idx) => `
                    <div style="position:relative; display:inline-block;">
                        <img src="${data}" style="width:48px; height:48px; object-fit:cover; border-radius:4px; border:1px solid #333;">
                        <button onclick="removeRefImage(${idx}); event.stopPropagation();" 
                            style="position:absolute; top:-6px; right:-6px; width:16px; height:16px; background:#f87171; border:none; border-radius:50%; color:#fff; font-size:10px; cursor:pointer; line-height:1;">×</button>
                    </div>
                `).join('');
            }
            if (mergeOptionsEl) mergeOptionsEl.style.display = 'block';
            if (imageCountEl) imageCountEl.textContent = total;
            previewEl.style.display = 'flex';

            // 多图时清空单图数据，生成时会合并
            window._commandRefData = { type: 'multi-image', imageList: window._commandRefImageList };
        }

        if (uploadBtn) uploadBtn.classList.add('has-ref');

        if (statusEl) {
            statusEl.textContent = total === 1
                ? `✅ 已添加参考图：${newImages[0].name}`
                : `✅ 已添加 ${total} 张参考图`;
            statusEl.className = 'command-status success';
            setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'command-status'; }, 3000);
        }

    } catch (e) {
        console.error('参考图片处理失败:', e);
        if (statusEl) {
            statusEl.textContent = '❌ 图片处理失败';
            statusEl.className = 'command-status error';
            setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'command-status'; }, 3000);
        }
    }

    input.value = '';
};

/**
 * 🆕 读取文件为DataURL
 */
function readFileAsDataURL(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

/**
 * 🆕 移除单张参考图
 */
window.removeRefImage = function (index) {
    window._commandRefImageList.splice(index, 1);

    const previewEl = document.getElementById('commandRefPreview');
    const imgEl = document.getElementById('refPreviewImg');
    const videoEl = document.getElementById('refPreviewVideo');
    const multiPreviewEl = document.getElementById('multiRefPreviewContainer');
    const mergeOptionsEl = document.getElementById('refMergeOptions');
    const imageCountEl = document.getElementById('refImageCount');
    const uploadBtn = document.querySelector('.command-upload-btn');

    const total = window._commandRefImageList.length;

    if (total === 0) {
        // 没有图片了
        window.removeCommandRef();
    } else if (total === 1) {
        // 切换回单图模式
        imgEl.src = window._commandRefImageList[0];
        imgEl.style.display = 'block';
        if (multiPreviewEl) multiPreviewEl.style.display = 'none';
        if (mergeOptionsEl) mergeOptionsEl.style.display = 'none';
        window._commandRefData = { type: 'image', base64: window._commandRefImageList[0] };
    } else {
        // 更新多图预览
        if (multiPreviewEl) {
            multiPreviewEl.innerHTML = window._commandRefImageList.map((data, idx) => `
                <div style="position:relative; display:inline-block;">
                    <img src="${data}" style="width:48px; height:48px; object-fit:cover; border-radius:4px; border:1px solid #333;">
                    <button onclick="removeRefImage(${idx}); event.stopPropagation();" 
                        style="position:absolute; top:-6px; right:-6px; width:16px; height:16px; background:#f87171; border:none; border-radius:50%; color:#fff; font-size:10px; cursor:pointer; line-height:1;">×</button>
                </div>
            `).join('');
        }
        if (imageCountEl) imageCountEl.textContent = total;
        window._commandRefData = { type: 'multi-image', imageList: window._commandRefImageList };
    }
};

