async function quickAddIdea(options = {}) {
    const {
        returnIdea = false,
        selectIdea = true,
        clearInput = true,
        automationLevelOverride = undefined
    } = (options && typeof options === 'object') ? options : {};
    const input = document.getElementById('quickIdeaInput');
    if (!input) {
        console.error('找不到quickIdeaInput元素');
        return alert('系统错误：找不到输入框');
    }
    const val = input.value.trim();
    if (!val) return alert('请输入创意内容');

    // 🧠 智能提示词解析：检测批量生成意图
    const smartResult = parseSmartPrompt(val);

    // 🆕 多主题独立任务：每个主题生成一张不同的图
    if (smartResult.type === 'multi_image' && smartResult.prompts && smartResult.prompts.length > 1) {
        console.log(`🎨 检测到多主题独立任务: ${smartResult.prompts.length}个不同主题`, smartResult.prompts);
        if (clearInput) input.value = '';
        // 为每个主题创建一个独立的图片节点
        for (let i = 0; i < smartResult.prompts.length; i++) {
            const prompt = smartResult.prompts[i];
            console.log(`  → 创建任务 ${i + 1}: "${prompt}"`);
            await batchCreateImageNodes(1, prompt, { autoRun: true, delayMs: i * 500 });
        }
        return;
    }

    if (smartResult.type === 'image' && smartResult.count > 1) {
        // 批量图片生成（相同提示词多张）
        console.log(`🎨 检测到批量图片生成意图: ${smartResult.count}张, 提示词: ${smartResult.prompt}`);
        if (clearInput) input.value = '';
        await batchCreateImageNodes(smartResult.count, smartResult.prompt, { autoRun: true });
        return;
    }
    if (smartResult.type === 'video' && smartResult.count > 1) {
        // 批量视频生成
        console.log(`🎬 检测到批量视频生成意图: ${smartResult.count}个, 提示词: ${smartResult.prompt}`);
        if (clearInput) input.value = '';
        await batchCreateVideoTasks(smartResult.count, smartResult.prompt, { autoRun: false });
        return;
    }

    const mode = document.getElementById('quickGenMode').value;

    // ✍️ 写作模式拦截：writing-novel / writing-script 等模式不应创建视频任务
    if (typeof mode === 'string' && mode.startsWith('writing-')) {
        if (clearInput) input.value = '';
        const numChapters = parseInt(document.getElementById('quickDuration')?.value) || 10;
        const wordNumber = parseInt(document.getElementById('quickScenes')?.value) || 2000;
        const writingIdea = __rrCreateWritingTaskData({ projectTitle: val });
        writingIdea.writing.novelConfig = __rrNormalizeNovelConfig({
            topic: val,
            genre: mode.replace('writing-', ''),
            num_chapters: numChapters,
            word_number: wordNumber
        });
        const pos = calculateNewTaskPosition();
        writingIdea.x = pos.x;
        writingIdea.y = pos.y;
        ideas.push(writingIdea);
        saveIdeasToHistory();
        renderIdeasList();
        renderCanvas();
        console.log('✍️ 写作任务已创建:', writingIdea.theme);
        if (typeof window.focusTaskWindow === 'function') {
            try { window.focusTaskWindow(String(writingIdea.id)); } catch (e) { }
        }
        if (returnIdea) return writingIdea;
        return;
    }

    const durInput = document.getElementById('quickDuration').value;   // ✅ 语义：总时长（秒）
    const scInput = document.getElementById('quickScenes').value;      // ✅ 语义：分镜数

    let totalDuration = durInput === '' ? 0 : parseInt(durInput);
    let scenes = scInput === '' ? 0 : parseInt(scInput);

    // 🔧 先根据生成模式设置正确的视频模型 + 固定分镜时长（用于总时长↔分镜换算）
    let videoModel = 'sora-2';
    if (mode === 'veo3.1' || mode === 'veo3.1-pro') videoModel = 'veo3.1';
    if (mode === 'grok-video-3' || mode === 'grok-video-3-text') videoModel = 'grok-video-3';
    if (mode === 'grok-video-3-10s' || mode === 'grok-video-3-10s-text') videoModel = 'grok-video-3-10s';
    if (mode === 'grok-video-3-15s' || mode === 'grok-video-3-15s-text') videoModel = 'grok-video-3-15s';
    videoModel = __normalizeVideoModelName(videoModel);
    let clipDuration = __getFixedClipDurationByModel(videoModel, undefined);

    // ✅ 用户填写了“总时长”，就直接换算分镜数，别让 AI 覆盖用户意图
    if (Number.isFinite(totalDuration) && totalDuration > 0 && (!Number.isFinite(scenes) || scenes <= 0)) {
        scenes = Math.ceil(totalDuration / clipDuration);
    }
    // ✅ 用户只填分镜数：推导总时长
    if (Number.isFinite(scenes) && scenes > 0 && (!Number.isFinite(totalDuration) || totalDuration <= 0)) {
        totalDuration = scenes * clipDuration;
    }

    // 🤖 智能参数分析：只有当“总时长 & 分镜数都没填”时才让 AI 推荐
    if (totalDuration === 0 && scenes === 0 && val.length >= 10) {
        const statusEl = document.querySelector('.voice-status');
        if (statusEl) {
            statusEl.textContent = '🤖 AI正在分析内容并推荐参数...';
            statusEl.style.color = '#60a5fa';
        }

        try {
            // 调用AI分析内容，推荐最佳参数
            const tempIdea = { theme: val, duration: 0, scenes: 0 };
            await analyzeContentStructure(tempIdea);

            // 使用AI推荐的参数
            totalDuration = tempIdea.duration || 45;
            scenes = tempIdea.scenes || Math.ceil(totalDuration / clipDuration) || 3;

            if (statusEl) {
                statusEl.textContent = `✅ AI推荐：时长${totalDuration}秒，${scenes}个分镜`;
                statusEl.style.color = '#10b981';
                setTimeout(() => {
                    statusEl.textContent = '支持连续对话，试试说出创意...';
                    statusEl.style.color = '#9ca3af';
                }, 3000);
            }
        } catch (e) {
            console.error('参数分析失败:', e);
            // 失败时使用保守默认值
            totalDuration = 45;
            scenes = Math.ceil(totalDuration / clipDuration) || 3;
        }
    }

    // 🔧 生成唯一ID，避免重复
    const uniqueId = Date.now() + Math.floor(Math.random() * 10000);

    // ✅ 统一分镜数/总时长的换算（解决“输入45秒却只出1个15秒片段/分镜乱”的根因）
    // - 用户填了分镜数：总时长=分镜数×单分镜时长
    // - 用户只填总时长：分镜数=ceil(总时长/单分镜时长)
    // - 两者都空：走上面的 AI 推荐（已经填充）
    if (!Number.isFinite(scenes) || scenes <= 0) scenes = 0;
    if (!Number.isFinite(totalDuration) || totalDuration <= 0) totalDuration = 0;
    if (scenes > 0 && totalDuration === 0) totalDuration = scenes * clipDuration;
    if (scenes === 0 && totalDuration > 0) scenes = Math.ceil(totalDuration / clipDuration);
    if (scenes === 0) scenes = 3; // 最小兜底：3镜更符合“故事短片”
    scenes = Math.min(Math.max(scenes, 1), 20);
    totalDuration = scenes * clipDuration;

    // 🎬 判断任务类型：连续性视频 / 常规视频
    const taskType = (mode === 'video-continuity') ? 'continuity' : 'video';

    const newIdea = {
        id: uniqueId,
        theme: val,
        type: taskType, // 🆕 连续性视频任务类型
        status: 'pending',
        automationLevel: (automationLevelOverride !== undefined ? automationLevelOverride : globalAutomationLevel),
        progress: 0,
        logs: [],
        stepLogs: [],
        videoResults: [],
        characterSheets: [],
        characterDescriptions: [],
        generatedScript: null,
        normalStoryboards: [],
        generatedVideoPrompts: [],
        generationMode: mode,
        videoModel: videoModel,  // 🔧 正确设置视频模型
        clipDuration: clipDuration,  // 🔧 正确设置分镜时长
        duration: clipDuration, // ⚠️ 兼容旧代码：duration 仍表示"单分镜时长"
        totalDuration: totalDuration,
        scenes: scenes,
        selected: false,
        forceRestart: true
    };

    // ✅ 同步 settings（后续流程优先读取 settings，避免“任务窗/流程窗不同步”）
    newIdea.settings = newIdea.settings || {};
    newIdea.settings.automationLevel = newIdea.automationLevel;
    newIdea.settings.videoModel = newIdea.videoModel;
    newIdea.settings.clipDuration = newIdea.clipDuration;
    newIdea.settings.sceneCount = newIdea.scenes;
    newIdea.settings.totalDuration = newIdea.totalDuration;
    newIdea.settings.generationMode = newIdea.generationMode;
    // 🕰️ 商用默认：不允许“现代↔古代”穿越漂移（除非后续显式开启）
    if (typeof newIdea.settings.allowTimeTravel === 'undefined') newIdea.settings.allowTimeTravel = false;
    // 🎨 从全局设置读取角色设定图开关（默认开启）
    if (typeof newIdea.settings.enableCharSheet === 'undefined') {
        const globalCharSheet = loadSettings().characterSheetEnabled;
        newIdea.settings.enableCharSheet = globalCharSheet !== false;
    }

    // ✅ 统一应用固定时长 + 自动换算分镜（最终兜底）
    try { __applyFixedVideoTimingToIdea(newIdea); } catch (e) { }

    // 🔧 智能计算不重叠的位置
    const pos = calculateNewTaskPosition();
    newIdea.x = pos.x;
    newIdea.y = pos.y;

    ideas.push(newIdea);
    if (clearInput) input.value = '';
    saveIdeasToHistory();

    console.log('✅ 新任务已添加:', newIdea.theme, '| 当前任务数:', ideas.length);

    // 强制刷新UI，确保任务立即显示
    renderIdeasList();
    renderCanvas();

    // 确保DOM更新后再选中
    if (selectIdea) {
        setTimeout(() => {
            window.toggleIdeaSelection(newIdea.id);
        }, 100);
    }

    // 显示成功提示
    console.log('📋 任务列表已更新');
    if (returnIdea) return newIdea;
}

function toggleIdeaSelection(id) {
    const idea = ideas.find(i => i.id === id);
    if (idea) {
        idea.selected = !idea.selected;
        saveIdeasToHistory();
        renderIdeasList();
        updateBatchButton();
    }
}

