    // 🔧 显示/隐藏 HD 选项（仅 sora-2-pro 支持）
    if (hdSettingItem) {
        hdSettingItem.style.display = (model === 'sora-2-pro') ? '' : 'none';
    }

    // 固定时长：veo=8 / grok=6 / sora2=15；sora2-pro 支持 15/25
    if (model === 'sora-2-pro') {
        const hdCheckbox = document.getElementById('set-videoHD');
        const isHD = hdCheckbox ? hdCheckbox.checked : true;
        const cur = isHD ? 15 : 25;
        clipSelect.innerHTML = `
            <option value="15" ${(cur === 15) ? 'selected' : ''}>15秒（Pro HD 1080p）</option>
            <option value="25" ${(cur === 25) ? 'selected' : ''}>25秒（Pro 720p）</option>
        `;
        clipSelect.value = String(cur);
        clipSelect.disabled = false;
    } else {
        const d = __getFixedClipDurationByModel(model, undefined);
        clipSelect.innerHTML = `<option value="${d}" selected>${d}秒（固定）</option>`;
        clipSelect.disabled = true;
    }

