/**
 * 🔄 轮询RH任务状态
 */
async function pollRHTask(taskId, apiKey) {
    const maxAttempts = 60; // 最多轮询60次（3分钟）
    console.log(`⏳ 开始轮询 RH 任务: ${taskId}`);

    for (let i = 0; i < maxAttempts; i++) {
        await sleep(3000); // 每3秒轮询一次

        try {
            // 直接调用 RunningHub API 查询任务状态
            const response = await fetch(`https://www.runninghub.cn/task/openapi/ai-app/result/${taskId}`, {
                method: 'GET',
                headers: {
                    'Authorization': `Bearer ${apiKey}`
                }
            });

            if (!response.ok) {
                console.warn(`轮询请求失败: ${response.status}`);
                continue;
            }

            const result = await response.json();
            const status = result.data?.result?.taskStatus || result.data?.taskStatus || result.taskStatus;

            console.log(`📡 RH 任务状态: ${status} (${i + 1}/${maxAttempts})`);

            if (status === 'SUCCESS' || status === 'COMPLETED') {
                // 提取图片URL
                const outputs = result.data?.result?.outputNodeList || result.data?.outputNodeList || result.outputNodeList || [];
                const imageOutputs = outputs.filter(o =>
                    o.type === 'image' ||
                    o.type === 'IMAGE' ||
                    (o.fieldValue && (o.fieldValue.startsWith('http') || o.fieldValue.includes('image')))
                );

                if (imageOutputs.length > 0) {
                    // 优先返回第一个图片
                    const imageUrl = imageOutputs[0].fieldValue || imageOutputs[0].value;
                    console.log(`✅ RH任务完成，获取到图片URL: ${imageUrl}`);
                    return imageUrl;
                }

                console.error('RH 返回数据:', result);
                throw new Error('任务完成但未找到图片输出');
            } else if (status === 'FAILED' || status === 'FAILURE' || status === 'ERROR') {
                const errMsg = result.data?.result?.errorMsg || result.data?.errorMsg || '未知错误';
                throw new Error(`RH任务失败: ${errMsg}`);
            }

            // 继续轮询
        } catch (pollError) {
            if (pollError.message.includes('RH任务失败')) {
                throw pollError; // 直接抛出任务失败错误
            }
            console.warn(`轮询出错: ${pollError.message}`);
        }
    }

    throw new Error('RH任务超时');
}

/**
 * 构建角色设定上下文（用于提示词生成）
 * @param {Array} sheets - 角色设定数组
 * @returns {string} 格式化的角色描述文本
 */
function buildCharacterContext(sheets, fallbackDescriptions = []) {
    const hasSheets = Array.isArray(sheets) && sheets.length > 0;
    const hasFallback = Array.isArray(fallbackDescriptions) && fallbackDescriptions.length > 0;
    if (!hasSheets && !hasFallback) return '';

    const list = hasSheets ? sheets : fallbackDescriptions;
    return list.map((s, idx) => {
        const name = s?.name || `角色${idx + 1}`;
        // 过滤非视觉角色（系统/旁白/VO）
        if (/(系统|旁白|VO|V\.O|voice|narrator)/i.test(String(name))) return '';
        const summary = s?.summary || s?.description || '';
        const img = s?.imageUrl || s?.variants?.poster || s?.variants?.turnaround || '';
        let desc = `角色${idx + 1}：${name}`;
        if (summary) desc += `\n描述：${summary}`;
        if (img) {
            desc += `\n设定图：${img}`;
            desc += `\n⚠️ 必须严格参考此角色设定图的外观特征（发型/服装/体型/脸型），全片保持一致！`;
        } else {
            desc += `\n⚠️ 必须在全片保持一致：发型/服装/体型/脸型不得变化（不要每镜换脸换衣）！`;
        }
        return desc;
    }).filter(Boolean).join('\n\n');
}

function addStepLog(idea, text, status) {
    if (!idea.steps) idea.steps = [];
    idea.steps.push({ text, status: status || 'processing' });

    // 🆕 同时更新遮罩层的实时步骤显示
    updateCineStepDisplay(text, status);
}

/**
 * 更新遮罩层的实时步骤显示
 * @param {string} text - 步骤文本
 * @param {string} status - 状态 (processing/completed/failed/warning/info/paused)
 */
function updateCineStepDisplay(text, status) {
    const stepList = document.getElementById('cineStepList');
    if (!stepList) return;

    // 状态对应的图标和颜色
    const statusConfig = {
        'processing': { icon: '⏳', color: '#60a5fa', bg: 'rgba(96,165,250,0.1)' },
        'completed': { icon: '✅', color: '#22c55e', bg: 'rgba(34,197,94,0.1)' },
        'failed': { icon: '❌', color: '#ef4444', bg: 'rgba(239,68,68,0.1)' },
        'warning': { icon: '⚠️', color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' },
        'info': { icon: 'ℹ️', color: '#94a3b8', bg: 'transparent' },
        'paused': { icon: '⏸️', color: '#a78bfa', bg: 'rgba(167,139,250,0.1)' }
    };

    const config = statusConfig[status] || statusConfig['info'];

    // 如果是 info 类型且是分割线，跳过
    if (status === 'info' && (text.includes('━━━') || text.startsWith('【'))) {
        return; // 不在遮罩层显示详细内容，保持简洁
    }

    // 创建步骤项
    const stepItem = document.createElement('div');
    stepItem.style.cssText = `
        display: flex;
        align-items: flex-start;
        gap: 8px;
        padding: 6px 10px;
        background: ${config.bg};
        border-radius: 6px;
        border-left: 3px solid ${config.color};
        animation: fadeInStep 0.3s ease-out;
    `;

    // 截断过长的文本
    const displayText = text.length > 60 ? text.substring(0, 60) + '...' : text;

    stepItem.innerHTML = `
        <span style="flex-shrink: 0;">${config.icon}</span>
        <span style="color: ${config.color}; word-break: break-word;">${displayText}</span>
    `;

    // 如果是 processing 状态，更新之前的 processing 项为完成（如果有的话）
    if (status === 'processing') {
        // 找到最后一个 processing 项并更新
        const lastProcessing = stepList.querySelector('[data-status="processing"]');
        if (lastProcessing) {
            lastProcessing.style.opacity = '0.5';
            lastProcessing.removeAttribute('data-status');
        }
        stepItem.setAttribute('data-status', 'processing');
    }

    stepList.appendChild(stepItem);

    // 自动滚动到底部
    const resultsContainer = document.getElementById('cineStepResults');
    if (resultsContainer) {
        resultsContainer.scrollTop = resultsContainer.scrollHeight;
    }

    // 限制显示的步骤数量（保留最新的15条）
    while (stepList.children.length > 15) {
        stepList.removeChild(stepList.firstChild);
    }
}

function saveIdeasToHistory() {
    try {
        // 🔧 更新所有任务的 updated_at 时间戳，用于三端同步时的冲突检测
        const now = new Date().toISOString();
        ideas.forEach(idea => {
            if (idea) idea.updated_at = now;
        });

        localStorage.setItem('ideas_history', JSON.stringify(ideas));

        // 🔧 修复：保存 flowNodes 前清理大型数据（如切图的 base64）
        const cleanedFlowNodes = flowNodes.map(node => {
            const cleaned = { ...node };
            if (cleaned.data) {
                cleaned.data = { ...cleaned.data };
                if (cleaned.data.generatedImage && cleaned.data.generatedImage.startsWith('data:') && cleaned.data.generatedImage.length > 200000) {
                    console.log(`🧹 清理节点 ${node.id} 的生成图 dataURI（过大，不写入本地存储）`);
                    cleaned.data.generatedImage = '';
                }
                if (cleaned.data.generatedImageDataUrl && cleaned.data.generatedImageDataUrl.startsWith('data:') && cleaned.data.generatedImageDataUrl.length > 200000) {
                    console.log(`🧹 清理节点 ${node.id} 的生成图 dataUrl 缓存（过大，不写入本地存储）`);
                    cleaned.data.generatedImageDataUrl = '';
                }
                // 清理表情包切图数据（太大会超出配额）
                if (cleaned.data.slices && cleaned.data.slices.length > 0) {
                    // 只保留切图的索引和基本信息，不保存 dataUrl
                    cleaned.data.slices = cleaned.data.slices.map(slice => ({
                        index: slice.index,
                        // 不保存 dataUrl，太大了
                    }));
                    console.log(`🧹 清理节点 ${node.id} 的切图数据以节省存储空间`);
                }
                // 🔧 保留绘图画布数据（用户手绘内容很重要，不再清理）
                // 如果确实太大（超过2MB），才压缩
                if (cleaned.data.drawingData && cleaned.data.drawingData.length > 2000000) {
                    console.log(`⚠️ 节点 ${node.id} 画布数据较大（${(cleaned.data.drawingData.length / 1024).toFixed(1)}KB），但保留用户绘制内容`);
                    // 不再清空，只是警告
                }
                // 清理表情包原图数据（如果是 base64）
                if (cleaned.data.sheetDataUrl && cleaned.data.sheetDataUrl.startsWith('data:') && cleaned.data.sheetDataUrl.length > 100000) {
                    console.log(`🧹 清理节点 ${node.id} 的表情包原图数据`);
                    // 保留 sheetUrl（远程URL），清除 sheetDataUrl（本地base64）
                    cleaned.data.sheetDataUrl = '';
                }
            }
            return cleaned;
        });

        localStorage.setItem('flow_nodes', JSON.stringify(cleanedFlowNodes));
        localStorage.setItem('node_connections', JSON.stringify(connections));

        // 🔧 保存已删除的任务ID到本地
        localStorage.setItem('deleted_task_ids', JSON.stringify(deletedTaskIds));
    } catch (e) {
        if (e.name === 'QuotaExceededError' || e.message.includes('quota')) {
            console.error('❌ localStorage 配额超限，尝试清理旧数据...');

            // 紧急清理：删除最旧的任务
            if (ideas.length > 10) {
                const oldestIdeas = ideas.slice(0, ideas.length - 10);
                ideas = ideas.slice(-10);
                console.log(`🧹 紧急清理：删除了 ${oldestIdeas.length} 个旧任务`);

                // 重试保存
                try {
                    localStorage.setItem('ideas_history', JSON.stringify(ideas));
                    localStorage.setItem('flow_nodes', JSON.stringify([])); // 清空节点
                    alert('⚠️ 存储空间不足，已自动清理旧数据。部分画板节点数据可能丢失。');
                } catch (e2) {
                    console.error('❌ 紧急清理后仍然失败:', e2);
                    alert('❌ 存储空间严重不足！请手动清理浏览器数据或删除部分任务。');
                }
            }
        } else {
            console.error('保存失败:', e);
        }
    }

    // 🔧 自动同步到云端（防抖，避免频繁调用）
    if (window._syncToCloudTimeout) {
        clearTimeout(window._syncToCloudTimeout);
    }

    // 🔧 捕获当前的deletedTaskIds副本
    const currentDeletedIds = [...deletedTaskIds];

    window._syncToCloudTimeout = setTimeout(async () => {
        try {
            // ✅ 没有任务且没有删除队列：完全不触发任何云端请求（减少卡顿）
            if ((!Array.isArray(ideas) || ideas.length === 0) && (!Array.isArray(currentDeletedIds) || currentDeletedIds.length === 0)) {
                return;
            }
            if (typeof NVAuth === 'undefined') return;

            // 🔧 先做“变化签名”去重：无变化直接 return（连 getCurrentUser 都不打）
            const syncSig = (() => {
                try {
                    const ids = (Array.isArray(ideas) ? ideas : [])
                        .map(i => `${i?.id ?? ''}:${i?.updated_at ?? i?.updatedAt ?? ''}:${i?.status ?? ''}`)
                        .join('|');
                    const dels = Array.isArray(currentDeletedIds) ? currentDeletedIds.join(',') : '';
                    return `v2|n=${Array.isArray(ideas) ? ideas.length : 0}|ids=${ids}|del=${dels}`;
                } catch (e) {
                    return `v2|n=${Array.isArray(ideas) ? ideas.length : 0}|del=${Array.isArray(currentDeletedIds) ? currentDeletedIds.length : 0}`;
                }
            })();
            if (window._lastCloudSyncSig === syncSig) return;
            window._lastCloudSyncSig = syncSig;

            // 🔧 性能修复：避免频繁 getCurrentUser() 触发网络请求（缓存 5 分钟）
            let user = window._nvCachedUser || null;
            const now = Date.now();
            if (!user || !window._nvCachedUserAt || (now - window._nvCachedUserAt) > 5 * 60 * 1000) {
                user = await NVAuth.getCurrentUser();
                if (user) {
                    window._nvCachedUser = user;
                    window._nvCachedUserAt = now;
                }
            }
            if (!user) return;

            // 🔧 传递已删除的任务ID
            await NVAuth.syncTasksToCloud(ideas, currentDeletedIds);
            if (localStorage.getItem('rr_debug') === '1') {
                console.log('✅ 任务已自动同步到云端，删除了', currentDeletedIds.length, '个任务');
            }

            // 🔧 同步成功后清空已删除的ID（它们已经在云端标记删除了）
            deletedTaskIds = deletedTaskIds.filter(id => !currentDeletedIds.includes(id));
            localStorage.setItem('deleted_task_ids', JSON.stringify(deletedTaskIds));
        } catch (err) {
            console.warn('自动同步任务失败:', err);
        }
    }, 3000); // 3秒防抖
}

function loadIdeasFromHistory() {
    // 🔧 恢复已删除的任务ID列表
    try {
        const savedDeletedIds = JSON.parse(localStorage.getItem('deleted_task_ids') || '[]');
        deletedTaskIds = savedDeletedIds;
        console.log('📝 已恢复待删除ID列表:', deletedTaskIds.length, '个');
    } catch (e) {
        deletedTaskIds = [];
    }

    // ✅ 修复：防止旧数据中存在 NaN/非法坐标导致任务窗渲染为 NaNpx（表现为“闪一下就丢/找不到”）
    let loaded = [];
    try {
        loaded = JSON.parse(localStorage.getItem('ideas_history') || '[]');
    } catch (e) {
        loaded = [];
    }
    if (!Array.isArray(loaded)) loaded = [];
    loaded.forEach((idea) => {
        if (!idea) return;
        if (!Number.isFinite(idea.x)) idea.x = 50;
        if (!Number.isFinite(idea.y)) idea.y = 50;
        // 限制极端值（避免被推到宇宙尽头）
        idea.x = Math.max(-50000, Math.min(50000, idea.x));
        idea.y = Math.max(-50000, Math.min(50000, idea.y));
    });
    return loaded;
}

function clearHistory() {
    if (confirm('确定清空所有历史记录吗？')) {
        // 记录当前所有任务ID，后续需要同步删除
        const idsToDelete = ideas
            .map(i => i.id)
            .filter(id => id !== undefined && id !== null);

        // 将这些ID加入删除列表，避免刷新后又从云端加载回来
        if (idsToDelete.length > 0) {
            const existingIds = new Set(deletedTaskIds);
            idsToDelete.forEach(id => {
                if (!existingIds.has(id)) {
                    deletedTaskIds.push(id);
                }
            });
            localStorage.setItem('deleted_task_ids', JSON.stringify(deletedTaskIds));
        }

        ideas = [];
        flowNodes = [];
        _setConnections([]);

        // 立即清空本地缓存，避免刷新后又出现
        localStorage.setItem('ideas_history', '[]');
        localStorage.setItem('flow_nodes', '[]');
        localStorage.setItem('node_connections', '[]');

        // ⚡ 确保全局变量与内存变量同步清空
        if (typeof window.flowNodes !== 'undefined') window.flowNodes = [];
        window.connections = connections;

        saveIdeasToHistory();
        renderIdeasList();
        renderCanvas();
        updateBatchButton();

        // 立即同步云端，防止刷新后又拉取历史记录
        (async () => {
            try {
                if (typeof NVAuth !== 'undefined') {
                    const user = await NVAuth.getCurrentUser();
                    if (user) {
                        await NVAuth.syncTasksToCloud([], idsToDelete);
                        console.log('🗑️ 已将历史记录清空并同步到云端');
                    }
                }
            } catch (err) {
                console.warn('⚠️ 清空历史记录后同步云端失败，可稍后自动同步:', err);
            }
        })();
    }
}
const clearAllIdeas = clearHistory;

