function setupNodeDragDrop(nodeId) {
    const dropZone = document.getElementById(`drop-${nodeId}`);
    if (!dropZone) return;

    dropZone.addEventListener('dragover', e => {
        e.preventDefault();
        dropZone.style.borderColor = 'var(--accent-gold)';
        dropZone.style.backgroundColor = 'rgba(212, 175, 55, 0.1)';
    });

    dropZone.addEventListener('dragleave', e => {
        e.preventDefault();
        dropZone.style.borderColor = '#444';
        dropZone.style.backgroundColor = 'transparent';
    });

    dropZone.addEventListener('drop', e => {
        e.preventDefault();
        dropZone.style.borderColor = '#444';
        dropZone.style.backgroundColor = 'transparent';

        if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
            handleNodeUpload(nodeId, { files: e.dataTransfer.files });
        }
    });
}

const MAX_REF_IMAGE_BYTES = 4 * 1024 * 1024; // 4MB
const MAX_REF_IMAGE_SIDE = 2048;

async function compressImageFile(file, maxSide = MAX_REF_IMAGE_SIDE, quality = 0.85) {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let { width, height } = img;
            const scale = Math.min(1, maxSide / Math.max(width, height));
            width = Math.round(width * scale);
            height = Math.round(height * scale);
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0, width, height);
            canvas.toBlob(blob => {
                if (!blob) return reject(new Error('压缩失败'));
                const reader = new FileReader();
                reader.onload = () => resolve(reader.result);
                reader.onerror = reject;
                reader.readAsDataURL(blob);
            }, 'image/jpeg', quality);
        };
        img.onerror = reject;
        img.src = URL.createObjectURL(file);
    });
}

async function compressDataUrl(dataUrl, maxSide = 1400, quality = 0.8) {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const scale = Math.min(1, maxSide / Math.max(img.width, img.height));
            const width = Math.round(img.width * scale);
            const height = Math.round(img.height * scale);
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality));
        };
        img.onerror = reject;
        img.src = dataUrl;
    });
}

/**
 * 🎨 将手绘图转换为黑白草图风格（适用于 Midjourney）
 * 提取线条，去除白色背景，增强对比度
 */
async function convertToSketchStyle(dataUrl) {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.width;
            canvas.height = img.height;
            const ctx = canvas.getContext('2d');

            // 1. 绘制原图
            ctx.drawImage(img, 0, 0);

            // 2. 获取像素数据
            const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const data = imageData.data;

            // 3. 图像处理：提取线条，去除背景
            for (let i = 0; i < data.length; i += 4) {
                const r = data[i];
                const g = data[i + 1];
                const b = data[i + 2];
                const a = data[i + 3];

                // 计算亮度（灰度值）
                const brightness = (r + g + b) / 3;

                // 🔑 关键逻辑：
                // - 白色背景 (brightness > 240) → 透明
                // - 浅色区域 (brightness > 200) → 淡化
                // - 深色线条 (brightness < 200) → 保留并增强
                if (brightness > 240) {
                    // 白色背景：设为透明
                    data[i] = 255;
                    data[i + 1] = 255;
                    data[i + 2] = 255;
                    data[i + 3] = 0;  // 完全透明
                } else if (brightness > 200) {
                    // 浅色区域：淡化
                    const fade = (brightness - 200) / 40;  // 0-1
                    data[i + 3] = Math.round(a * (1 - fade * 0.8));
                } else {
                    // 深色线条：转换为黑色，增强对比
                    const darkness = Math.max(0, 200 - brightness) / 200;  // 0-1
                    const newValue = Math.round(brightness * (1 - darkness * 0.5));  // 增强暗部
                    data[i] = newValue;
                    data[i + 1] = newValue;
                    data[i + 2] = newValue;
                    // 保持原始透明度，略微增强
                    data[i + 3] = Math.min(255, a * 1.1);
                }
            }

            // 4. 写回画布
            ctx.putImageData(imageData, 0, 0);

            // 5. 输出为 PNG（支持透明度）
            resolve(canvas.toDataURL('image/png'));
        };
        img.onerror = reject;
        img.src = dataUrl;
    });
}

async function readImageFile(file) {
    if (file.size <= MAX_REF_IMAGE_BYTES) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(reader.result);
            reader.onerror = reject;
            reader.readAsDataURL(file);
        });
    }
    return compressImageFile(file);
}

async function blobToDataURL(blob) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(blob);
    });
}

async function fetchImageAsDataURL(url) {
    try {
        const direct = await fetch(url);
        if (!direct.ok) throw new Error('fetch failed');
        const blob = await direct.blob();
        return await blobToDataURL(blob);
    } catch (err) {
        console.warn('⚠️ 直接获取图片失败，使用代理尝试:', err.message);
        const proxyRes = await fetch(`${PROXY_ENDPOINT}?method=GET`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ targetUrl: url, method: 'GET' })
        });
        if (!proxyRes.ok) throw new Error(`代理获取图片失败 (${proxyRes.status})`);
        // 🔧 代理返回 JSON 格式，包含 dataUrl 字段
        const data = await proxyRes.json();
        if (data.dataUrl) {
            return data.dataUrl;
        }
        // 兼容旧格式：如果返回的是 blob
        if (data.data) {
            return data.data;
        }
        throw new Error('代理未返回有效图片数据');
    }
}

async function handleNodeUpload(nodeId, input) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    // 🔧 兼容 FileList 和 input 元素
    const files = input?.files || input;
    if (!files || files.length === 0) return;

    // 初始化 refImages 数组
    if (!node.data.refImages) node.data.refImages = [];

    const fileArr = Array.from(files);
    const existingUrls = new Set((node.data.refImages || []).map(x => x?.url).filter(Boolean));
    const existingNameSize = new Set((node.data.refImages || []).map(x => `${x?.name || ''}::${x?.size || ''}`));

    for (const file of fileArr) {
        try {
            const dataUrl = await readImageFile(file);
            // ✅ 去重：同一张图不重复添加
            const nsKey = `${file.name || ''}::${file.size || ''}`;
            if (existingUrls.has(dataUrl) || existingNameSize.has(nsKey)) {
                console.log(`⏭️ 跳过重复参考图: ${file.name}`);
                continue;
            }
            const byteSize = Math.round((dataUrl.length * 3) / 4);
            if (byteSize > MAX_REF_IMAGE_BYTES) {
                alert(`⚠️ ${file.name} 压缩后仍超过 4MB，请先压缩再上传`);
                continue;
            }
            node.data.refImages.push({
                id: 'ref_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
                url: dataUrl,
                name: file.name,
                size: file.size
            });
            existingUrls.add(dataUrl);
            existingNameSize.add(nsKey);
            updateNodeRefImages(nodeId);
            updateNodeImageIndex(nodeId);  // 🆕 分配图像编号
            saveIdeasToHistory();
            console.log(`✅ 参考图已添加: ${file.name}`);
        } catch (err) {
            console.error('参考图读取失败:', err);
            alert(`⚠️ 无法读取 ${file.name}，请尝试使用更小的图片`);
        }
    }

    // ✅ 清空 input.value：允许用户重复选择同一张图也能触发 change
    try {
        if (input && input.tagName === 'INPUT') input.value = '';
    } catch (e) { }
}

async function ensureEditableDataUrl(node, url) {
    if (!url) return null;
    if (url.startsWith('data:')) return url;
    if (node.data.generatedImageDataUrl) return node.data.generatedImageDataUrl;
    const dataUrl = await fetchImageAsDataURL(url);
    node.data.generatedImageDataUrl = dataUrl;
    return dataUrl;
}

function loadImageOntoCanvas(nodeId, dataUrl, { markHasEdits = false, silent = false } = {}) {
    if (!dataUrl) return;
    const canvas = document.querySelector(`#node-${nodeId} canvas`);
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const img = new Image();
    img.onload = () => {
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        const scale = Math.min(canvas.width / img.width, canvas.height / img.height);
        const drawW = img.width * scale;
        const drawH = img.height * scale;
        const offsetX = (canvas.width - drawW) / 2;
        const offsetY = (canvas.height - drawH) / 2;
        ctx.drawImage(img, offsetX, offsetY, drawW, drawH);

        const node = flowNodes.find(n => n.id === nodeId);
        if (node) {
            node.data.drawingData = canvas.toDataURL();
            node.data.generatedImageDataUrl = node.data.drawingData;
            node.data.hasEdits = !!markHasEdits;
            saveIdeasToHistory();
        }
        if (!silent) {
            console.log('🎨 已载入图片到画布，可继续涂抹。');
        }
    };
    img.onerror = (err) => {
        console.warn('无法加载图片到画布', err);
    };
    img.src = dataUrl;
}

async function applyResultToCanvas(nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node || !node.data.generatedImage) {
        alert('当前没有可载入的生成图片');
        return;
    }
    try {
        const dataUrl = await ensureEditableDataUrl(node, node.data.generatedImage);
        loadImageOntoCanvas(nodeId, dataUrl, { markHasEdits: false });
        alert('✅ 已载入生成图片到画布，可直接使用画笔局部修改');
    } catch (err) {
        console.error('载入生成图片失败:', err);
        alert('⚠️ 无法载入生成图片，请稍后重试');
    }
}

function updateNodeRefImages(nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    // 🔧 查找或创建参考图容器
    let container = document.getElementById(`refs-${nodeId}`);
    if (!container) {
        // 在上传区域后面创建容器
        const uploadZone = document.querySelector(`#node-${nodeId} .image-upload-zone`);
        if (uploadZone) {
            container = document.createElement('div');
            container.id = `refs-${nodeId}`;
            container.className = 'ref-images-container';
            container.style.cssText = 'display:flex; flex-wrap:wrap; gap:5px; padding:5px 10px; max-height:100px; overflow-y:auto;';
            uploadZone.parentNode.insertBefore(container, uploadZone.nextSibling);
        }
    }
    if (!container) return;

    const refImages = node.data.refImages || [];
    // ✅ 横向缩略图条：不裁切，点击可看大图
    container.style.cssText = 'display:flex; flex-wrap:nowrap; gap:6px; padding:6px 10px; overflow-x:auto; overflow-y:hidden; scrollbar-gutter: stable both-edges;';
    container.innerHTML = refImages.length > 0 ? refImages.map((img) => `
        <div class="ref-img-item" style="position:relative; width:64px; height:64px; border-radius:6px; overflow:hidden; border:1px solid #444; cursor:pointer; background:#0b0b0b;" title="${img.name || '参考图'}" onclick="event.stopPropagation(); window.open('${img.url}')">
            <img src="${img.url}" style="width:100%; height:100%; object-fit:contain; display:block;">
            <div class="ref-remove-overlay" onclick="event.stopPropagation(); removeNodeRef('${nodeId}', '${img.id}')" style="position:absolute; top:0; right:0; width:16px; height:16px; background:rgba(239,68,68,0.9); color:#fff; font-size:12px; display:flex; align-items:center; justify-content:center; cursor:pointer; border-radius:0 0 0 4px;">×</div>
        </div>
    `).join('') : '';
}

function removeNodeRef(nodeId, imgId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (node && node.data.refImages) {
        node.data.refImages = node.data.refImages.filter(img => img.id !== imgId);
        updateNodeRefImages(nodeId);
        saveIdeasToHistory();
        console.log(`🗑️ 参考图已移除: ${imgId}`);
    }
}

// 🔧 暴露到全局
