function getNodeFinalPrompt(node) {
    if (!node || !node.data) return '';
    // 🔧 修复：同时检查 customPrompt（批量创建节点使用）
    const basePrompt = (node.data.knollingPrompt || node.data.customPrompt || '').trim();
    const supplement = (node.data.prompt || '').trim();

    if (basePrompt && supplement) {
        return `${basePrompt}\n\n补充描述:\n${supplement}`;
    }
    return basePrompt || supplement;
}

/**
 * 🔄 递归获取上游节点的提示词（穿透空节点）
 * @param {string} nodeId - 当前节点ID
 * @param {Set} visited - 已访问节点集合（防止循环）
 * @returns {string[]} - 收集到的提示词数组
 */
function collectUpstreamPrompts(nodeId, visited = new Set()) {
    const nid = String(nodeId);
    if (visited.has(nid)) return []; // 防止循环引用
    visited.add(nid);

    const prompts = [];
    const incomingConnections = connections.filter(c => String(c.target) === nid);

    incomingConnections.forEach(conn => {
        // 🔧 修复：同时检查 flowNodes 和 ideas (任务卡片)
        let sourceNode = flowNodes.find(n => String(n.id) === String(conn.source));
        let sourcePrompt = '';

        console.log(`%c🔍 检查上游连接: ${conn.source} -> ${nid}`, 'color: orange; font-weight: bold;');
        console.log(`   sourceNode存在: ${!!sourceNode}`);

        if (sourceNode) {
            console.log(`   sourceNode.type: "${sourceNode.type}"`);
            console.log(`   sourceNode.data:`, JSON.stringify(sourceNode.data || {}, null, 2).substring(0, 200));
            console.log(`   generatedPrompt: "${(sourceNode.data?.generatedPrompt || '【空】').substring(0, 50)}"`);
            console.log(`   knollingPrompt: "${(sourceNode.data?.knollingPrompt || '【空】').substring(0, 50)}"`);

            // ✅ Prompt Template 节点批量输出：优先收集 prompts 列表（支持 A|B|C 批量）
            try {
                const list = (sourceNode.data && (sourceNode.data.promptTemplateAllPrompts || sourceNode.data.generatedPromptsList)) || [];
                if (Array.isArray(list) && list.length > 0) {
                    const cleaned = list.map(x => String(x || '').trim()).filter(Boolean);
                    if (cleaned.length > 0) {
                        prompts.push(...cleaned);
                        console.log(`%c✅ 策略A2命中 (prompt list) x${cleaned.length}`, 'color: lime; font-weight: bold;');
                        return; // ⛔ 本连接已收集到多条提示词，无需继续回溯
                    }
                }
            } catch (e) { }

            // 策略 A: 提示词工坊 / Knolling 节点
            if (sourceNode.data && sourceNode.data.generatedPrompt) {
                sourcePrompt = sourceNode.data.generatedPrompt.trim();
                console.log(`%c✅ 策略A命中 (generatedPrompt)`, 'color: lime; font-weight: bold;');
            }
            // 策略 B: Banana 节点 (作为上游)
            else if (sourceNode.type === 'banana-draw' || !sourceNode.type) {
                sourcePrompt = (sourceNode.data.knollingPrompt || sourceNode.data.prompt || '').trim();
            }
            // 策略 C: Sticker 节点
            else if (sourceNode.type === 'sticker') {
                sourcePrompt = (sourceNode.data.customPrompt || '').trim();
            }
            // 策略 D: Sketchpad 节点
            else if (sourceNode.type === 'sketchpad') {
                sourcePrompt = (sourceNode.data.prompt || '').trim();
            }
        } else {
            // 🆕 策略 E: 任务卡片 (ideas) - 作为上游
            const sourceIdea = ideas.find(i => String(i.id) === String(conn.source));
            if (sourceIdea) {
                // 优先使用生成的剧本，其次使用主题
                sourcePrompt = (sourceIdea.generatedScript || sourceIdea.theme || '').trim();
                console.log(`📋 从任务卡片获取提示词: ${sourcePrompt.substring(0, 50)}...`);
            }
        }

        // ✅ 修复：收集当前节点的提示词
        if (sourcePrompt) {
            prompts.push(sourcePrompt);
            console.log(`%c✅ 收集到提示词: "${sourcePrompt.substring(0, 50)}..."`, 'color: lime; font-weight: bold;');
        }

        // ✅ 关键修复：无论当前节点是否有提示词，都继续递归收集它的上游节点的提示词
        // 这样可以实现"节点1 -> 节点2 -> 节点3"时，节点3能同时看到节点1和节点2的提示词
        if (sourceNode) {
            console.log(`%c🔄 继续向上游递归: ${conn.source}`, 'color: cyan;');
            const upstreamPrompts = collectUpstreamPrompts(conn.source, visited);
            if (upstreamPrompts.length > 0) {
                console.log(`%c✅ 从上游收集到 ${upstreamPrompts.length} 个提示词`, 'color: lime;');
                prompts.push(...upstreamPrompts);
            }
        }
    });

    return prompts;
}

function updateNodeAutoPromptDisplay(nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    // 🔄 使用递归函数收集上游提示词（可穿透空节点）
    // 🔧 修复：传入空集合，让函数自己处理visited
    const accumulatedPrompts = collectUpstreamPrompts(nodeId, new Set());

    // 聚合结果（去重）
    const finalPrompt = [...new Set(accumulatedPrompts)].join('\n\n');

    // 🔧 关键：无论DOM是否存在，都要更新节点数据
    console.log(`%c📝 updateNodeAutoPromptDisplay(${nodeId})`, 'color: cyan; font-weight: bold;');
    console.log(`   收集到的提示词数量: ${accumulatedPrompts.length}`);
    console.log(`   finalPrompt: "${finalPrompt.substring(0, 100)}..."`);

    if (node.data) {
        node.data.knollingPrompt = finalPrompt;
    }

    // 更新 DOM 显示（如果存在）
    const box = document.getElementById(`auto-prompt-box-${nodeId}`);
    const textEl = document.getElementById(`auto-prompt-${nodeId}`);
    console.log(`   DOM元素: box=${!!box}, textEl=${!!textEl}`);

    if (box && textEl) {
        if (finalPrompt) {
            textEl.textContent = finalPrompt;
            box.style.display = 'block';
            console.log(`   ✅ 已显示提示词区域`);

            const titleEl = box.querySelector('.auto-prompt-title');
            if (titleEl) {
                const uniqueCount = [...new Set(accumulatedPrompts)].length;
                titleEl.textContent = uniqueCount > 1 ? `📝 引用提示词 (${uniqueCount}个来源)` : '📝 引用提示词';
            }
        } else {
            textEl.textContent = '';
            box.style.display = 'none';
            console.log(`   ⚠️ 提示词为空，隐藏区域`);
        }
    } else {
        console.log(`   ❌ DOM元素不存在，无法更新显示`);
    }

    return finalPrompt;  // 🆕 返回结果供调用者使用
}

window.updateNodeAutoPromptDisplay = updateNodeAutoPromptDisplay;

async function generateNodeImage(nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    // 🔧 1. 立即更新按钮状态为"正在生成"
    const nodeEl = document.getElementById(`node-${nodeId}`);
    const generateBtn = nodeEl?.querySelector('.btn-generate');
    if (generateBtn) {
        generateBtn.disabled = true;
        generateBtn.innerHTML = '⏳ 生成中...';
        generateBtn.style.opacity = '0.6';
    }

    // 🆕 先从上游节点拉取提示词（关键修复！）
    const autoPrompt = updateNodeAutoPromptDisplay(nodeId);

    // Use data stored in node object (updated by oninput/onchange)
    let promptVal = getNodeFinalPrompt(node);
    if (!promptVal) {
        // 🔧 修复：传入空集合
        const upstreamPrompts = collectUpstreamPrompts(nodeId, new Set());
        if (upstreamPrompts.length > 0) {
            promptVal = [...new Set(upstreamPrompts)].join('\n\n');
            node.data.knollingPrompt = promptVal; // 缓存下来
        }
    }
    // 🔧 获取模型：优先级 node.data.model > node.data.backend > 默认值
    // ⚠️ 关键修复：指令框创建的节点使用 backend 存储模型，需要同时检查
    let modelVal = node.data.model || node.data.backend || 'nano-banana-2';
    console.log(`🎯 节点模型来源: model=${node.data.model}, backend=${node.data.backend}, 最终=${modelVal}`);
    if (modelVal === 'recraft-v3') {
        console.warn(`⚠️ 模型 ${modelVal} 已废弃，自动替换为 nano-banana-2`);
        modelVal = 'nano-banana-2';
        node.data.model = 'nano-banana-2';
    }

    // 🔧 检查模型权限
    const permission = checkModelPermission(modelVal);
    if (!permission.allowed) {
        alert(permission.message);
        resetGenerateButton(generateBtn);
        return;
    }

    console.log(`🎨 当前选择模型: ${modelVal}`);

    // Ensure prompt is not empty
    if (!promptVal) {
        alert('请输入或生成提示词');
        resetGenerateButton(generateBtn);
        return;
    }

    // 🔧 智能获取参考图（支持多图融合）
    let refImages = [];  // 🆕 改为数组，支持多图
    let refSources = [];

    // 1. 递归收集所有上游节点的图片（跳过空节点）
    const collectUpstreamImages = (targetId, visited = new Set()) => {
        if (visited.has(targetId)) return;
        visited.add(targetId);

        const incomingConns = connections.filter(c => c.target === targetId);
        incomingConns.forEach(conn => {
            const sourceNode = flowNodes.find(n => n.id === conn.source);
            if (!sourceNode) return;

            // 🆕 检查节点是否有有效图像内容
            if (nodeHasImageContent(sourceNode)) {
                // 有内容：收集图片
                const img = sourceNode.data.generatedImage ||
                    (sourceNode.data.refImages?.[0]?.url) ||
                    (sourceNode.data.drawingData && sourceNode.data.hasEdits ? sourceNode.data.drawingData : null);
                if (img) {
                    const label = sourceNode.data.imageLabel || `节点${conn.source.slice(-4)}`;
                    refImages.push(img);
                    refSources.push(label);
                    console.log(`🔗 收集 ${label} 的图片`);
                }
            } else {
                // 🆕 空节点：跳过，继续向上游查找
                console.log(`⏭️ 跳过空节点 ${conn.source}，继续向上游查找`);
                collectUpstreamImages(conn.source, visited);
            }
        });
    };

    collectUpstreamImages(nodeId);
    if (refImages.length > 0) {
        console.log(`📎 共收集 ${refImages.length} 张上游参考图: ${refSources.join(', ')}`);
    }

    // 🆕 优先级调整：如果当前节点画布有手绘修改（涂鸦/文字标注），优先使用画布数据
    // 因为 drawingData 包含了原图 + 用户的手绘涂鸦 + 文字标注
    if (node.data.drawingData && node.data.hasEdits === true) {
        const hasDrawing = checkCanvasHasContentSync(node.data.drawingData);
        if (hasDrawing) {
            // 清空之前收集的上游图片，使用当前画布数据（包含手绘修改）
            let processedDrawing = node.data.drawingData;

            // 🎨 针对 Midjourney 模型优化手绘草图
            if (modelVal.startsWith('midjourney-')) {
                console.log('🎨 [MJ优化] 检测到Midjourney模型，正在优化手绘草图...');
                try {
                    // 转换为黑白草图风格（提取线条，去除背景噪音）
                    processedDrawing = await convertToSketchStyle(node.data.drawingData);
                    console.log('✅ [MJ优化] 手绘草图已转换为sketch风格');

                    // 自动在提示词中添加草图相关关键词（如果还没有）
                    const sketchKeywords = ['sketch', 'line art', 'drawing', '草图', '线稿'];
                    const hasSketchKeyword = sketchKeywords.some(kw =>
                        promptVal.toLowerCase().includes(kw.toLowerCase())
                    );
                    if (!hasSketchKeyword) {
                        promptVal = `based on this sketch reference, ${promptVal}`;
                        console.log('✅ [MJ优化] 已添加sketch提示词前缀');
                    }
                } catch (err) {
                    console.warn('⚠️ [MJ优化] 草图转换失败，使用原图:', err);
                }
            }

            refImages = [processedDrawing];
            refSources = ['手绘标注参考图'];
            console.log('🎨 检测到画布手绘修改，使用带标注的画布图片作为参考（涂鸦+文字会影响生成结果）');
        }
    }

    // 3. 如果没有手绘图，检查上传的参考图（支持多张）
    if (refImages.length === 0 && node.data.refImages && node.data.refImages.length > 0) {
        node.data.refImages.forEach(img => {
            refImages.push(img.url);
            refSources.push(img.name || '上传图');
        });
        console.log(`🖼️ 使用 ${node.data.refImages.length} 张上传参考图`);
    }

    // 🆕 兼容旧代码：单图场景
    const refImage = refImages.length > 0 ? refImages[0] : null;
    const refSource = refSources.length > 0 ? refSources.join(', ') : '';

    // 🔧 如果有参考图但当前模型不支持图生图，自动切换模型
    if (refImage && modelVal === 'modelscope') {
        console.log('⚠️ 智能引擎不支持图生图，自动切换到 Banana');
        modelVal = 'nano-banana-2';
        node.data.model = 'nano-banana-2';
    }

    if (refImage) {
        console.log(`📎 参考图来源: ${refSource}，使用模型: ${modelVal}`);
    } else {
        console.log('📝 无参考图，将进行纯文生图');
    }

    const resArea = document.getElementById(`result-${nodeId}`);
    if (resArea) {
        resArea.innerHTML = '<div class="cine-status" style="color:var(--accent-gold); font-size:12px; padding:5px;">✨ AI 正在绘图...</div>';
    }

    // 辅助函数：重置按钮状态
    function resetGenerateButton(btn) {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = '⚡ 生成';
            btn.style.opacity = '1';
        }
    }

    async function callBananaWithFallback(options, manualFallback = false) {
        // 🔧 不再用retryableAPICall包装，因为callBanana2ImageAPI内部已有3次重试
        // 这里只处理413参考图过大的压缩降级
        try {
            return await callBanana2ImageAPI(promptVal, options);
        } catch (error) {
            if (error.message?.includes('413') && !manualFallback) {
                console.warn('⚠️ 参考图过大，自动压缩后重试');
                if (resArea) {
                    resArea.innerHTML = '<div class="cine-status" style="color:#fbbf24; font-size:12px; padding:5px;">⚠️ 参考图过大，正在自动压缩...</div>';
                }
                const compressed = await compressDataUrl(options.refImage, 1400, 0.8);
                options.refImage = compressed;
                return await callBananaWithFallback(options, true);
            }
            throw error;
        }
    }

    try {
        let url;

        // 🔧 根据模型选择调用不同的 API
        // 🆕 优先使用上游节点的比例设置，否则使用本节点设置（默认1:1）
        let nodeAspectRatio = node.data.aspectRatio || '1:1';

        // 🔗 检查上游节点是否有比例设置
        const savedConns = JSON.parse(localStorage.getItem('node_connections') || '[]');
        const allConns = [...connections, ...savedConns];
        const uniqueConns = allConns.filter((conn, idx, self) =>
            idx === self.findIndex(c => c.source === conn.source && c.target === conn.target)
        );
        const incomingConns = uniqueConns.filter(c => c.target === nodeId);

        for (const conn of incomingConns) {
            const sourceNode = flowNodes.find(n => n.id === conn.source);
            if (sourceNode && sourceNode.data && sourceNode.data.aspectRatio) {
                nodeAspectRatio = sourceNode.data.aspectRatio;
                console.log(`📐 使用上游节点 ${conn.source} 的比例: ${nodeAspectRatio}`);
                break; // 找到第一个有比例设置的上游节点就使用
            }
        }

        console.log(`📐 最终使用比例: ${nodeAspectRatio}`);

        if (modelVal === 'modelscope') {
            // 🆕 智能绘图引擎（仅支持文生图）
            console.log(`📡 节点使用智能绘图引擎 (文生图模式)`);
            const msOptions = { aspectRatio: nodeAspectRatio };
            // 🔧 ModelScope 不支持图生图，refImage 在前面已经处理过了（自动切换模型）
            // 🎞️ 扣费逻辑已内置于 callModelScopeImageAPI 中
            url = await callModelScopeImageAPI(promptVal, msOptions);
        } else if (modelVal === 'rh-flux') {
            // 🚫 RH Flux 暂时禁用（并发限制问题）
            throw new Error('Flux Pro 功能暂时维护中，请选择其他模型');
        } else {
            // 调用 Banana2 API（支持 nano-banana-2, nano-banana-2-2k, nano-banana-2-4k）
            console.log(`📡 节点使用 ${modelVal} 生图...${refImage ? ' (带参考图)' : ''}`);

            // 🔄 包装调用以显示重试状态（支持多图融合）
            const apiOptions = { aspectRatio: nodeAspectRatio, model: modelVal };
            // 🎨 Midjourney 版本参数
            if (modelVal.startsWith('midjourney-') && node.data.mjVersion) {
                apiOptions.version = node.data.mjVersion;
            }
            if (refImages.length > 0) {
                apiOptions.refImages = refImages;  // 🆕 多图数组
                apiOptions.refImage = refImages[0];  // 兼容压缩重试
            }
            url = await callBananaWithFallback(apiOptions);

            // 🎨 处理 Midjourney 网格图：前端切图 + 用户选择 + 后端 upscale
            if (url && typeof url === 'object' && url.isMjGrid && url.taskId) {
                console.log(`🎨 [MJ] 收到网格图，开始前端切图选择流程`);

                const gridUrl = url.url;
                const mjTaskId = url.taskId;
                const gridBase64 = url.gridBase64;  // 🆕 后端返回的 base64 网格图

                try {
                    // 1️⃣ 前端切图（优先用 base64，解决跨域问题）
                    const imageToSplit = gridBase64 || gridUrl;
                    console.log(`🔪 [MJ] 开始切图，使用: ${gridBase64 ? 'base64' : 'URL'}`);
                    const splitImages = await splitMjGridImage(imageToSplit);
                    console.log(`🔪 [MJ] 前端切图完成，得到 ${splitImages.length} 张图片`);

                    // 🆕 保存4张小图和taskId到节点数据，支持多次选择放大
                    node.data.mjGridImages = splitImages;
                    node.data.mjTaskId = mjTaskId;
                    node.data.mjGridUrl = gridUrl;

                    // 2️⃣ 弹出选择器让用户选择（返回索引 1-4，传入gridUrl支持下载）
                    const selectedIndex = await new Promise((resolve) => {
                        showNodeMjImagePicker(nodeId, splitImages, (index) => {
                            resolve(index);
                        }, gridUrl);
                    });

                    console.log(`🎨 [MJ] 用户选择了图片 ${selectedIndex}`);

                    if (selectedIndex && selectedIndex >= 1 && selectedIndex <= 4) {
                        // 3️⃣ 调用后端 upscale API 放大选中的图片
                        console.log(`🔍 [MJ] 开始 upscale 第 ${selectedIndex} 张图片, taskId=${mjTaskId}`);

                        if (resArea) {
                            resArea.innerHTML = `<div style="color:#f59e0b; font-size:12px; padding:5px;">🔄 正在放大选中的图片...</div>`;
                        }

                        const upscaleRes = await fetch('/api/yunwu', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                action: 'mj-upscale',
                                taskId: mjTaskId,
                                index: selectedIndex,
                                userId: (typeof NVAuth !== 'undefined' && NVAuth.getCurrentUser) ? (await NVAuth.getCurrentUser())?.id : null  // 🔧 修复 401
                            })
                        });

                        const upscaleData = await upscaleRes.json();

                        if (upscaleData.success && upscaleData.imageUrl) {
                            url = upscaleData.imageUrl;
                            console.log(`✅ [MJ] Upscale 成功:`, url);
                        } else {
                            console.warn(`⚠️ [MJ] Upscale 失败，使用前端切图:`, upscaleData.message);
                            // upscale 失败，使用前端切图的 base64
                            url = splitImages[selectedIndex - 1];
                        }
                    } else {
                        // 用户取消，使用第一张切图
                        console.log(`🎨 [MJ] 用户取消，使用第一张切图`);
                        url = splitImages[0];
                    }
                } catch (splitErr) {
                    console.error(`❌ [MJ] 切图失败，使用网格图:`, splitErr);
                    url = gridUrl;
                }
            }
        }

        // Save result to node data
        node.data.generatedImage = url;
        node.data.generatedImageDataUrl = null;
        node.data.hasEdits = false;
        saveIdeasToHistory();

        console.log(`✅ 图片生成成功: ${url.substring(0, 50)}...`);

        // 🔧 尝试更新结果区域
        let resultArea = resArea;
        if (!resultArea) {
            // 如果之前没找到，再尝试一次
            resultArea = document.getElementById(`result-${nodeId}`);
            console.log(`🔍 重新查找结果区域: result-${nodeId}, 找到: ${!!resultArea}`);
        }

        // 🆕 检查是否有MJ多图可选
        const hasMjGrid = node.data.mjGridImages && node.data.mjGridImages.length > 1 && node.data.mjTaskId;

        if (resultArea) {
            resultArea.innerHTML = `
                <div class="node-result-image">
                    <img src="${url}" onclick="window.open('${url}')" oncontextmenu="showNodeImageMenu(event, '${url}')" title="左键查看大图 | 右键保存">
                    <div class="result-image-actions">
                        <button onclick="downloadNodeImage('${url}', 'banana_${nodeId}_${Date.now()}.png')" title="下载图片">💾</button>
                        <button onclick="copyImageUrl('${url}')" title="复制链接">🔗</button>
                        <button onclick="applyResultToCanvas('${nodeId}')" title="载入画布继续涂抹">✏️</button>
                        ${hasMjGrid ? `<button onclick="reopenMjPicker('${nodeId}')" title="选择其他图片放大" style="background:#8b5cf6;">🎨</button>` : ''}
                    </div>
                </div>
            `;
            console.log(`✅ 已更新节点 ${nodeId} 的结果区域`);
        } else {
            // 🔧 如果还是找不到，强制重新渲染画布
            console.warn(`⚠️ 找不到节点 ${nodeId} 的结果区域，触发画布重新渲染`);
            renderCanvas();
        }

        try {
            const editableData = await ensureEditableDataUrl(node, url);
            if (editableData) {
                // 🔧 关键：载入画布时明确设置 hasEdits=false，避免下次误判为图生图
                loadImageOntoCanvas(nodeId, editableData, { markHasEdits: false, silent: true });
            }
        } catch (loadErr) {
            console.warn('生成图载入画布失败:', loadErr);
        }

        // ✅ 生成成功，重置按钮状态
        resetGenerateButton(generateBtn);

        // 🔗 自动触发下游节点生成（如果有连接）
        await triggerDownstreamNodes(nodeId);
    } catch (e) {
        console.error('❌ 节点图片生成失败:', e);
        if (resArea) {
            // 🔧 根据错误类型给出更友好的提示
            let errorMsg = e.message;
            if (e.message.includes('502') || e.message.includes('Bad Gateway')) {
                errorMsg = 'API网关错误 (502)，上游服务暂时不可用，请稍后重试';
            } else if (e.message.includes('503')) {
                errorMsg = '服务暂时不可用 (503)，请稍后重试';
            } else if (e.message.includes('429')) {
                errorMsg = '请求过于频繁 (429)，请稍后重试';
            }
            resArea.innerHTML = `<div style="color:#ef4444; font-size:12px; padding:5px; line-height:1.4;">❌ 生成失败: ${errorMsg}</div>`;
        }
        // ❌ 生成失败，也要重置按钮状态
        resetGenerateButton(generateBtn);
    }
}

// Add helper functions

/**
 * 🔗 自动触发下游节点生成
 * 当一个节点生成完成后，自动触发所有连接到它的下游节点
 * @param {string} sourceNodeId - 源节点ID
 */
async function triggerDownstreamNodes(sourceNodeId) {
    // 查找所有以当前节点为源的连接
    const downstreamConns = connections.filter(c => c.source === sourceNodeId);

    if (downstreamConns.length === 0) {
        console.log(`🔗 节点 ${sourceNodeId} 没有下游连接`);
        return;
    }

    console.log(`🔗 节点 ${sourceNodeId} 有 ${downstreamConns.length} 个下游节点，开始触发生成...`);

    for (const conn of downstreamConns) {
        const targetNode = flowNodes.find(n => n.id === conn.target);
        if (!targetNode) continue;

        // 只处理 banana-draw 类型的节点
        if (targetNode.type !== 'banana-draw') {
            console.log(`⏭️ 跳过非图片节点: ${targetNode.id} (${targetNode.type})`);
            continue;
        }

        // 检查目标节点是否已经有生成结果（避免重复生成）
        if (targetNode.data.generatedImage) {
            console.log(`⏭️ 节点 ${targetNode.id} 已有生成结果，跳过`);
            continue;
        }

        console.log(`🎨 触发下游节点生成: ${targetNode.id}`);

        // 延迟一小段时间，避免请求过快
        await new Promise(r => setTimeout(r, 300));

        try {
            await generateNodeImage(targetNode.id);
        } catch (e) {
            console.error(`❌ 下游节点 ${targetNode.id} 生成失败:`, e);
        }
    }
}

window.triggerDownstreamNodes = triggerDownstreamNodes;

/**
 * 🔪 前端切图：将 Midjourney 2x2 网格图切成4张独立图片
 * @param {string} gridImageUrl - 网格图 URL
 * @returns {Promise<string[]>} 4张图片的 base64 数据
 */
async function splitMjGridImage(gridImageUrl) {
    console.log(`🔪 [MJ] 开始切图:`, gridImageUrl);

    // 用 fetch + blob 绕过跨域限制
    try {
        const response = await fetch(gridImageUrl);
        if (!response.ok) throw new Error(`图片加载失败: ${response.status}`);
        const blob = await response.blob();
        const blobUrl = URL.createObjectURL(blob);

        return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => {
                const w = img.width / 2;
                const h = img.height / 2;
                const results = [];
                const positions = [[0, 0], [w, 0], [0, h], [w, h]];  // 左上、右上、左下、右下
                for (const [x, y] of positions) {
                    const canvas = document.createElement('canvas');
                    canvas.width = w;
                    canvas.height = h;
                    const ctx = canvas.getContext('2d');
                    ctx.drawImage(img, x, y, w, h, 0, 0, w, h);
                    results.push(canvas.toDataURL('image/png'));
                }
                URL.revokeObjectURL(blobUrl);
                console.log(`🔪 [MJ] 切图完成: ${w}x${h} × 4`);
                resolve(results);
            };
            img.onerror = (err) => {
                URL.revokeObjectURL(blobUrl);
                console.error('❌ [MJ] 切图加载失败:', err);
                reject(new Error('网格图加载失败'));
            };
            img.src = blobUrl;
        });
    } catch (fetchErr) {
        console.error('❌ [MJ] fetch 图片失败:', fetchErr);
        throw fetchErr;
    }
}
window.splitMjGridImage = splitMjGridImage;

/**
 * 🎨 节点 Midjourney 图片选择器
 * 弹出一个选择器让用户从4张切图中选择一张
 * @param {string} nodeId - 节点ID
 * @param {string[]} images - 4张切图的 base64 数据
 * @param {function} callback - 回调函数，返回索引 1-4，取消返回 null
 * @param {string} gridUrl - 原始网格图URL（可选，用于下载）
 */
function showNodeMjImagePicker(nodeId, images, callback, gridUrl = '') {
    // 保存到全局以便下载
    window.__currentDesktopMjPickerData = { images, nodeId, gridUrl };

    // 创建弹窗
    const overlay = document.createElement('div');
    overlay.id = 'mj-picker-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.85);z-index:99999;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px;overflow-y:auto;';

    overlay.innerHTML = `
        <div style="color:white;font-size:18px;margin-bottom:16px;">🎨 Midjourney 生成了4张图片，请选择一张进行放大</div>
        <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:12px;max-width:800px;">
            ${images.map((dataUrl, i) => `
                <div class="mj-pick-item" data-index="${i + 1}" style="cursor:pointer;border:3px solid transparent;border-radius:8px;overflow:hidden;transition:all 0.2s;">
                    <img src="${dataUrl}" style="width:100%;height:auto;display:block;" />
                    <div style="text-align:center;background:#222;color:#fff;padding:6px;font-size:14px;">图片 ${i + 1}</div>
                </div>
            `).join('')}
        </div>
        <div style="margin-top:16px;display:flex;gap:12px;flex-wrap:wrap;justify-content:center;">
            <button id="mj-pick-download-all" style="padding:10px 20px;background:#10b981;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:14px;">💾 下载全部(5张)</button>
            <button id="mj-pick-cancel" style="padding:10px 20px;background:#555;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:14px;">取消（使用第一张）</button>
        </div>
        <div style="margin-top:8px;color:#888;font-size:12px;">💡 「下载全部」会下载4张分割图 + 1张原始网格图</div>
    `;

    document.body.appendChild(overlay);

    // 点击图片选择
    overlay.querySelectorAll('.mj-pick-item').forEach(item => {
        item.addEventListener('click', () => {
            const selectedIndex = parseInt(item.getAttribute('data-index'));  // 1-4
            document.body.removeChild(overlay);
            callback(selectedIndex);
        });
        item.addEventListener('mouseenter', () => {
            item.style.borderColor = '#f59e0b';
            item.style.transform = 'scale(1.02)';
        });
        item.addEventListener('mouseleave', () => {
            item.style.borderColor = 'transparent';
            item.style.transform = 'scale(1)';
        });
    });

    // 下载全部按钮
    overlay.querySelector('#mj-pick-download-all').addEventListener('click', async () => {
        await downloadAllDesktopMjImages();
    });

    // 取消按钮
    overlay.querySelector('#mj-pick-cancel').addEventListener('click', () => {
        document.body.removeChild(overlay);
        callback(null);  // 返回null表示取消
    });
}
window.showNodeMjImagePicker = showNodeMjImagePicker;

/**
 * 💾 下载所有桌面版 MJ 图片
 */
async function downloadAllDesktopMjImages() {
    const data = window.__currentDesktopMjPickerData;
    if (!data || !data.images || data.images.length === 0) {
        alert('没有可下载的图片');
        return;
    }

    const timestamp = Date.now();
    let downloadCount = 0;

    try {
        // 下载4张切图
        for (let i = 0; i < data.images.length; i++) {
            const link = document.createElement('a');
            link.href = data.images[i];
            link.download = `mj_${timestamp}_part${i + 1}.png`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            downloadCount++;
            await new Promise(r => setTimeout(r, 300));
        }

        // 下载原始网格图（如果有URL）
        if (data.gridUrl && data.gridUrl.startsWith('http')) {
            try {
                const response = await fetch(data.gridUrl);
                const blob = await response.blob();
                const blobUrl = URL.createObjectURL(blob);
                const link = document.createElement('a');
                link.href = blobUrl;
                link.download = `mj_${timestamp}_grid.png`;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                URL.revokeObjectURL(blobUrl);
                downloadCount++;
            } catch (e) {
                console.warn('网格图下载失败，打开新窗口:', e.message);
                window.open(data.gridUrl, '_blank');
            }
        }

        alert(`✅ 下载完成（${downloadCount}张）`);
    } catch (err) {
        console.error('下载失败:', err);
        alert('部分图片下载失败');
    }
}
window.downloadAllDesktopMjImages = downloadAllDesktopMjImages;

/**
 * 🆕 重新打开MJ图片选择器，选择其他图片放大
 * @param {string} nodeId - 节点ID
 */
window.reopenMjPicker = async function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node || !node.data.mjGridImages || !node.data.mjTaskId) {
        alert('没有可选的MJ图片');
        return;
    }

    const splitImages = node.data.mjGridImages;
    const mjTaskId = node.data.mjTaskId;
    const gridUrl = node.data.mjGridUrl || '';

    // 弹出选择器（传入gridUrl支持下载）
    const selectedIndex = await new Promise((resolve) => {
        showNodeMjImagePicker(nodeId, splitImages, (index) => {
            resolve(index);
        }, gridUrl);
    });

    if (!selectedIndex || selectedIndex < 1 || selectedIndex > 4) {
        return; // 用户取消
    }

    console.log(`🎨 [MJ] 重新选择图片 ${selectedIndex}，开始放大...`);

    const resArea = document.getElementById(`result-${nodeId}`);
    if (resArea) {
        resArea.innerHTML = `<div style="color:#f59e0b; font-size:12px; padding:5px;">🔄 正在放大选中的图片...</div>`;
    }

    try {
        const upscaleRes = await fetch('/api/yunwu', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'mj-upscale',
                taskId: mjTaskId,
                index: selectedIndex,
                userId: (typeof NVAuth !== 'undefined' && NVAuth.getCurrentUser) ? (await NVAuth.getCurrentUser())?.id : null
            })
        });

        const upscaleData = await upscaleRes.json();
        let url;

        if (upscaleData.success && upscaleData.imageUrl) {
            url = upscaleData.imageUrl;
            console.log(`✅ [MJ] Upscale 成功:`, url);
        } else {
            console.warn(`⚠️ [MJ] Upscale 失败，使用前端切图:`, upscaleData.message);
            url = splitImages[selectedIndex - 1];
        }

        // 更新节点数据
        node.data.generatedImage = url;
        saveIdeasToHistory();

        // 更新显示
        if (resArea) {
            resArea.innerHTML = `
                <div class="node-result-image">
                    <img src="${url}" onclick="window.open('${url}')" oncontextmenu="showNodeImageMenu(event, '${url}')" title="左键查看大图 | 右键保存">
                    <div class="result-image-actions">
                        <button onclick="downloadNodeImage('${url}', 'banana_${nodeId}_${Date.now()}.png')" title="下载图片">💾</button>
                        <button onclick="copyImageUrl('${url}')" title="复制链接">🔗</button>
                        <button onclick="applyResultToCanvas('${nodeId}')" title="载入画布继续涂抹">✏️</button>
                        <button onclick="reopenMjPicker('${nodeId}')" title="选择其他图片放大" style="background:#8b5cf6;">🎨</button>
                    </div>
                </div>
            `;
        }
    } catch (err) {
        console.error('放大失败:', err);
        if (resArea) {
            resArea.innerHTML = `<div style="color:#ef4444; font-size:12px; padding:5px;">❌ 放大失败: ${err.message}</div>`;
        }
    }
};

/**
 * 🔧 检查画布数据是否有实际绘制内容（不只是白色背景）
 * @param {string} dataUrl - 画布的 dataURL
 * @returns {boolean} 是否有内容
 */
function checkCanvasHasContent(dataUrl) {
    if (!dataUrl) return false;

    // 创建临时画布来检查内容
    return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.width;
            canvas.height = img.height;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0);

            const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const data = imageData.data;

            // 检查是否有非白色像素
            for (let i = 0; i < data.length; i += 4) {
                const r = data[i];
                const g = data[i + 1];
                const b = data[i + 2];
                // 如果有任何非白色像素（容差10），认为有内容
                if (r < 245 || g < 245 || b < 245) {
                    resolve(true);
                    return;
                }
            }
            resolve(false);
        };
        img.onerror = () => resolve(false);
        img.src = dataUrl;
    });
}

// 同步版本的检查（简单检查dataURL长度，白色画布通常较短）
function checkCanvasHasContentSync(dataUrl) {
    if (!dataUrl) return false;
    // 纯白色画布的dataURL通常比较短（约5KB以下），有内容的会更长
    // 这是一个快速但不太精确的检查
    return dataUrl.length > 6000;
}

