/**
 * 🆕 执行视频编辑 (Remix)
 * @param {string} nodeId - 节点ID
 * @param {number} resultIndex - 结果索引
 * @param {string} videoId - 视频ID
 */
window.vrRemixVideo = async function (nodeId, resultIndex, videoId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    const promptEl = document.getElementById(`remix-prompt-${nodeId}-${resultIndex}`);
    const remixPrompt = promptEl?.value?.trim() || '';

    if (!remixPrompt) {
        alert('请输入编辑指令');
        return;
    }

    try {
        // 在结果中添加"编辑中"状态
        if (!node.data.cloneResults[resultIndex].remixes) {
            node.data.cloneResults[resultIndex].remixes = [];
        }

        const remixIndex = node.data.cloneResults[resultIndex].remixes.length;
        node.data.cloneResults[resultIndex].remixes.push({
            index: remixIndex,
            prompt: remixPrompt,
            status: 'processing',
            original_video_id: videoId
        });

        saveIdeasToHistory();
        renderCanvas();

        // 调用后端 API（合并到 sora2）
        const response = await fetch('/api/sora2', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'remix',
                video_id: videoId,
                prompt: remixPrompt
            })
        });

        const data = await response.json();

        if (!response.ok || !data.success) {
            throw new Error(data.message || '视频编辑失败');
        }

        console.log('[sora2-remix] 编辑任务已提交:', data);

        // 更新状态为"轮询中"
        node.data.cloneResults[resultIndex].remixes[remixIndex].status = 'polling';
        node.data.cloneResults[resultIndex].remixes[remixIndex].new_video_id = data.new_video_id || data.data?.id;

        saveIdeasToHistory();
        renderCanvas();

        // 开始轮询结果
        if (data.new_video_id || data.data?.id) {
            await _pollRemixResult(nodeId, resultIndex, remixIndex, data.new_video_id || data.data.id);
        } else {
            throw new Error('未返回新视频ID');
        }

    } catch (error) {
        console.error('[video-remix] 编辑失败:', error);
        alert('视频编辑失败: ' + (error?.message || String(error)));

        // 更新失败状态
        if (node.data.cloneResults[resultIndex]?.remixes) {
            const remixIndex = node.data.cloneResults[resultIndex].remixes.length - 1;
            if (remixIndex >= 0) {
                node.data.cloneResults[resultIndex].remixes[remixIndex].status = 'failed';
                node.data.cloneResults[resultIndex].remixes[remixIndex].error = error?.message || String(error);
            }
        }

        saveIdeasToHistory();
        renderCanvas();
    }
};

/**
 * 🆕 轮询单个视频任务状态 (返回状态对象)
 * @param {string} taskId - 任务ID (video_xxx 或 task_xxx 格式)
 * @returns {Promise<{status: string, url?: string, error?: string}>}
 * @private
 */
async function _pollVideoTaskId(taskId) {
    try {
        const res = await fetch('/api/sora2', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'poll',
                task_id: taskId
            })
        });

        if (!res.ok) {
            return { status: 'error', error: `轮询请求失败: ${res.status}` };
        }

        const data = await res.json();

        // 🔧 健壮的状态检查（兼容多种格式）
        const status = (data.status || data.state || data.task_status || '').toUpperCase();

        // ✅ 成功状态
        if (status === 'SUCCESS' || status === 'COMPLETED' || status === 'DONE') {
            // 🔧 健壮的URL提取（尝试多种路径）
            const videoUrl =
                data.video_url ||
                data.videoUrl ||
                data.url ||
                data.data?.output ||
                data.data?.video_url ||
                data.data?.url ||
                (Array.isArray(data.data) && data.data[0]?.url) ||
                (Array.isArray(data.data) && data.data[0]?.video_url) ||
                data.result?.url ||
                data.result?.video_url;

            if (videoUrl) {
                return { status: 'completed', url: videoUrl };
            } else {
                return { status: 'error', error: '任务完成但未找到视频URL' };
            }
        }

        // ❌ 失败状态
        if (status === 'FAILURE' || status === 'FAILED' || status === 'ERROR') {
            const errorMsg = data.fail_reason || data.error || data.message || '未知错误';
            return { status: 'failed', error: errorMsg };
        }

        // ⏳ 进行中
        return { status: 'processing' };

    } catch (error) {
        console.error('[poll-video-task] 轮询异常:', error);
        return { status: 'error', error: error.message || String(error) };
    }
}

/**
 * 🆕 轮询视频编辑结果
 * @private
 */
async function _pollRemixResult(nodeId, resultIndex, remixIndex, newVideoId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node || !node.data.cloneResults[resultIndex]?.remixes?.[remixIndex]) return;

    const maxAttempts = 120; // 最多轮询2分钟 (120 * 1秒)
    let attempts = 0;

    const poll = async () => {
        if (attempts >= maxAttempts) {
            node.data.cloneResults[resultIndex].remixes[remixIndex].status = 'timeout';
            node.data.cloneResults[resultIndex].remixes[remixIndex].error = '编辑超时，请稍后查询结果';
            saveIdeasToHistory();
            renderCanvas();
            return;
        }

        attempts++;

        try {
            // 调用轮询 API (复用现有的 sora2 poll 逻辑)
            const result = await _pollVideoTaskId(newVideoId);

            if (result.status === 'completed' && result.url) {
                // 编辑成功
                node.data.cloneResults[resultIndex].remixes[remixIndex].status = 'completed';
                node.data.cloneResults[resultIndex].remixes[remixIndex].url = result.url;
                node.data.cloneResults[resultIndex].remixes[remixIndex].video_id = newVideoId;
                saveIdeasToHistory();
                renderCanvas();
                return;
            } else if (result.status === 'failed' || result.status === 'error') {
                // 编辑失败
                node.data.cloneResults[resultIndex].remixes[remixIndex].status = 'failed';
                node.data.cloneResults[resultIndex].remixes[remixIndex].error = result.error || '编辑失败';
                saveIdeasToHistory();
                renderCanvas();
                return;
            } else {
                // 继续轮询
                setTimeout(poll, 1000);
            }
        } catch (error) {
            console.error('[video-remix] 轮询失败:', error);
            // 继续轮询，不中断
            setTimeout(poll, 2000);
        }
    };

    poll();
}

