/**
 * 🎵 智能分析内容并推荐风格
 */
function analyzeContentForMusicStyle(content) {
    const text = content.toLowerCase();

    // 情感关键词分析
    const emotionKeywords = {
        sad: ['悲伤', '难过', '心碎', '眼泪', '分手', '离别', '孤独', 'sad', 'cry', 'tear', 'lonely', 'break'],
        happy: ['快乐', '开心', '幸福', '阳光', '笑', '欢乐', 'happy', 'joy', 'smile', 'sun', 'bright'],
        romantic: ['爱', '浪漫', '甜蜜', '心动', '恋爱', 'love', 'romantic', 'heart', 'sweet'],
        epic: ['史诗', '壮阔', '英雄', '战斗', '冒险', 'epic', 'hero', 'battle', 'adventure', 'grand'],
        calm: ['平静', '安静', '舒缓', '放松', '冥想', 'calm', 'peace', 'relax', 'quiet', 'meditation'],
        energetic: ['活力', '激情', '热血', '运动', '派对', 'energy', 'party', 'dance', 'power', 'fire']
    };

    // 场景关键词分析
    const sceneKeywords = {
        chinese: ['中国', '古风', '汉服', '江南', '山水', '唐诗', '宋词', '国风'],
        electronic: ['科技', '未来', '赛博', '电子', '机器', 'cyber', 'tech', 'future', 'digital'],
        nature: ['自然', '森林', '海洋', '山川', '田野', 'nature', 'forest', 'ocean', 'mountain'],
        urban: ['城市', '都市', '街头', '夜晚', 'city', 'urban', 'street', 'night']
    };

    let suggestedStyle = 'pop'; // 默认流行
    let emotion = 'neutral';
    let maxScore = 0;

    // 检测情感
    for (const [emo, keywords] of Object.entries(emotionKeywords)) {
        let score = keywords.filter(k => text.includes(k)).length;
        if (score > maxScore) {
            maxScore = score;
            emotion = emo;
        }
    }

    // 检测场景
    for (const [scene, keywords] of Object.entries(sceneKeywords)) {
        if (keywords.some(k => text.includes(k))) {
            if (scene === 'chinese') suggestedStyle = 'chinese';
            else if (scene === 'electronic') suggestedStyle = 'electronic';
        }
    }

    // 根据情感调整风格
    if (emotion === 'sad') suggestedStyle = 'ballad';
    else if (emotion === 'epic') suggestedStyle = 'cinematic';
    else if (emotion === 'calm') suggestedStyle = 'ambient';
    else if (emotion === 'energetic') suggestedStyle = 'edm';

    return {
        style: suggestedStyle,
        emotion: emotion,
        template: SUNO_STYLE_TEMPLATES[suggestedStyle] || SUNO_STYLE_TEMPLATES['pop']
    };
}

