/**
 * 🔍 获取上游节点信息（包含类型和内容）
 */
function getUpstreamNodesInfo(nodeId, visited = new Set()) {
    const nid = String(nodeId);
    if (visited.has(nid)) return [];
    visited.add(nid);

    const results = [];
    const incomingConnections = connections.filter(c => String(c.target) === nid);

    incomingConnections.forEach(conn => {
        const sourceNode = flowNodes.find(n => String(n.id) === String(conn.source));
        if (sourceNode) {
            // 收集节点信息
            const info = {
                id: sourceNode.id,
                type: sourceNode.type || 'unknown',
                data: sourceNode.data || {}
            };

            // 根据节点类型提取内容
            if (sourceNode.type === 'minibook') {
                // 故事节点 - 提取故事内容
                info.content = sourceNode.data?.storyContent || sourceNode.data?.generatedStory ||
                    sourceNode.data?.script || sourceNode.data?.generatedPrompt || '';
                info.isStory = true;
            } else if (sourceNode.type === 'knolling' || sourceNode.type === 'prompt-template') {
                info.content = sourceNode.data?.generatedPrompt || '';
            } else {
                info.content = sourceNode.data?.generatedPrompt || sourceNode.data?.knollingPrompt ||
                    sourceNode.data?.prompt || '';
            }

            if (info.content || info.type === 'minibook') {
                results.push(info);
            }

            // 递归获取更上游
            const upstreamInfos = getUpstreamNodesInfo(conn.source, visited);
            results.push(...upstreamInfos);
        }
    });

    return results;
}

/**
 * ✍️ 生成歌词
 */
window.musicNodeGenerateLyrics = async function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    const d = node.data;
    const statusEl = document.getElementById(`music-status-${nodeId}`);

    // 获取主题/描述
    let theme = d.prompt || d.title || '';

    // 🔍 获取上游节点信息，检测是否有故事节点
    let upstreamInfos = [];
    let storyContent = '';
    let isFromStory = false;

    try {
        upstreamInfos = getUpstreamNodesInfo(nodeId);
        // 检查是否有故事节点
        const storyNode = upstreamInfos.find(info => info.isStory && info.content);
        if (storyNode) {
            storyContent = storyNode.content;
            isFromStory = true;
            console.log('🎵 检测到上游故事节点，将基于故事内容生成歌词');
        }
    } catch (e) {
        console.warn('获取上游节点信息失败:', e);
    }

    // 从上游节点获取内容
    let upstreamPrompts = [];
    try {
        upstreamPrompts = collectUpstreamPrompts(nodeId);
    } catch (e) {
        console.warn('获取上游提示词失败:', e);
    }

    if (!theme.trim() && upstreamPrompts.length > 0) {
        theme = upstreamPrompts.join('\n');
    }

    // 如果有故事内容，优先使用故事
    if (isFromStory && storyContent) {
        theme = storyContent;
    }

    if (!theme.trim()) {
        showToast('请输入歌曲主题或描述，或连接上游故事节点');
        return;
    }

    // 🔐 获取用户ID
    let currentUserId = null;
    try {
        const user = await NVAuth.getCurrentUser();
        currentUserId = user?.id || null;
    } catch (e) { }

    if (statusEl) statusEl.textContent = isFromStory ? '正在根据故事生成歌词...' : '正在生成歌词...';
    d.status = 'generating_lyrics';

    try {
        const tags = d.tags || 'pop';
        // 构建歌词结构参考
        const structureTags = SUNO_LYRICS_STRUCTURES.map(s => `${s.tag} - ${s.name}: ${s.desc}`).join('\n');

        // 根据是否来自故事调整prompt
        let prompt;
        if (isFromStory) {
            prompt = `你是一位专业的歌词创作者。请根据以下故事内容，创作一首能够表达故事情感和主题的歌词。

【故事内容】
${theme}

【音乐风格】${tags}

【可用的歌词结构标记】
${structureTags}

【创作要求】
1. 必须使用上述结构标记来标注歌词各部分
2. 推荐结构: [Intro] → [Verse] → [Pre-Chorus] → [Chorus] → [Verse] → [Chorus] → [Bridge] → [Chorus] → [Outro]
3. 歌词要提炼故事的核心情感和主题
4. 可以从故事主角的视角来写，表达内心独白
5. 副歌部分要有记忆点，能概括故事精髓
6. 歌词要有韵律感，朗朗上口
7. 直接输出歌词内容，不要加任何解释

请创作歌词:`;
        } else {
            prompt = `你是一位专业的歌词创作者。请根据以下主题和风格，创作一首完整的歌词。

主题/描述: ${theme}
音乐风格: ${tags}

可用的歌词结构标记：
${structureTags}

要求:
1. 必须使用上述结构标记来标注歌词各部分
2. 推荐结构: [Intro] → [Verse] → [Pre-Chorus] → [Chorus] → [Verse] → [Chorus] → [Bridge] → [Chorus] → [Outro]
3. 歌词要有韵律感，朗朗上口
4. 内容要符合主题，情感真挚
5. 副歌部分要有记忆点，可重复
6. 直接输出歌词内容，不要加任何解释

请创作歌词:`;
        }

        const response = await fetch('/api/yunwu', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'text',
                model: 'roll',
                prompt: prompt,
                userId: currentUserId
            })
        });

        if (!response.ok) {
            throw new Error('API请求失败');
        }

        const data = await response.json();
        const lyrics = data.content || data.text || data.response || '';

        if (lyrics) {
            // 将生成的歌词填入prompt字段
            d.prompt = lyrics;
            d.mode = 'custom'; // 切换到自定义模式以便编辑
            d.status = 'lyrics_ready';
            if (statusEl) statusEl.textContent = '歌词已生成，可编辑后生成音乐';
            showToast('歌词生成成功！');
            renderCanvas();
            saveIdeasToHistory();
        } else {
            throw new Error('未获取到歌词内容');
        }
    } catch (error) {
        console.error('生成歌词失败:', error);
        d.status = 'error';
        if (statusEl) statusEl.textContent = '歌词生成失败: ' + error.message;
        showToast('歌词生成失败: ' + error.message);
    }
};

