/**
 * 🎵 生成音乐
 */
window.musicNodeGenerate = async function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    const d = node.data;
    const mode = d.mode || 'custom';

    // 从上游节点获取提示词
    let upstreamPrompts = [];
    try {
        upstreamPrompts = collectUpstreamPrompts(nodeId);
    } catch (e) {
        console.warn('获取上游提示词失败:', e);
    }

    // 🔐 获取用户ID（后端要求必须提供 userId）
    let currentUserId = null;
    try {
        const user = await NVAuth.getCurrentUser();
        currentUserId = user?.id || null;
    } catch (e) {
        console.warn('[music] 获取用户ID失败:', e);
    }
    if (!currentUserId) {
        showToast('请先登录后再使用');
        return;
    }

    // 构建请求参数
    const requestBody = {
        action: 'generate',
        userId: currentUserId,
        mv: d.model || 'chirp-auk',
        make_instrumental: !!d.makeInstrumental
    };

    if (mode === 'inspiration') {
        // 灵感模式
        const desc = d.prompt || upstreamPrompts.join('\n') || '';
        if (!desc.trim()) {
            showToast('请输入音乐描述');
            return;
        }
        requestBody.gpt_description_prompt = desc;
    } else if (mode === 'smart') {
        // 🤖 智能模式 - 根据上游内容自动生成
        const upstreamContent = d.upstreamContent || upstreamPrompts.join('\n') || '';
        if (!upstreamContent.trim()) {
            showToast('请先获取上游内容或连接上游节点');
            return;
        }

        // 智能分析内容
        const analysis = analyzeContentForMusicStyle(upstreamContent);
        console.log('🤖 智能分析结果:', analysis);

        // 使用用户选择的风格或智能推荐的风格
        const selectedStyle = d.selectedStyle || d.selectedPreset;
        let finalTags = d.tags || '';
        let stylePrompt = d.stylePrompt || '';

        if (!finalTags && !selectedStyle) {
            // 没有选择风格，使用智能推荐
            finalTags = analysis.template.tags;
            showToast(`智能推荐风格: ${analysis.template.name}`);
        }

        // 使用灵感模式API，让AI根据内容生成歌词
        const smartPrompt = stylePrompt
            ? `${stylePrompt}\n\n基于以下内容创作: ${upstreamContent.slice(0, 1000)}`
            : `创作一首关于以下内容的歌曲: ${upstreamContent.slice(0, 1000)}`;

        requestBody.gpt_description_prompt = smartPrompt;
        if (finalTags) {
            requestBody.tags = finalTags;
        }
    } else {
        // 自定义模式
        const lyrics = d.prompt || upstreamPrompts.join('\n') || '';
        if (!lyrics.trim() && !d.makeInstrumental) {
            showToast('请输入歌词内容');
            return;
        }
        requestBody.prompt = lyrics;
        requestBody.title = d.title || '未命名歌曲';
        requestBody.tags = d.tags || '';

        if (d.negativeTags) {
            requestBody.negative_tags = d.negativeTags;
        }
        if (d.vocalGender) {
            requestBody.metadata = { create_mode: 'custom', vocal_gender: d.vocalGender };
        }

        // 续写模式
        if (d.continueClipId) {
            requestBody.continue_clip_id = d.continueClipId;
            requestBody.continue_at = d.continueAt || 0;
            requestBody.task = 'extend';
        }
    }

    // 更新状态
    d.status = '提交中...';
    updateMusicNodeStatus(nodeId, d.status);

    try {
        console.log('🎵 提交音乐生成任务:', requestBody);
        const res = await fetch('/api/suno', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(requestBody)
        });

        const result = await res.json().catch(() => ({}));
        console.log('🎵 任务提交结果:', result);

        if (!res.ok) {
            const errMsg = typeof result.message === 'string' ? result.message
                : typeof result.error === 'string' ? result.error
                    : `API错误: ${res.status}`;
            throw new Error(errMsg);
        }
        if (!result.success || !result.task_id) {
            const errMsg = typeof result.message === 'string' ? result.message
                : typeof result.error === 'string' ? result.error
                    : JSON.stringify(result).slice(0, 200);
            throw new Error(errMsg || '任务提交失败');
        }

        d.taskId = result.task_id;
        d.status = '生成中...';
        // 清除续写参数
        d.continueClipId = '';
        d.continueAt = 0;
        updateMusicNodeStatus(nodeId, d.status);
        saveIdeasToHistory();

        // 开始轮询
        await pollMusicTask(nodeId, result.task_id);

    } catch (e) {
        console.error('🎵 音乐生成失败:', e);
        d.status = `失败: ${e.message}`;
        updateMusicNodeStatus(nodeId, d.status);
        showToast(`音乐生成失败: ${e.message}`);
    }
};

/**
 * 🎵 轮询音乐任务状态
 */
async function pollMusicTask(nodeId, taskId, maxAttempts = 120) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    for (let attempt = 0; attempt < maxAttempts; attempt++) {
        try {
            const res = await fetch('/api/suno', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'fetch', task_id: taskId })
            });

            const result = await res.json();
            console.log(`🎵 轮询 #${attempt + 1}:`, result.status, 'is_complete:', result.is_complete);

            if (result.is_complete) {
                // 完成
                node.data.status = '✅ 完成';
                console.log('🎵 音乐生成完成，原始结果:', JSON.stringify(result, null, 2));

                // 🔧 增强：检查多种可能的数据结构
                let musicData = result.music || [];

                // 尝试从 result.data 获取
                if (!musicData.length && result.data) {
                    musicData = Array.isArray(result.data) ? result.data : [result.data];
                }

                // 尝试从 result.raw.data 获取
                if (!musicData.length && result.raw && result.raw.data) {
                    musicData = Array.isArray(result.raw.data) ? result.raw.data : [result.raw.data];
                }

                // 🔧 新增：尝试从 result.raw 直接获取（如果 raw 本身就是数组）
                if (!musicData.length && result.raw && Array.isArray(result.raw)) {
                    musicData = result.raw;
                }

                // 🔧 新增：尝试从 result.raw 获取单个对象（如果 raw 有 audio_url）
                if (!musicData.length && result.raw && (result.raw.audio_url || result.raw.url)) {
                    musicData = [result.raw];
                }

                console.log('🎵 解析后的音乐数据:', musicData);

                if (musicData && musicData.length > 0) {
                    // 标准化数据格式
                    const normalizedMusic = musicData.map(item => ({
                        id: item.id || item.clip_id || '',
                        title: item.title || '未命名',
                        audio_url: item.audio_url || item.url || '',
                        video_url: item.video_url || '',
                        image_url: item.image_url || item.cover || '',
                        duration: item.duration || 0,
                        tags: item.tags || '',
                        prompt: item.prompt || ''
                    })).filter(m => m.audio_url); // 只保留有音频URL的

                    console.log('🎵 标准化后的音乐数据:', normalizedMusic);
                    node.data.results = [...(node.data.results || []), ...normalizedMusic];
                }
                updateMusicNodeStatus(nodeId, node.data.status);
                renderCanvas();
                // 🔧 修复：renderCanvas 之后再更新结果区域，确保 DOM 元素存在
                setTimeout(() => {
                    updateMusicNodeResults(nodeId);
                }, 100);
                saveIdeasToHistory();
                showToast('🎵 音乐生成完成！');
                return;
            }

            if (result.is_failed) {
                throw new Error(result.fail_reason || '生成失败');
            }

            // 更新进度状态
            node.data.status = `生成中... (${attempt + 1}/${maxAttempts})`;
            updateMusicNodeStatus(nodeId, node.data.status);

            // 等待3秒后继续轮询
            await new Promise(r => setTimeout(r, 3000));

        } catch (e) {
            console.error('🎵 轮询错误:', e);
            node.data.status = `失败: ${e.message}`;
            updateMusicNodeStatus(nodeId, node.data.status);
            return;
        }
    }

    // 超时
    node.data.status = '⏰ 超时';
    updateMusicNodeStatus(nodeId, node.data.status);
    showToast('音乐生成超时，请稍后重试');
}

