/**
 * 🤖 创建AI对话节点
 */
function createChatNode(x, y, sourceId = null) {
    const nodeId = 'chat_' + Date.now();
    const node = {
        id: nodeId,
        type: 'chat',
        x: x,
        y: y,
        width: 420,
        height: 550,
        data: {
            messages: [],
            status: 'idle',
            model: 'gemini-3.1-pro-preview'
        }
    };

    flowNodes.push(node);
    if (sourceId) {
        connections.push({
            id: 'conn_' + Date.now(),
            source: sourceId,
            target: nodeId
        });
    }

    try { window.__rrSuppressAutoFocusTaskWindow && window.__rrSuppressAutoFocusTaskWindow(1200); } catch (e) { }
    renderCanvas();
    try { window.__rrFocusCanvasOnNode && window.__rrFocusCanvasOnNode(node, { animate: false }); } catch (e) { }
    initChatNodeUI(node);
    saveIdeasToHistory();
    return node;
}

/**
 * 🤖 获取AI对话节点HTML
 */
function getChatNodeHTML(node) {
    const d = node.data || {};
    const messages = Array.isArray(d.messages) ? d.messages : [];
    const status = String(d.status || 'idle');
    const nodeLocked = node.locked || false;

    const messagesHtml = messages.length === 0
        ? `<div style="text-align:center; color:#888; padding:40px 20px;">
            <div style="font-size:24px; margin-bottom:8px;">👋</div>
            <div style="font-size:13px;">你好！我是AI助手</div>
            <div style="font-size:11px; color:#666; margin-top:4px;">每次对话消耗 1 胶片</div>
           </div>`
        : messages.map((m) => {
            const isUser = m.role === 'user';
            const bgColor = isUser ? '#fbbf24' : '#1a1a2e';
            const textColor = isUser ? '#000' : '#fff';
            const align = isUser ? 'flex-end' : 'flex-start';
            const content = escapeHtml(String(m.content || '')).replace(/\n/g, '<br>');
            return `<div style="display:flex; justify-content:${align}; margin-bottom:8px;">
                <div style="max-width:85%; padding:8px 12px; background:${bgColor}; color:${textColor}; border-radius:12px; font-size:13px; line-height:1.5; word-break:break-word;">${content}</div>
            </div>`;
        }).join('');

    const isGenerating = status === 'generating';

    return `
        <div class="input-handle" onmouseup="endConnection(event, '${node.id}')" title="输入连接点"></div>
        <div class="banana-node-header" style="background: linear-gradient(135deg, #10b981, #059669);">
            <span>🤖 AI对话 ${nodeLocked ? '<span style="margin-left:4px;" title="节点已固定">🔒</span>' : ''}</span>
            <div style="display:flex;gap:4px;">
                <button class="btn-lock-node" onclick="toggleNodeLock('${node.id}')" title="${nodeLocked ? '解锁节点' : '固定节点'}" style="background:${nodeLocked ? '#ef4444' : '#3b82f6'};padding:2px 8px;border-radius:4px;color:#fff;border:none;cursor:pointer;font-size:12px;">${nodeLocked ? '🔓' : '🔒'}</button>
                <button onclick="chatNodeClear('${node.id}')" title="清空对话" style="background:#333;padding:2px 8px;border-radius:4px;color:#fff;border:none;cursor:pointer;font-size:12px;">🗑️</button>
                <button class="btn-close-node" onclick="removeNode('${node.id}')">×</button>
            </div>
        </div>
        <div class="node-content" style="padding:10px; display:flex; flex-direction:column; height:calc(100% - 40px);">
            <div id="chatMessages_${node.id}" style="flex:1; overflow-y:auto; background:#0a0a0a; border-radius:8px; padding:10px; margin-bottom:10px; min-height:300px;">
                ${messagesHtml}
                ${isGenerating ? `<div style="display:flex; justify-content:flex-start; margin-bottom:8px;">
                    <div style="padding:8px 12px; background:#1a1a2e; border-radius:12px;">
                        <div style="display:flex; gap:4px;">
                            <span style="width:6px;height:6px;background:#888;border-radius:50%;animation:chatBounce 1.4s infinite ease-in-out;animation-delay:-0.32s;"></span>
                            <span style="width:6px;height:6px;background:#888;border-radius:50%;animation:chatBounce 1.4s infinite ease-in-out;animation-delay:-0.16s;"></span>
                            <span style="width:6px;height:6px;background:#888;border-radius:50%;animation:chatBounce 1.4s infinite ease-in-out;"></span>
                        </div>
                    </div>
                </div>` : ''}
            </div>
            <div style="display:flex; flex-wrap:wrap; gap:4px; margin-bottom:8px;">
                <button onclick="chatNodeQuickAsk('${node.id}', '帮我写一个短视频剧本')" style="background:#222; border:1px solid #444; color:#fff; padding:4px 8px; border-radius:12px; font-size:10px; cursor:pointer;">📝 写剧本</button>
                <button onclick="chatNodeQuickAsk('${node.id}', '给我一些创意灵感')" style="background:#222; border:1px solid #444; color:#fff; padding:4px 8px; border-radius:12px; font-size:10px; cursor:pointer;">💡 找灵感</button>
                <button onclick="chatNodeQuickAsk('${node.id}', '帮我优化这段文案')" style="background:#222; border:1px solid #444; color:#fff; padding:4px 8px; border-radius:12px; font-size:10px; cursor:pointer;">✨ 优化文案</button>
            </div>
            <div style="display:flex; gap:8px;">
                <textarea id="chatInput_${node.id}" placeholder="输入消息..." onmousedown="event.stopPropagation()" onkeydown="chatNodeHandleKeydown(event, '${node.id}')" style="flex:1; background:#222; border:1px solid #333; border-radius:12px; padding:10px; color:#fff; font-size:13px; resize:none; height:40px;"></textarea>
                <button onclick="chatNodeSend('${node.id}')" ${isGenerating ? 'disabled' : ''} style="width:40px; height:40px; border-radius:50%; background:${isGenerating ? '#333' : '#10b981'}; border:none; color:#fff; font-size:16px; cursor:${isGenerating ? 'not-allowed' : 'pointer'};">➤</button>
            </div>
        </div>
        <style>
            @keyframes chatBounce {
                0%, 80%, 100% { transform: scale(0); }
                40% { transform: scale(1); }
            }
        </style>
    `;
}

function initChatNodeUI(node) {
    setTimeout(() => {
        const msgContainer = document.getElementById(`chatMessages_${node.id}`);
        if (msgContainer) {
            msgContainer.scrollTop = msgContainer.scrollHeight;
        }
    }, 100);
}

window.chatNodeHandleKeydown = function (e, nodeId) {
    if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        chatNodeSend(nodeId);
    }
};

window.chatNodeQuickAsk = function (nodeId, question) {
    const input = document.getElementById(`chatInput_${nodeId}`);
    if (input) {
        input.value = question;
        chatNodeSend(nodeId);
    }
};

window.chatNodeClear = function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    if (!confirm('确定清空对话？')) return;
    node.data.messages = [];
    node.data.status = 'idle';
    renderCanvas();
    initChatNodeUI(node);
    saveIdeasToHistory();
};

window.chatNodeSend = async function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    const input = document.getElementById(`chatInput_${nodeId}`);
    const text = input ? input.value.trim() : '';
    if (!text || node.data.status === 'generating') return;

    const CHAT_COST = 1;
    const canProceed = await chatNodePreDeduct(CHAT_COST, 'AI对话');
    if (!canProceed) return;

    node.data.messages.push({ role: 'user', content: text });
    node.data.status = 'generating';
    input.value = '';

    renderCanvas();
    initChatNodeUI(node);

    let deducted = true;

    try {
        const response = await fetch('/api/yunwu', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'text',
                prompt: text,
                model: node.data.model || 'gemini-3.1-pro-preview'
            })
        });

        const data = await response.json();

        if (data.error) {
            throw new Error(data.error);
        }

        const aiText = data.content || data.text || data.response || '抱歉，我没有理解你的问题。';
        node.data.messages.push({ role: 'assistant', content: aiText });
        node.data.status = 'idle';

    } catch (error) {
        node.data.messages.push({ role: 'assistant', content: '出错了：' + error.message });
        node.data.status = 'idle';
        if (deducted) await chatNodeRefund(CHAT_COST, 'AI对话失败退款');
    }

    renderCanvas();
    initChatNodeUI(node);
    saveIdeasToHistory();
};

async function chatNodePreDeduct(cost, description) {
    try {
        if (typeof NVAuth === 'undefined') {
            showToast('请先登录', 'warning');
            return false;
        }
        const user = await NVAuth.getCurrentUser();
        if (!user) {
            showToast('请先登录', 'warning');
            return false;
        }

        const balance = getFilmBalance();
        if (balance < cost) {
            showToast(`胶片不足，需要${cost}胶片`, 'warning');
            return false;
        }

        const res = await fetch('/api/supabase-proxy', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'consume', userId: user.id, amount: cost, description })
        });
        const data = await res.json();
        if (data.success) {
            localStorage.setItem('film_balance', String(data.newBalance));
            if (typeof updateUsageDisplay === 'function') updateUsageDisplay();
            console.log(`🎞️ AI对话预扣费成功: -${cost}胶片, 余额=${data.newBalance}`);
            return true;
        }
        throw new Error(data.message || '扣费失败');
    } catch (e) {
        showToast('扣费失败: ' + e.message, 'error');
        return false;
    }
}

