/**
 * 🎬 预加载 FFmpeg.wasm 核心文件（后台静默加载）
 * 这样用户真正需要合并视频时，核心已经缓存好了
 */
async function preloadFFmpegCore() {
    // 延迟3秒后开始预加载，避免影响页面初始加载
    setTimeout(async () => {
        try {
            console.log('🎬 [预加载] 开始后台加载 FFmpeg 核心...');

            // 加载 ESM 模块
            if (!window.FFmpegLoaded) {
                const { FFmpeg } = await import('https://esm.sh/@ffmpeg/ffmpeg@0.12.10');
                const { fetchFile, toBlobURL } = await import('https://esm.sh/@ffmpeg/util@0.12.1');

                window.FFmpegClass = FFmpeg;
                window.fetchFile = fetchFile;
                window.toBlobURL = toBlobURL;
                window.FFmpegLoaded = true;

                console.log('✅ [预加载] FFmpeg ESM 模块加载成功');
            }

            // 预加载核心 WASM 文件（转为 BlobURL 缓存）
            if (!window.__ffmpegCoreBlobUrls && window.toBlobURL) {
                const coreBases = [
                    'https://fastly.jsdelivr.net/npm/@ffmpeg/core@0.12.6/dist/esm',
                    'https://cdn.jsdelivr.net/npm/@ffmpeg/core@0.12.6/dist/esm',
                    'https://npm.elemecdn.com/@ffmpeg/core@0.12.6/dist/esm'
                ];

                for (const base of coreBases) {
                    try {
                        const blobUrls = {
                            coreURL: await window.toBlobURL(`${base}/ffmpeg-core.js`, 'text/javascript'),
                            wasmURL: await window.toBlobURL(`${base}/ffmpeg-core.wasm`, 'application/wasm'),
                            workerURL: await window.toBlobURL(`${base}/ffmpeg-core.worker.js`, 'text/javascript')
                        };
                        window.__ffmpegCoreBlobUrls = blobUrls;
                        window.__ffmpegCoreBase = base;
                        console.log('✅ [预加载] FFmpeg 核心已缓存:', base);
                        break;
                    } catch (e) {
                        console.warn('[预加载] CDN 失败:', base, e.message);
                    }
                }
            }
        } catch (e) {
            console.warn('[预加载] FFmpeg 预加载失败（不影响正常使用）:', e.message);
        }
    }, 3000);
}

/**
 * 🔧 计算新任务卡片的不重叠位置
 * @returns {{x: number, y: number}} 新任务的坐标
 */
function calculateNewTaskPosition() {
    // ✅ 动态估算任务窗尺寸：与“自动缩放适配”一致，避免创建时布局失真
    const container = document.getElementById('taskCanvasContainer');
    const scale = window.getCurrentScale ? window.getCurrentScale() : 1;
    const vwWorld = container ? (container.clientWidth / scale) : (window.innerWidth / scale);
    const vhWorld = container ? (container.clientHeight / scale) : (window.innerHeight / scale);
    const cardWidth = Math.min(vwWorld * 0.92, 1900);
    const cardHeight = Math.min(vhWorld * 0.82, 720);
    const padding = 40;     // 卡片间距
    const startX = 50;      // 起始X
    const startY = 50;      // 起始Y

    // 收集所有矩形（任务+节点），避免重叠
    const existingRects = [];
    ideas.forEach(i => {
        if (i.x !== undefined && i.y !== undefined) {
            existingRects.push({ x: i.x, y: i.y, width: cardWidth, height: cardHeight });
        }
    });
    if (typeof flowNodes !== 'undefined') {
        flowNodes.forEach(n => {
            existingRects.push({
                x: n.x, y: n.y,
                width: n.width || 400,
                height: n.height || 500
            });
        });
    }

    // 网格扫描寻找第一个不重叠位置
    const maxCols = 4;
    const maxRows = 50;
    for (let row = 0; row < maxRows; row++) {
        for (let col = 0; col < maxCols; col++) {
            const x = startX + col * (cardWidth + padding);
            const y = startY + row * (cardHeight + padding);
            const rect = { x, y, width: cardWidth, height: cardHeight };
            const overlap = existingRects.some(r => !(
                rect.x + rect.width + padding <= r.x ||
                rect.x >= r.x + r.width + padding ||
                rect.y + rect.height + padding <= r.y ||
                rect.y >= r.y + r.height + padding
            ));
            if (!overlap) {
                return { x, y };
            }
        }
    }
    // 如果网格满了，继续向下堆叠
    return { x: startX, y: startY + (cardHeight + padding) * maxRows };
}

/**
 * 🧲 计算不重叠的节点位置（网格布局 + 智能排斥）
 * @param {number} baseX - 基础X坐标
 * @param {number} baseY - 基础Y坐标
 * @param {number} nodeWidth - 节点宽度
 * @param {number} nodeHeight - 节点高度
 * @returns {{x: number, y: number}} 调整后的坐标
 */
function findNonOverlappingPosition(baseX, baseY, nodeWidth = 400, nodeHeight = 500) {
    const padding = 25; // 节点间距（适度紧凑）
    const gridCols = 3; // 网格列数
    const cellWidth = nodeWidth + padding;
    const cellHeight = nodeHeight + padding;
    const startX = 50; // 网格起始X
    const startY = 50; // 网格起始Y

    // 获取所有现有节点和任务卡片的位置
    const existingRects = [];

    // 添加流程节点
    flowNodes.forEach(node => {
        existingRects.push({
            x: node.x,
            y: node.y,
            width: node.width || 400,
            height: node.height || 500
        });
    });

    // 添加任务卡片（🔧 修正：使用正确的任务卡片尺寸 950x600）
    const taskCardWidth = 950;
    const taskCardHeight = 600;
    ideas.forEach(idea => {
        if (idea.canvasX !== undefined && idea.canvasY !== undefined) {
            existingRects.push({
                x: idea.canvasX,
                y: idea.canvasY,
                width: taskCardWidth,
                height: taskCardHeight
            });
        }
        // 也检查x,y属性（任务卡片的另一种存储方式）
        if (idea.x !== undefined && idea.y !== undefined) {
            existingRects.push({
                x: idea.x,
                y: idea.y,
                width: taskCardWidth,
                height: taskCardHeight
            });
        }
    });

    // 检查是否重叠
    function isOverlapping(x, y) {
        for (const rect of existingRects) {
            const overlapX = x < rect.x + rect.width + padding && x + nodeWidth + padding > rect.x;
            const overlapY = y < rect.y + rect.height + padding && y + nodeHeight + padding > rect.y;
            if (overlapX && overlapY) return true;
        }
        return false;
    }

    // 如果基础位置不重叠，直接返回
    if (!isOverlapping(baseX, baseY)) {
        return { x: baseX, y: baseY };
    }

    // 🎯 优先使用网格布局查找空位
    const maxGridCells = 30; // 最多检查30个网格位置
    for (let i = 0; i < maxGridCells; i++) {
        const col = i % gridCols;
        const row = Math.floor(i / gridCols);
        const gridX = startX + col * cellWidth;
        const gridY = startY + row * cellHeight;

        if (!isOverlapping(gridX, gridY)) {
            return { x: gridX, y: gridY };
        }
    }

    // 🔄 网格满了，使用紧凑螺旋搜索（步长更小）
    const spiralStep = 50; // 更小的步长，位置更紧凑
    let angle = 0;
    let radius = spiralStep;

    for (let i = 0; i < 40; i++) {
        const testX = baseX + radius * Math.cos(angle);
        const testY = baseY + radius * Math.sin(angle);

        if (!isOverlapping(testX, testY) && testX > 20 && testY > 20) {
            return { x: testX, y: testY };
        }

        angle += Math.PI / 6; // 每次旋转30度（更密集搜索）
        if (angle >= Math.PI * 2) {
            angle = 0;
            radius += spiralStep;
        }
    }

    // 最后备选：在基础位置附近找个位置
    return {
        x: Math.max(50, baseX + padding),
        y: Math.max(50, baseY + padding)
    };
}

/**
 * 🆕 工具栏按钮：在画布中央创建节点（带排斥）
 */
window.addBananaNodeAtCenter = function () {
    const containerEl = document.getElementById('taskCanvasContainer') || document.getElementById('taskCanvas');
    const rect = containerEl.getBoundingClientRect();
    addBananaNodeAt(rect.left + rect.width / 2, rect.top + rect.height / 2);
};

window.addKnollingNodeAtCenter = function () {
    const containerEl = document.getElementById('taskCanvasContainer') || document.getElementById('taskCanvas');
    const rect = containerEl.getBoundingClientRect();
    const p = getCanvasWorldPointFromScreen(rect.left + rect.width / 2, rect.top + rect.height / 2);
    const pos = findNonOverlappingPosition(p.x, p.y, 350, 400);
    const node = createKnollingNodeData(pos.x, pos.y);
    flowNodes.push(node);
    try { window.__rrSuppressAutoFocusTaskWindow && window.__rrSuppressAutoFocusTaskWindow(1200); } catch (e) { }
    renderCanvas();
    try { window.__rrFocusCanvasOnNode && window.__rrFocusCanvasOnNode(node, { animate: false }); } catch (e) { }
    saveIdeasToHistory();
};

window.addStickerNodeAtCenter = function () {
    const containerEl = document.getElementById('taskCanvasContainer') || document.getElementById('taskCanvas');
    const rect = containerEl.getBoundingClientRect();
    addStickerNodeAt(rect.left + rect.width / 2, rect.top + rect.height / 2);
};

