function _ptBaseVarName(instanceKey) {
    const s = String(instanceKey || '');
    const m = s.match(/^(.*?)-(\d+)$/);
    return m ? m[1] : s;
}

function _extractTemplateVarInstances(text) {
    const s = String(text || '');
    const re = /\{\{\s*([a-zA-Z0-9_-]+)\s*\}\}/g;
    const occurrences = [];
    const counts = {};
    let m;
    while ((m = re.exec(s))) {
        const base = m[1];
        counts[base] = (counts[base] || 0) + 1;
        occurrences.push({ base });
    }
    // 分配 key：同一变量出现多次时，按 PromptFill 习惯编号 base-0/base-1
    const idxMap = {};
    occurrences.forEach(o => {
        idxMap[o.base] = (idxMap[o.base] || 0);
        const multi = (counts[o.base] || 0) > 1;
        o.key = multi ? `${o.base}-${idxMap[o.base]}` : o.base;
        idxMap[o.base] += 1;
    });
    return occurrences;
}

function createPromptTemplateNodeData(x, y) {
    // ✅ 默认使用"电影级视频"模板——最强大的专业模板
    const preset = PT_PRESET_TEMPLATES.video_cinematic;
    return {
        id: 'pt_' + Date.now(),
        type: 'prompt-template',
        x,
        y,
        width: 400,
        height: 880, // ✅ 从720增加到880，彻底解决显示不全
        data: {
            templateName: 'Untitled',
            presetKey: 'video_cinematic',
            templateText: preset.templateText,
            vars: { ...preset.defaultVars },
            generatedPrompt: '',
            generatedMeta: {
                vars: {},
                updatedAt: ''
            },
            autoRandomize: true // ✅ 新增：自动随机化选项
        }
    };
}

function _extractTemplateVars(text) {
    // 兼容旧逻辑：只返回 base 变量名集合
    const occ = _extractTemplateVarInstances(text);
    return [...new Set(occ.map(o => o.base))];
}

function _ensurePromptTemplateVars(node) {
    if (!node?.data) return;
    const occ = _extractTemplateVarInstances(node.data.templateText || '');
    const names = [...new Set(occ.map(o => o.key))];
    node.data.vars = node.data.vars || {};
    // add missing
    names.forEach((n) => {
        if (!node.data.vars[n]) {
            // 多实例变量：共享 base 的 options
            const base = _ptBaseVarName(n);
            const baseEntry = node.data.vars[base];
            const sharedOptions = Array.isArray(baseEntry?.options) ? baseEntry.options : [];
            node.data.vars[n] = { options: sharedOptions, value: '' };
        }
    });
    // remove stale (keep if user created but not used? keep to avoid data loss)
    // 这里不删除旧变量，只标记未使用时不渲染，避免用户误删
}

function _renderPromptTemplateVarsHTML(node) {
    const data = node.data || {};
    const occ = _extractTemplateVarInstances(data.templateText || '');
    if (!occ.length) {
        return `<div style="font-size:12px;color:#9ca3af;">未检测到变量。用 <code style="color:#fcd34d;">{{var}}</code> 写变量。</div>`;
    }

    const __ptCnLabelMap = {
        // 视频相关
        timeline: '时间线/节奏',
        visual_style: '视觉风格',
        character: '角色/主角',
        characters: '角色们',
        environment: '环境/场景',
        mood: '情绪氛围',
        camera_movement: '镜头运动',
        music_feel: '音乐氛围',
        special_requirements: '特殊要求',
        special_requirement: '特殊要求',
        special_require: '特殊要求',
        // 艺术/绘画相关
        theme: '创作主题',
        art_movement: '艺术流派',
        technique: '绘画技法',
        color_theory: '色彩理论',
        art_composition: '构图设计',
        emotion: '情感表达',
        symbolism: '象征意义',
        master_artist: '大师参考',
        canvas_size: '画布尺寸',
        exhibition_quality: '展览级别',
        // 通用变量
        subject: '主题/对象',
        object: '物体/对象',
        topic: '话题/主题',
        scene: '场景',
        style: '风格',
        name: '名称/姓名',
        title: '标题',
        // 产品相关
        product: '产品名称',
        brand: '品牌名称',
        company: '公司/组织',
        project: '项目名称',
        // 人物相关
        age: '年龄',
        clothing: '服装/穿着',
        occupation: '职业',
        // 创意设计
        app_name: 'App名称',
        icon_style: '图标风格',
        album_name: '专辑名称',
        book_title: '书籍标题',
        movie_title: '电影标题',
        genre: '类型/风格',
        // 食物/宠物
        food: '食物',
        pet: '宠物',
        dish: '菜品名称',
        plant: '植物名称',
        // 文化相关
        region: '地区',
        dynasty: '朝代',
        mythology: '神话体系',
        craft: '工艺名称',
        tea_type: '茶叶种类',
        period: '时间段',
        year: '年份',
        month: '月份',
        // 游戏化
        category: '分类',
        field: '领域',
        activity: '活动',
        milestone: '里程碑',
        challenge_name: '挑战名称',
        // 数据/技术
        dataset: '数据集',
        sequence: '序列',
        formula: '公式',
        word: '单词',
        effect: '效果',
        artwork: '艺术品',
        // 情感/心理
        anxiety_type: '焦虑类型',
        // 内容创作
        work: '作品名称',
        universe: '宇宙/世界观',
        story: '故事内容',
        before_state: '之前状态',
        after_state: '之后状态',
        service: '服务名称',
        // 日历相关
        date: '日期',
        day: '日',
        weekday: '星期',
        solar_term: '节气',
        festival: '节日',
        quote: '语录/格言',
        lunar_date: '农历日期',
        zodiac: '生肖',
        constellation: '星座'
    };

    function __ptCnLabel(base) {
        const k = String(base || '').trim();
        return __ptCnLabelMap[k] || k;
    }

    // 生成唯一 key 列表（同变量多处出现会有 key-0/key-1）
    const usedKeys = occ.map(o => o.key);
    return `
        <div class="pt-vars">
            ${usedKeys.map((key) => {
        const base = _ptBaseVarName(key);
        const cnBase = __ptCnLabel(base);
        const idx = (key.match(/-(\d+)$/)?.[1] ? (Number(key.match(/-(\d+)$/)[1]) + 1) : null);
        const display = key === base ? cnBase : `${cnBase}（${idx || ''}）`;
        const entry = (data.vars && data.vars[key]) ? data.vars[key] : { options: [], value: '' };
        // options 以 base 为准（所有实例共享）
        const baseOpts = Array.isArray(data.vars?.[base]?.options) ? data.vars[base].options : (Array.isArray(entry.options) ? entry.options : []);
        const opts = baseOpts;
        const val = (entry.value ?? '');
        const optionsHtml = [
            `<option value="" ${val === '' ? 'selected' : ''}>（未选择）</option>`,
            ...opts.map(o => `<option value="${escapeHtml(String(o))}" ${String(o) === String(val) ? 'selected' : ''}>${escapeHtml(String(o))}</option>`),
            `<option value="__pt_custom__">＋ 添加自定义选项…</option>`
        ].join('');
        return `
                    <div class="pt-var-row">
                        <div class="pt-var-name" title="${escapeHtml(display)}">${escapeHtml(display)}</div>
                        <select class="pt-select" onchange="window.ptSetVarValue('${node.id}','${escapeHtml(key)}', this.value)" onmousedown="event.stopPropagation()">
                            ${optionsHtml}
                        </select>
                        <button class="pt-btn" onclick="window.ptEditVarOptions('${node.id}','${escapeHtml(base)}')" onmousedown="event.stopPropagation()">选项</button>
                    </div>
                `;
    }).join('')}
        </div>
    `;
}

function getPromptTemplateNodeHTML(node) {
    const d = node.data || {};
    _ensurePromptTemplateVars(node);
    const varsHtml = _renderPromptTemplateVarsHTML(node);
    const out = d.generatedPrompt || '';
    const presetKey = d.presetKey || 'video_cinematic';
    const presetOptions = Object.entries(PT_PRESET_TEMPLATES).map(([k, v]) =>
        `<option value="${escapeHtml(k)}" ${String(k) === String(presetKey) ? 'selected' : ''}>${escapeHtml(v.name)}</option>`
    ).join('');
    const nodeLocked = node.locked || false;
    return `
        <div class="input-handle" onmouseup="endConnection(event, '${node.id}')" title="输入连接点"></div>
        <div class="prompt-template-node-header">
            <span>🧩 提示词模版（填空） ${nodeLocked ? '<span style="margin-left:4px;" title="节点已固定">🔒</span>' : ''}</span>
            <div style="display:flex;gap:4px;">
                <button class="btn-lock-node" onclick="toggleNodeLock('${node.id}')" title="${nodeLocked ? '解锁节点' : '固定节点'}" style="background:${nodeLocked ? '#ef4444' : '#3b82f6'};padding:2px 8px;border-radius:4px;color:#fff;border:none;cursor:pointer;font-size:12px;">${nodeLocked ? '🔓' : '🔒'}</button>
                <button class="btn-close-node" onclick="removeNode('${node.id}')">×</button>
            </div>
        </div>
        <div class="prompt-template-content">
            <div class="pt-inner">
                <div style="display:flex; gap:8px; align-items:center;">
                    <input type="text" value="${escapeHtml(d.templateName || 'Untitled')}" 
                        oninput="window.ptSetTemplateName('${node.id}', this.value)" 
                        onmousedown="event.stopPropagation()"
                        style="flex:1; background:#222; border:1px solid #444; color:#fff; padding:6px 8px; border-radius:8px; font-size:12px;">
                    <button class="pt-btn" onclick="window.ptRescanVars('${node.id}')" onmousedown="event.stopPropagation()">刷新变量</button>
                </div>
                <div style="display:flex; gap:8px; align-items:center;">
                    <select class="pt-select" onchange="window.ptSelectPreset('${node.id}', this.value)" onmousedown="event.stopPropagation()" style="flex:1;">
                        ${presetOptions}
                    </select>
                    <button class="pt-btn" onclick="window.ptApplyPreset('${node.id}')" onmousedown="event.stopPropagation()">套用</button>
                </div>
                <div>
                    <div style="font-size:11px;color:#9ca3af;margin-bottom:6px;">模板（用 <code style="color:#fcd34d;">{{var}}</code> 写变量）</div>
                    <textarea class="pt-textarea"
                        oninput="window.ptSetTemplateText('${node.id}', this.value)"
                        onmousedown="event.stopPropagation()"
                    >${escapeHtml(d.templateText || '')}</textarea>
                </div>
                <div>
                    <div style="font-size:11px;color:#9ca3af;margin-bottom:6px;">变量填空</div>
                    ${varsHtml}
                </div>
                <div style="display: flex; align-items: center; gap: 8px; margin-bottom: 8px;">
                    <label style="font-size: 11px; color: #9ca3af; display: flex; align-items: center; gap: 4px; cursor: pointer;">
                        <input type="checkbox" ${node.data.autoRandomize !== false ? 'checked' : ''} 
                               onchange="window.ptToggleRandomize('${node.id}', this.checked)"
                               onmousedown="event.stopPropagation()"
                               style="cursor: pointer;">
                        🎲 随机组合
                    </label>
                </div>
                <div style="display:flex; gap:8px;">
                    <button class="pt-btn pt-btn-primary" onclick="window.ptGenerate('${node.id}')" onmousedown="event.stopPropagation()" style="flex:1;">⚡ 生成</button>
                    <button class="pt-btn" onclick="window.ptCopy('${node.id}')" onmousedown="event.stopPropagation()">📋</button>
                </div>
                <div>
                    <div style="font-size:11px;color:#9ca3af;margin-bottom:6px;">输出（可连线传递给多个下游节点）</div>
                    <div class="pt-output" id="pt-output-${node.id}">${escapeHtml(out)}</div>
                </div>
            </div>
        </div>
        <div class="output-handle" onmousedown="startConnection(event, '${node.id}')" ontouchstart="startConnectionTouch(event, '${node.id}')" title="输出连接点"></div>
        <div class="resize-handle" onmousedown="startNodeResize(event, '${node.id}')" title="拖拽调整大小"></div>
    `;
}

function _ptPropagateToDownstream(sourceId, payload) {
    const prompt = String(payload?.prompt || '').trim();
    if (!prompt) return;
    const meta = payload?.meta || {};

    // 合并 connections + localStorage，保持与旧逻辑一致
    const savedConns = JSON.parse(localStorage.getItem('node_connections') || '[]');
    const allConns = [...connections, ...savedConns];
    const uniqueConns = allConns.filter((conn, index, self) =>
        index === self.findIndex(c => c.source === conn.source && c.target === conn.target)
    );

    const outgoing = uniqueConns.filter(c => c.source === sourceId);
    outgoing.forEach(conn => {
        const targetNode = flowNodes.find(n => n.id === conn.target);
        if (!targetNode) return;
        if (!targetNode.data) targetNode.data = {};
        // ✅ 对下游：仍沿用 knollingPrompt 字段，保持兼容
        targetNode.data.knollingPrompt = prompt;
        // ✅ 多字段输出：额外附带 meta（暂不参与生成，供后续扩展/调试）
        targetNode.data.promptTemplateMeta = meta;
    });

    saveIdeasToHistory();
    renderCanvas();
    // 延迟刷新显示
    setTimeout(() => {
        outgoing.forEach(conn => {
            try { updateNodeAutoPromptDisplay(conn.target); } catch (e) { }
        });
    }, 120);
}

window.ptSetTemplateName = function (nodeId, name) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    node.data.templateName = String(name || '').slice(0, 60);
    saveIdeasToHistory();
};

window.ptSetTemplateText = function (nodeId, text) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    node.data.templateText = String(text || '');
    _ensurePromptTemplateVars(node);
    saveIdeasToHistory();
};

window.ptSetPreset = function (nodeId, presetKey) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    node.data.presetKey = String(presetKey || 'video_cinematic');
    saveIdeasToHistory();
};

// ✅ 对齐 PromptFill：选择预设=立即生效（无需再点"套用"）
window.ptSelectPreset = function (nodeId, presetKey) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    node.data.presetKey = String(presetKey || 'video_cinematic');
    // 立刻套用模板与变量，并刷新 UI
    window.ptApplyPreset(nodeId);
};

window.ptApplyPreset = function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    const key = String(node.data?.presetKey || 'video_cinematic');
    const preset = PT_PRESET_TEMPLATES[key] || PT_PRESET_TEMPLATES.video_cinematic;
    node.data.templateText = preset.templateText;
    // 合并变量：保留已有值，但补齐 preset 中新增项
    node.data.vars = node.data.vars || {};
    Object.entries(preset.defaultVars || {}).forEach(([k, v]) => {
        if (!node.data.vars[k]) node.data.vars[k] = { options: [], value: '' };
        const nextOpts = Array.isArray(v?.options) ? v.options : [];
        const keepVal = String(node.data.vars[k]?.value ?? '').trim();
        node.data.vars[k].options = [...new Set([...(node.data.vars[k].options || []), ...nextOpts])];
        if (!keepVal) node.data.vars[k].value = String(v?.value ?? '');
    });
    _ensurePromptTemplateVars(node);
    saveIdeasToHistory();
    renderCanvas();
};

window.ptRescanVars = function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    _ensurePromptTemplateVars(node);
    saveIdeasToHistory();
    renderCanvas();
};

window.ptSetVarValue = function (nodeId, varName, value) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    node.data.vars = node.data.vars || {};
    node.data.vars[varName] = node.data.vars[varName] || { options: [], value: '' };
    const v = String(value ?? '');
    console.log(`🔧 [ptSetVarValue] 节点: ${nodeId}, 变量: ${varName}, 新值: "${v}"`);
    if (v === '__pt_custom__') {
        const base = _ptBaseVarName(varName);
        const custom = prompt(`为变量「${base}」添加自定义选项：`, '');
        if (custom === null) return;
        const c = String(custom || '').trim();
        if (!c) return;
        // 写入 base 的 options，并同步到同名实例
        node.data.vars[base] = node.data.vars[base] || { options: [], value: '' };
        node.data.vars[base].options = [...new Set([...(node.data.vars[base].options || []), c])];
        // 所有实例共享 options（保持一致）
        Object.keys(node.data.vars).forEach((k) => {
            if (_ptBaseVarName(k) === base) {
                node.data.vars[k].options = node.data.vars[base].options;
            }
        });
        node.data.vars[varName].value = c;
        saveIdeasToHistory();
        renderCanvas();
        return;
    }
    node.data.vars[varName].value = v;
    saveIdeasToHistory();
};

window.ptEditVarOptions = function (nodeId, varName) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    node.data.vars = node.data.vars || {};
    const base = _ptBaseVarName(varName);
    node.data.vars[base] = node.data.vars[base] || { options: [], value: '' };
    const entry = node.data.vars[base];
    const current = Array.isArray(entry.options) ? entry.options.join('\n') : '';
    const next = prompt(`编辑变量「${varName}」的选项（每行一个）`, current);
    if (next === null) return;
    const options = String(next || '').split(/\r?\n/).map(s => s.trim()).filter(Boolean);
    entry.options = [...new Set(options)];
    // 同步所有实例的 options
    Object.keys(node.data.vars).forEach((k) => {
        if (_ptBaseVarName(k) === base) {
            node.data.vars[k].options = entry.options;
        }
    });
    saveIdeasToHistory();
    renderCanvas();
};

window.ptGenerate = function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    _ensurePromptTemplateVars(node);
    const data = node.data || {};
    const tpl = String(data.templateText || '');
    const occ = _extractTemplateVarInstances(tpl);
    const vars = data.vars || {};

    const presetKey = String(data.presetKey || '');
    const preset = (typeof PT_PRESET_TEMPLATES !== 'undefined' && presetKey && PT_PRESET_TEMPLATES[presetKey])
        ? PT_PRESET_TEMPLATES[presetKey]
        : null;
    const isImageTemplate = String(preset?.category || '') === 'image';

    // ✅ 新增：随机化功能
    const autoRandomize = data.autoRandomize !== false; // 默认开启随机化

    // ✅ 对齐并超越 PromptFill：支持 "A|B|C" 批量生成
    // - 你可以在"自定义选项"里填：写实|日漫|赛博朋克
    // - 生成时会做组合展开（有限上限），并把第 1 条作为主输出传递给下游
    const mappingSingle = {};
    const mappingChoices = {};

    const _shuffleInPlace = (arr) => {
        try {
            for (let i = arr.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [arr[i], arr[j]] = [arr[j], arr[i]];
            }
        } catch (e) { }
        return arr;
    };

    const splitChoices = (s) => {
        const raw = String(s ?? '').trim();
        if (!raw) return [''];
        const parts = raw.split('|').map(x => x.trim()).filter(Boolean);
        const out = parts.length ? parts : [raw];
        // ✅ 让 A|B|C 自填也能随机变化：随机打乱顺序，从而改变第1条输出
        if (autoRandomize && out.length > 1) _shuffleInPlace(out);
        return out;
    };

    occ.forEach((o) => {
        const raw = String(vars?.[o.key]?.value ?? vars?.[o.base]?.value ?? '').trim();
        console.log(`🔍 [ptGenerate] 变量 ${o.key}: value="${raw}"`);
        const choices = splitChoices(raw);

        // 🎲 随机化：
        // - 优先使用预设 options（更标准）
        // - 若用户用 A|B|C 自填：splitChoices 已经随机打乱
        if (autoRandomize && vars?.[o.key]?.options && vars[o.key].options.length > 1) {
            const randomOptions = _shuffleInPlace([...(vars[o.key].options || [])]);
            const randomChoice = randomOptions[0];
            mappingChoices[o.key] = [randomChoice];
            mappingSingle[o.key] = randomChoice;
        } else {
            mappingChoices[o.key] = choices;
            // ✅ 关键：不要永远取 choices[0]（可能固定不变）
            mappingSingle[o.key] = (autoRandomize && choices.length > 1)
                ? choices[Math.floor(Math.random() * choices.length)]
                : (choices[0] || '');
        }
    });

    // ✅ 保证“每次点生成都不同”：注入轻量随机变化因子
    // - 若模板里包含 {{variation}} / {{random}} 占位符：自动填充（即使用户不填）
    // - 若模板不包含：在输出末尾追加一行【随机细节】（对模型影响很小，但能保证文本差异）
    const _ptRandomPool = [
        '细微胶片颗粒与散景bokeh',
        '轻微镜头光晕与高光溢出',
        '背景增加若隐若现的环境元素',
        '色彩分级偏暖，阴影更深',
        '色彩分级偏冷，反差更强',
        '构图稍微偏左，留白更多',
        '增加前景遮挡增强空间层次',
        '加入微弱薄雾与体积光',
        '增加材质细节（布料纹理/金属反光）'
    ];
    const _ptPickRand = () => _ptRandomPool[Math.floor(Math.random() * _ptRandomPool.length)];
    const _hasVariationPlaceholder = occ.some(o => ['variation', 'random'].includes(String(o.base || o.key || '').trim()));
    if (autoRandomize && _hasVariationPlaceholder) {
        occ.forEach((o) => {
            const k = String(o.key || '').trim();
            const b = String(o.base || '').trim();
            if (!(b === 'variation' || b === 'random' || k === 'variation' || k === 'random')) return;
            if (String(mappingSingle[k] || '').trim()) return;
            const v = _ptPickRand();
            mappingChoices[k] = [v];
            mappingSingle[k] = v;
        });
    }

    const maxBatch = Math.max(1, Math.min(24, Number(data.batchMax || 8)));
    let prompts = [];

    const buildPromptWithMapping = (mapping) => {
        let out = tpl;
        const counters = {};
        out = out.replace(/\{\{\s*([a-zA-Z0-9_-]+)\s*\}\}/g, (_, base) => {
            counters[base] = (counters[base] || 0);
            const multi = occ.filter(x => x.base === base).length > 1;
            const key = multi ? `${base}-${counters[base]}` : base;
            counters[base] += 1;
            return String(mapping[key] ?? '');
        });
        return String(out || '').trim();
    };

    // 组合展开（按变量实例顺序）
    const keys = occ.map(o => o.key);
    const dfs = (i, cur) => {
        if (prompts.length >= maxBatch) return;
        if (i >= keys.length) {
            const p = buildPromptWithMapping(cur);
            if (p) prompts.push(p);
            return;
        }
        const k = keys[i];
        const options = Array.isArray(mappingChoices[k]) ? mappingChoices[k] : [''];
        for (const opt of options) {
            if (prompts.length >= maxBatch) break;
            cur[k] = opt;
            dfs(i + 1, cur);
        }
    };
    dfs(0, { ...mappingSingle });

    // fallback
    if (!prompts.length) prompts = [buildPromptWithMapping(mappingSingle)].filter(Boolean);

    // ✅ 如果是批量 prompts：随机打乱并选一条作为主输出，避免每次都输出第1条
    if (autoRandomize && prompts.length > 1) {
        prompts = _shuffleInPlace(prompts);
    }

    let out = String(prompts[0] || '').trim();
    if (!isImageTemplate && autoRandomize && !_hasVariationPlaceholder) {
        out = out ? `${out}\n【随机细节】${_ptPickRand()}` : out;
    }

    // ✅ 主题/subject 强制影响：
    // 如果用户在 vars 中填写了 subject/topic/theme，但模板里没写 {{subject}}，也要注入到输出
    try {
        const _themeVal = String(vars?.subject?.value || vars?.topic?.value || vars?.theme?.value || '').trim();
        const _tplHasTheme = /\{\{\s*(subject|topic|theme)\s*\}\}/i.test(tpl);
        if (!isImageTemplate && _themeVal && !_tplHasTheme) {
            out = `【主题】${_themeVal}\n${out}`;
        }
    } catch (e) { }

    // ✅ 若是批量列表，确保第 1 条与 out 对齐（否则复制/下游用列表时看起来“不生效”）
    if (Array.isArray(prompts) && prompts.length > 0) {
        prompts[0] = out;
    }
    console.log(`✅ [ptGenerate] 最终生成提示词: "${out.substring(0, 100)}..."`);
    console.log(`📊 [ptGenerate] 变量映射:`, mappingSingle);
    data.generatedPrompt = out;
    data.generatedPrompts = prompts;
    // ✅ 兼容：供下游递归收集 prompts 列表（视频节点/批量任务）
    data.promptTemplateAllPrompts = prompts;
    data.generatedMeta = {
        vars: mappingSingle,
        varsChoices: mappingChoices,
        prompts,
        batchMax: maxBatch,
        updatedAt: new Date().toISOString(),
        templateName: data.templateName || '',
        presetKey: data.presetKey || ''
    };

    const el = document.getElementById(`pt-output-${nodeId}`);
    if (el) el.textContent = out ? (prompts.length > 1 ? `${out}\n\n（批量生成 ${prompts.length} 条，已输出第1条；其余可在“📋”复制中查看）` : out) : '';

    // ✅ 传递给多个下游（默认第 1 条），meta 带全量列表
    _ptPropagateToDownstream(nodeId, { prompt: out, meta: data.generatedMeta });
    saveIdeasToHistory();
};

window.ptCopy = function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    const prompts = Array.isArray(node?.data?.generatedPrompts) ? node.data.generatedPrompts : [];
    const text = prompts.length > 1 ? prompts.join('\n\n---\n\n') : (node?.data?.generatedPrompt || '');
    if (!text) return alert('请先生成提示词');
    navigator.clipboard.writeText(text);
    alert('✅ 已复制');
};

function initPromptTemplateNodeUI(node) {
    const nodeEl = document.getElementById(`node-${node.id}`);
    if (!nodeEl) return;
    const header = nodeEl.querySelector('.prompt-template-node-header');
    if (!header) return;

    header.addEventListener('mousedown', (e) => {
        if (e.target.closest('button') || e.target.closest('select') || e.target.closest('input') || e.target.closest('textarea')) return;
        e.preventDefault();
        e.stopPropagation();
        const startX = e.clientX;
        const startY = e.clientY;
        const origX = node.x;
        const origY = node.y;
        const scale = window.getCurrentScale ? window.getCurrentScale() : 1;

        const onMove = (moveE) => {
            const dx = (moveE.clientX - startX) / scale;
            const dy = (moveE.clientY - startY) / scale;
            node.x = origX + dx;
            node.y = origY + dy;
            nodeEl.style.left = node.x + 'px';
            nodeEl.style.top = node.y + 'px';
            renderConnections();
        };
        const onUp = () => {
            document.removeEventListener('mousemove', onMove);
            document.removeEventListener('mouseup', onUp);
            saveIdeasToHistory();
        };
        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup', onUp);
    });
}

