/**
 * 更新纯文本输入节点的值
 */
window.updateTextInputValue = function (nodeId, value) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    node.data.text = value;
    node.data.knollingPrompt = value; // 同步更新 knollingPrompt 以便下游节点读取
    saveIdeasToHistory();
};

/**
 * 传递文本到下游节点
 */
window.propagateTextInput = function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    const text = (node.data.text || '').trim();
    if (!text) {
        alert('请先输入文本内容');
        return;
    }

    // 更新 knollingPrompt
    node.data.knollingPrompt = text;

    // 查找所有下游连接
    const outgoingConns = connections.filter(c => c.source === nodeId);
    if (outgoingConns.length === 0) {
        alert('请先连接下游节点');
        return;
    }

    let propagatedCount = 0;
    for (const conn of outgoingConns) {
        const targetNode = flowNodes.find(n => n.id === conn.target);
        if (targetNode) {
            targetNode.data.knollingPrompt = text;
            targetNode.data.prompt = text;
            propagatedCount++;

            // 更新下游节点的显示
            if (typeof updateNodeAutoPromptDisplay === 'function') {
                updateNodeAutoPromptDisplay(targetNode.id, text);
            }
        }
    }

    saveIdeasToHistory();
    renderCanvas();

    // 显示成功提示
    const toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);background:#10b981;color:#fff;padding:10px 20px;border-radius:8px;z-index:99999;font-size:14px;';
    toast.textContent = `✅ 已传递到 ${propagatedCount} 个下游节点`;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2000);
};

/**
 * 复制文本输入内容
 */
window.copyTextInputValue = function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    const text = node.data.text || '';
    navigator.clipboard.writeText(text).then(() => {
        const toast = document.createElement('div');
        toast.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);background:#3b82f6;color:#fff;padding:10px 20px;border-radius:8px;z-index:99999;font-size:14px;';
        toast.textContent = '📋 已复制到剪贴板';
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 1500);
    });
};

