/**
 * 生成 Knolling 提示词
 */
window.generateKnollingPrompt = function (nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    const tpl = PROMPT_TEMPLATES[node.data.template] || PROMPT_TEMPLATES.knolling;
    let prompt = tpl.template;

    // 替换所有变量 - 统一用 subject 替换
    const rawSubject = String(node.data.subject || '').trim();
    let subject = rawSubject || '物品';

    // 🎲 随机化：如果启用，添加随机修饰词让每次生成都不同
    const autoRandomize = node.data.autoRandomize !== false;
    const _kRandPool = [
        '电影感光影与胶片颗粒',
        '浅景深散景bokeh',
        '暖色灯串与柔光',
        '冷暖对比与轮廓光',
        '体积光与薄雾氛围',
        '更干净的构图与留白',
        '材质细节（布料纹理/金属反光）',
        '高对比度与更深阴影',
        '更鲜艳的节日配色点缀'
    ];
    const _kPick = () => _kRandPool[Math.floor(Math.random() * _kRandPool.length)];
    const _kRand = _kPick();
    if (autoRandomize) {
        const randomEnhancements = [
            '', // 有时不加修饰
            '精致的',
            '独特的',
            '创意的',
            '极简的',
            '复古的',
            '现代的',
            '梦幻的',
            '时尚的',
            '经典的',
            '未来感的',
            '手工的',
            '艺术的',
            '简约的',
            '华丽的'
        ];
        const randomStyles = [
            '',
            '，高清细节',
            '，4K画质',
            '，电影感光线',
            '，柔和光线',
            '，温暖色调',
            '，冷色调',
            '，鲜艳色彩',
            '，简洁背景',
            '，干净构图',
            '，专业摄影',
            '，工作室级',
            '，精细纹理'
        ];

        const enhancement = randomEnhancements[Math.floor(Math.random() * randomEnhancements.length)];
        const style = randomStyles[Math.floor(Math.random() * randomStyles.length)];

        subject = enhancement + subject + style;
    }

    // ✅ 新增：支持 "______（说明）" 格式的填空
    // 将所有 "______（任意说明文字）" 替换为用户输入的subject
    prompt = prompt.replace(/______(?:（[^）]*）)?/g, subject);

    // 通用变量替换 {variable} 格式
    prompt = prompt.replace(/{subject}/g, subject);
    prompt = prompt.replace(/{product}/g, subject);
    prompt = prompt.replace(/{object}/g, subject);
    prompt = prompt.replace(/{characters}/g, subject);
    prompt = prompt.replace(/{character}/g, subject);
    prompt = prompt.replace(/{topic}/g, subject);
    prompt = prompt.replace(/{scene}/g, subject);
    prompt = prompt.replace(/{food}/g, subject);
    prompt = prompt.replace(/{pet}/g, subject);
    prompt = prompt.replace(/{app_name}/g, subject);
    prompt = prompt.replace(/{album_name}/g, subject);
    prompt = prompt.replace(/{book_title}/g, subject);
    prompt = prompt.replace(/{movie_title}/g, subject);

    // 带默认值的变量
    prompt = prompt.replace(/{name}/g, node.data.customVars?.name || subject);
    prompt = prompt.replace(/{occupation}/g, node.data.customVars?.occupation || 'Artist');
    prompt = prompt.replace(/{company}/g, node.data.customVars?.company || 'Studio');
    prompt = prompt.replace(/{type}/g, node.data.customVars?.type || '亚克力');
    prompt = prompt.replace(/{bag_type}/g, node.data.customVars?.bag_type || 'LV');
    prompt = prompt.replace(/{style}/g, node.data.customVars?.style || '现代简约');
    prompt = prompt.replace(/{genre}/g, node.data.customVars?.genre || '流行');
    prompt = prompt.replace(/{age}/g, node.data.customVars?.age || '5');
    prompt = prompt.replace(/{clothing}/g, node.data.customVars?.clothing || '白色T恤');
    prompt = prompt.replace(/{icon_style}/g, node.data.customVars?.icon_style || '扁平化');

    // ✅ 确保“主题输入必生效”：如果模板本身没有任何占位符导致主题没进入 prompt，则强制注入
    try {
        if (rawSubject) {
            const hasRaw = prompt.includes(rawSubject);
            const hasSubject = prompt.includes(subject);
            if (!hasRaw && !hasSubject) {
                prompt = `主题：${rawSubject}，${prompt}`;
            }
        }
    } catch (e) { }

    // ✅ 确保“随机变化必生效”：即使模板不使用 subject，也追加一段随机细节
    if (autoRandomize) {
        prompt = `${prompt}\n【随机变化】${_kRand}`;
    }

    node.data.generatedPrompt = prompt;

    // 更新显示
    const outputEl = document.getElementById(`knolling-output-${nodeId}`);
    if (outputEl) {
        outputEl.value = prompt;
    }

    // 🔗 自动传递提示词到所有连接的节点
    // 合并 connections 和 localStorage 的连接
    const savedConns = JSON.parse(localStorage.getItem('node_connections') || '[]');
    const allConns = [...connections, ...savedConns];
    // 去重
    const uniqueConns = allConns.filter((conn, index, self) =>
        index === self.findIndex(c => c.source === conn.source && c.target === conn.target)
    );
    console.log('🔗 所有连接:', uniqueConns.length, 'nodeId:', nodeId);

    // 检查作为 source 的连接（从本节点输出）
    const outgoingConns = uniqueConns.filter(c => c.source === nodeId);
    // 也检查作为 target 的连接（可能连接方向相反）
    const incomingConns = uniqueConns.filter(c => c.target === nodeId);
    console.log('📤 输出:', outgoingConns.length, '📥 输入:', incomingConns.length);

    // 传递到所有连接的 Banana 节点
    let transferred = false;

    outgoingConns.forEach(conn => {
        const targetNode = flowNodes.find(n => n.id === conn.target);
        console.log('🎯 目标:', conn.target, targetNode?.type);
        if (targetNode) {
            targetNode.data.knollingPrompt = prompt;
            transferred = true;
            console.log('✅ 传递到:', conn.target);
        }
    });

    incomingConns.forEach(conn => {
        const sourceNode = flowNodes.find(n => n.id === conn.source);
        console.log('🎯 源:', conn.source, sourceNode?.type);
        if (sourceNode) {
            sourceNode.data.knollingPrompt = prompt;
            transferred = true;
            console.log('✅ 传递到:', conn.source);
        }
    });

    // 统一刷新画布和更新显示 - 🔧 无论是否有连接都执行刷新
    saveIdeasToHistory();
    renderCanvas();

    // 延迟更新所有连接节点的提示词显示
    setTimeout(() => {
        [...outgoingConns, ...incomingConns].forEach(conn => {
            updateNodeAutoPromptDisplay(conn.target);
            updateNodeAutoPromptDisplay(conn.source);
        });
        console.log(`%c✅ 提示词已生成并传递: ${prompt.substring(0, 50)}...`, 'color: lime; font-weight: bold;');
        console.log(`   传递到 ${outgoingConns.length} 个下游节点`);
    }, 150);
};

