function openLibrary(tab = null) {
    const overlay = document.getElementById('libraryOverlay');
    overlay.style.display = 'flex';
    // Force reflow
    overlay.offsetHeight;
    overlay.classList.add('active');

    // 记住角色库打开状态
    localStorage.setItem('library_open', 'true');

    // 如果指定了 tab，切换到该 tab
    if (tab) {
        switchLibTab(tab);
    } else if (!document.querySelector('.lib-tab.active')) {
        // Default to 'tasks' tab if none active
        const savedTab = localStorage.getItem('library_tab') || 'tasks';
        switchLibTab(savedTab);
    }
}

function closeLibrary() {
    const overlay = document.getElementById('libraryOverlay');
    overlay.classList.remove('active');

    // 清除角色库打开状态
    localStorage.removeItem('library_open');

    setTimeout(() => {
        overlay.style.display = 'none';
    }, 300); // Wait for transition
}

function switchLibTab(tab) {
    document.querySelectorAll('.lib-tab').forEach(t => t.classList.remove('active'));
    document.querySelectorAll('.lib-panel').forEach(p => p.classList.remove('active'));

    // 记住当前 tab
    localStorage.setItem('library_tab', tab);

    if (tab === 'tasks') {
        document.querySelector('.lib-tab[onclick="switchLibTab(\'tasks\')"]').classList.add('active');
        document.getElementById('libTasksPanel').classList.add('active');
        renderLibTasks();
    } else {
        document.querySelector('.lib-tab[onclick="switchLibTab(\'chars\')"]').classList.add('active');
        document.getElementById('libCharsPanel').classList.add('active');
        renderLibChars();
    }
}

