// ==================== Video Playback Logic ====================

function playNextClip(id) {
    const vid = document.getElementById(`v-${id}`);
    if (!vid) return;
    const idea = (typeof ideas !== 'undefined' && Array.isArray(ideas)) ? ideas.find(i => i.id === id) : null;
    // ✅ 如果已经有合并后的单文件（非顺序播放模式），就不切片段
    if (idea && idea.finalVideoUrl && idea.mergedSuccessfully && !idea.playlistMode) {
        return;
    }
    const playlistAttr = vid.getAttribute('data-playlist') || '';
    const playlist = playlistAttr ? playlistAttr.split(',') : [];
    let currentIdx = parseInt(vid.getAttribute('data-current') || '0');

    currentIdx++;
    if (currentIdx < playlist.length && playlist[currentIdx]) {
        vid.src = playlist[currentIdx];
        vid.setAttribute('data-current', currentIdx);
        vid.play();
    } else {
        // Finished loop
    }
}

function replayAll(id) {
    const vid = document.getElementById(`v-${id}`);
    if (!vid) return;
    const idea = (typeof ideas !== 'undefined' && Array.isArray(ideas)) ? ideas.find(i => i.id === id) : null;
    if (idea && idea.finalVideoUrl && idea.mergedSuccessfully && !idea.playlistMode) {
        vid.setAttribute('data-current', '0');
        vid.src = idea.finalVideoUrl;
        vid.play().catch(() => { });
        return;
    }
    const playlistAttr = vid.getAttribute('data-playlist') || '';
    const playlist = playlistAttr ? playlistAttr.split(',') : [];
    if (playlist.length > 0 && playlist[0]) {
        vid.setAttribute('data-current', '0');
        vid.src = playlist[0];
        vid.play().catch(() => { });
    }
}

// ✅ 下载合并后的成片（优先 MP4；如果是 blob: 也可下载）
async function downloadMergedVideo(id) {
    try {
        const idea = (typeof ideas !== 'undefined' && Array.isArray(ideas)) ? ideas.find(i => i.id === id) : null;
        const url = idea?.finalVideoUrl;
        if (!url) return alert('没有可下载的成片，请先点击“🔄合成/▶️”生成成片');

        const a = document.createElement('a');
        a.href = url;
        const baseName = (idea?.theme ? String(idea.theme).slice(0, 12) : 'RollRoll_video').replace(/[\\/:*?"<>|]/g, '_');
        a.download = `${baseName}_${Date.now()}.mp4`;
        document.body.appendChild(a);
        a.click();
        a.remove();
    } catch (e) {
        console.error('downloadMergedVideo failed:', e);
        alert('下载失败：' + (e?.message || e));
    }
}
window.downloadMergedVideo = downloadMergedVideo;

