function editScript(id) {
    const idea = ideas.find(i => i.id === id);
    if (!idea) return;

    const contentEl = document.getElementById(`script-content-${id}`);
    if (!contentEl) return;
    if (contentEl.querySelector('textarea')) return;

    const oldText = idea.generatedScript || '';
    const height = Math.max(200, contentEl.offsetHeight);

    contentEl.innerHTML = `
        <textarea class="inline-edit-textarea" style="width:100%; height:${height}px; background:#222; color:#fff; border:1px solid #444; padding:8px; border-radius:4px; resize:vertical; font-size:13px; line-height:1.5; outline:none;">${oldText}</textarea>
        <div class="inline-edit-actions" style="display:flex; gap:5px; margin-top:5px; justify-content:flex-end;">
            <button class="btn-xs" onclick="cancelEditScript(${id})" style="background:#444; color:#ccc; border:none; padding:4px 8px; border-radius:4px; cursor:pointer;">取消</button>
            <button class="btn-xs" onclick="saveEditScript(${id})" style="background:var(--success-color); color:#fff; border:none; padding:4px 8px; border-radius:4px; cursor:pointer;">保存</button>
        </div>
    `;

    const textarea = contentEl.querySelector('textarea');
    if (textarea) {
        textarea.focus();
        textarea.addEventListener('mousedown', e => e.stopPropagation());
        textarea.addEventListener('touchstart', e => e.stopPropagation());
    }
}

