window.saveEditPrompt = function (id, index) {
    const textEl = document.getElementById(`vp-text-${id}-${index}`);
    if (!textEl) return;
    const textarea = textEl.querySelector('textarea');
    if (!textarea) return;

    const newText = textarea.value;
    const idea = ideas.find(i => i.id === id);
    if (idea) {
        if (typeof idea.generatedVideoPrompts[index] === 'string') {
            idea.generatedVideoPrompts[index] = newText;
        } else {
            idea.generatedVideoPrompts[index].prompt = newText;
        }
        // 🔀 编辑提示词后同步重建融合提示词（用于实验对比/生成）
        try {
            const base = Array.isArray(idea.generatedVideoPrompts) ? idea.generatedVideoPrompts : [];
            idea.fusedVideoPrompts = buildFusedVideoPrompts(idea.normalStoryboards || [], base, idea);
        } catch (e) { }
        saveIdeasToHistory();
        renderCanvas();
    }
};

async function retryPrompt(id, idx) {
    const idea = ideas.find(i => i.id === id);
    if (!idea) return;

    updateCinematicOverlaySteps('💡 正在优化视频提示词...', 'processing', id);

    // 直接重新生成
    idea.generatedVideoPrompts = null;
    idea.videoResults = [];

    // 🔧 只生成提示词，不触发完整流程
    if (idea.normalStoryboards && idea.normalStoryboards.length > 0) {
        // 🔧 修复：需要调用AI API来生成提示词，而不是直接使用请求字符串
        const charContext = buildCharacterContext(idea.characterSheets, idea.characterDescriptions || []);
        const vpReq = generateSora2PromptRequest(idea, idea.normalStoryboards, charContext);
        const vpText = await callZhenzhenTextAPI(vpReq);
        const videoPrompts = parsePrompts(vpText, idea.scenes);

        if (videoPrompts.length === 0) {
            // 重试一次
            const vpText2 = await callZhenzhenTextAPI(vpReq + '\n\n⚠️ 请务必使用@标记格式，每个分镜必须包含 @角色 @场景 @动作 @镜头 等标记！');
            const videoPrompts2 = parsePrompts(vpText2, idea.scenes);
            if (videoPrompts2.length === 0) {
                throw new Error('Sora2提示词生成失败：AI未返回正确的@标记格式');
            }
            idea.generatedVideoPrompts = videoPrompts2;
        } else {
            idea.generatedVideoPrompts = videoPrompts;
        }

        // 🔀 提示词刷新后同步生成融合提示词
        try {
            const base = Array.isArray(idea.generatedVideoPrompts) ? idea.generatedVideoPrompts : [];
            idea.fusedVideoPrompts = buildFusedVideoPrompts(idea.normalStoryboards || [], base, idea);
        } catch (e) { }

        updateCinematicOverlaySteps(`✅ 提示词优化完成: ${idea.generatedVideoPrompts.length}个`, 'completed', id);
        saveIdeasToHistory();
        renderCanvas();
    } else {
        throw new Error('没有分镜文本，无法生成提示词');
    }
}

async function retryVideo(id, idx) {
    const idea = ideas.find(i => i.id === id);
    if (!idea) return;

    updateCinematicOverlaySteps(`🎥 正在生成视频片段 ${idx + 1}...`, 'processing', id);

    // 移除对应的视频结果
    idea.videoResults = idea.videoResults.filter(r => r.index !== idx);
    renderCanvas();

    // 🔧 只生成单个视频（复用自动重试）
    const promptsForGen = getEffectiveVideoPromptsForGeneration(idea);
    if (!(promptsForGen && promptsForGen[idx])) {
        throw new Error('没有提示词，无法生成视频');
    }

    const prompt = promptsForGen[idx];
    const result = await generateOneClipWithRetry(idea, idx, prompt, (promptsForGen || []).length, { maxAttempts: 3 });

    if (result?.cancelled) return;
    if (result?.ok) {
        if (!idea.videoResults) idea.videoResults = [];
        idea.videoResults.push({ index: idx, url: result.url, attempts: result.attempts });
        updateCinematicOverlaySteps(`✅ 视频片段 ${idx + 1} 生成完成`, 'completed', id);
        saveIdeasToHistory();
        renderCanvas();
        return;
    }

    const { errorDetail, refundReason } = result || {};
    try { __applyFixedVideoTimingToIdea(idea); } catch (e) { }
    const s = idea?.settings || {};
    const _vm = s.videoModel || idea.videoModel || 'sora-2';
    const _vh = __getVideoHdFlag(s);
    const clipDur = s.clipDuration || idea.clipDuration || idea.duration || __getFixedClipDurationByModel(__normalizeVideoModelName(_vm), _vh);
    const filmCost = __estimateSoraVideoFilmCost(_vm, clipDur, _vh);
    const stats = getUsageStats();
    if (stats.limit !== Infinity && stats.count > 0) {
        refundQuota(1);
    } else {
        // 付费用户：成功才扣费，失败不应退费（避免胶片凭空增加）
    }

    updateCinematicOverlaySteps(`❌ 视频片段 ${idx + 1} 失败: ${errorDetail || '生成失败'}`, 'failed', id);
    alert(`视频生成失败: ${errorDetail || '生成失败'}\n\n可直接重试；若是超时/网络问题，稍后再试更稳。`);
    throw new Error(errorDetail || '生成失败');
}

/**
 * 一键重试：仅重试失败/缺失的视频片段
 * @param {number} id
 */
window.retryFailedClips = async function (id) {
    const idea = ideas.find(i => i.id === id);
    if (!idea) return;

    const prompts = getEffectiveVideoPromptsForGeneration(idea) || [];
    if (!prompts.length) {
        alert('没有提示词，无法重试视频片段');
        return;
    }

    // 找到失败或缺失的分镜
    const failedIdx = [];
    const results = idea.videoResults || [];
    for (let i = 0; i < prompts.length; i++) {
        const r = results.find(x => x.index === i);
        if (!r || (!r.url && r.error)) failedIdx.push(i);
        if (!r) failedIdx.push(i);
        if (r && !r.url && !r.error) failedIdx.push(i);
    }
    const uniqueIdx = [...new Set(failedIdx)].sort((a, b) => a - b);
    if (uniqueIdx.length === 0) {
        alert('没有失败片段，无需重试');
        return;
    }

    updateCinematicOverlaySteps(`🔄 正在重试失败片段（${uniqueIdx.length}个）...`, 'processing', id);

    // 顺序重试（避免并发引发429）
    for (const idx of uniqueIdx) {
        if (checkCancel(idea)) break;
        try {
            await retryVideo(id, idx);
        } catch (e) {
            // 单段失败不阻断批量重试
        }
    }

    updateCinematicOverlaySteps(`✅ 重试完成`, 'completed', id);
    saveIdeasToHistory();
    renderCanvas();
};

/**
 * 一键重试合成
 * @param {number} id
 */
window.retryMergeVideo = async function (id) {
    const idea = ideas.find(i => i.id === id);
    if (!idea) return;
    try {
        updateCinematicOverlaySteps('🎞️ 正在重试合成...', 'processing', id);
        await mergeVideos(idea);
        updateCinematicOverlaySteps('✅ 合成完成', 'completed', id);
    } catch (e) {
        updateCinematicOverlaySteps(`❌ 合成失败: ${e.message}`, 'failed', id);
        alert('合成失败: ' + e.message);
    } finally {
        saveIdeasToHistory();
        renderCanvas();
    }
};

function __getVipLevel() {
    // 1. 优先从 window.currentMembershipLevel 获取
    try {
        const lv = Number(window.currentMembershipLevel);
        if (Number.isFinite(lv) && lv > 0) return Math.max(0, Math.min(10, Math.floor(lv)));
    } catch (e) { }
    // 2. 根据 membership_type 推导（pro/studio=10, vip=6, creator=4）
    try {
        const mt = String(localStorage.getItem('membership_type') || 'free').trim().toLowerCase();
        const map = { free: 0, creator: 4, vip: 6, pro: 10, studio: 10 };
        if (map[mt] !== undefined && map[mt] > 0) return map[mt];
    } catch (e) { }
    // 3. 从 localStorage membership_level 获取
    try {
        const lv = Number(localStorage.getItem('membership_level'));
        if (Number.isFinite(lv) && lv > 0) return Math.max(0, Math.min(10, Math.floor(lv)));
    } catch (e) { }
    // 4. 从 nv_user_profile 中获取
    try {
        const profile = JSON.parse(localStorage.getItem('nv_user_profile') || 'null');
        if (profile && profile.membership_level) {
            const lv = Number(profile.membership_level);
            if (Number.isFinite(lv) && lv > 0) return Math.max(0, Math.min(10, Math.floor(lv)));
        }
    } catch (e) { }
    return 0;
}

function __countHdInflight() {
    try {
        const list = Array.isArray(ideas) ? ideas : [];
        return list.filter(i => i && i.hdUpscale && (i.hdUpscale.status === 'uploading' || i.hdUpscale.status === 'processing')).length;
    } catch (e) {
        return 0;
    }
}

function __setHdStatusText(ideaId, text, color) {
    try {
        const el = document.getElementById(`hd-status-${ideaId}`);
        if (!el) return;
        el.textContent = String(text || '');
        if (color) el.style.color = color;
    } catch (e) { }
}

async function __getCurrentUserIdForHd() {
    if (typeof NVAuth === 'undefined') return '';
    try {
        const u = await NVAuth.getCurrentUser();
        return String(u?.id || u?.user?.id || '').trim();
    } catch (e) {
        return '';
    }
}

async function __callHdApi(payload) {
    const p = payload || {};
    const act = String(p.action || '').trim();
    const mappedAction = act === 'start' ? 'runninghubHdStart' : act === 'poll' ? 'runninghubHdPoll' : act === 'cancel' ? 'runninghubHdCancel' : act;
    const nextPayload = { ...p, action: mappedAction };

    const r = await fetch('/api/supabase-proxy', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(nextPayload)
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) {
        const msg = j?.message || j?.error || `HTTP_${r.status}`;
        const err = new Error(String(msg));
        err.status = r.status;
        err.data = j;
        throw err;
    }
    return j;
}

async function __pollHdForIdea(idea) {
    if (!idea || !idea.hdUpscale || !idea.hdUpscale.taskId) return;
    const ideaId = idea.id;
    const userId = await __getCurrentUserIdForHd();
    if (!userId) {
        idea.hdUpscale.status = 'failed';
        idea.hdUpscale.error = '未登录';
        __setHdStatusText(ideaId, '❌ 未登录', '#ef4444');
        saveIdeasToHistory();
        renderCanvas();
        return;
    }

    const taskId = String(idea.hdUpscale.taskId || '').trim();
    if (!taskId) return;

    const maxAttempts = 120;
    let attempts = 0;
    const intervalMs = 3000;

    if (!window.__hdPollTimers) window.__hdPollTimers = {};
    if (window.__hdPollTimers[String(ideaId)]) return;

    window.__hdPollTimers[String(ideaId)] = setInterval(async () => {
        attempts++;
        try {
            const data = await __callHdApi({ action: 'poll', userId, taskId });
            const st = String(data?.status || '').toUpperCase();

            if (st === 'SUCCESS' || st === 'COMPLETED') {
                const url = String(data?.videoUrl || '').trim();
                idea.hdUpscale.status = 'completed';
                idea.hdUpscale.videoUrl = url;
                idea.hdUpscale.updatedAt = new Date().toISOString();

                if (url) {
                    idea.finalVideoUrl = url;
                    idea.mergedSuccessfully = true;
                    idea.playlistMode = false;
                }

                __setHdStatusText(ideaId, url ? '✅ 高清完成（已替换成片）' : '✅ 高清完成（但未获取到视频地址）', url ? '#10b981' : '#fbbf24');
                clearInterval(window.__hdPollTimers[String(ideaId)]);
                delete window.__hdPollTimers[String(ideaId)];
                saveIdeasToHistory();
                renderCanvas();
                return;
            }

            if (st === 'FAILED' || st === 'FAILURE' || st === 'ERROR') {
                idea.hdUpscale.status = 'failed';
                idea.hdUpscale.error = '高清任务失败';
                idea.hdUpscale.updatedAt = new Date().toISOString();
                __setHdStatusText(ideaId, '❌ 高清失败（可重试）', '#ef4444');
                clearInterval(window.__hdPollTimers[String(ideaId)]);
                delete window.__hdPollTimers[String(ideaId)];
                saveIdeasToHistory();
                renderCanvas();
                return;
            }

            idea.hdUpscale.status = 'processing';
            idea.hdUpscale.updatedAt = new Date().toISOString();
            __setHdStatusText(ideaId, `⏳ 高清处理中... (${attempts}/${maxAttempts})`, '#9ca3af');
            if (attempts % 10 === 0) {
                saveIdeasToHistory();
                renderCanvas();
            }
        } catch (e) {
            if (attempts >= maxAttempts) {
                idea.hdUpscale.status = 'failed';
                idea.hdUpscale.error = String(e?.message || e);
                idea.hdUpscale.updatedAt = new Date().toISOString();
                __setHdStatusText(ideaId, '❌ 高清超时（可稍后重试）', '#ef4444');
                clearInterval(window.__hdPollTimers[String(ideaId)]);
                delete window.__hdPollTimers[String(ideaId)];
                saveIdeasToHistory();
                renderCanvas();
            }
        }

        if (attempts >= maxAttempts) {
            clearInterval(window.__hdPollTimers[String(ideaId)]);
            delete window.__hdPollTimers[String(ideaId)];
        }
    }, intervalMs);
}

window.startHDVideo = async function (ideaId) {
    const idea = (Array.isArray(ideas) ? ideas : []).find(i => i && i.id === ideaId);
    if (!idea) return;

    const vipLv = __getVipLevel();
    if (vipLv < 10) {
        __setHdStatusText(ideaId, '🔒 VIP10 专属功能', '#fbbf24');
        alert('🔒 高清功能仅对 VIP10 用户开放');
        return;
    }

    const userId = await __getCurrentUserIdForHd();
    if (!userId) {
        __setHdStatusText(ideaId, '❌ 未登录', '#ef4444');
        alert('🔒 请先登录后再使用高清功能');
        if (typeof window.showAuthModal === 'function') window.showAuthModal();
        return;
    }

    if (!idea.hdUpscale) idea.hdUpscale = { status: 'idle' };

    if (idea.hdUpscale.status === 'uploading' || idea.hdUpscale.status === 'processing') {
        __setHdStatusText(ideaId, '⏳ 高清任务进行中...', '#9ca3af');
        await __pollHdForIdea(idea);
        return;
    }

    const inflight = __countHdInflight();
    if (inflight >= 5) {
        __setHdStatusText(ideaId, '⚠️ 同时最多 5 个高清任务', '#fbbf24');
        alert('⚠️ 同时最多进行 5 个高清任务，请等待部分任务完成后再试');
        return;
    }

    const srcUrl = String(idea.finalVideoUrl || idea.mergedVideoUrl || (idea.videoResults && idea.videoResults.find(r => r && r.url)?.url) || '').trim();
    if (!srcUrl) {
        __setHdStatusText(ideaId, '⚠️ 暂无可高清的视频', '#fbbf24');
        alert('当前任务还没有可用的视频链接');
        return;
    }

    idea.hdUpscale.status = 'uploading';
    idea.hdUpscale.sourceUrl = srcUrl;
    idea.hdUpscale.error = '';
    idea.hdUpscale.updatedAt = new Date().toISOString();
    __setHdStatusText(ideaId, '⏫ 正在上传并启动高清任务...', '#9ca3af');
    saveIdeasToHistory();
    renderCanvas();

    try {
        const data = await __callHdApi({ action: 'start', userId, videoUrl: srcUrl });
        const taskId = String(data?.taskId || '').trim();
        idea.hdUpscale.status = 'processing';
        idea.hdUpscale.taskId = taskId;
        idea.hdUpscale.updatedAt = new Date().toISOString();
        __setHdStatusText(ideaId, '⏳ 高清处理中...', '#9ca3af');
        saveIdeasToHistory();
        renderCanvas();
        await __pollHdForIdea(idea);
    } catch (e) {
        const msg = String(e?.data?.message || e?.data?.error || e?.message || e);
        idea.hdUpscale.status = 'failed';
        idea.hdUpscale.error = msg;
        idea.hdUpscale.updatedAt = new Date().toISOString();
        __setHdStatusText(ideaId, `❌ 启动失败：${msg}`, '#ef4444');
        saveIdeasToHistory();
        renderCanvas();
        alert('高清启动失败：' + msg);
    }
};

/**
 * 🎬 节点视频高清化（通过 RunningHub 二次处理）
 */
window.vnodeUpscaleVideo = async function (nodeId, resultIdx, videoUrl) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;

    const vipLv = (typeof __getVipLevel === 'function') ? __getVipLevel() : 0;
    if (vipLv < 10) {
        alert('🔒 高清功能仅对 VIP10 用户开放');
        return;
    }

    const userId = await __getCurrentUserIdForHd();
    if (!userId) {
        alert('🔒 请先登录后再使用高清功能');
        if (typeof window.showAuthModal === 'function') window.showAuthModal();
        return;
    }

    const inflight = (typeof __countHdInflight === 'function') ? __countHdInflight() : 0;
    if (inflight >= 5) {
        alert('⚠️ 同时最多进行 5 个高清任务，请等待部分任务完成后再试');
        return;
    }

    if (!videoUrl) {
        alert('⚠️ 暂无可高清的视频');
        return;
    }

    // 更新结果状态
    if (!node.data.results) node.data.results = [];
    if (node.data.results[resultIdx]) {
        node.data.results[resultIdx].hdStatus = 'processing';
    }
    saveIdeasToHistory();
    renderCanvas();

    try {
        const data = await __callHdApi({ action: 'start', userId, videoUrl });
        const taskId = String(data?.taskId || '').trim();

        // 轮询高清任务状态
        await __pollVnodeHdTask(nodeId, resultIdx, taskId, videoUrl);
    } catch (e) {
        const msg = String(e?.data?.message || e?.data?.error || e?.message || e);
        if (node.data.results[resultIdx]) {
            node.data.results[resultIdx].hdStatus = 'failed';
        }
        saveIdeasToHistory();
        renderCanvas();
        alert('高清启动失败：' + msg);
    }
};

/**
 * 🔄 轮询节点视频高清任务状态
 */
async function __pollVnodeHdTask(nodeId, resultIdx, taskId, originalUrl) {
    const maxAttempts = 120; // 最多轮询10分钟
    const intervalMs = 5000;

    for (let i = 0; i < maxAttempts; i++) {
        await new Promise(r => setTimeout(r, intervalMs));

        const node = flowNodes.find(n => n.id === nodeId);
        if (!node) return;

        const userId = await __getCurrentUserIdForHd();
        if (!userId) return;

        try {
            const data = await __callHdApi({ action: 'poll', userId, taskId });
            const status = String(data?.status || '').toLowerCase();

            if (status === 'completed' || status === 'success') {
                const hdUrl = String(data?.outputUrl || data?.resultUrl || '').trim();
                if (node.data.results[resultIdx]) {
                    node.data.results[resultIdx].hdStatus = 'done';
                    if (hdUrl) {
                        node.data.results[resultIdx].url = hdUrl;
                        node.data.results[resultIdx].hdUrl = hdUrl;
                    }
                }
                saveIdeasToHistory();
                renderCanvas();
                return;
            } else if (status === 'failed' || status === 'error') {
                if (node.data.results[resultIdx]) {
                    node.data.results[resultIdx].hdStatus = 'failed';
                }
                saveIdeasToHistory();
                renderCanvas();
                return;
            }
            // 继续轮询
        } catch (e) {
            console.warn('[vnodeHD] poll error:', e);
        }
    }

    // 超时
    const node = flowNodes.find(n => n.id === nodeId);
    if (node && node.data.results[resultIdx]) {
        node.data.results[resultIdx].hdStatus = 'failed';
        saveIdeasToHistory();
        renderCanvas();
    }
}

function downloadResult(url, filename) {
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
}

async function downloadAll(id) {
    const idea = ideas.find(i => i.id === id);
    if (!idea) return;

    if (typeof JSZip === 'undefined') {
        alert('JSZip 库未加载，无法打包下载。请检查网络或刷新页面。');
        return;
    }

    const zip = new JSZip();
    const folder = zip.folder(`RollRoll_${idea.id}`);

    // Script
    if (idea.generatedScript) folder.file("script.txt", idea.generatedScript);

    // Characters (Links and JSON)
    if (idea.characterSheets && idea.characterSheets.length > 0) {
        const charText = idea.characterSheets.map(c => `Name: ${c.name}
Desc: ${c.summary}
URL: ${c.imageUrl}`).join('\n\n');
        folder.file("characters.txt", charText);
    }

    // Video Links
    const validVideos = idea.videoResults.filter(r => r.url);
    if (validVideos.length > 0) {
        const videoLinks = validVideos.map(r => `Scene ${r.index + 1}: ${r.url}`).join('\n');
        folder.file("video_links.txt", videoLinks);
    }

    // Prompts
    if (idea.generatedVideoPrompts) {
        const promptsStr = idea.generatedVideoPrompts.map((p, i) => `Scene ${i + 1}: ${typeof p === 'string' ? p : p.prompt}`).join('\n\n');
        folder.file("prompts.txt", promptsStr);
    }

    try {
        const blob = await zip.generateAsync({ type: "blob" });
        const url = URL.createObjectURL(blob);
        downloadResult(url, `Task_${idea.theme.substring(0, 10)}.zip`);
    } catch (e) {
        console.error(e);
        alert('打包失败: ' + e.message);
    }
}

