/**
 * 🖼️ 显示角色图片右键菜单
 */
function showCharImageMenu(event, imageUrl, charName) {
    event.preventDefault();
    event.stopPropagation();

    // 移除旧菜单
    const oldMenu = document.querySelector('.context-menu');
    if (oldMenu) oldMenu.remove();

    const menu = document.createElement('div');
    menu.className = 'context-menu';
    menu.innerHTML = `
        <div class="menu-item" onclick="downloadImage('${imageUrl}', '${charName}')">💾 保存图片</div>
        <div class="menu-item" onclick="window.open('${imageUrl}')">🔍 查看原图</div>
        <div class="menu-item" onclick="copyToClipboard('${imageUrl}')">📋 复制链接</div>
    `;

    menu.style.left = event.clientX + 'px';
    menu.style.top = event.clientY + 'px';
    document.body.appendChild(menu);

    // 点击其他地方关闭菜单
    setTimeout(() => {
        document.addEventListener('click', () => menu.remove(), { once: true });
    }, 100);
}

/**
 * 💾 下载图片
 */
async function downloadImage(url, filename) {
    try {
        // 🔒 非 VIP 用户下载时烧录水印
        let downloadUrl = url;
        if (typeof Watermark !== 'undefined' && Watermark.shouldApply()) {
            try {
                downloadUrl = await Watermark.burnWatermark(url);
            } catch (e) {
                console.warn('[Watermark] 下载水印失败:', e.message);
            }
        }
        const response = await fetch(downloadUrl);
        const blob = await response.blob();
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `${filename || 'character'}_${Date.now()}.png`;
        link.click();
        URL.revokeObjectURL(link.href);
    } catch (e) {
        // 如果跨域失败，直接打开新标签让用户手动保存
        window.open(url, '_blank');
        alert('💡 请在新标签页中右键保存图片');
    }
}

/**
 * 📋 复制到剪贴板
 */
function copyToClipboard(text) {
    navigator.clipboard.writeText(text).then(() => {
        alert('✅ 已复制到剪贴板');
    }).catch(() => {
        prompt('复制链接:', text);
    });
}

window.copyTextToClipboard = async function (text) {
    const s = String(text ?? '');
    try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
            await navigator.clipboard.writeText(s);
            alert('✅ 已复制');
            return true;
        }
    } catch (e) { }
    try {
        const ta = document.createElement('textarea');
        ta.value = s;
        ta.style.position = 'fixed';
        ta.style.left = '-9999px';
        ta.style.top = '-9999px';
        document.body.appendChild(ta);
        ta.focus();
        ta.select();
        const ok = document.execCommand('copy');
        ta.remove();
        if (ok) alert('✅ 已复制');
        return ok;
    } catch (e) {
        alert('❌ 复制失败');
        return false;
    }
};

window.showCharImageMenu = showCharImageMenu;
window.downloadImage = downloadImage;
window.copyToClipboard = copyToClipboard;

// 🆕 步骤控制函数
window.startStep = async function (id, step, index) {
    const idea = ideas.find(i => i.id === id);
    if (!idea) {
        alert('❌ 找不到任务');
        return;
    }

    console.log(`▶️ 开始步骤: Task ${id}, Step ${step}, Index ${index}`);

    // 🔧 显示加载状态（传入 id 以便正确显示）
    const stepName = getStepName(step);
    showCinematicOverlay(id);
    updateCreativeScreenText(`⏳ 正在执行: ${stepName}...`);
    updateCinematicOverlaySteps(`⏳ ${stepName}...`, 'processing', id);

    try {
        // 根据不同步骤执行不同逻辑
        if (step === 'script') {
            await retryStepScript(id);
        } else if (step === 'roles') {
            await retryStepRoles(id);
        } else if (step === 'storyboard_text') {
            await retryStoryboardText(id);
        } else if (step === 'prompts') {
            await retryPrompt(id, index);
        } else if (step === 'video_clip') {
            await retryVideo(id, index);
        } else if (step === 'video_clips_all') {
            await retryStepScenes(id);
        } else if (step === 'final_video') {
            await mergeVideos(idea);
        } else {
            console.warn('未知的步骤:', step);
            alert('❌ 未知的步骤类型');
        }

        updateCreativeScreenText(`✅ ${stepName} 完成`);
        updateCinematicOverlaySteps(`✅ ${stepName} 完成`, 'completed', id);
        setTimeout(() => hideCinematicOverlay(), 1500);
    } catch (error) {
        console.error(`❌ ${stepName} 失败:`, error);
        updateCreativeScreenText(`❌ ${stepName} 失败: ${error.message}`);
        updateCinematicOverlaySteps(`❌ ${stepName} 失败`, 'error', id);
        setTimeout(() => hideCinematicOverlay(), 3000);
    }
};

// 🔴 全局任务控制器 - 用于暂停/取消正在进行的任务
window.taskControllers = window.taskControllers || {};

window.pauseStep = function (id, step, index) {
    console.log(`⏸️ 暂停步骤: Task ${id}, Step ${step}`);
    const idea = ideas.find(i => i.id === id);
    if (!idea) return;

    // 检查当前是否有正在进行的任务
    if (idea.status !== 'processing' && idea.status !== 'generating') {
        alert('⚠️ 当前没有正在进行的任务可暂停');
        return;
    }

    // 标记暂停状态
    idea.status = 'paused';
    idea.pausedStep = step;
    idea.pausedIndex = index;

    // 中止正在进行的请求
    const controllerKey = `${id}_${step}_${index || 0}`;
    if (window.taskControllers[controllerKey]) {
        window.taskControllers[controllerKey].abort();
        delete window.taskControllers[controllerKey];
    }

    saveIdeasToHistory();
    renderCanvas();
    renderIdeasList();

    alert(`⏸️ 任务已暂停

步骤: ${getStepName(step)}

点击 ▶️ 可恢复继续`);
};

window.cancelStep = function (id, step, index) {
    console.log(`⏹️ 取消步骤: Task ${id}, Step ${step}`);
    const idea = ideas.find(i => i.id === id);
    if (!idea) return;

    const stepName = getStepName(step);

    if (!confirm(`确定取消 "${stepName}" 吗？\n\n已生成的内容将被清除。`)) return;

    // 中止正在进行的请求
    const controllerKey = `${id}_${step}_${index || 0}`;
    if (window.taskControllers[controllerKey]) {
        window.taskControllers[controllerKey].abort();
        delete window.taskControllers[controllerKey];
    }

    // 根据步骤清除对应内容
    if (step === 'script') {
        idea.generatedScript = null;
        idea.status = 'new';
    } else if (step === 'roles') {
        idea.characterSheets = [];
        idea.status = 'waiting_roles';
    } else if (step === 'storyboard_text') {
        idea.normalStoryboards = [];
        idea.status = 'waiting_storyboard';
    } else if (step === 'prompts') {
        idea.videoPrompts = [];
        idea.status = 'waiting_prompts';
    } else if (step === 'video_clip' && typeof index === 'number') {
        if (idea.generatedVideos && idea.generatedVideos[index]) {
            idea.generatedVideos[index] = null;
        }
    } else if (step === 'video_clips_all') {
        idea.generatedVideos = [];
        idea.status = 'waiting_video';
    } else if (step === 'final_video') {
        idea.finalVideo = null;
        idea.status = 'waiting_merge';
    }

    saveIdeasToHistory();
    renderCanvas();
    renderIdeasList();

    alert(`⏹️ "${stepName}" 已取消`);
};

/**
 * 获取步骤名称
 * @param {string} step - 步骤标识
 * @returns {string} 步骤名称
 */
function getStepName(step) {
    const names = {
        'script': '剧本生成',
        'roles': '角色设计',
        'storyboard_text': '分镜文本',
        'prompts': '视频提示词',
        'video_clip': '视频片段',
        'video_clips_all': '全部视频片段',
        'final_video': '成片合成'
    };
    return names[step] || step;
}

window.editStoryboard = function (id, index) {
    const idea = ideas.find(i => i.id === id);
    if (!idea || !idea.normalStoryboards) return;

    const textEl = document.getElementById(`sb-text-${id}-${index}`);
    if (!textEl) return;

    // Prevent multiple edits
    if (textEl.querySelector('textarea')) return;

    const currentText = idea.normalStoryboards[index] || '';
    const height = Math.max(100, textEl.offsetHeight);

    textEl.innerHTML = `
        <textarea class="inline-edit-textarea" style="width:100%; height:${height}px; background:#222; color:#fff; border:1px solid #444; padding:8px; border-radius:4px; resize:vertical; font-size:13px; line-height:1.5; outline:none;">${currentText}</textarea>
        <div class="inline-edit-actions" style="display:flex; gap:5px; margin-top:5px; justify-content:flex-end;">
            <button class="btn-xs" onclick="cancelEditStoryboard()" style="background:#444; color:#ccc; border:none; padding:4px 8px; border-radius:4px; cursor:pointer;">取消</button>
            <button class="btn-xs" onclick="saveEditStoryboard(${id}, ${index})" style="background:var(--success-color); color:#fff; border:none; padding:4px 8px; border-radius:4px; cursor:pointer;">保存</button>
        </div>
    `;

    const textarea = textEl.querySelector('textarea');
    if (textarea) {
        textarea.focus();
        // Prevent canvas drag when interacting with textarea
        textarea.addEventListener('mousedown', e => e.stopPropagation());
        textarea.addEventListener('touchstart', e => e.stopPropagation());
    }
};

window.saveEditStoryboard = function (id, index) {
    const textEl = document.getElementById(`sb-text-${id}-${index}`);
    if (!textEl) return;
    const textarea = textEl.querySelector('textarea');
    if (!textarea) return;

    const newText = textarea.value;
    const idea = ideas.find(i => i.id === id);
    if (idea) {
        idea.normalStoryboards[index] = newText;
        // 🔀 编辑分镜后同步重建融合提示词（非破坏性）
        try {
            const base = Array.isArray(idea.generatedVideoPrompts) ? idea.generatedVideoPrompts : [];
            idea.fusedVideoPrompts = buildFusedVideoPrompts(idea.normalStoryboards || [], base, idea);
        } catch (e) { }
        saveIdeasToHistory();
        renderCanvas();
    }
};

window.cancelEditStoryboard = function () {
    renderCanvas();
};

window.retryStoryboardText = async function (id) {
    const idea = ideas.find(i => i.id === id);
    if (!idea) {
        console.error('❌ 找不到任务:', id);
        return;
    }

    // 不再弹确认框，因为 startStep 已经显示了加载动画
    updateCinematicOverlaySteps('📝 正在生成分镜文本...', 'processing', id);

    // 检查是否有剧本
    if (!idea.generatedScript) {
        alert('⚠️ 请先生成剧本');
        return;
    }

    idea.status = 'processing';
    renderCanvas();
    renderIdeasList();

    try {
        console.log('🎬 开始重新生成分镜文本...');

        // 重新调用分镜生成逻辑
        const charContext = (idea.characterSheets || []).map(c => `${c.name}: ${c.summary}`).join('\n') || '无角色信息';
        const storyboardReq = generateNormalStoryboardRequest(idea, idea.generatedScript, charContext);
        const storyboardRes = await callZhenzhenTextAPI(storyboardReq);

        // 解析分镜
        idea.normalStoryboards = parseStoryboards(storyboardRes, idea.scenes || 4);

        console.log('✅ 分镜生成完成:', idea.normalStoryboards);
        updateCinematicOverlaySteps(`✅ 分镜生成完成: ${idea.normalStoryboards.length}个`, 'completed', id);
        saveIdeasToHistory();
    } catch (e) {
        console.error('❌ 分镜生成失败:', e);
        updateCinematicOverlaySteps(`❌ 分镜生成失败: ${e.message}`, 'failed', id);
        throw e;
    } finally {
        idea.status = 'waiting_storyboard_confirm';
        renderCanvas();
        renderIdeasList();
    }
};

