// 画布缩放控制（使用 transform: translate() + scale()）
window.zoomIn = function () {
    const canvas = document.getElementById('taskCanvas');
    if (!canvas) return;

    // ✅ 统一走 setCanvasTransform，保持内部状态与“视角持久化”一致
    const t = (typeof window.getCanvasTransform === 'function') ? window.getCanvasTransform() : null;
    const currentScale = t?.scale ?? window.getCurrentScale?.() ?? 1;
    const translate = t ? { x: t.translateX, y: t.translateY } : (window.getCanvasTranslate?.() ?? { x: 0, y: 0 });
    const newScale = Math.min(currentScale + 0.1, 5);
    if (typeof window.setCanvasTransform === 'function') {
        window.setCanvasTransform({ scale: newScale, translateX: translate.x, translateY: translate.y }, { animate: true });
    } else {
        canvas.style.transform = `translate(${translate.x}px, ${translate.y}px) scale(${newScale})`;
        canvas.style.transformOrigin = '0 0';
        const zoomDisplay = document.querySelector('.zoom-level');
        if (zoomDisplay) zoomDisplay.textContent = Math.round(newScale * 100) + '%';
        if (typeof renderConnections === 'function') renderConnections();
    }
};

window.zoomOut = function () {
    const canvas = document.getElementById('taskCanvas');
    if (!canvas) return;

    // ✅ 统一走 setCanvasTransform，保持内部状态与“视角持久化”一致
    const t = (typeof window.getCanvasTransform === 'function') ? window.getCanvasTransform() : null;
    const currentScale = t?.scale ?? window.getCurrentScale?.() ?? 1;
    const translate = t ? { x: t.translateX, y: t.translateY } : (window.getCanvasTranslate?.() ?? { x: 0, y: 0 });
    const newScale = Math.max(currentScale - 0.1, 0.1);
    if (typeof window.setCanvasTransform === 'function') {
        window.setCanvasTransform({ scale: newScale, translateX: translate.x, translateY: translate.y }, { animate: true });
    } else {
        canvas.style.transform = `translate(${translate.x}px, ${translate.y}px) scale(${newScale})`;
        canvas.style.transformOrigin = '0 0';
        const zoomDisplay = document.querySelector('.zoom-level');
        if (zoomDisplay) zoomDisplay.textContent = Math.round(newScale * 100) + '%';
        if (typeof renderConnections === 'function') renderConnections();
    }
};

window.resetZoom = function () {
    const canvas = document.getElementById('taskCanvas');
    if (!canvas) return;

    const t = (typeof window.getCanvasTransform === 'function') ? window.getCanvasTransform() : null;
    const translate = t ? { x: t.translateX, y: t.translateY } : (window.getCanvasTranslate?.() ?? { x: 0, y: 0 });
    if (typeof window.setCanvasTransform === 'function') {
        window.setCanvasTransform({ scale: 1, translateX: translate.x, translateY: translate.y }, { animate: true });
    } else {
        canvas.style.transform = `translate(${translate.x}px, ${translate.y}px) scale(1)`;
        canvas.style.transformOrigin = '0 0';
        const zoomDisplay = document.querySelector('.zoom-level');
        if (zoomDisplay) zoomDisplay.textContent = '100%';
        if (typeof renderConnections === 'function') renderConnections();
    }
};

