/**
 * 🎖️ 根据累计充值金额更新会员等级（方案B）
 * @param {number} newRechargeAmount - 本次充值金额
 */
function updateMemberLevel(newRechargeAmount) {
    // 获取累计充值金额
    let totalRecharge = parseFloat(localStorage.getItem('total_recharge') || '0');
    totalRecharge += newRechargeAmount;
    localStorage.setItem('total_recharge', totalRecharge.toString());

    // 根据累计金额确定会员等级（方案B阈值）
    let newLevel = 'free';
    if (totalRecharge >= 299) {
        newLevel = 'studio';   // 工作室：85折
    } else if (totalRecharge >= 129) {
        newLevel = 'pro';      // 专业版：9折
    } else if (totalRecharge >= 59) {
        newLevel = 'creator';  // 创作者：95折
    }

    // 更新会员信息
    if (newLevel !== 'free') {
        const vipInfo = {
            type: newLevel,
            totalRecharge: totalRecharge,
            activatedAt: new Date().toISOString()
        };
        localStorage.setItem('vip_info', JSON.stringify(vipInfo));
        localStorage.setItem('is_vip', 'true');
        localStorage.setItem('vip_type', newLevel);
        window.currentUserLevel = newLevel;

        const levelNames = { studio: '🏆 工作室', pro: '⭐ 专业版', creator: '🎬 创作者' };
        const discounts = { studio: '85折', pro: '9折', creator: '95折' };
        console.log(`🎖️ 会员等级更新: ${levelNames[newLevel]} (${discounts[newLevel]})`);
    }

    return newLevel;
}

/**
 * 🎞️ 添加胶片到用户账户（充值成功后调用）
 * @param {number} filmAmount - 胶片数量
 * @param {number} rechargeAmount - 充值金额（用于计算会员等级）
 */
async function addFilmToAccount(filmAmount, rechargeAmount) {
    let finalFilmAmount = filmAmount;
    try {
        if (Number(rechargeAmount) > 0) {
            const discount = getMemberDiscount();
            if (discount && discount > 0 && discount < 1) {
                finalFilmAmount = Math.round((Number(filmAmount) / discount) * 100) / 100;
            }
        }
    } catch (e) { }

    // 统一使用 getFilmBalance/setFilmBalance
    const currentFilm = getFilmBalance();
    const newFilm = currentFilm + finalFilmAmount;
    await setFilmBalance(newFilm); // 立即同步云端

    // 更新会员等级
    const newLevel = updateMemberLevel(rechargeAmount);

    // 同步到用户profile
    try {
        const profile = JSON.parse(localStorage.getItem('nv_user_profile') || '{}');
        if (profile.id) {
            profile.quota_balance = newFilm;
            localStorage.setItem('nv_user_profile', JSON.stringify(profile));
        }
    } catch (e) { }

    // 更新显示
    updateUsageDisplay();

    const levelInfo = getMemberLevelInfo();
    console.log(`🎞️ 胶片充值成功: +${finalFilmAmount}胶片, 当前余额: ${newFilm}, 会员等级: ${levelInfo.name}`);

    return { newFilm, level: newLevel };
}

