// 1. Update saveCharacterToLibrary to accept videoUrl
window.saveCharacterToLibrary = (n, s, posterUrl, v, turnaroundUrl) => {
    try {
        // 🔧 修复：增加 try-catch 防止数据解析错误
        let lib = [];
        try {
            lib = JSON.parse(localStorage.getItem('character_library') || '[]');
            if (!Array.isArray(lib)) {
                console.warn('⚠️ 角色库数据格式错误，已重置');
                lib = [];
            }
        } catch (error) {
            console.error('❌ 角色库数据解析失败，已清空:', error);
            lib = [];
        }

        // 验证输入参数
        if (!n || typeof n !== 'string') {
            alert('❌ 角色名称无效，无法保存到角色库');
            console.error('Invalid character name:', n);
            return;
        }

        // 检查是否存在相同名字的角色，如果存在则更新
        const existingIdx = lib.findIndex(c => c.name === n);
        if (existingIdx >= 0) {
            if (confirm(`角色 \"${n}\" 已存在，是否更新？\\n(将覆盖原有的设定、图片和视频)`)) {
                lib[existingIdx] = {
                    name: n,
                    summary: s || '',
                    imageUrl: posterUrl || lib[existingIdx].imageUrl || '',
                    videoUrl: v || lib[existingIdx].videoUrl || '',
                    variants: {
                        poster: posterUrl || lib[existingIdx].variants?.poster || lib[existingIdx].imageUrl || '',
                        turnaround: turnaroundUrl || lib[existingIdx].variants?.turnaround || ''
                    }
                };
                alert('✅ 角色已更新！\\n\\n💡 建议：定期点击角色库中的\"保存到本地\"按钮，备份您的角色数据哦~');
            } else {
                return; // 用户取消更新
            }
        } else {
            lib.push({
                name: n,
                summary: s || '',
                imageUrl: posterUrl || '',
                videoUrl: v || '',
                variants: {
                    poster: posterUrl || '',
                    turnaround: turnaroundUrl || ''
                }
            });
            alert('🎉 已保存到角色库！\\n\\n💡 重要提醒：\\n为避免数据丢失，请定期点击角色库中的\"💾 保存到本地\"按钮备份您的角色！');
        }

        localStorage.setItem('character_library', JSON.stringify(lib));
        if (typeof renderLibChars === 'function') renderLibChars();

        // 🔧 自动同步角色到云端
        setTimeout(async () => {
            try {
                if (typeof NVAuth !== 'undefined') {
                    const user = await NVAuth.getCurrentUser();
                    if (user) {
                        await NVAuth.syncCharactersToCloud(lib);
                        console.log('✅ 角色已自动同步到云端');
                    }
                }
            } catch (err) {
                console.warn('自动同步角色失败:', err);
            }
        }, 1000);
    } catch (err) {
        console.error('❌ 保存角色到角色库时发生错误:', err);
        alert(`❌ 保存失败: ${err.message}\\n\\n请查看控制台了解详细信息`);
    }
};


// 显示任务错误日志
window.showTaskError = function (id) {
    const idea = ideas.find(i => i.id === id);
    if (!idea) return;

    // 收集所有错误日志
    const logs = (idea.stepLogs || []).filter(l => l.status === 'error' || l.status === 'failed');
    if (logs.length === 0 && idea.status !== 'failed') {
        // 如果没有显式错误且状态不是失败，显示最近日志
        alert('当前任务状态正常\n\n最新日志：\n' + (idea.stepLogs && idea.stepLogs.length ? idea.stepLogs[idea.stepLogs.length - 1].message : '无日志'));
        return;
    }

    const errorMsg = logs.length > 0 ? logs.map(l => `[${new Date(l.time).toLocaleTimeString()}] ${l.message}`).join('\n') : '未知错误，请检查控制台';
    alert(`❌ 任务执行出错\n\n${errorMsg}`);
};

window.cancelNodeGeneration = function (nodeId) {
    const el = document.getElementById(`node-${nodeId}`);
    if (!el) return;
    const btn = el.querySelector('.btn-generate');
    if (btn) {
        btn.innerText = '⚡ 生成';
        btn.disabled = false;
    }
};

if (typeof window.endConnection === 'undefined') {
    window.endConnection = function (e, targetId) {
        e.stopPropagation();
        e.preventDefault();

        if (!tempConnection) return;

        const sourceId = tempConnection.sourceId || tempConnection.from;
        if (!sourceId || sourceId === targetId) {
            tempConnection = null;
            renderConnections();
            return;
        }

        const exists = connections.some(c => c.source === sourceId && c.target === targetId);
        if (exists) {
            tempConnection = null;
            renderConnections();
            return;
        }

        connections.push({
            id: 'conn_' + Date.now(),
            source: sourceId,
            target: targetId
        });

        // 🔄 连接建立后，立即刷新目标节点的自动提示词
        if (typeof updateNodeAutoPromptDisplay === 'function') {
            try { updateNodeAutoPromptDisplay(targetId); } catch (err) { console.warn('updateNodeAutoPromptDisplay error:', err); }
        }

        tempConnection = null;
        renderConnections();
        saveIdeasToHistory();
    };
}

