/**
 * 🏠 关闭欢迎页
 * 🔧 不再使用 sessionStorage，确保刷新页面时一定显示欢迎页
 */
function closeWelcomeScreen() {
    // 🔧 移除开场动画注入的CSS（解除 .app-container display:none!important）
    var injectedStyle = document.getElementById('cinemaIntroInjectedStyle');
    if (injectedStyle) injectedStyle.remove();
    if (typeof _introStyleTag !== 'undefined' && _introStyleTag && _introStyleTag.parentNode) {
        _introStyleTag.parentNode.removeChild(_introStyleTag);
        _introStyleTag = null;
    }

    const welcomeScreen = document.getElementById('welcomeScreen');
    if (welcomeScreen) {
        welcomeScreen.style.transition = 'opacity 0.5s ease-out';
        welcomeScreen.style.opacity = '0';
        setTimeout(() => {
            welcomeScreen.style.display = 'none';
        }, 500);
    }

    // 确保 .app-container 可见（只移除隐藏，不覆盖原有布局样式）
    var appContainer = document.querySelector('.app-container');
    if (appContainer) {
        appContainer.style.removeProperty('display');
        appContainer.style.opacity = '1';
        appContainer.style.visibility = 'visible';
    }
}

/**
 * 🏠 检查是否应该显示欢迎页
 * 🔧 修复：已登录用户刷新时不显示欢迎页，和手机版保持一致
 * 逻辑：
 * 1. 带 logged_in=1 或 skip_welcome=1 参数 → 跳过欢迎页
 * 2. 已登录用户 → 跳过欢迎页，直接进入工作区
 * 3. 未登录用户 → 显示欢迎页
 */
async function checkWelcomeScreen() {
    const welcomeScreen = document.getElementById('welcomeScreen');
    console.log('🏠 checkWelcomeScreen 开始执行, welcomeScreen:', !!welcomeScreen);

    // 🔧 如果开场动画正在播放，不操作 welcomeScreen（由 finishIntro 接管）
    if (typeof _showIntro !== 'undefined' && _showIntro) {
        console.log('🏠 开场动画正在播放，跳过 checkWelcomeScreen');
        return true;
    }

    // 1. 检查 URL 参数：从登录页跳转回来或从功能页返回时跳过欢迎页
    const urlParams = new URLSearchParams(window.location.search);
    const isLoggedInRedirect = urlParams.has('logged_in') || urlParams.has('skip_welcome');

    if (isLoggedInRedirect) {
        // 清理 URL 参数
        try {
            const cleanUrl = window.location.pathname;
            history.replaceState({}, '', cleanUrl);
        } catch (e) { }

        if (welcomeScreen) welcomeScreen.style.display = 'none';
        console.log('🏠 跳过欢迎页（从登录页/功能页返回）');

        // 🔄 后台同步数据
        try {
            if (typeof NVAuth !== 'undefined' && NVAuth && typeof NVAuth.getCurrentUser === 'function') {
                (async () => {
                    try {
                        console.log('🔄 [登录返回] 开始同步云端数据...');
                        if (typeof syncDataFromCloud === 'function') {
                            await syncDataFromCloud();
                        } else if (typeof refreshFilmBalanceFromCloud === 'function') {
                            await refreshFilmBalanceFromCloud(true);
                        }
                        console.log('✅ [登录返回] 数据同步完成');
                    } catch (e) {
                        console.warn('⚠️ [登录返回] 同步失败:', e?.message);
                    }
                })();
            }
        } catch (e) { }

        return false;
    }

    // 2. 🔧 检查用户是否已登录 - 已登录用户直接跳过欢迎页
    try {
        if (typeof NVAuth !== 'undefined' && NVAuth && typeof NVAuth.getCurrentUser === 'function') {
            let user = null;
            // 轮询等待 session 就绪（最多等待1.5秒）
            for (let i = 0; i < 5; i++) {
                try {
                    user = await NVAuth.getCurrentUser();
                    if (user) break;
                } catch (e) { }
                try { await sleep(300); } catch (e) { }
            }

            if (user) {
                // 已登录用户，跳过欢迎页
                console.log('🏠 已登录用户，跳过欢迎页，直接进入工作区');
                if (welcomeScreen) welcomeScreen.style.display = 'none';

                // 🔄 后台同步数据
                (async () => {
                    try {
                        console.log('🔄 [已登录刷新] 开始同步云端数据...');
                        if (typeof syncDataFromCloud === 'function') {
                            await syncDataFromCloud();
                        } else if (typeof refreshFilmBalanceFromCloud === 'function') {
                            await refreshFilmBalanceFromCloud(true);
                        }
                        console.log('✅ [已登录刷新] 数据同步完成');
                    } catch (e) {
                        console.warn('⚠️ [已登录刷新] 同步失败:', e?.message);
                    }
                })();

                return false;
            }
        }
    } catch (e) {
        console.warn('🏠 检查登录状态失败:', e?.message);
    }

    // 3. 未登录用户，显示欢迎页
    console.log('🏠 未登录用户，显示欢迎页');
    if (welcomeScreen) {
        try {
            welcomeScreen.style.display = 'flex';
            welcomeScreen.style.opacity = '1';
        } catch (e) { }
    }
    return true;
}

// 监听来自iframe的消息
window.addEventListener('message', function (event) {
    if (event.data === 'closeWelcome') {
        closeWelcomeScreen();
    }
});

window.closeWelcomeScreen = closeWelcomeScreen;
window.checkWelcomeScreen = checkWelcomeScreen;

// ==================== 📱 移动端菜单控制 ====================

// ==================== 📱 安卓/旧WebView 兼容增强 ====================
function syncModeToggleCheckedState() {
    try {
        const labels = document.querySelectorAll('.mode-toggle label');
        labels.forEach(label => label.classList.remove('is-checked'));

        const checked = document.querySelector('.mode-toggle input[type="radio"]:checked');
        if (checked && checked.closest('label')) {
            checked.closest('label').classList.add('is-checked');
        }
    } catch (e) {
        // ignore
    }
}

/**
 * 切换移动端侧边栏
 */
function toggleMobileSidebar() {
    const sidebar = document.getElementById('sidebar');
    const overlay = document.getElementById('sidebarOverlay');
    const menuBtn = document.getElementById('mobileMenuBtn');

    if (!sidebar || !overlay) return;

    // ✅ 仅在“抽屉模式”允许使用 ☰（避免桌面端出现按钮但点了无效果）
    const drawerMode = (() => {
        try {
            const isNarrow = window.matchMedia && window.matchMedia('(max-width: 768px)').matches;
            const isTouch = document.documentElement.classList.contains('is-touch');
            const isTabletWidth = window.matchMedia && window.matchMedia('(max-width: 1024px)').matches;
            return !!(isNarrow || (isTouch && isTabletWidth));
        } catch (e) {
            return window.innerWidth <= 768;
        }
    })();
    if (!drawerMode) {
        // 桌面宽屏：确保侧边栏可见、隐藏遮罩/按钮状态
        sidebar.classList.remove('open');
        overlay.classList.remove('show');
        if (menuBtn) menuBtn.innerHTML = '☰';
        try { document.documentElement.classList.remove('sidebar-open'); } catch (e) { }
        // 清除可能残留的抽屉内联样式
        try {
            sidebar.style.removeProperty('transform');
            sidebar.style.removeProperty('position');
            sidebar.style.removeProperty('height');
            sidebar.style.removeProperty('width');
            sidebar.style.removeProperty('box-shadow');
        } catch (e) { }
        return;
    }

    const isOpen = sidebar.classList.contains('open');

    if (isOpen) {
        sidebar.classList.remove('open');
        overlay.classList.remove('show');
        if (menuBtn) menuBtn.innerHTML = '☰';
        try { document.documentElement.classList.remove('sidebar-open'); } catch (e) { }
        // ✅ 强制关闭：不依赖 CSS，避免“点了没反应”
        try {
            sidebar.style.position = 'fixed';
            sidebar.style.top = '0';
            sidebar.style.left = '0';
            sidebar.style.transform = 'translateX(-105%)';
        } catch (e) { }
    } else {
        sidebar.classList.add('open');
        overlay.classList.add('show');
        if (menuBtn) menuBtn.innerHTML = '✕';
        try { document.documentElement.classList.add('sidebar-open'); } catch (e) { }
        // ✅ 强制打开：不依赖 CSS，避免某些桌面浏览器/缩放导致断点样式未命中
        try {
            sidebar.style.position = 'fixed';
            sidebar.style.top = '0';
            sidebar.style.left = '0';
            sidebar.style.height = '100dvh';
            sidebar.style.width = 'min(92vw, 360px)';
            sidebar.style.maxWidth = '92vw';
            sidebar.style.transform = 'translateX(0)';
            sidebar.style.zIndex = '10050';
            sidebar.style.boxShadow = '18px 0 40px rgba(0, 0, 0, 0.45)';
        } catch (e) { }
    }
}

/**
 * 关闭移动端侧边栏
 */
function closeMobileSidebar() {
    const sidebar = document.getElementById('sidebar');
    const overlay = document.getElementById('sidebarOverlay');
    const menuBtn = document.getElementById('mobileMenuBtn');

    if (sidebar) sidebar.classList.remove('open');
    if (overlay) overlay.classList.remove('show');
    if (menuBtn) menuBtn.innerHTML = '☰';
    try { document.documentElement.classList.remove('sidebar-open'); } catch (e) { }
    // ✅ 强制关闭（兜底）
    try {
        if (sidebar) {
            sidebar.style.position = 'fixed';
            sidebar.style.top = '0';
            sidebar.style.left = '0';
            sidebar.style.transform = 'translateX(-105%)';
        }
    } catch (e) { }
}

window.toggleMobileSidebar = toggleMobileSidebar;
window.closeMobileSidebar = closeMobileSidebar;
window.syncModeToggleCheckedState = syncModeToggleCheckedState;

// ==================== DOMContentLoaded ====================

document.addEventListener('DOMContentLoaded', async () => {

    // 🎬 预加载 FFmpeg.wasm 核心（后台静默加载，加速后续视频合并）
    preloadFFmpegCore();

    // 🏠 检查是否跳过欢迎页（刷新时保持在工作区）
    // 🔧 必须await，否则登录状态检测未完成就会显示欢迎页
    await checkWelcomeScreen();

    // 📱 移动端检测
    if (window.innerWidth <= 768) {
        console.log('📱 移动端模式');
    }

    // 📱 兼容：安卓/旧WebView 不支持 :has() 时，仍能显示“模式选中态”
    syncModeToggleCheckedState();
    document.querySelectorAll('.mode-toggle input[type="radio"]').forEach(radio => {
        radio.addEventListener('change', syncModeToggleCheckedState);
    });

    // 📱 触控设备兜底：不依赖 max-width(768) 来启用移动端样式
    try {
        const isTouch = ('ontouchstart' in window) || (navigator.maxTouchPoints > 0);
        if (isTouch) document.documentElement.classList.add('is-touch');
    } catch (e) { }

    // ✅ 统一同步“抽屉模式/桌面模式”，避免电脑端出现☰但侧栏不响应
    function syncSidebarMode() {
        const sidebar = document.getElementById('sidebar');
        const overlay = document.getElementById('sidebarOverlay');
        if (!sidebar || !overlay) return; // ✅ 移除对已删除按钮的检查

        const isNarrow = window.matchMedia && window.matchMedia('(max-width: 768px)').matches;
        const isTouch = document.documentElement.classList.contains('is-touch');
        const isTabletWidth = window.matchMedia && window.matchMedia('(max-width: 1024px)').matches;
        const drawerMode = !!(isNarrow || (isTouch && isTabletWidth));

        if (drawerMode) {
            // 抽屉模式默认收起：确保初始 transform 生效
            try {
                if (!sidebar.classList.contains('open')) {
                    sidebar.style.position = 'fixed';
                    sidebar.style.top = '0';
                    sidebar.style.left = '0';
                    sidebar.style.transform = 'translateX(-105%)';
                }
            } catch (e) { }
        } else {
            // 桌面模式：强制侧边栏可用
            closeMobileSidebar();
            try {
                sidebar.style.removeProperty('transform');
                sidebar.style.removeProperty('position');
                sidebar.style.removeProperty('height');
                sidebar.style.removeProperty('width');
                sidebar.style.removeProperty('box-shadow');
            } catch (e) { }
        }
    }
    window._syncSidebarMode = syncSidebarMode;
    try { syncSidebarMode(); } catch (e) { }
    window.addEventListener('resize', () => {
        try { syncSidebarMode(); } catch (e) { }
    });

    // 📱 安卓/旧WebView兜底：不要依赖 inline onclick，改成显式绑定 click/touchstart
    try {
        const menuBtn = document.getElementById('mobileMenuBtn');
        const overlay = document.getElementById('sidebarOverlay');
        const sidebar = document.getElementById('sidebar');

        if (menuBtn) {
            const onMenuBtn = (e) => {
                try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
                toggleMobileSidebar();
            };
            menuBtn.addEventListener('click', onMenuBtn, { passive: false });
            menuBtn.addEventListener('touchstart', onMenuBtn, { passive: false });
        }

        if (overlay) {
            const onOverlay = (e) => {
                try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
                closeMobileSidebar();
            };
            overlay.addEventListener('click', onOverlay, { passive: false });
            overlay.addEventListener('touchstart', onOverlay, { passive: false });
        }

        // 点击画布区域自动收起侧边栏（避免挡操作）
        document.addEventListener('click', (e) => {
            try {
                if (!sidebar) return;
                if (!sidebar.classList.contains('open')) return;
                if (e.target && e.target.closest('#sidebar')) return;
                closeMobileSidebar();
            } catch (err) { }
        }, { capture: true });
    } catch (e) { }

    // 📱 移动端虚拟鼠标悬浮按钮和工具栏
    initMobileUI();

    // 🔧 立即加载本地数据
    ideas = JSON.parse(localStorage.getItem('ideas_history') || '[]');
    flowNodes = JSON.parse(localStorage.getItem('flow_nodes') || '[]');
    window.flowNodes = flowNodes; // ⚡ 暴露给全局以便 Knolling 节点访问
    _setConnections(JSON.parse(localStorage.getItem('node_connections') || '[]'));

    // 🔧 从 localStorage 恢复 VIP 状态和用户等级
    try {
        // 🔧 优先使用云端同步的membership_type
        const memberType = localStorage.getItem('membership_type');
        if (memberType && memberType !== 'free') {
            window.currentUserLevel = memberType;
            console.log('✅ 用户等级已恢复(云端):', window.currentUserLevel);
        } else {
            // 兼容旧的vip_info格式
            const vipInfo = JSON.parse(localStorage.getItem('vip_info') || '{}');
            const isVip = vipInfo.expiry && new Date(vipInfo.expiry) > new Date();
            if (isVip && vipInfo.type) {
                window.currentUserLevel = vipInfo.type; // 'pro', 'mid', 'basic', 'vip'
                console.log('✅ 用户等级已恢复(本地):', window.currentUserLevel);
            } else {
                window.currentUserLevel = 'free';
            }
        }
    } catch (e) {
        console.warn('VIP状态恢复失败:', e);
        window.currentUserLevel = 'free';
    }

    // Check for stuck tasks
    ideas.forEach(i => {
        if (i.status === 'processing') i.status = 'paused';
    });
    saveIdeasToHistory();

    // 🔧 立即渲染本地数据（不等待云端）
    renderIdeasList();
    renderCanvas();

    // 🔧 如果已登录，立即尝试加载云端数据
    if (typeof NVAuth !== 'undefined') {
        try {
            const user = await NVAuth.getCurrentUser();
            if (user) {
                // 显示加载提示
                const list = document.getElementById('ideas-list');
                if (list && ideas.length === 0) {
                    list.innerHTML = '<div style="text-align: center; padding: 20px; color: #888;"><div style="font-size: 24px; margin-bottom: 8px;">⏳</div>正在加载云端数据...</div>';
                }

                // 立即加载云端数据
                await loadDataFromCloud();
            }
        } catch (e) {
            console.warn('云端数据预加载失败:', e);
        }
    }

    // Re-init node UI for loaded nodes
    flowNodes.forEach(node => {
        initBananaNodeUI(node);
        // Restore ref images
        updateNodeRefImages(node.id);
    });

    updateUsageDisplay();
    try { if (typeof updateApiStatusDisplay === 'function') updateApiStatusDisplay(); } catch (e) { } // 更新 API 状态显示
    setupInfiniteCanvas('taskCanvasContainer', 'taskCanvas');
    // 🗺️ 初始化小地图（含状态恢复）
    if (typeof window.initMinimap === 'function') {
        window.initMinimap();
    }

    // ⚡ 一键生成快捷键：Ctrl/⌘ + Enter（漫画模式→漫画；视频模式→视频）
    try {
        const input = document.getElementById('quickIdeaInput');
        if (input && !input._rrQuickHotkeyBound) {
            input._rrQuickHotkeyBound = true;
            input.addEventListener('keydown', (e) => {
                const isEnter = e.key === 'Enter';
                const withCmd = e.metaKey || e.ctrlKey;
                if (!isEnter || !withCmd) return;
                const mode = document.getElementById('quickGenMode')?.value || '';
                e.preventDefault();
                if (String(mode).includes('comic')) {
                    window.oneSentenceComic?.();
                } else {
                    window.oneSentenceVideo?.();
                }
            });
        }
    } catch (e) { }

    // ✅ 初始加载：注入“⚡一句话生成视频/漫画”入口（用 setTimeout 避免初始化阶段 DOM/函数尚未就绪导致静默失败）
    setTimeout(() => {
        try {
            const mode = document.getElementById('quickGenMode')?.value || '';
            if (String(mode).includes('comic')) {
                // 漫画模式由切换器控制注入，这里做一次兜底
                try { addComicStyleSelector?.(); } catch (e) { }
            } else {
                addVideoQuickSelector();
            }
        } catch (e) { }
    }, 0);

    // 🆕 初始化用户状态 - 必须 await 确保完成
    await initUserStatus();

    // 🕒 在线时长统计：登录后每分钟上报一次（页面隐藏时自动暂停）
    try {
        if (typeof NVAuth !== 'undefined') {
            const user = await NVAuth.getCurrentUser();
            if (user) startUserActivityHeartbeat();
        }
    } catch (e) { }

    // 🆕 恢复自动托管模式
    const savedAutoHosting = localStorage.getItem('auto_hosting_enabled');
    if (savedAutoHosting === 'true') {
        autoHostingMode = true;
        console.log('🤖 自动托管模式已恢复');

        // 检查是否有未完成的任务，自动加入托管队列
        const pendingTasks = ideas.filter(i =>
            i.status !== 'completed' &&
            i.status !== 'cancelled' &&
            i.status !== 'failed'
        );

        if (pendingTasks.length > 0) {
            console.log(`📥 发现 ${pendingTasks.length} 个未完成任务，自动加入托管队列`);
            batchAddToAutoHosting(pendingTasks);

            // 延迟启动，确保页面完全加载
            setTimeout(() => {
                if (confirm(
                    `🤖 自动托管模式已恢复\n\n` +
                    `发现 ${pendingTasks.length} 个未完成任务\n\n` +
                    `是否立即开始自动处理？`
                )) {
                    startAutoHosting();
                }
            }, 2000);
        }
    }

    // Init Voice (Optional)
    setTimeout(() => {
        if (window.getSetting && getSetting('autoVoice') !== false) startVoiceInput();
    }, 1000);

    // 浏览器插件阻断检测（自动 & 焦点返回时复检）
    setTimeout(() => runPluginDetection(false), 1200);
    window.addEventListener('focus', () => setTimeout(() => runPluginDetection(false), 600));

    // 🔧 Edge浏览器全面修复
    if (/Edg\//.test(navigator.userAgent)) {
        console.log('🔧 Edge: 启动全面兼容性修复');

        /**
         * Edge专用修复函数
         */
        // ✅ 重要：旧版 fixEdgeCards 会重写卡片 cssText（含固定 1100×550），会导致任务窗“闪一下就丢/靠近后消失”。
        // 现在仅做最小必要修复：容器溢出/定位 + transform-origin，不再覆盖卡片尺寸与布局。
        function fixEdgeCards() {
            const taskCanvas = document.getElementById('taskCanvas');
            const taskContainer = document.getElementById('taskCanvasContainer');
            if (taskContainer) {
                taskContainer.style.overflow = 'hidden';
                taskContainer.style.position = 'relative';
                taskContainer.style.width = '100%';
                taskContainer.style.height = '100%';
            }
            if (taskCanvas) {
                taskCanvas.style.position = 'relative';
                taskCanvas.style.transformOrigin = '0 0';
            }
            // 仅确保 absolute，不覆盖 width/height
            document.querySelectorAll('.result-card.horizontal-flow').forEach(card => {
                if (getComputedStyle(card).position !== 'absolute') card.style.position = 'absolute';
            });
        }

        // 轻量单次修复（避免频繁覆盖样式导致闪烁/跑丢）
        setTimeout(fixEdgeCards, 200);

        // 监听窗口resize：轻量修复
        window.addEventListener('resize', () => setTimeout(fixEdgeCards, 100));

        // 暴露全局修复函数供手动调用
        window.fixEdgeCards = fixEdgeCards;
    }

    // 🔧 恢复角色库状态（如果之前是打开的）
    setTimeout(() => {
        const wasLibraryOpen = localStorage.getItem('library_open');
        if (wasLibraryOpen === 'true') {
            const savedTab = localStorage.getItem('library_tab') || 'chars';
            openLibrary(savedTab);
            console.log('📚 角色库已自动恢复');
        }
    }, 500);

    // ✍️ 检查从 AI写作 页面传递过来的内容
    setTimeout(() => checkWritingToGeneration(), 800);
});

// 🍌 节点管理
window.removeNode = function (nodeId) {
    if (confirm('确定要删除这个画板吗？')) {
        if (typeof flowNodes !== 'undefined') {
            flowNodes = flowNodes.filter(n => n.id !== nodeId);
        }
        if (typeof connections !== 'undefined') {
            _setConnections(connections.filter(c => c.source !== nodeId && c.target !== nodeId));
        }
        if (typeof renderCanvas === 'function') renderCanvas();
        if (typeof saveIdeasToHistory === 'function') saveIdeasToHistory();
    }
};

// ==================== 用户状态管理 ====================

/**
 * 初始化用户状态
 * @param {number} retryCount - 重试次数
 */
async function initUserStatus(retryCount = 0) {
    console.log('🔐 initUserStatus 开始执行, retryCount:', retryCount);

    // 检查NVAuth是否可用
    if (typeof NVAuth === 'undefined') {
        // 🔧 如果 NVAuth 未加载，延迟重试（最多20次，每次间隔500ms）
        if (retryCount < 20) {
            console.log(`⏳ NVAuth未加载，${500}ms后重试... (${retryCount + 1}/20)`);
            setTimeout(() => initUserStatus(retryCount + 1), 500);
        } else {
            console.log('⚠️ NVAuth未加载，跳过用户状态初始化');
            // 即使 NVAuth 未加载，也要显示未登录状态
            resetUserStatusBar();
            resetWelcomeUserBar();
        }
        return;
    }

    console.log('✅ NVAuth 已加载，开始检查用户状态');

    async function __rrHandleSignedIn(user) {
        if (!user) {
            console.log('⚠️ __rrHandleSignedIn: user 为空');
            return;
        }
        console.log('🔐 __rrHandleSignedIn: 处理已登录用户', user.email || user.id);

        let profile = null;
        try {
            profile = await NVAuth.getUserProfile(user.id);
        } catch (e) {
            try {
                profile = JSON.parse(localStorage.getItem('nv_user_profile') || 'null');
            } catch (err) {
                profile = null;
            }
        }

        try {
            if (profile && typeof profile === 'object') {
                localStorage.setItem('nv_user_profile', JSON.stringify(profile));
                const mt = String(profile?.membership_type || profile?.membership || localStorage.getItem('membership_type') || 'free');
                localStorage.setItem('membership_type', mt);
                if (profile?.membership_level !== undefined && profile?.membership_level !== null) {
                    const lv = Number(profile.membership_level);
                    if (Number.isFinite(lv)) {
                        localStorage.setItem('membership_level', String(lv));
                        window.currentMembershipLevel = lv;
                    }
                }
                window.currentUserLevel = mt || 'free';
            }
        } catch (e) { }

        // 即使 profile 拉取失败，也要显示为“已登录”（昵称用邮箱兜底）
        updateUserStatusBar(user, profile);
        updateWelcomeUserBar(user, profile);

        try {
            const skipWelcome = sessionStorage.getItem('skip_welcome');
            if (skipWelcome !== 'true') {
                closeWelcomeScreen();
            }
        } catch (e) { }

        try {
            window.currentUserLevel = profile?.membership_type || profile?.membership || localStorage.getItem('membership_type') || 'free';
        } catch (e) {
            window.currentUserLevel = 'free';
        }

        // 同步余额（若 profile 有 quota_balance）
        try {
            if (profile?.quota_balance !== undefined && profile?.quota_balance !== null) {
                const cloudBalance = Number(profile.quota_balance) || 0;
                const cloudUsed = Number(profile.quota_used) || 0;
                localStorage.setItem('film_balance', String(cloudBalance));
                localStorage.setItem('cloud_film_balance', String(cloudBalance));
                localStorage.setItem('quota_used', String(cloudUsed));
                console.log('🎞️ 云端余额同步:', cloudBalance, '已用:', cloudUsed);
            } else {
                console.log('⚠️ 云端余额未获取到，使用本地缓存');
            }
            // 无论如何都要更新显示
            updateUsageDisplay();
        } catch (e) {
            console.error('❌ 余额同步失败:', e);
            updateUsageDisplay();
        }

        // ✅ 拉取“待领取/锁定”赠送胶片（不依赖打开会员中心）
        try { refreshGiftUnlockCacheIfNeeded(true); } catch (e) { }
        try {
            if (window.__rrGiftUnlockRefreshTimer) clearInterval(window.__rrGiftUnlockRefreshTimer);
            window.__rrGiftUnlockRefreshTimer = setInterval(() => {
                try { refreshGiftUnlockCacheIfNeeded(false); } catch (e) { }
            }, 2 * 60 * 1000);
        } catch (e) { }
    }

    function __rrHandleSignedOut() {
        resetUserStatusBar();
        resetWelcomeUserBar();

        try {
            if (window.__rrGiftUnlockRefreshTimer) clearInterval(window.__rrGiftUnlockRefreshTimer);
            window.__rrGiftUnlockRefreshTimer = null;
        } catch (e) { }

        try {
            localStorage.setItem('gift_unlock_can_unlock', '0');
            localStorage.setItem('gift_unlock_ts', String(Date.now()));
        } catch (e) { }

        // 🔧 登出时清空本地数据（防止数据混淆）
        localStorage.removeItem('ideas_history');
        localStorage.removeItem('character_library');
        localStorage.removeItem('flow_nodes');
        localStorage.removeItem('node_connections');
        localStorage.removeItem('last_logged_user_id');
        localStorage.removeItem('film_quota');
        localStorage.removeItem('film_balance');
        localStorage.removeItem('cloud_film_balance');
        localStorage.removeItem('vip_info');
        localStorage.removeItem('free_quota_date');
        localStorage.removeItem('first_time_image_used');
        localStorage.removeItem('first_time_video_used');
        localStorage.removeItem('first_time_task_used');
        localStorage.removeItem('free_shares_today');
        ideas = [];
        ideasHistory = [];
        window.flowNodes = [];
        _setConnections([]);
        renderIdeasList();
        renderCanvas();
    }

    // ✅ 无论初始是否取到 user，都要绑定一次监听（否则会出现“已登录但UI不更新”）
    try {
        if (!window.__rrAuthListenerBound) {
            window.__rrAuthListenerBound = true;
            NVAuth.onAuthStateChange(async (event, session) => {
                if (event === 'SIGNED_OUT') {
                    __rrHandleSignedOut();
                    return;
                }
                if (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED' || event === 'USER_UPDATED') {
                    const u = session?.user;
                    if (u) {
                        try { localStorage.setItem('last_logged_user_id', u.id); } catch (e) { }
                        await __rrHandleSignedIn(u);
                    } else {
                        // session.user 不一定同步到位，兜底再取一次
                        try {
                            const u2 = await NVAuth.getCurrentUser();
                            if (u2) await __rrHandleSignedIn(u2);
                        } catch (e) { }
                    }
                }
            });
        }
    } catch (e) { }

    try {
        // 轮询等待 session 就绪（避免“已登录但初次 getCurrentUser 为空”）
        let user = null;
        for (let i = 0; i < 10; i++) {
            try {
                user = await NVAuth.getCurrentUser();
                if (user) break;
            } catch (e) { }
            await sleep(300);
        }

        if (user) {
            await __rrHandleSignedIn(user);

            // 🔄 从云端加载设置（API Key等）- 数据已在DOMContentLoaded中加载
            try {
                const cloudLoaded = await loadSettingsFromCloud();
                if (cloudLoaded && typeof updateApiStatusDisplay === 'function') {
                    updateApiStatusDisplay();
                }
            } catch (e) { }
        } else {
            // 未登录（但监听已绑定，后续 SIGNED_IN 会自动更新 UI）
            resetUserStatusBar();
            resetWelcomeUserBar();
        }
    } catch (error) {
        console.error('用户状态初始化失败:', error);
        // 出错时不要强行判定为未登录，保留监听兜底
        try {
            const u = await NVAuth.getCurrentUser();
            if (u) {
                await __rrHandleSignedIn(u);
                return;
            }
        } catch (e) { }
        resetUserStatusBar();
        resetWelcomeUserBar();
        try { updateUsageDisplay(); } catch (e) { }
    }
}

/**
 * 更新用户状态栏（已登录）
 * 🔧 取云端和本地的较大值（防止数据丢失）
 */
function updateUserStatusBar(user, profile) {
    const statusBar = document.getElementById('userStatusBar');
    if (!statusBar) return;

    const email = (user && user.email) ? String(user.email) : '';
    const phone = (user && user.phone) ? String(user.phone) : '';
    const fallbackName = email ? email.split('@')[0] : (phone ? phone : (user && user.id ? String(user.id).slice(0, 6) : '用户'));
    const nickname = String(profile?.nickname || profile?.username || fallbackName || '用户');
    const initial = nickname.charAt(0).toUpperCase();
    const membershipType = String(profile?.membership_type || profile?.membership || localStorage.getItem('membership_type') || 'free');
    let membershipLabel = membershipType;
    const mLv = String(membershipType || '').match(/^(?:lv)?\s*(\d{1,2})$/i);
    if (mLv && mLv[1]) {
        membershipLabel = `LV${parseInt(mLv[1], 10)}`;
    } else {
        const membershipLabelMap = { free: '免费', basic: '基础', mid: '中级', pro: '高级', vip: 'VIP', creator: '创作者', studio: '工作室' };
        membershipLabel = membershipLabelMap[membershipType] || membershipType;
    }
    const membershipBgMap = { free: 'rgba(148,163,184,0.15)', basic: 'rgba(251,191,36,0.15)', mid: 'rgba(59,130,246,0.18)', pro: 'rgba(168,85,247,0.18)', vip: 'rgba(236,72,153,0.18)', creator: 'rgba(34,197,94,0.16)', studio: 'rgba(245,158,11,0.16)' };
    const membershipColorMap = { free: '#94a3b8', basic: '#fbbf24', mid: '#60a5fa', pro: '#c084fc', vip: '#f472b6', creator: '#34d399', studio: '#fbbf24' };
    const membershipBg = membershipBgMap[membershipType] || 'rgba(148,163,184,0.15)';
    const membershipColor = membershipColorMap[membershipType] || '#e5e7eb';
    const cloudQuotaRaw = Number(profile?.quota_balance);
    const cloudQuota = Number.isFinite(cloudQuotaRaw) ? cloudQuotaRaw : 0;
    const localQuotaRaw = parseFloat(localStorage.getItem('film_balance') || '0');
    const localQuota = Number.isFinite(localQuotaRaw) ? localQuotaRaw : 0;
    // 🔧 取较大值（防止充值后被旧数据覆盖）
    const quota = Math.max(cloudQuota, localQuota);
    console.log(`🎞️ [状态栏] 云端:${cloudQuota}, 本地:${localQuota}, 使用:${quota}`);

    try {
        // 同步到本地缓存
        localStorage.setItem('cloud_film_balance', String(quota));
        localStorage.setItem('film_balance', String(quota));
    } catch (e) { }

    try { updateUsageDisplay(); } catch (e) { }

    // 🔧 修复：状态栏只显示余额，不显示"可领"
    const displayQuota = Math.round(quota * 100) / 100;
    const quotaBadge = `🎞️ ${displayQuota}`;

    // 🔧 获取完整会员信息：等级 + 类型 + 年卡
    const memberLevel = profile?.membership_level || localStorage.getItem('membership_level') || '';
    const expiresAt = profile?.membership_expires_at || localStorage.getItem('membership_expires_at') || '';
    const expiresDate = expiresAt ? new Date(expiresAt) : null;
    const now = new Date();

    // 计算是否年卡（剩余天数>300天视为年卡）
    const daysRemaining = expiresDate ? Math.ceil((expiresDate - now) / (1000 * 60 * 60 * 24)) : 0;
    const isYearCard = daysRemaining > 300;
    const isValid = expiresDate && expiresDate > now;

    // 构建会员标签数组
    const memberTags = [];
    // 等级标签
    if (memberLevel && Number(memberLevel) > 0) {
        memberTags.push({ text: `LV${memberLevel}`, bg: 'rgba(251,191,36,0.2)', color: '#fbbf24' });
    }
    // 类型标签（PRO/VIP等，排除lv格式）
    if (membershipType && !membershipType.match(/^lv\d+$/i) && membershipType !== 'free') {
        const typeLabel = { basic: '基础', mid: '中级', pro: 'PRO', vip: 'VIP', creator: '创作者', studio: '工作室' }[membershipType] || membershipType.toUpperCase();
        memberTags.push({ text: typeLabel, bg: 'rgba(168,85,247,0.2)', color: '#c084fc' });
    }
    // 年卡标签
    if (isYearCard && isValid) {
        memberTags.push({ text: '年卡', bg: 'rgba(34,197,94,0.2)', color: '#34d399' });
    }

    // 生成标签HTML（支持两排）
    const tagsHtml = memberTags.length > 0
        ? memberTags.map(t => `<span style="font-size:9px; padding:1px 4px; border-radius:999px; background:${t.bg}; color:${t.color}; flex-shrink:0; white-space:nowrap;">${t.text}</span>`).join('')
        : `<span style="font-size:9px; padding:1px 4px; border-radius:999px; background:rgba(148,163,184,0.15); color:#94a3b8; flex-shrink:0;">免费</span>`;

    statusBar.innerHTML = `
        <div class="user-status-logged" style="display:flex; align-items:center; gap:6px;">
            <a href="user.html" class="user-avatar-btn" title="${nickname}\n${memberTags.map(t => t.text).join(' ')}\n${quotaBadge}\n点击进入用户中心" style="display:flex; align-items:center; gap:6px; padding:4px 8px; background:rgba(251,191,36,0.1); border:1px solid rgba(251,191,36,0.3); border-radius:16px; text-decoration:none;">
                <span class="user-avatar-small" style="width:24px; height:24px; border-radius:50%; background:linear-gradient(135deg,#fbbf24,#f59e0b); display:flex; align-items:center; justify-content:center; font-size:12px; font-weight:bold; color:#000; flex-shrink:0;">${initial}</span>
                <span style="display:flex; flex-direction:column; line-height:1.2; min-width:0; gap:2px;">
                    <span style="font-size:11px; color:#e5e7eb; font-weight:600; max-width:80px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${nickname}</span>
                    <span style="display:flex; align-items:center; gap:2px; flex-wrap:wrap;">${tagsHtml}</span>
                </span>
            </a>
            <button onclick="handleLogoutFromMain()" title="退出登录" style="background:rgba(239,68,68,0.15); border:1px solid rgba(239,68,68,0.3); color:#f87171; padding:4px 8px; border-radius:8px; cursor:pointer; font-size:11px; white-space:nowrap;">退出</button>
        </div>
    `;

    console.log('✅ 用户状态栏已更新:', nickname, membershipLabel);
}

/**
 * 主界面退出登录处理函数
 */
window.handleLogoutFromMain = async function () {
    if (!confirm('确定要退出登录吗？')) return;

    try {
        if (typeof NVAuth !== 'undefined') {
            await NVAuth.signOut();
            console.log('✅ 已退出登录');
        }

        // 清除本地数据
        localStorage.removeItem('nv_user_profile');
        localStorage.removeItem('membership_type');
        localStorage.removeItem('vip_info');
        localStorage.removeItem('film_balance');
        localStorage.removeItem('cloud_film_balance');

        // 重置UI
        resetUserStatusBar();
        resetWelcomeUserBar();

        // 提示用户
        alert('已成功退出登录');

        // 刷新页面以确保状态完全重置
        location.reload();
    } catch (e) {
        console.error('退出登录失败:', e);
        alert('退出登录失败，请重试');
    }
};

