function updateWelcomeCTA(isLoggedIn) {
    const btn = document.getElementById('welcomeEnterBtn');
    if (!btn) return;
    if (isLoggedIn) {
        btn.textContent = '🚪 进入创作';
        btn.setAttribute('href', 'javascript:void(0)');
        btn.onclick = function (ev) {
            try { ev.preventDefault(); } catch (e) { }
            closeWelcomeScreen();
            return false;
        };
    } else {
        btn.textContent = '🔒 登录 / 注册开始创作';
        btn.setAttribute('href', 'auth.html');
        btn.onclick = null;
    }
}

// 标记是否已从云端加载过数据（防止重复加载覆盖本地操作）
let cloudDataLoaded = false;

/**
 * 从云端加载用户数据（任务和角色）
 * @param {boolean} force - 是否强制重新加载
 */
async function loadDataFromCloud(force = false) {
    // 如果已经加载过且不是强制刷新，跳过
    if (cloudDataLoaded && !force) {
        console.log('☁️ 云端数据已加载，跳过重复加载');
        return true;
    }

    if (typeof NVAuth === 'undefined') {
        console.log('NVAuth 未定义，跳过云端数据加载');
        return false;
    }

    try {
        const user = await NVAuth.getCurrentUser();
        if (!user) {
            console.log('用户未登录，使用本地数据');
            return false;
        }

        console.log('🔄 开始从云端加载用户数据...');

        // 1. 加载云端任务并智能合并
        try {
            const cloudTasks = await NVAuth.getTasksFromCloud();
            console.log('☁️ 云端返回任务数:', cloudTasks?.length || 0);
            console.log('📝 本地任务数:', ideas.length);

            // 🔧 智能合并策略：基于 updated_at 时间戳决定保留哪个版本
            const localTasks = [...ideas];
            const mergedTasks = [];
            const cloudTaskMap = new Map();
            const localTaskMap = new Map();

            // 建立云端任务索引
            (cloudTasks || []).forEach(task => {
                if (task && task.id) cloudTaskMap.set(task.id, task);
            });

            // 建立本地任务索引
            localTasks.forEach(task => {
                if (task && task.id) localTaskMap.set(task.id, task);
            });

            // 获取本地已删除的任务ID
            const localDeletedIds = new Set(deletedTaskIds || []);

            // 合并逻辑
            const processedIds = new Set();

            // 1. 处理云端任务
            cloudTaskMap.forEach((cloudTask, taskId) => {
                // 如果本地已删除，跳过云端任务
                if (localDeletedIds.has(taskId)) {
                    console.log(`🗑️ 跳过已删除的云端任务: ${taskId}`);
                    return;
                }

                const localTask = localTaskMap.get(taskId);
                if (localTask) {
                    // 两边都有，比较时间戳
                    const cloudTime = new Date(cloudTask.updated_at || cloudTask.created_at || 0).getTime();
                    const localTime = new Date(localTask.updated_at || localTask.created_at || 0).getTime();

                    if (localTime > cloudTime) {
                        // 本地更新，使用本地版本
                        console.log(`📝 任务 ${taskId} 使用本地版本（本地更新）`);
                        mergedTasks.push(localTask);
                    } else {
                        // 云端更新或相同，使用云端版本
                        console.log(`☁️ 任务 ${taskId} 使用云端版本`);
                        mergedTasks.push(cloudTask);
                    }
                } else {
                    // 只有云端有，使用云端版本
                    mergedTasks.push(cloudTask);
                }
                processedIds.add(taskId);
            });

            // 2. 处理只在本地存在的任务（新建的）
            localTaskMap.forEach((localTask, taskId) => {
                if (!processedIds.has(taskId) && !localDeletedIds.has(taskId)) {
                    console.log(`📝 保留本地新任务: ${taskId}`);
                    mergedTasks.push(localTask);
                }
            });

            ideas = mergedTasks;
            ideasHistory = ideas;
            localStorage.setItem('ideas_history', JSON.stringify(ideas));
            console.log(`✅ 智能合并完成: ${ideas.length} 个任务`);

            // 清空删除列表（已处理）
            deletedTaskIds = [];
            localStorage.removeItem('deleted_task_ids');

            // 将合并后的数据同步回云端
            if (ideas.length > 0) {
                try {
                    await NVAuth.syncTasksToCloud(ideas);
                    console.log('📤 合并后的任务已同步到云端');
                } catch (syncErr) {
                    console.warn('同步合并结果到云端失败:', syncErr);
                }
            }

            // 刷新UI
            renderIdeasList();
            renderCanvas();

            if (mergedTasks.length === 0) {
                console.log('☁️ 合并后没有任务数据');
            }
        } catch (taskErr) {
            console.warn('加载云端任务失败:', taskErr);
        }

        // 2. 加载云端角色（智能合并，保留完整数据）
        try {
            const cloudChars = await NVAuth.getCharactersFromCloud();
            const localChars = JSON.parse(localStorage.getItem('character_library') || '[]');

            if (cloudChars && cloudChars.length > 0) {
                // 🔧 智能合并：云端数据为主，本地数据补充缺失字段
                const cloudCharMap = new Map(cloudChars.map(c => [c.name, c]));
                const localCharMap = new Map(localChars.map(c => [c.name, c]));

                const mergedChars = cloudChars.map(cloudChar => {
                    const localChar = localCharMap.get(cloudChar.name);
                    if (localChar) {
                        // 合并：云端为主，本地补充缺失的 variants 等字段
                        return {
                            ...localChar,
                            ...cloudChar,
                            // 确保 variants 存在
                            variants: cloudChar.variants || localChar.variants || {
                                poster: cloudChar.imageUrl || cloudChar.posterUrl || localChar.imageUrl || '',
                                turnaround: cloudChar.turnaroundUrl || localChar.turnaroundUrl || cloudChar.imageUrl || ''
                            },
                            // 确保 posterUrl 存在
                            posterUrl: cloudChar.posterUrl || cloudChar.imageUrl || localChar.posterUrl || localChar.imageUrl || '',
                            imageUrl: cloudChar.imageUrl || localChar.imageUrl || ''
                        };
                    }
                    return cloudChar;
                });

                // 添加本地独有的角色（云端没有的）
                localChars.forEach(localChar => {
                    if (!cloudCharMap.has(localChar.name)) {
                        mergedChars.push(localChar);
                    }
                });

                localStorage.setItem('character_library', JSON.stringify(mergedChars));
                console.log(`✅ 已从云端加载并合并 ${mergedChars.length} 个角色`);
            } else if (localChars.length > 0) {
                console.log(`☁️ 云端无角色，保留本地 ${localChars.length} 个角色`);
            } else {
                console.log('云端和本地都没有角色数据');
            }
        } catch (charErr) {
            console.warn('加载云端角色失败:', charErr);
        }

        // 标记已加载
        cloudDataLoaded = true;

        // 3. 刷新UI
        renderIdeasList();
        renderCanvas();
        if (typeof renderLibChars === 'function') {
            renderLibChars();
        }

        console.log('✅ 云端数据加载完成');
        return true;
    } catch (error) {
        console.error('从云端加载数据失败:', error);
        return false;
    }
}

/**
 * 静默同步本地任务到云端（后台执行，不阻塞）
 */
async function syncLocalTasksToCloud() {
    if (typeof NVAuth === 'undefined') return;

    try {
        const user = await NVAuth.getCurrentUser();
        if (!user) return;

        const tasks = JSON.parse(localStorage.getItem('ideas_history') || '[]');
        if (tasks.length > 0) {
            await NVAuth.syncTasksToCloud(tasks);
            console.log('📤 本地任务已同步到云端');
        }
    } catch (e) {
        console.warn('后台同步任务失败:', e);
    }
}

/**
 * 同步本地数据到云端（快捷方法）
 */
async function quickSyncToCloud() {
    if (typeof NVAuth === 'undefined') {
        alert('请先登录后再同步数据');
        window.location.href = 'auth.html';
        return;
    }

    try {
        const user = await NVAuth.getCurrentUser();
        if (!user) {
            alert('请先登录后再同步数据');
            window.location.href = 'auth.html';
            return;
        }

        // 同步任务
        const tasks = JSON.parse(localStorage.getItem('ideas_history') || '[]');
        if (tasks.length > 0) {
            await NVAuth.syncTasksToCloud(tasks);
        }

        // 同步角色
        const characters = JSON.parse(localStorage.getItem('character_library') || '[]');
        if (characters.length > 0) {
            await NVAuth.syncCharactersToCloud(characters);
        }

        console.log('✅ 数据已同步到云端');
        return true;
    } catch (error) {
        console.error('同步失败:', error);
        return false;
    }
}

// 导出函数
window.initUserStatus = initUserStatus;
window.quickSyncToCloud = quickSyncToCloud;

// ==================== 视频编辑器功能 ====================

let editorClips = []; // 编辑器中的视频片段
let currentTrimIndex = -1; // 当前裁剪的片段索引
let currentEditIdeaId = null; // 当前编辑的任务ID

/**
 * 打开视频编辑器
 */
window.openVideoEditor = function (ideaId) {
    const idea = ideas.find(i => i.id === ideaId) || ideasHistory.find(i => i.id === ideaId);
    if (!idea) {
        alert('找不到该任务');
        return;
    }

    currentEditIdeaId = ideaId;

    // 获取视频片段
    const videos = idea.videoResults?.filter(r => r.url).sort((a, b) => a.index - b.index) || [];
    if (videos.length === 0 && idea.finalVideoUrl) {
        videos.push({ index: 0, url: idea.finalVideoUrl });
    }

    if (videos.length === 0) {
        alert('没有可编辑的视频片段，请先生成视频');
        return;
    }

    // 初始化编辑器片段
    editorClips = videos.map((v, i) => ({
        id: i,
        url: v.url,
        name: `片段 ${i + 1}`,
        startTime: 0,
        endTime: 5, // 默认5秒，加载后更新
        duration: 5,
        order: i
    }));

    // 显示编辑器
    document.getElementById('videoEditorModal').style.display = 'flex';

    // 渲染时间线
    renderTimeline();

    // 更新状态栏
    updateEditorStatus();

    // 加载第一个视频获取时长
    loadClipDurations();
};

/**
 * 关闭视频编辑器
 */
window.closeVideoEditor = function () {
    // ✅ 关闭编辑器时再释放合并后的 blob URL（避免用户二次下载时变“网络错误”）
    try {
        if (window.__rrEditorMerged?.url && String(window.__rrEditorMerged.url).startsWith('blob:')) {
            URL.revokeObjectURL(window.__rrEditorMerged.url);
        }
    } catch (e) { }
    window.__rrEditorMerged = null;
    document.getElementById('videoEditorModal').style.display = 'none';
    editorClips = [];
    currentTrimIndex = -1;
    currentEditIdeaId = null;
};

/**
 * 渲染时间线
 */
function renderTimeline() {
    const track = document.getElementById('timelineTrack');
    if (!track) return;

    if (editorClips.length === 0) {
        track.innerHTML = '<div style="color: #666; font-size: 14px;">暂无视频片段</div>';
        return;
    }

    // 按order排序
    const sortedClips = [...editorClips].sort((a, b) => a.order - b.order);

    track.innerHTML = sortedClips.map((clip, displayIndex) => `
        <div class="timeline-clip" data-id="${clip.id}" draggable="true"
             style="min-width: 120px; height: 80px; background: linear-gradient(135deg, #2a2a4a, #1a1a3a); 
                    border: 2px solid #444; border-radius: 8px; cursor: grab; position: relative; 
                    display: flex; flex-direction: column; overflow: hidden; transition: all 0.2s;"
             ondragstart="handleDragStart(event, ${clip.id})"
             ondragover="handleDragOver(event)"
             ondrop="handleDrop(event, ${clip.id})"
             ondblclick="openTrimPanel(${clip.id})"
             onclick="previewClip(${clip.id})">
            <!-- 缩略图 -->
            <div style="flex: 1; background: #000; display: flex; align-items: center; justify-content: center; overflow: hidden;">
                <video src="${clip.url}" style="width: 100%; height: 100%; object-fit: cover;" muted playsinline crossorigin="anonymous" preload="metadata"></video>
            </div>
            <!-- 信息栏 -->
            <div style="padding: 4px 6px; background: rgba(0,0,0,0.6); font-size: 10px; color: #fff; display: flex; justify-content: space-between; align-items: center;">
                <span>${clip.name}</span>
                <span style="color: var(--accent-gold);">${(clip.endTime - clip.startTime).toFixed(1)}s</span>
            </div>
            <!-- 删除按钮 -->
            <button onclick="event.stopPropagation(); removeClip(${clip.id})" 
                    style="position: absolute; top: 2px; right: 2px; width: 18px; height: 18px; 
                           background: rgba(244,67,54,0.8); border: none; border-radius: 50%; 
                           color: #fff; font-size: 10px; cursor: pointer; opacity: 0; transition: opacity 0.2s;"
                    onmouseover="this.style.opacity=1" onmouseout="this.style.opacity=0">×</button>
        </div>
    `).join('');

    // 添加hover效果
    track.querySelectorAll('.timeline-clip').forEach(clip => {
        clip.addEventListener('mouseenter', () => {
            clip.style.borderColor = 'var(--accent-gold)';
            clip.querySelector('button').style.opacity = '1';
        });
        clip.addEventListener('mouseleave', () => {
            clip.style.borderColor = '#444';
            clip.querySelector('button').style.opacity = '0';
        });
    });
}

/**
 * 加载视频时长
 */
async function loadClipDurations() {
    for (let clip of editorClips) {
        try {
            const video = document.createElement('video');
            video.src = clip.url;
            video.preload = 'metadata';

            await new Promise((resolve, reject) => {
                video.onloadedmetadata = () => {
                    clip.duration = video.duration;
                    clip.endTime = video.duration;
                    resolve();
                };
                video.onerror = reject;
                setTimeout(reject, 5000); // 5秒超时
            });
        } catch (e) {
            console.warn(`无法加载片段 ${clip.id} 的时长`);
        }
    }

    renderTimeline();
    updateEditorStatus();
}

/**
 * 预览单个片段
 */
window.previewClip = function (clipId) {
    const clip = editorClips.find(c => c.id === clipId);
    if (!clip) return;

    const video = document.getElementById('editorVideo');
    video.src = clip.url;
    video.currentTime = clip.startTime;
    video.play();

    // 在结束时间暂停
    const checkEnd = () => {
        if (video.currentTime >= clip.endTime) {
            video.pause();
            video.removeEventListener('timeupdate', checkEnd);
        }
    };
    video.addEventListener('timeupdate', checkEnd);
};

/**
 * 预览全部片段
 */
window.previewAllClips = async function () {
    const sortedClips = [...editorClips].sort((a, b) => a.order - b.order);
    const video = document.getElementById('editorVideo');

    for (let clip of sortedClips) {
        video.src = clip.url;
        video.currentTime = clip.startTime;

        await new Promise(resolve => {
            video.play();
            const checkEnd = () => {
                if (video.currentTime >= clip.endTime) {
                    video.pause();
                    video.removeEventListener('timeupdate', checkEnd);
                    resolve();
                }
            };
            video.addEventListener('timeupdate', checkEnd);
        });
    }
};

/**
 * 拖拽排序
 */
let draggedClipId = null;

window.handleDragStart = function (e, clipId) {
    draggedClipId = clipId;
    e.dataTransfer.effectAllowed = 'move';
    e.target.style.opacity = '0.5';
};

window.handleDragOver = function (e) {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
};

window.handleDrop = function (e, targetId) {
    e.preventDefault();

    if (draggedClipId === null || draggedClipId === targetId) return;

    const draggedClip = editorClips.find(c => c.id === draggedClipId);
    const targetClip = editorClips.find(c => c.id === targetId);

    if (draggedClip && targetClip) {
        // 交换order
        const tempOrder = draggedClip.order;
        draggedClip.order = targetClip.order;
        targetClip.order = tempOrder;

        renderTimeline();
    }

    draggedClipId = null;
    document.querySelectorAll('.timeline-clip').forEach(el => el.style.opacity = '1');
};

/**
 * 删除片段
 */
window.removeClip = function (clipId) {
    if (!confirm('确定删除这个片段吗？')) return;

    editorClips = editorClips.filter(c => c.id !== clipId);
    renderTimeline();
    updateEditorStatus();
};

/**
 * 打开裁剪面板
 */
window.openTrimPanel = function (clipId) {
    const clip = editorClips.find(c => c.id === clipId);
    if (!clip) return;

    currentTrimIndex = clipId;

    document.getElementById('trimClipName').textContent = clip.name;
    document.getElementById('trimStart').max = clip.duration * 10;
    document.getElementById('trimEnd').max = clip.duration * 10;
    document.getElementById('trimStart').value = clip.startTime * 10;
    document.getElementById('trimEnd').value = clip.endTime * 10;
    document.getElementById('trimStartTime').textContent = clip.startTime.toFixed(1) + 's';
    document.getElementById('trimEndTime').textContent = clip.endTime.toFixed(1) + 's';

    document.getElementById('trimPanel').style.display = 'block';

    // 预览该片段
    previewClip(clipId);

    // 添加滑块事件
    document.getElementById('trimStart').oninput = (e) => {
        const time = e.target.value / 10;
        document.getElementById('trimStartTime').textContent = time.toFixed(1) + 's';
        document.getElementById('editorVideo').currentTime = time;
    };

    document.getElementById('trimEnd').oninput = (e) => {
        const time = e.target.value / 10;
        document.getElementById('trimEndTime').textContent = time.toFixed(1) + 's';
        document.getElementById('editorVideo').currentTime = time;
    };
};

/**
 * 关闭裁剪面板
 */
window.closeTrimPanel = function () {
    document.getElementById('trimPanel').style.display = 'none';
    currentTrimIndex = -1;
};

/**
 * 应用裁剪
 */
window.applyTrim = function () {
    if (currentTrimIndex === -1) return;

    const clip = editorClips.find(c => c.id === currentTrimIndex);
    if (!clip) return;

    clip.startTime = parseFloat(document.getElementById('trimStart').value) / 10;
    clip.endTime = parseFloat(document.getElementById('trimEnd').value) / 10;

    closeTrimPanel();
    renderTimeline();
    updateEditorStatus();
};

/**
 * 更新编辑器状态栏
 */
function updateEditorStatus() {
    const totalDuration = editorClips.reduce((sum, c) => sum + (c.endTime - c.startTime), 0);
    document.getElementById('totalDuration').textContent = totalDuration.toFixed(1);
    document.getElementById('clipCount').textContent = editorClips.length;
}

/**
 * 合并并导出视频
 */
window.mergeAndExport = async function () {
    if (editorClips.length === 0) {
        alert('没有可合并的视频片段');
        return;
    }

    const statusEl = document.getElementById('editorStatus');
    statusEl.innerHTML = '🔄 正在合并视频，请稍候...';
    statusEl.style.color = 'var(--accent-gold)';

    try {
        // 按order排序获取URL列表
        const sortedClips = [...editorClips].sort((a, b) => a.order - b.order);
        const videoUrls = sortedClips.map(c => c.url);

        // 🔧 进度回调更新UI
        const onProgress = (progress, message) => {
            statusEl.innerHTML = `🔄 ${message} (${progress}%)`;
        };

        // ✅ mergeVideosInBrowser 统一返回 { url, mime, ext, blob? }
        const merged = await mergeVideosInBrowser(videoUrls, onProgress);
        const blobUrl = (typeof merged === 'string') ? merged : (merged && merged.url ? merged.url : '');
        const ext = (typeof merged === 'object' && merged?.ext) ? merged.ext : (_guessExtFromUrl(blobUrl) || 'mp4');

        if (blobUrl) {

            statusEl.innerHTML = '✅ 合并成功！';
            statusEl.style.color = '#4caf50';

            // 显示合并后的视频
            const video = document.getElementById('editorVideo');
            video.src = blobUrl;
            video.play();

            // 🔧 修复：正确下载视频文件
            const downloadLink = document.createElement('a');
            downloadLink.href = blobUrl;
            downloadLink.download = `RollRoll_merged_${Date.now()}.${ext}`;
            document.body.appendChild(downloadLink);
            downloadLink.click();
            document.body.removeChild(downloadLink);

            // ✅ 不再 60 秒自动 revoke：否则用户二次下载会显示“网络错误”，并且容易误以为文件没下到
            // 统一在关闭编辑器时清理
            window.__rrEditorMerged = { url: blobUrl, ext };

            alert('✅ 视频合并成功！已开始下载。');
        } else {
            throw new Error('合并返回空结果');
        }
    } catch (error) {
        console.error('合并失败:', error);
        statusEl.innerHTML = `❌ 合并失败: ${error.message}`;
        statusEl.style.color = '#f44336';

        alert('视频合并失败: ' + error.message + '\n\n您可以手动下载各片段后使用其他软件合并。');
    }
};

