// ==================== 漫画标题智能生成（短标题） ====================
function _isLikelyComicBookTitle(raw = '') {
    const s = String(raw || '').trim()
        .replace(/^["'“”‘’《》]+|["'“”‘’《》]+$/g, '')
        .replace(/\s+/g, '')
        .replace(/\.\.\.|…/g, '')
        .trim();
    if (!s) return false;
    // 2-8 字更像“漫画书名”（太长通常是句子）
    if (s.length < 2 || s.length > 8) return false;
    // 禁止标点/括号/引号等
    if (/[，,。.!?！？:：;；\(\)（）【】\[\]「」"“”'‘’]/.test(s)) return false;
    // 常见“叙述开头”不是标题
    if (/^(在|当|清晨|夜晚|午后|傍晚|某天|有一天|那天|此刻|这一天|这一刻|清晨的|夜晚的)/.test(s)) return false;
    // 避免“半句话”常见尾巴
    if (/(的时候|之后|之前|之中|之下|之上|之处|之时|之际)$/.test(s)) return false;
    // 允许少量“的”，但如果全是虚词就不行（粗略）
    const nonHan = s.replace(/[\u4e00-\u9fa5]/g, '');
    if (nonHan.length > 0) return false;
    return true;
}

function _normalizeComicTitleHeuristic(raw = '') {
    const s = String(raw || '').trim()
        .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
        .replace(/\s+/g, ' ')
        .replace(/\.\.\.|…/g, '')
        .trim();
    if (!s) return '';

    // 优先取第一句/第一段
    const first = s.split(/[，,。.!?！？:：;；\n]/)[0]?.trim() || s;

    // 去掉明显的叙述口吻前缀（不是标题）
    const cleaned = first
        .replace(/^(在|当|清晨|夜晚|午后|傍晚|某天|有一天|那天|此刻|这一天|这一刻)/, '')
        .replace(/^[的，。,.!?！？:：;；\s]+/, '')
        .trim();

    // 如果仍然过长，尽量保留“名词短语”感觉：去掉一些虚词
    const noParticles = cleaned.replace(/[的一了着地得很就又还都与和及或而把被]/g, '').trim();
    const candidate = (noParticles.length >= 4 && noParticles.length <= 12) ? noParticles : cleaned;

    const t = candidate.replace(/[《》"'“”‘’]/g, '').replace(/\s+/g, '').trim();
    if (_isLikelyComicBookTitle(t)) return t;
    return '';
}

async function _generateComicBookTitleByStory(basisText = '') {
    // ✅ 全新方式：基于“文章/剧本整体内容”取书名，不依赖开头截断
    const basis = String(basisText || '').trim();
    if (!basis) return '';
    const prompt =
        `你是漫画编辑，请根据故事内容取一个“漫画书名”（中文）。\n` +
        `硬性要求：\n` +
        `- 必须是 2-8 个汉字\n` +
        `- 必须是名词短语（像书名），不能是句子/半句话\n` +
        `- 不能包含任何标点、空格、省略号、英文、数字\n` +
        `- 不要出现“第X章/第X话/某某的一天/在……里/当……时/清晨/夜晚/某天/有一天/那天/此刻”等叙述口吻\n` +
        `- 不要输出解释，只输出 JSON 数组，包含 8 个候选书名\n` +
        `故事内容（节选）：\n` +
        basis.substring(0, 1200) + `\n` +
        `示例输出：["晨光列车","谷底来客","纸上回声","雾中铃声","小镇信号","旧站台","回声书包","风的名字"]`;

    const raw = await callZhenzhenTextAPI(prompt);
    let arr = [];
    try {
        const m = String(raw || '').match(/\[[\s\S]*\]/);
        if (m) arr = JSON.parse(m[0]);
    } catch (e) { }
    if (!Array.isArray(arr)) arr = [];
    for (const c of arr) {
        const t = _normalizeComicTitleHeuristic(c);
        if (t) return t;
    }
    return '';
}

async function ensureSmartComicTitle(task, storyAnalysis) {
    if (!task || !storyAnalysis) return;

    // ✅ 只要执行到这里，就保证最终一定落到“短书名”（不允许几十字剧情当标题）
    let shortTitle = '';

    // 0) 用户手填“书名”优先，但必须像书名（否则视为用户输入的是剧情，不当标题）
    const userTitleRaw = String(task.userInputTitle || '').trim();
    const userTitle = _normalizeComicTitleHeuristic(userTitleRaw);
    if (userTitle) {
        shortTitle = userTitle;
    }

    // 1) ✅ 新方式：直接基于“文章整体内容/分镜摘要”生成书名（不依赖开头/不依赖storyAnalysis.title）
    if (!shortTitle) {
        const pagesDigest = Array.isArray(storyAnalysis.pages)
            ? storyAnalysis.pages.slice(0, 16).map(p => {
                const d = (p.descriptionZh || p.description || '').toString().trim();
                const scenes = Array.isArray(p.scenes) ? p.scenes.map(s => (s.action || s.dialogue || '').toString().trim()).filter(Boolean).slice(0, 2).join('；') : '';
                return `第${p.pageNumber || ''}页：${d}${scenes ? `（${scenes}）` : ''}`;
            }).join('\n')
            : '';
        const basis = [
            storyAnalysis.summaryZh || storyAnalysis.summary || '',
            pagesDigest,
            storyAnalysis.expandedScript || task.expandedScript || task.story || ''
        ].filter(Boolean).join('\n\n');
        try {
            shortTitle = await _generateComicBookTitleByStory(basis);
        } catch (e) {
            // ignore
        }
    }

    // 2) 兜底：如果分析给了候选（且符合书名），可用作备用
    if (!shortTitle) {
        const candidates = Array.isArray(storyAnalysis.titleCandidates) ? storyAnalysis.titleCandidates : [];
        for (const c of candidates) {
            const t = _normalizeComicTitleHeuristic(c);
            if (t) { shortTitle = t; break; }
        }
    }

    // 4) 仍失败则用占位（保证不会出现长句）
    if (!shortTitle) shortTitle = '我的漫画';

    // ✅ 写回任务标题字段（全局统一）
    task.analyzedTitle = shortTitle;
    task.displayTitle = shortTitle;
    task.theme = shortTitle;

    // ✅ 强制把 storyAnalysis.title 也同步为“书名”（避免任何地方显示长句标题）
    try {
        if (!storyAnalysis.rawTitle) storyAnalysis.rawTitle = storyAnalysis.title;
        storyAnalysis.title = shortTitle;
        storyAnalysis.titleShort = shortTitle;
    } catch (e) { }

    try { saveIdeasToHistory(); } catch (e) { }
}

// ==================== 漫画“文字质量”策略 ====================
// 默认 modelscope：只生成无文字（overlay）
// embedded（图内文字）：自动切到 gemini-flash-4k
function resolveComicTextPolicy(requestedImageModel = 'modelscope', requestedDialogMode = 'overlay') {
    let imageModel = requestedImageModel || 'modelscope';
    let dialogMode = requestedDialogMode || 'overlay';

    if (dialogMode === 'embedded') {
        // 图内文字：强制用 Gemini Flash 4K
        if (imageModel === 'modelscope') imageModel = 'gemini-flash-4k';
    } else {
        // 标准模型：只出无文字
        if (imageModel === 'modelscope') dialogMode = 'overlay';
    }

    return { imageModel, dialogMode };
}

/**
 * ✍️ 检查从 AI写作 或 提示词工坊 页面传递过来的内容
 * 如果有，自动填充到快速输入框并设置相应的模式
 */
function checkWritingToGeneration() {
    try {
        console.log('✍️ [写作转生成] 开始检查...');
        console.log('✍️ [写作转生成] URL:', window.location.href);

        // 1. 检查 URL 参数
        const urlParams = new URLSearchParams(window.location.search);
        const fromWriting = urlParams.get('from_writing');
        const fromKnolling = urlParams.get('from_knolling');
        const isBatch = urlParams.get('batch') === '1';
        console.log('✍️ [写作转生成] from_writing参数:', fromWriting, 'from_knolling:', fromKnolling, 'batch:', isBatch);

        // 🔧 修复：也检查 localStorage 是否有数据（即使 URL 参数丢失）
        const transferDataStr = localStorage.getItem('writing_to_generation');
        console.log('✍️ [写作转生成] localStorage数据:', transferDataStr ? '存在' : '不存在');

        // 如果 URL 参数不存在且 localStorage 也没数据，直接返回
        if (fromWriting !== '1' && fromKnolling !== '1' && !transferDataStr) {
            console.log('✍️ [写作转生成] 没有传递数据，跳过');
            return;
        }

        // 2. 从 localStorage 读取传递的数据
        if (!transferDataStr) {
            console.warn('[写作转生成] URL参数存在但localStorage数据丢失');
            return;
        }

        const transferData = JSON.parse(transferDataStr);
        const { content, target, mode, timestamp, from, prompts, batchCount } = transferData;

        console.log(`✍️ [写作转生成] 解析数据: target=${target}, mode=${mode}, from=${from}, timestamp=${timestamp}, content长度=${content?.length || 0}, prompts数量=${prompts?.length || 0}`);

        // 3. 检查数据是否过期（超过10分钟视为过期，放宽时间）
        if (Date.now() - timestamp > 10 * 60 * 1000) {
            console.warn('[写作转生成] 数据已过期');
            localStorage.removeItem('writing_to_generation');
            return;
        }

        console.log(`✍️ [写作转生成] 数据有效，开始处理...`);

        // 4. 切换产品类型（视频/漫画）
        if (typeof window.switchProductType === 'function') {
            window.switchProductType(target || 'video');
        }

        // 5. 设置操作模式（全自动/半自动/手动）
        const modeRadio = document.querySelector(`input[name="autoMode"][value="${mode || 'full-auto'}"]`);
        if (modeRadio) {
            modeRadio.checked = true;
            if (typeof window.onModeChange === 'function') {
                window.onModeChange(mode || 'full-auto');
            }
        }

        // 🔧 修复：处理从knolling传来的批量提示词
        const isFromKnolling = from === 'knolling' || fromKnolling === '1';
        if (isFromKnolling && prompts && prompts.length > 0) {
            console.log(`📝 [工坊转视频] 检测到 ${prompts.length} 个提示词，批量创建视频任务...`);
            
            // 6. 批量创建视频任务
            const quickInput = document.getElementById('quickIdeaInput');
            if (quickInput) {
                quickInput.value = prompts.join('\n---\n');
            }

            // 7. 清除 localStorage 数据（避免重复处理）
            localStorage.removeItem('writing_to_generation');

            // 8. 清除 URL 参数（避免刷新后重复处理）
            try {
                const cleanUrl = window.location.pathname;
                window.history.replaceState({}, '', cleanUrl);
            } catch (e) { }

            // 9. 显示提示并自动创建任务
            setTimeout(() => {
                const confirmMsg = `📝 提示词工坊导入！\n\n` +
                    `🎬 目标: AI视频\n` +
                    `📊 数量: ${prompts.length} 个提示词\n\n` +
                    `点击"确定"立即开始生成\n点击"取消"可先编辑内容`;

                if (confirm(confirmMsg)) {
                    // 批量创建视频任务
                    (async () => {
                        for (let i = 0; i < prompts.length; i++) {
                            const prompt = prompts[i];
                            console.log(`🎬 [工坊转视频] 创建任务 ${i + 1}/${prompts.length}: ${prompt.substring(0, 50)}...`);
                            await batchCreateVideoTasks(1, prompt, { 
                                autoRun: true, 
                                videoModel: 'sora-2',
                                connectTasks: false 
                            });
                            // 每个任务间隔500ms避免拥挤
                            if (i < prompts.length - 1) {
                                await new Promise(r => setTimeout(r, 500));
                            }
                        }
                        console.log(`✅ [工坊转视频] 已创建 ${prompts.length} 个视频任务`);
                    })();
                }
            }, 500);
            return;
        }

        // 6. 填充写作内容到快速输入框（非批量模式）
        const quickInput = document.getElementById('quickIdeaInput');
        console.log('✍️ [写作转生成] 快速输入框:', quickInput ? '找到' : '未找到');
        if (quickInput && content) {
            quickInput.value = content;
            quickInput.focus();
            console.log('✍️ [写作转生成] 已填充内容到输入框');
        }

        // 7. 清除 localStorage 数据（避免重复处理）
        localStorage.removeItem('writing_to_generation');

        // 8. 清除 URL 参数（避免刷新后重复处理）
        try {
            const cleanUrl = window.location.pathname;
            window.history.replaceState({}, '', cleanUrl);
        } catch (e) { }

        // 9. 显示提示
        const targetLabel = (target || 'video') === 'video' ? 'AI视频' : 'AI漫画';
        const modeLabels = {
            'full-auto': '全自动',
            'semi-auto': '半自动',
            'manual': '手动'
        };
        const modeLabel = modeLabels[mode] || mode || '全自动';

        // 10. 弹出确认提示
        setTimeout(() => {
            const confirmMsg = `✍️ 写作内容已导入！\n\n` +
                `🎬 目标: ${targetLabel}\n` +
                `⚙️ 模式: ${modeLabel}\n` +
                `📝 内容长度: ${content?.length || 0}字\n\n` +
                `点击"确定"立即开始生成\n点击"取消"可先编辑内容`;

            if (confirm(confirmMsg)) {
                // 用户确认，自动添加任务并开始
                if (typeof quickAddIdea === 'function') {
                    quickAddIdea({ automationLevelOverride: mode || 'full-auto' }).then(() => {
                        // 如果是全自动模式，自动开始生成
                        if ((mode || 'full-auto') === 'full-auto' && typeof startBatchGeneration === 'function') {
                            setTimeout(() => startBatchGeneration(), 500);
                        }
                    }).catch(e => {
                        console.error('[写作转生成] 添加任务失败:', e);
                    });
                }
            }
        }, 500);

    } catch (e) {
        console.error('[写作转生成] 处理失败:', e);
    }
}

// 导出到 window 供外部调用
window.checkWritingToGeneration = checkWritingToGeneration;

// ==================== 🧩 Skill 技能系统集成 ====================

/**
 * 渲染 Skill 历史记录
 */
function renderSkillHistory() {
    const container = document.getElementById('skillHistoryList');
    if (!container) return;

    if (typeof SkillManager === 'undefined') {
        container.innerHTML = '<div class="skill-empty-state"><div class="skill-empty-icon">📜</div><div class="skill-empty-text">技能系统还没有加载</div></div>';
        return;
    }

    const history = SkillManager.getHistory();
    if (!history || history.length === 0) {
        container.innerHTML = '<div class="skill-empty-state"><div class="skill-empty-icon">📜</div><div class="skill-empty-text">还没有执行过任何技能</div></div>';
        return;
    }

    // 最多显示最近 10 条
    const recentHistory = history.slice(-10).reverse();

    container.innerHTML = recentHistory.map(item => {
        const skill = SkillManager.getById(item.skillId);
        const icon = item.skillIcon || skill?.icon || '🧩';
        const name = item.skillName || skill?.name || item.skillId;
        const statusClass = item.status || 'completed';
        const statusLabels = {
            'completed': '完成',
            'failed': '失败',
            'cancelled': '已取消'
        };
        const statusLabel = statusLabels[statusClass] || item.status;
        const time = item.timestamp ? new Date(item.timestamp).toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';

        return `
            <div class="skill-history-item">
                <span class="skill-history-icon">${icon}</span>
                <span class="skill-history-name" title="${name}">${name}</span>
                <span class="skill-history-status ${statusClass}">${statusLabel}</span>
                <span style="font-size:10px;color:#666;">${time}</span>
            </div>
        `;
    }).join('');
}

// 暴露给全局
window.renderSkillHistory = renderSkillHistory;

// ==================== 🧩 桌面版技能执行管理器 ====================

/**
 * 更新技能Tab上的活跃任务数 Badge
 */
function _updateSkillTabBadge() {
    const badge = document.getElementById('skillTabBadge');
    if (!badge) return;
    if (typeof SkillManager === 'undefined') { badge.style.display = 'none'; return; }
    const count = SkillManager.getActiveCount();
    if (count > 0) {
        badge.textContent = count;
        badge.style.display = 'inline';
    } else {
        badge.style.display = 'none';
    }
}

/**
 * 渲染技能执行管理器浮窗内容
 */
function _renderSkillExecManager() {
    const manager = document.getElementById('skillExecManager');
    const list = document.getElementById('skillExecList');
    if (!manager || !list) return;
    if (typeof SkillManager === 'undefined') { manager.style.display = 'none'; return; }

    const execs = SkillManager.getActiveExecutions();
    if (execs.length === 0) {
        manager.style.display = 'none';
        return;
    }

    manager.style.display = 'block';
    list.innerHTML = execs.map(exec => {
        const pct = Math.round(exec.progress || 0);
        const elapsed = Math.round((Date.now() - exec.startTime) / 1000);
        const elapsedStr = elapsed >= 60 ? `${Math.floor(elapsed / 60)}m${elapsed % 60}s` : `${elapsed}s`;
        const stepText = exec.currentStep || '准备中';
        return `
            <div style="padding:8px 0; border-bottom:1px solid rgba(255,255,255,0.06);">
                <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
                    <span style="font-size:13px; color:#eee;">${exec.skillIcon || '🧩'} ${exec.skillName || exec.skillId}</span>
                    <button onclick="SkillManager.cancel('${exec.id}')" style="background:none; border:none; color:#f87171; font-size:11px; cursor:pointer; padding:2px 6px;">✕</button>
                </div>
                <div style="font-size:11px; color:#888; margin-bottom:4px;">${stepText} · ${elapsedStr}</div>
                <div style="height:4px; background:#333; border-radius:2px; overflow:hidden;">
                    <div style="height:100%; width:${pct}%; background:linear-gradient(90deg,#fbbf24,#f59e0b); border-radius:2px; transition:width 0.3s;"></div>
                </div>
            </div>
        `;
    }).join('');
}

/**
 * 初始化技能执行管理器事件监听
 */
function _initSkillExecManagerEvents() {
    if (typeof SkillManager === 'undefined') return;

    const refresh = () => {
        _updateSkillTabBadge();
        _renderSkillExecManager();
    };

    SkillManager.on('executionStarted', refresh);
    SkillManager.on('executionProgress', refresh);
    SkillManager.on('executionCompleted', () => { refresh(); renderSkillHistory(); });
    SkillManager.on('executionFailed', () => { refresh(); renderSkillHistory(); });

    // 初始刷新
    refresh();
    console.log('✅ [SkillExecManager] 桌面端执行管理器已初始化');
}

// 页面加载后初始化
if (document.readyState === 'complete' || document.readyState === 'interactive') {
    setTimeout(_initSkillExecManagerEvents, 500);
} else {
    window.addEventListener('DOMContentLoaded', () => setTimeout(_initSkillExecManagerEvents, 500));
}

/**
 * 切换产品类型（视频/漫画/技能）
 * @param {string} type - 'video' | 'comic' | 'writing' | 'skills'
 */
window.switchProductType = function (type) {
    currentProductType = type;

    // 更新Tab样式
    document.querySelectorAll('.product-tab').forEach(tab => {
        tab.classList.toggle('active', tab.dataset.type === type);
    });

    // 更新body class
    document.body.classList.remove('video-mode', 'comic-mode', 'writing-mode', 'skills-mode');
    document.body.classList.add(type + '-mode');

    // 🧩 Skills 模式：显示技能面板，隐藏其他
    const skillsPanel = document.getElementById('skillsPanel');
    const ideasList = document.getElementById('ideasList');
    const writingPanel = document.getElementById('writingProjectsPanel');
    const quickInputSection = document.querySelector('.quick-input-section');
    const modeToggle = document.querySelector('.mode-toggle');
    const taskLimit = document.querySelector('.task-limit-control');
    const startBtn = document.getElementById('startBatchBtn');

    if (type === 'skills') {
        // 切换到技能模式
        if (skillsPanel) skillsPanel.style.display = 'block';
        if (ideasList) ideasList.style.display = 'none';
        if (writingPanel) writingPanel.style.display = 'none';
        if (quickInputSection) quickInputSection.style.display = 'none';
        if (modeToggle) modeToggle.style.display = 'none';
        if (taskLimit) taskLimit.style.display = 'none';
        if (startBtn) startBtn.style.display = 'none';

        // 渲染技能列表
        if (typeof SkillUI !== 'undefined' && SkillUI.renderSkillList) {
            SkillUI.renderSkillList();
        }
        // 渲染历史记录
        renderSkillHistory();

        console.log('[产品类型] 切换到: 🧩技能');
        return;
    }

    // 非 skills 模式：隐藏技能面板
    if (skillsPanel) skillsPanel.style.display = 'none';

    // 更新侧边栏选项
    updateSidebarForProductType(type);

    // 更新快速输入区域
    updateQuickInputForProductType(type);

    console.log(`[产品类型] 切换到: ${type === 'video' ? 'AI视频' : (type === 'comic' ? 'AI漫画' : 'AI写作')}`);
};

