// 📷 视频参考图临时存储
window._videoRefImageDataUrl = null;
window._videoRefImageList = [];  // 🆕 多图列表

// 📷 处理快速入口的角色图上传（index.html 左侧面板）
window.handleQuickRefImageUpload = function (input) {
    const file = input?.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
        window._videoRefImageDataUrl = String(reader.result || '');
        const preview = document.getElementById('quickRefImagePreview');
        const text = document.getElementById('quickRefImageText');
        if (preview) {
            preview.src = window._videoRefImageDataUrl;
            preview.style.display = 'block';
        }
        if (text) text.textContent = file.name || '已上传';
        input.value = '';
        console.log('📷 [快速入口] 角色参考图已上传:', file.name);
    };
    reader.onerror = () => {
        alert('读取图片失败，请重试');
        input.value = '';
    };
    reader.readAsDataURL(file);
};

// 🆕 处理视频参考图上传（支持多图）
window.handleVideoRefImageUpload = async function (input) {
    if (!input.files || input.files.length === 0) return;

    const files = Array.from(input.files);
    const nameEl = document.getElementById('videoRefImageName');
    const clearBtn = document.getElementById('videoRefImageClear');
    const previewContainer = document.getElementById('videoRefImagePreviewContainer');
    const mergeOptions = document.getElementById('videoRefMergeOptions');
    const imageCountEl = document.getElementById('videoRefImageCount');

    console.log('📷 [视频] 上传图片数量:', files.length);

    // 读取所有图片
    for (const file of files) {
        try {
            const dataUrl = await new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = () => resolve(reader.result);
                reader.onerror = reject;
                reader.readAsDataURL(file);
            });
            window._videoRefImageList.push(dataUrl);
        } catch (e) {
            console.warn('📷 [视频] 图片读取失败:', file.name);
        }
    }

    const total = window._videoRefImageList.length;

    if (total === 1) {
        // 单图模式
        window._videoRefImageDataUrl = window._videoRefImageList[0];
        if (nameEl) nameEl.textContent = files[0]?.name || '1 张图片';
        if (clearBtn) clearBtn.style.display = 'inline-block';
        if (previewContainer) previewContainer.style.display = 'none';
        if (mergeOptions) mergeOptions.style.display = 'none';
    } else if (total > 1) {
        // 多图模式
        window._videoRefImageDataUrl = '';  // 清空单图，生成时合并
        if (nameEl) nameEl.textContent = `已选择 ${total} 张图片`;
        if (clearBtn) clearBtn.style.display = 'inline-block';
        if (imageCountEl) imageCountEl.textContent = total;
        if (mergeOptions) mergeOptions.style.display = 'block';

        // 渲染预览缩略图
        if (previewContainer) {
            previewContainer.style.display = 'flex';
            previewContainer.innerHTML = window._videoRefImageList.map((data, idx) => `
                <div style="position:relative; display:inline-block;">
                    <img src="${data}" style="width:48px; height:48px; object-fit:cover; border-radius:4px; border:1px solid #333;">
                    <button onclick="window.removeVideoRefImage(${idx}); event.stopPropagation();" 
                        style="position:absolute; top:-6px; right:-6px; width:16px; height:16px; background:#f87171; border:none; border-radius:50%; color:#fff; font-size:10px; cursor:pointer; line-height:1;">×</button>
                </div>
            `).join('');
        }
    }

    input.value = '';
    console.log('📷 [视频] 参考图列表更新，当前数量:', total);
};

// 🆕 移除单张视频参考图
window.removeVideoRefImage = function (index) {
    window._videoRefImageList.splice(index, 1);

    const nameEl = document.getElementById('videoRefImageName');
    const clearBtn = document.getElementById('videoRefImageClear');
    const previewContainer = document.getElementById('videoRefImagePreviewContainer');
    const mergeOptions = document.getElementById('videoRefMergeOptions');
    const imageCountEl = document.getElementById('videoRefImageCount');

    const total = window._videoRefImageList.length;

    if (total === 0) {
        window.clearVideoRefImages();
    } else if (total === 1) {
        // 切换回单图模式
        window._videoRefImageDataUrl = window._videoRefImageList[0];
        if (nameEl) nameEl.textContent = '1 张图片';
        if (previewContainer) previewContainer.style.display = 'none';
        if (mergeOptions) mergeOptions.style.display = 'none';
    } else {
        // 更新多图预览
        if (nameEl) nameEl.textContent = `已选择 ${total} 张图片`;
        if (imageCountEl) imageCountEl.textContent = total;
        if (previewContainer) {
            previewContainer.innerHTML = window._videoRefImageList.map((data, idx) => `
                <div style="position:relative; display:inline-block;">
                    <img src="${data}" style="width:48px; height:48px; object-fit:cover; border-radius:4px; border:1px solid #333;">
                    <button onclick="window.removeVideoRefImage(${idx}); event.stopPropagation();" 
                        style="position:absolute; top:-6px; right:-6px; width:16px; height:16px; background:#f87171; border:none; border-radius:50%; color:#fff; font-size:10px; cursor:pointer; line-height:1;">×</button>
                </div>
            `).join('');
        }
    }
};

// 🆕 清空所有视频参考图
window.clearVideoRefImages = function () {
    window._videoRefImageDataUrl = null;
    window._videoRefImageList = [];

    const nameEl = document.getElementById('videoRefImageName');
    const clearBtn = document.getElementById('videoRefImageClear');
    const previewContainer = document.getElementById('videoRefImagePreviewContainer');
    const mergeOptions = document.getElementById('videoRefMergeOptions');

    if (nameEl) nameEl.textContent = '';
    if (clearBtn) clearBtn.style.display = 'none';
    if (previewContainer) {
        previewContainer.innerHTML = '';
        previewContainer.style.display = 'none';
    }
    if (mergeOptions) mergeOptions.style.display = 'none';

    console.log('📷 [视频] 参考图已清空');
};

// 兼容旧版函数名
window.clearVideoRefImage = window.clearVideoRefImages;

