async function writingTaskRefreshChapters(ideaId) {
    const idea = __rrGetWritingIdea(ideaId);
    if (!idea) return;
    const pid = String(idea.writing.projectId || '').trim();
    if (!pid) return;
    // 🔧 验证UUID格式
    if (!__isValidUUID(pid)) {
        console.warn('⚠️ writingTaskRefreshChapters: 无效的projectId格式:', pid);
        return;
    }

    const data = await writingApi('writingListChapters', { projectId: pid });
    idea.writing.chapters = Array.isArray(data.chapters) ? data.chapters : [];

    const cur = String(idea.writing.currentChapterId || '').trim();
    const exists = idea.writing.chapters.some(c => String(c?.id || '') === cur);
    if (!exists) {
        idea.writing.currentChapterId = String(idea.writing.chapters[0]?.id || '');
    }

    renderCanvas();
    saveIdeasToHistory();

    if (idea.writing.currentChapterId) {
        await writingTaskSelectChapter(ideaId, idea.writing.currentChapterId);
    }
}

async function writingTaskSelectChapter(ideaId, chapterId) {
    const idea = __rrGetWritingIdea(ideaId);
    if (!idea) return;
    const cid = String(chapterId || '').trim();
    if (!cid) return;
    // 🔧 验证UUID格式
    if (!__isValidUUID(cid)) {
        console.warn('⚠️ writingTaskSelectChapter: 无效的chapterId格式:', cid);
        return;
    }

    idea.writing.status = '加载章节中...';
    renderCanvas();
    saveIdeasToHistory();

    try {
        const data = await writingApi('writingGetChapter', { chapterId: cid });
        const ch = data.chapter || null;
        if (!ch) throw new Error('章节不存在');
        idea.writing.currentChapterId = cid;
        idea.writing.currentChapterVersion = Number(ch.version || 1);
        idea.writing.chapterTitle = String(ch.title || '');
        idea.writing.chapterContent = String(ch.content || '');
        idea.writing.status = `已打开章节 v${idea.writing.currentChapterVersion}`;
        renderCanvas();
        saveIdeasToHistory();
    } catch (e) {
        idea.writing.status = String(e?.message || e);
        renderCanvas();
        saveIdeasToHistory();
        alert('❌ 打开章节失败：' + (e?.message || e));
    }
}

async function writingTaskCreateChapter(ideaId) {
    const idea = __rrGetWritingIdea(ideaId);
    if (!idea) return;
    const pid = String(idea.writing.projectId || '').trim();
    if (!pid) {
        alert('请先载入项目');
        return;
    }
    // 🔧 验证UUID格式
    if (!__isValidUUID(pid)) {
        alert('❌ project_id 格式无效，请先载入有效的项目');
        return;
    }
    const title = prompt('章节标题：', '新章节');
    if (title === null) return;

    idea.writing.status = '创建章节中...';
    renderCanvas();
    saveIdeasToHistory();
    try {
        const data = await writingApi('writingCreateChapter', { projectId: pid, title: String(title || '') });
        await writingTaskRefreshChapters(ideaId);
        const cid = data?.chapter?.id;
        if (cid) await writingTaskSelectChapter(ideaId, cid);
    } catch (e) {
        idea.writing.status = String(e?.message || e);
        renderCanvas();
        saveIdeasToHistory();
        alert('❌ 创建章节失败：' + (e?.message || e));
    }
}

async function writingTaskSaveChapter(ideaId) {
    const idea = __rrGetWritingIdea(ideaId);
    if (!idea) return;
    const cid = String(idea.writing.currentChapterId || '').trim();
    if (!cid) {
        alert('请先选择章节');
        return;
    }
    // 🔧 验证UUID格式
    if (!__isValidUUID(cid)) {
        alert('❌ 章节ID格式无效，请重新选择章节');
        return;
    }

    idea.writing.status = '保存中...';
    renderCanvas();
    saveIdeasToHistory();

    try {
        const patch = {
            title: String(idea.writing.chapterTitle || ''),
            content: String(idea.writing.chapterContent || '')
        };
        const data = await writingApi('writingUpdateChapter', {
            chapterId: cid,
            expectedVersion: idea.writing.currentChapterVersion,
            patch,
            createSnapshot: true
        });
        const ch = data.chapter;
        idea.writing.currentChapterVersion = Number(ch?.version || (idea.writing.currentChapterVersion || 1));
        idea.writing.status = `已保存 v${idea.writing.currentChapterVersion}`;
        await writingTaskRefreshChapters(ideaId);
    } catch (e) {
        if (e && e.status === 409 && e.data && e.data.error === 'WRITING_CONFLICT') {
            idea.writing.status = '版本冲突';
            renderCanvas();
            saveIdeasToHistory();
            alert('⚠️ 版本冲突：有人已更新此章节。请先点“刷新”，合并后再保存。');
            return;
        }
        idea.writing.status = String(e?.message || e);
        renderCanvas();
        saveIdeasToHistory();
        alert('❌ 保存失败：' + (e?.message || e));
    }
}

async function writingTaskRunAI(ideaId, mode) {
    const idea = __rrGetWritingIdea(ideaId);
    if (!idea) return;
    try {
        if (typeof NVAuth === 'undefined') throw new Error('未登录');
        const u = await NVAuth.getCurrentUser();
        if (!u) throw new Error('未登录');

        const title = String(idea.writing.chapterTitle || '').trim();
        const content = String(idea.writing.chapterContent || '');
        idea.writing.status = 'AI 生成中...';
        renderCanvas();
        saveIdeasToHistory();

        const instructionMap = {
            continue: '请基于已有内容继续写下去，保持风格一致，直接输出正文，不要解释。',
            polish: '请对内容进行润色与改写：更自然、更有画面感、逻辑更顺，尽量不改变剧情，直接输出润色后的正文，不要解释。',
            expand: '请对内容进行扩写：增加细节、动作、环境与对话，保持原剧情走向，直接输出扩写后的正文，不要解释。'
        };
        const instruction = instructionMap[String(mode)] || instructionMap.continue;
        const userHint = prompt('可选：补充你的要求（留空直接执行）', '');
        const sys = '你是中文长篇小说/剧本写作助手。输出必须是可直接粘贴的正文内容。';
        const base = (content && content.trim()) ? content.trim() : `标题：${title || '未命名'}\n\n（目前无正文，请从开头写起）`;
        const msg = [
            { role: 'system', content: sys },
            {
                role: 'user', content: `${instruction}

${userHint ? ('附加要求：' + userHint + '\n\n') : ''}当前内容：\n${base}`
            }
        ];

        const out = await callWriterLLM(msg);
        if (!out) throw new Error('AI 未返回内容');

        if (String(mode) === 'continue') {
            idea.writing.chapterContent = (content ? (content.replace(/\s+$/, '') + '\n\n') : '') + out;
        } else {
            const ok = confirm('AI 已生成完成，是否覆盖当前内容？\n\n确定=覆盖；取消=追加到末尾');
            if (ok) idea.writing.chapterContent = out;
            else idea.writing.chapterContent = (content ? (content.replace(/\s+$/, '') + '\n\n') : '') + out;
        }

        idea.writing.status = 'AI 已生成（未保存）';
        renderCanvas();
        saveIdeasToHistory();
    } catch (e) {
        idea.writing.status = String(e?.message || e);
        renderCanvas();
        saveIdeasToHistory();
        alert('❌ AI 写作失败：' + (e?.message || e));
    }
}

function updateWritingTaskField(ideaId, field, value) {
    const idea = __rrGetWritingIdea(ideaId);
    if (!idea) return;
    idea.writing[field] = String(value ?? '');
    try {
        if (!window.__rrWritingTaskSaveTimers) window.__rrWritingTaskSaveTimers = new Map();
        const m = window.__rrWritingTaskSaveTimers;
        const prev = m.get(String(ideaId));
        if (prev) clearTimeout(prev);
        m.set(String(ideaId), setTimeout(() => {
            try { saveIdeasToHistory(); } catch (e) { }
        }, 450));
    } catch (e) { }
}

