async function refreshWritingChapters() {
    const pid = WRITING_STATE.currentProjectId;
    if (!pid) return;
    // 🔧 验证UUID格式
    if (!__isValidUUID(pid)) return;
    const data = await writingApi('writingListChapters', { projectId: pid });
    WRITING_STATE.chapters = Array.isArray(data.chapters) ? data.chapters : [];
    renderWritingChaptersList();
    if (!WRITING_STATE.currentChapterId && WRITING_STATE.chapters.length > 0) {
        await selectWritingChapter(String(WRITING_STATE.chapters[0].id));
    }
}

function renderWritingChaptersList() {
    const list = document.getElementById('writingChaptersList');
    if (!list) return;
    const chapters = Array.isArray(WRITING_STATE.chapters) ? WRITING_STATE.chapters : [];
    if (chapters.length === 0) {
        list.innerHTML = `<div style="padding:10px; color:#888; font-size:12px;">暂无章节</div>`;
        return;
    }
    list.innerHTML = chapters.map((c, idx) => {
        const cid = escapeHtml(String(c.id || ''));
        const t = escapeHtml(String(c.title || `Chapter ${idx + 1}`));
        const active = String(WRITING_STATE.currentChapterId || '') === String(c.id) ? 'border:1px solid var(--accent-gold);' : 'border:1px solid rgba(255,255,255,0.08);';
        return `
            <div style="padding:10px; border-radius:12px; background:rgba(0,0,0,0.25); margin-bottom:10px; cursor:pointer; ${active}" onclick="selectWritingChapter('${cid}')">
                <div style="font-weight:800; color:#fff; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${t}</div>
                <div style="font-size:11px; color:#666; margin-top:4px;">v${Number(c.version || 1)}</div>
            </div>
        `;
    }).join('');
}

async function selectWritingChapter(chapterId) {
    const cid = String(chapterId || '').trim();
    if (!cid) return;
    // 🔧 验证UUID格式
    if (!__isValidUUID(cid)) {
        alert('❌ 章节ID格式无效');
        return;
    }
    const status = document.getElementById('writingStatusBar');
    if (status) status.textContent = '加载章节...';
    try {
        const data = await writingApi('writingGetChapter', { chapterId: cid });
        const ch = data.chapter || null;
        if (!ch) throw new Error('章节不存在');
        WRITING_STATE.currentChapterId = cid;
        WRITING_STATE.currentChapterVersion = Number(ch.version || 1);
        const titleInput = document.getElementById('writingChapterTitleInput');
        const contentInput = document.getElementById('writingChapterContentInput');
        if (titleInput) titleInput.value = String(ch.title || '');
        if (contentInput) contentInput.value = String(ch.content || '');
        renderWritingChaptersList();
        if (status) status.textContent = `已打开章节 v${WRITING_STATE.currentChapterVersion}`;
    } catch (e) {
        if (status) status.textContent = String(e && e.message ? e.message : e);
        alert('❌ 打开章节失败：' + (e && e.message ? e.message : e));
    }
}

async function createWritingProject() {
    try {
        const title = prompt('写作项目名称：', '我的写作项目');
        if (title === null) return;
        const data = await writingApi('writingCreateProject', { title });
        await refreshWritingProjects();
        const pid = data?.project?.id;
        if (pid) await openWritingProject(pid);
    } catch (e) {
        alert('❌ 创建项目失败：' + (e && e.message ? e.message : e));
    }
}

/**
 * 左侧写作面板 - AI写作操作（续写/润色/扩写）
 * @param {string} action - 'continue' | 'polish' | 'expand'
 */
async function sidebarWritingAction(action) {
    const contentEl = document.getElementById('sidebarWritingContent');
    const topicEl = document.getElementById('sidebarWritingTopic');
    const genreEl = document.getElementById('sidebarWritingGenre');

    if (!contentEl) return alert('找不到输入框');
    const content = contentEl.value.trim();
    if (!content) return alert('请先输入写作内容');

    const topic = topicEl?.value?.trim() || '';
    const genre = genreEl?.value?.trim() || '';

    const actionLabels = { continue: '续写', polish: '润色', expand: '扩写' };
    const label = actionLabels[action] || action;

    try {
        contentEl.disabled = true;
        contentEl.placeholder = `正在${label}中，请稍候...`;

        const systemPrompt = `你是一位专业的${genre || '小说'}作家，擅长${topic || '各类题材'}的创作。`;
        let userPrompt = '';

        if (action === 'continue') {
            userPrompt = `请根据以下内容继续创作，保持风格一致，自然衔接：\n\n${content}`;
        } else if (action === 'polish') {
            userPrompt = `请对以下内容进行润色优化，提升文字表达，但保持原意不变：\n\n${content}`;
        } else if (action === 'expand') {
            userPrompt = `请对以下内容进行扩写，增加细节描写和情节展开：\n\n${content}`;
        }

        const result = await writingApi('writingLLM', {
            messages: [
                { role: 'system', content: systemPrompt },
                { role: 'user', content: userPrompt }
            ],
            max_tokens: 2000
        });

        const aiContent = result?.content || result?.choices?.[0]?.message?.content || '';
        if (aiContent) {
            if (action === 'continue') {
                contentEl.value = content + '\n\n' + aiContent;
            } else {
                contentEl.value = aiContent;
            }
        } else {
            throw new Error('AI未返回内容');
        }
    } catch (e) {
        alert(`❌ ${label}失败：` + (e?.message || e));
    } finally {
        contentEl.disabled = false;
        contentEl.placeholder = '在这里输入您的写作内容或大纲...';
    }
}

/**
 * 左侧写作面板 - 创建写作节点到画布
 */
function sidebarWritingCreateNode() {
    const topicEl = document.getElementById('sidebarWritingTopic');
    const genreEl = document.getElementById('sidebarWritingGenre');
    const chaptersEl = document.getElementById('sidebarWritingChapters');
    const wordsEl = document.getElementById('sidebarWritingWords');
    const contentEl = document.getElementById('sidebarWritingContent');

    const topic = topicEl?.value?.trim() || '';
    const genre = genreEl?.value?.trim() || '';
    const numChapters = parseInt(chaptersEl?.value) || 10;
    const wordNumber = parseInt(wordsEl?.value) || 2000;
    const content = contentEl?.value?.trim() || '';

    const title = topic || genre || '写作项目';

    // 创建写作任务
    const newIdea = {
        id: Date.now(),
        theme: title,
        type: 'writing',
        status: 'pending',
        selected: false,
        x: 100 + Math.random() * 200,
        y: 100 + Math.random() * 200,
        writing: {
            projectId: '',
            projectTitle: title,
            status: '待创建',
            chapters: [],
            currentChapterId: '',
            chapterTitle: '',
            chapterContent: content,
            novelConfig: {
                topic: topic,
                genre: genre,
                num_chapters: numChapters,
                word_number: wordNumber,
                filepath: ''
            }
        }
    };

    ideas.push(newIdea);
    saveIdeasToHistory();
    renderCanvas();

    // 清空输入
    if (contentEl) contentEl.value = '';

    console.log('✍️ 创建写作节点:', newIdea);
    alert(`✅ 已创建写作节点「${title}」\n\n请在画布上找到节点，点击"载入"按钮创建云端项目。`);
}

// ✅ 挂载到window供HTML onclick调用
window.sidebarWritingAction = sidebarWritingAction;
window.sidebarWritingCreateNode = sidebarWritingCreateNode;

/**
 * ✍️ 侧边栏写作面板 - 转换为 AI视频
 */
function sidebarWritingToVideo() {
    sidebarWritingToGeneration('video');
}

/**
 * ✍️ 侧边栏写作面板 - 转换为 AI漫画
 */
function sidebarWritingToComic() {
    sidebarWritingToGeneration('comic');
}

/**
 * ✍️ 侧边栏写作面板 - 转换为 AI视频/漫画 通用函数
 * @param {string} target - 'video' | 'comic'
 */
function sidebarWritingToGeneration(target) {
    const contentEl = document.getElementById('sidebarWritingContent');
    const content = contentEl?.value?.trim() || '';

    if (!content) {
        alert('请先在写作输入框中输入内容');
        return;
    }

    // 获取当前选中的操作模式
    const modeRadio = document.querySelector('input[name="autoMode"]:checked');
    const mode = modeRadio?.value || 'full-auto';

    const targetLabel = target === 'video' ? 'AI视频' : 'AI漫画';
    const modeLabels = {
        'full-auto': '全自动',
        'semi-auto': '半自动',
        'manual': '手动'
    };
    const modeLabel = modeLabels[mode] || mode;

    const confirmMsg = `✍️ 将写作内容转换为 ${targetLabel}\n\n` +
        `📝 内容长度: ${content.length}字\n` +
        `⚙️ 操作模式: ${modeLabel}\n\n` +
        `点击"确定"开始生成`;

    if (!confirm(confirmMsg)) return;

    // 1. 切换产品类型
    if (typeof window.switchProductType === 'function') {
        window.switchProductType(target);
    }

    // 2. 填充内容到快速输入框
    const quickInput = document.getElementById('quickIdeaInput');
    if (quickInput) {
        quickInput.value = content;
        quickInput.focus();
    }

    // 3. 添加任务并开始生成
    if (typeof quickAddIdea === 'function') {
        quickAddIdea({ automationLevelOverride: mode }).then(() => {
            // 如果是全自动模式，自动开始生成
            if (mode === 'full-auto' && typeof startBatchGeneration === 'function') {
                setTimeout(() => startBatchGeneration(), 500);
            }
        }).catch(e => {
            console.error('[写作转生成] 添加任务失败:', e);
            alert('添加任务失败: ' + (e?.message || e));
        });
    }
}

// 导出到 window
window.sidebarWritingToVideo = sidebarWritingToVideo;
window.sidebarWritingToComic = sidebarWritingToComic;
window.sidebarWritingToGeneration = sidebarWritingToGeneration;

