/**
 * ✍️ 保存写作任务设置
 * @param {number} ideaId - 任务ID
 */
function saveWritingTaskSettings(ideaId) {
    const idea = ideas.find(i => i.id === ideaId);
    if (!idea || idea.type !== 'writing') {
        alert('❌ 找不到写作任务');
        return;
    }

    const w = idea.writing || (idea.writing = {});

    // 读取输入值
    const topic = document.getElementById('writing-set-topic')?.value?.trim() || '';
    const genre = document.getElementById('writing-set-genre')?.value?.trim() || '';
    const numChapters = parseInt(document.getElementById('writing-set-chapters')?.value) || 10;
    const wordNumber = parseInt(document.getElementById('writing-set-words')?.value) || 2000;
    const filepath = document.getElementById('writing-set-filepath')?.value?.trim() || '';
    const projectTitle = document.getElementById('writing-set-title')?.value?.trim() || '';
    const projectId = document.getElementById('writing-set-projectId')?.value?.trim() || '';

    // 更新配置
    w.novelConfig = __rrNormalizeNovelConfig({
        topic,
        genre,
        num_chapters: numChapters,
        word_number: wordNumber,
        filepath
    });

    // 更新项目信息
    if (projectTitle) {
        w.projectTitle = projectTitle;
        idea.theme = projectTitle;
    }
    if (projectId) {
        w.projectId = projectId;
    }

    // 保存并渲染
    saveIdeasToHistory();
    renderCanvas();
    renderIdeasList();

    // 关闭面板
    closeAdvancedSettings();

    alert('✅ 写作任务设置已保存');
}

// ✅ 挂载写作设置面板函数到window
window.openWritingTaskSettings = openWritingTaskSettings;
window.saveWritingTaskSettings = saveWritingTaskSettings;

async function saveWritingCurrentChapter() {
    const cid = WRITING_STATE.currentChapterId;
    if (!cid) {
        alert('请先选择章节');
        return;
    }
    // 🔧 验证UUID格式
    if (!__isValidUUID(cid)) {
        alert('❌ 章节ID格式无效，请重新选择章节');
        return;
    }
    const titleInput = document.getElementById('writingChapterTitleInput');
    const contentInput = document.getElementById('writingChapterContentInput');
    const patch = {
        title: String(titleInput?.value || ''),
        content: String(contentInput?.value || '')
    };
    const status = document.getElementById('writingStatusBar');
    if (status) status.textContent = '保存中...';
    try {
        const data = await writingApi('writingUpdateChapter', {
            chapterId: cid,
            expectedVersion: WRITING_STATE.currentChapterVersion,
            patch,
            createSnapshot: true
        });
        const ch = data.chapter;
        WRITING_STATE.currentChapterVersion = Number(ch?.version || (WRITING_STATE.currentChapterVersion || 1));
        await refreshWritingChapters();
        if (status) status.textContent = `已保存 v${WRITING_STATE.currentChapterVersion}`;
    } catch (e) {
        if (e && e.status === 409 && e.data && e.data.error === 'WRITING_CONFLICT') {
            if (status) status.textContent = '版本冲突';
            alert('⚠️ 版本冲突：有人已更新此章节。请先点“刷新”，合并后再保存。');
            return;
        }
        if (status) status.textContent = String(e && e.message ? e.message : e);
        alert('❌ 保存失败：' + (e && e.message ? e.message : e));
    }
}

async function exportWriting(format) {
    try {
        const pid = WRITING_STATE.currentProjectId;
        if (!pid) throw new Error('未选择项目');
        // 🔧 验证UUID格式
        if (!__isValidUUID(pid)) throw new Error('项目ID格式无效');
        const data = await writingApi('writingExport', { projectId: pid, format: String(format || 'md') });
        const content = String(data.content || '');
        const fmt = String(data.format || format || 'md');
        const title = String(WRITING_STATE.project?.title || 'writing');
        const safeName = title.replace(/[\\/:*?"<>|]/g, '_');
        const fileName = `${safeName}.${fmt === 'txt' ? 'txt' : 'md'}`;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        a.remove();
        URL.revokeObjectURL(url);
    } catch (e) {
        alert('❌ 导出失败：' + (e && e.message ? e.message : e));
    }
}

