function __rrGetCanvasCenterWorldPoint() {
    try {
        const container = document.getElementById('taskCanvasContainer');
        const rect = container ? container.getBoundingClientRect() : null;
        const cx = rect ? (rect.left + rect.width / 2) : (window.innerWidth / 2);
        const cy = rect ? (rect.top + rect.height / 2) : (window.innerHeight / 2);
        if (typeof getCanvasWorldPointFromScreen === 'function') {
            return getCanvasWorldPointFromScreen(cx, cy);
        }
        return { x: 120, y: 120 };
    } catch (e) {
        return { x: 120, y: 120 };
    }
}

async function openWritingProjectInCanvas(projectId) {
    const pid = String(projectId || '').trim();
    if (!pid) return;

    let node = null;
    try {
        node = flowNodes.find(n => n && n.type === 'writing' && String(n.data?.projectId || '').trim() === pid);
    } catch (e) {
        node = null;
    }

    if (!node) {
        const p = __rrGetCanvasCenterWorldPoint();
        node = createWritingNodeData(p.x - 260, p.y - 220);
        node.data.projectId = pid;
        flowNodes.push(node);
        renderCanvas();
        saveIdeasToHistory();
    }

    await loadWritingNodeProject(node.id, pid);
}

window.openWritingProjectInCanvas = openWritingProjectInCanvas;

function createWritingNodeData(x, y, novelConfig = null) {
    return {
        id: 'writing_' + Date.now(),
        type: 'writing',
        x,
        y,
        width: 560,
        height: 560,
        data: {
            projectId: '',
            projectTitle: '',
            chapters: [],
            currentChapterId: '',
            currentChapterVersion: null,
            chapterTitle: '',
            chapterContent: '',
            status: '',
            novelConfig: novelConfig || { topic: '', genre: '', num_chapters: 10, word_number: 2000, filepath: '' }
        }
    };
}

function getWritingNodeHTML(node) {
    const nodeLocked = node.locked || false;
    const pid = escapeHtml(String(node.data?.projectId || ''));
    const title = escapeHtml(String(node.data?.projectTitle || ''));
    const status = escapeHtml(String(node.data?.status || ''));
    const chapters = Array.isArray(node.data?.chapters) ? node.data.chapters : [];
    const curCid = String(node.data?.currentChapterId || '');
    const chapterOptions = chapters.map((c, idx) => {
        const cid = escapeHtml(String(c?.id || ''));
        const t = escapeHtml(String(c?.title || `Chapter ${idx + 1}`));
        const v = Number(c?.version || 1);
        const sel = (String(c?.id || '') === curCid) ? 'selected' : '';
        return `<option value="${cid}" ${sel}>${t} (v${v})</option>`;
    }).join('');
    const chapterTitle = escapeHtml(String(node.data?.chapterTitle || ''));
    const chapterContent = escapeHtml(String(node.data?.chapterContent || ''));
    return `
        <div class="input-handle" onmouseup="endConnection(event, '${node.id}')" title="输入连接点"></div>
        <div class="banana-node-header">
            <span>✍️ 写作节点 ${nodeLocked ? '<span style="margin-left:4px;" title="节点已固定">🔒</span>' : ''}</span>
            <div style="display:flex;gap:4px;">
                <button class="btn-lock-node" onclick="toggleNodeLock('${node.id}')" title="${nodeLocked ? '解锁节点' : '固定节点'}" style="background:${nodeLocked ? '#ef4444' : '#3b82f6'};padding:2px 8px;border-radius:4px;color:#fff;border:none;cursor:pointer;font-size:12px;">${nodeLocked ? '🔓' : '🔒'}</button>
                <button class="btn-close-node" onclick="removeNode('${node.id}')">×</button>
            </div>
        </div>
        <div class="node-content" style="padding:10px; display:flex; flex-direction:column; gap:10px;">
            <div>
                <div style="font-size:11px; color:#888; margin-bottom:6px;">绑定写作项目 ID（可空，点击新建）</div>
                <input id="writing-node-pid-${node.id}" value="${pid}" placeholder="project_id" style="width:100%; background:#111; border:1px solid #333; color:#fff; padding:8px; border-radius:10px;" oninput="updateWritingNodeProjectId('${node.id}', this.value)" />
                <div style="display:flex; gap:8px; margin-top:10px;">
                    <button class="btn-text" onclick="loadWritingNodeProject('${node.id}')" style="flex:1; background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.12); border-radius: 10px; padding: 8px 10px; cursor: pointer;">载入</button>
                    <button class="btn-text" onclick="createWritingProjectFromNode('${node.id}')" style="flex:1; background: var(--accent-gold); color:#000; font-weight:900; border: none; border-radius: 10px; padding: 8px 10px; cursor: pointer;">新建</button>
                </div>
                <div style="margin-top:8px; font-size:11px; color:#888;">${status}</div>
            </div>

            <div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 10px;">
                <div style="font-size:12px; font-weight:900; color:#fff; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${title || '未加载项目'}</div>
                <div style="display:flex; gap:8px; margin-top:8px; flex-wrap:wrap;">
                    <select onchange="selectWritingNodeChapter('${node.id}', this.value)" onmousedown="event.stopPropagation()" style="flex:1; min-width: 180px; background:#111; border:1px solid #333; color:#fff; padding:8px; border-radius:10px;">
                        ${chapterOptions || '<option value="">暂无章节</option>'}
                    </select>
                    <button class="btn-text" onclick="createWritingChapterForNode('${node.id}')" style="background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.12); border-radius: 10px; padding: 8px 10px; cursor: pointer;">➕章节</button>
                    <button class="btn-text" onclick="refreshWritingNodeChapters('${node.id}')" style="background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.12); border-radius: 10px; padding: 8px 10px; cursor: pointer;">刷新</button>
                </div>

                <input value="${chapterTitle}" placeholder="章节标题" oninput="updateWritingNodeField('${node.id}','chapterTitle', this.value)" style="margin-top:10px; width:100%; background:#0b0b0b; color:#fff; border: 1px solid #333; padding: 10px; border-radius: 10px;" />
                <textarea placeholder="在这里写作..." oninput="updateWritingNodeField('${node.id}','chapterContent', this.value)" style="margin-top:10px; width:100%; height: 180px; background:#0b0b0b; color:#fff; border: 1px solid #333; padding: 12px; border-radius: 10px; resize: vertical;">${chapterContent}</textarea>

                <div style="display:flex; gap:8px; flex-wrap:wrap; margin-top:10px;">
                    <button class="btn-text" onclick="runWritingAIForNode('${node.id}','continue')" style="background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.12); border-radius: 10px; padding: 8px 10px; cursor: pointer;">AI续写</button>
                    <button class="btn-text" onclick="runWritingAIForNode('${node.id}','polish')" style="background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.12); border-radius: 10px; padding: 8px 10px; cursor: pointer;">AI润色</button>
                    <button class="btn-text" onclick="runWritingAIForNode('${node.id}','expand')" style="background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.12); border-radius: 10px; padding: 8px 10px; cursor: pointer;">AI扩写</button>
                    <button class="btn-text" onclick="saveWritingNodeChapter('${node.id}')" style="margin-left:auto; background: var(--accent-gold); color:#000; font-weight:900; border: none; border-radius: 10px; padding: 8px 14px; cursor: pointer;">保存</button>
                </div>
            </div>
        </div>
        <div class="output-handle" onmousedown="startConnection(event, '${node.id}')" ontouchstart="startConnectionTouch(event, '${node.id}')" title="输出连接点"></div>
    `;
}

function initWritingNodeUI(node) {
    const nodeEl = document.getElementById(`node-${node.id}`);
    if (!nodeEl) return;
    const header = nodeEl.querySelector('.banana-node-header');
    if (!header) return;
    header.addEventListener('mousedown', (e) => {
        if (e.target.closest('button') || e.target.closest('input') || e.target.closest('textarea') || e.target.closest('select')) return;
        e.preventDefault();
        e.stopPropagation();
        const startX = e.clientX;
        const startY = e.clientY;
        const origX = node.x;
        const origY = node.y;
        const scale = window.getCurrentScale ? window.getCurrentScale() : 1;
        const onMove = (moveE) => {
            const dx = (moveE.clientX - startX) / scale;
            const dy = (moveE.clientY - startY) / scale;
            node.x = origX + dx;
            node.y = origY + dy;
            nodeEl.style.left = node.x + 'px';
            nodeEl.style.top = node.y + 'px';
            if (typeof renderConnections === 'function') renderConnections();
        };
        const onUp = () => {
            document.removeEventListener('mousemove', onMove);
            document.removeEventListener('mouseup', onUp);
            saveIdeasToHistory();
        };
        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup', onUp);
    });
}

function updateWritingNodeProjectId(nodeId, v) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    node.data.projectId = String(v || '').trim();
    saveIdeasToHistory();
}

function updateWritingNodeField(nodeId, field, value) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    if (!node.data) node.data = {};
    node.data[field] = String(value ?? '');
    try {
        if (!window.__rrWritingNodeSaveTimers) window.__rrWritingNodeSaveTimers = new Map();
        const m = window.__rrWritingNodeSaveTimers;
        const prev = m.get(nodeId);
        if (prev) clearTimeout(prev);
        m.set(nodeId, setTimeout(() => {
            try { saveIdeasToHistory(); } catch (e) { }
        }, 450));
    } catch (e) { }
}

window.updateWritingNodeField = updateWritingNodeField;

async function openWritingFromNode(nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    const pid = String(node?.data?.projectId || '').trim();
    if (!pid) {
        alert('请先填写 project_id 或点击新建');
        return;
    }
    await openWritingProjectInCanvas(pid);
}

async function createWritingProjectFromNode(nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    try {
        const title = prompt('写作项目名称：', '我的写作项目');
        if (title === null) return;

        // ✅ 修复：创建项目时传递novelConfig（包含用户输入的topic）
        const novelConfig = node.data?.novelConfig || {};
        const data = await writingApi('writingCreateProject', {
            title,
            meta: { novel_config: novelConfig }
        });
        const pid = data?.project?.id;
        if (pid) {
            node.data.projectId = pid;
            renderCanvas();
            saveIdeasToHistory();
            await refreshWritingProjects();
            await openWritingProject(pid);
        }
    } catch (e) {
        alert('❌ 创建失败：' + (e && e.message ? e.message : e));
    }
}

