async function loadWritingNodeProject(nodeId, projectIdOverride) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    const pid = String(projectIdOverride || node.data?.projectId || '').trim();
    if (!pid) {
        alert('请先填写 project_id 或点击新建');
        return;
    }
    node.data.projectId = pid;
    node.data.status = '加载项目中...';
    renderCanvas();
    saveIdeasToHistory();
    try {
        const proj = await writingApi('writingGetProject', { projectId: pid });
        node.data.projectTitle = String(proj?.project?.title || '未命名写作项目');
        await refreshWritingNodeChapters(nodeId);
        node.data.status = '已加载';
        renderCanvas();
        saveIdeasToHistory();
    } catch (e) {
        node.data.status = String(e?.message || e);
        renderCanvas();
        saveIdeasToHistory();
        alert('❌ 加载项目失败：' + (e?.message || e));
    }
}

async function refreshWritingNodeChapters(nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    const pid = String(node.data?.projectId || '').trim();
    if (!pid) return;
    const data = await writingApi('writingListChapters', { projectId: pid });
    node.data.chapters = Array.isArray(data.chapters) ? data.chapters : [];
    const cur = String(node.data.currentChapterId || '').trim();
    const exists = node.data.chapters.some(c => String(c?.id || '') === cur);
    if (!exists) node.data.currentChapterId = String(node.data.chapters[0]?.id || '');
    renderCanvas();
    saveIdeasToHistory();
    if (node.data.currentChapterId) {
        await selectWritingNodeChapter(nodeId, node.data.currentChapterId);
    }
}

async function selectWritingNodeChapter(nodeId, chapterId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    const cid = String(chapterId || '').trim();
    if (!cid) return;
    node.data.status = '加载章节中...';
    renderCanvas();
    saveIdeasToHistory();
    try {
        const data = await writingApi('writingGetChapter', { chapterId: cid });
        const ch = data.chapter || null;
        if (!ch) throw new Error('章节不存在');
        node.data.currentChapterId = cid;
        node.data.currentChapterVersion = Number(ch.version || 1);
        node.data.chapterTitle = String(ch.title || '');
        node.data.chapterContent = String(ch.content || '');
        node.data.status = `已打开章节 v${node.data.currentChapterVersion}`;
        renderCanvas();
        saveIdeasToHistory();
    } catch (e) {
        node.data.status = String(e?.message || e);
        renderCanvas();
        saveIdeasToHistory();
        alert('❌ 打开章节失败：' + (e?.message || e));
    }
}

async function createWritingChapterForNode(nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    const pid = String(node.data?.projectId || '').trim();
    if (!pid) {
        alert('请先载入项目');
        return;
    }
    const title = prompt('章节标题：', '新章节');
    if (title === null) return;
    node.data.status = '创建章节中...';
    renderCanvas();
    saveIdeasToHistory();
    try {
        const data = await writingApi('writingCreateChapter', { projectId: pid, title: String(title || '') });
        await refreshWritingNodeChapters(nodeId);
        const cid = data?.chapter?.id;
        if (cid) await selectWritingNodeChapter(nodeId, cid);
    } catch (e) {
        node.data.status = String(e?.message || e);
        renderCanvas();
        saveIdeasToHistory();
        alert('❌ 创建章节失败：' + (e?.message || e));
    }
}

async function saveWritingNodeChapter(nodeId) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    const cid = String(node.data?.currentChapterId || '').trim();
    if (!cid) {
        alert('请先选择章节');
        return;
    }
    node.data.status = '保存中...';
    renderCanvas();
    saveIdeasToHistory();
    try {
        const patch = {
            title: String(node.data?.chapterTitle || ''),
            content: String(node.data?.chapterContent || '')
        };
        const data = await writingApi('writingUpdateChapter', {
            chapterId: cid,
            expectedVersion: node.data.currentChapterVersion,
            patch,
            createSnapshot: true
        });
        const ch = data.chapter;
        node.data.currentChapterVersion = Number(ch?.version || (node.data.currentChapterVersion || 1));
        node.data.status = `已保存 v${node.data.currentChapterVersion}`;
        await refreshWritingNodeChapters(nodeId);
    } catch (e) {
        if (e && e.status === 409 && e.data && e.data.error === 'WRITING_CONFLICT') {
            node.data.status = '版本冲突';
            renderCanvas();
            saveIdeasToHistory();
            alert('⚠️ 版本冲突：有人已更新此章节。请先点“刷新”，合并后再保存。');
            return;
        }
        node.data.status = String(e?.message || e);
        renderCanvas();
        saveIdeasToHistory();
        alert('❌ 保存失败：' + (e?.message || e));
    }
}

async function runWritingAIForNode(nodeId, mode) {
    const node = flowNodes.find(n => n.id === nodeId);
    if (!node) return;
    try {
        if (typeof NVAuth === 'undefined') throw new Error('未登录');
        const u = await NVAuth.getCurrentUser();
        if (!u) throw new Error('未登录');

        const title = String(node.data?.chapterTitle || '').trim();
        const content = String(node.data?.chapterContent || '');
        node.data.status = 'AI 生成中...';
        renderCanvas();
        saveIdeasToHistory();

        const instructionMap = {
            continue: '请基于已有内容继续写下去，保持风格一致，直接输出正文，不要解释。',
            polish: '请对内容进行润色与改写：更自然、更有画面感、逻辑更顺，尽量不改变剧情，直接输出润色后的正文，不要解释。',
            expand: '请对内容进行扩写：增加细节、动作、环境与对话，保持原剧情走向，直接输出扩写后的正文，不要解释。'
        };
        const instruction = instructionMap[String(mode)] || instructionMap.continue;
        const userHint = prompt('可选：补充你的要求（留空直接执行）', '');
        const sys = '你是中文长篇小说/剧本写作助手。输出必须是可直接粘贴的正文内容。';
        const base = (content && content.trim()) ? content.trim() : `标题：${title || '未命名'}\n\n（目前无正文，请从开头写起）`;
        const msg = [
            { role: 'system', content: sys },
            {
                role: 'user', content: `${instruction}

${userHint ? ('附加要求：' + userHint + '\n\n') : ''}当前内容：\n${base}`
            }
        ];
        const out = await callWriterLLM(msg);
        if (!out) throw new Error('AI 未返回内容');

        if (String(mode) === 'continue') {
            node.data.chapterContent = (content ? (content.replace(/\s+$/, '') + '\n\n') : '') + out;
        } else {
            const ok = confirm('AI 已生成完成，是否覆盖当前内容？\n\n确定=覆盖；取消=追加到末尾');
            if (ok) node.data.chapterContent = out;
            else node.data.chapterContent = (content ? (content.replace(/\s+$/, '') + '\n\n') : '') + out;
        }
        node.data.status = 'AI 已生成（未保存）';
        renderCanvas();
        saveIdeasToHistory();
    } catch (e) {
        node.data.status = String(e?.message || e);
        renderCanvas();
        saveIdeasToHistory();
        alert('❌ AI 写作失败：' + (e?.message || e));
    }
}

window.loadWritingNodeProject = loadWritingNodeProject;
window.refreshWritingNodeChapters = refreshWritingNodeChapters;
window.selectWritingNodeChapter = selectWritingNodeChapter;
window.createWritingChapterForNode = createWritingChapterForNode;
window.saveWritingNodeChapter = saveWritingNodeChapter;
window.runWritingAIForNode = runWritingAIForNode;

// ==================== 🎭 Sora2 角色管理功能 ====================

/**
 * 创建Sora2角色
 * @param {string} videoUrlOrTaskId - 包含角色的视频URL 或 任务ID（task_xxx 格式）
 * @param {string} timestamps - 时间范围，如 '1,3'
 * @param {string} characterName - 角色名称（可选）
 * @returns {Promise<Object>} 角色信息
 */
window.createSora2Character = async function (videoUrlOrTaskId, timestamps = '1,3', characterName = null) {
    try {
        const userId = await getCurrentUserId();
        if (!userId) throw new Error('请先登录');

        // 判断是URL还是任务ID
        const isTaskId = String(videoUrlOrTaskId || '').startsWith('task_');
        const requestBody = {
            action: 'create-character',
            userId: userId,
            timestamps: timestamps
        };

        if (isTaskId) {
            requestBody.from_task = videoUrlOrTaskId;
        } else {
            requestBody.url = videoUrlOrTaskId;
        }

        const res = await fetch('/api/sora2', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(requestBody)
        });

        const data = await res.json();
        if (!res.ok) throw new Error(data.message || '角色创建失败');

        // 自动保存角色
        const name = characterName || `角色_${Date.now()}`;
        saveSora2Character(name, data.character.username, videoUrlOrTaskId, timestamps);

        console.log(`✅ 角色 \"${name}\" 创建成功:`, data.character.username);
        return data.character;
    } catch (error) {
        console.error('❌ 创建角色失败:', error);
        throw error;
    }
};

/**
 * 保存角色到本地存储
 * @param {string} name - 角色名称
 * @param {string} username - 角色username
 * @param {string} videoUrl - 源视频URL
 * @param {string} timestamps - 时间范围
 */
window.saveSora2Character = function (name, username, videoUrl = '', timestamps = '1,3') {
    const chars = JSON.parse(localStorage.getItem('sora2_characters') || '{}');
    chars[name] = {
        username: username,
        videoUrl: videoUrl,
        timestamps: timestamps,
        createdAt: new Date().toISOString()
    };
    localStorage.setItem('sora2_characters', JSON.stringify(chars));
    console.log(`💾 角色 "${name}" 已保存`);
};

/**
 * 获取角色username
 * @param {string} name - 角色名称
 * @returns {string|null} username
 */
window.getSora2Character = function (name) {
    const chars = JSON.parse(localStorage.getItem('sora2_characters') || '{}');
    return chars[name]?.username || null;
};

/**
 * 获取所有角色
 * @returns {Object} 所有角色
 */
window.listSora2Characters = function () {
    return JSON.parse(localStorage.getItem('sora2_characters') || '{}');
};

/**
 * 删除角色
 * @param {string} name - 角色名称
 */
window.deleteSora2Character = function (name) {
    const chars = JSON.parse(localStorage.getItem('sora2_characters') || '{}');
    delete chars[name];
    localStorage.setItem('sora2_characters', JSON.stringify(chars));
    console.log(`🗑️ 角色 "${name}" 已删除`);
};

/**
 * 使用角色生成视频
 * @param {string} prompt - 视频提示词
 * @param {string|Array} characters - 角色名称或username（可以是数组）
 * @param {Object} options - 其他选项
 */
window.generateVideoWithCharacter = async function (prompt, characters, options = {}) {
    try {
        const userId = await getCurrentUserId();
        if (!userId) throw new Error('请先登录');

        // 处理角色参数
        let characterUsernames = [];
        if (Array.isArray(characters)) {
            characterUsernames = characters.map(c => {
                // 如果是角色名称，从本地存储获取username
                const saved = getSora2Character(c);
                return saved || c; // 如果找不到，假设它本身就是username
            });
        } else {
            const saved = getSora2Character(characters);
            characterUsernames = [saved || characters];
        }

        const res = await fetch('/api/sora2', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                action: 'text-to-video',
                userId: userId,
                prompt: prompt,
                model: options.model || 'sora-2-all',
                character_usernames: characterUsernames,
                aspect_ratio: options.aspectRatio || '16:9',
                duration: options.duration || 15,
                hd: options.hd || false
            })
        });

        const data = await res.json();
        if (!res.ok) throw new Error(data.message || '视频生成失败');

        console.log('✅ 视频任务已提交:', data.task_id);
        return data;
    } catch (error) {
        console.error('❌ 视频生成失败:', error);
        throw error;
    }
};

