/**
 * 保存漫画设置
 * @param {number} ideaId - 任务ID
 */
window.saveComicSettings = function (ideaId) {
    const idea = ideas.find(i => i.id === ideaId);
    if (!idea) return;

    const style = document.getElementById('comicSettingStyle')?.value || 'japanese';
    const pages = parseInt(document.getElementById('comicSettingPages')?.value) || 8;
    let dialog = document.getElementById('comicSettingDialog')?.value || 'overlay';
    let imageModel = document.getElementById('comicSettingImageModel')?.value || 'modelscope';

    // ✅ 文字质量策略：默认模型不出字；要出字自动用 Gemini Flash 4K
    const resolved = resolveComicTextPolicy(imageModel, dialog);
    if (dialog === 'embedded' && imageModel === 'modelscope' && resolved.imageModel === 'gemini-flash-4k') {
        addLog('✨ 已自动切换到 Gemini Flash 4K：图内文字更清晰（标准模型默认无文字）', 'info');
    }
    imageModel = resolved.imageModel;
    dialog = resolved.dialogMode;

    // 更新任务
    idea.comicStyle = style;
    idea.comicPages = pages;
    idea.comicDialogMode = dialog;
    idea.comicImageModel = imageModel;
    idea.settings = idea.settings || {};
    idea.settings.comicStyle = style;
    idea.settings.comicPages = pages;
    idea.settings.comicDialogMode = dialog;
    idea.settings.comicImageModel = imageModel;

    // 保存并刷新
    saveIdeasToHistory();
    renderIdeasList();
    renderCanvas();

    // 关闭弹窗
    document.getElementById('comicSettingsModal')?.remove();

    console.log(`[漫画] 设置已保存: ${COMIC_STYLES[style]?.name}, ${pages}页, ${dialog}, 模型:${imageModel}`);
};

/**
 * 渲染漫画任务卡片（画布上的详细流程视图）
 * 5步流程：文章分析 → 角色设计 → 分镜规划 → 漫画生成 → 成品合并
 * @param {Object} idea - 漫画任务
 * @returns {string} HTML字符串
 */
/**
 * 开启微型书预览（SVG精美翻页动画）
 */
window.startMiniBookPreview = function (bookId, ideaId) {
    const svgContainer = document.getElementById(bookId);
    if (!svgContainer) return;

    const idea = ideas.find(i => i.id === ideaId);
    const pages = idea?.generatedPages?.filter(p => p.imageUrl) || [];
    if (pages.length === 0) return;

    // 获取 SVG 内部元素
    const coverGroup = svgContainer.querySelector('.svg-cover-group');
    const pagesGroup = svgContainer.querySelector('.svg-pages-group');
    const pageContent = svgContainer.querySelector('.svg-page-image');
    const flipPage = svgContainer.querySelector('.svg-flip-page');
    const flipImage = svgContainer.querySelector('.svg-flip-image');

    if (!coverGroup || !pagesGroup) return;

    // 1. 优雅打开书本动画
    // 封面像门一样打开 180度
    coverGroup.style.transition = 'transform 0.8s cubic-bezier(0.4, 0, 0.2, 1)';
    coverGroup.style.transform = 'rotateY(-160deg)';

    // 内页显示第一页
    if (pageContent) pageContent.setAttribute('href', pages[0].imageUrl);

    // 2. 开始自动翻页循环
    let pageIndex = 0;

    if (window.miniBookIntervals?.[bookId]) clearInterval(window.miniBookIntervals[bookId]);
    if (!window.miniBookIntervals) window.miniBookIntervals = {};

    // 定义翻页动画函数
    const doFlip = () => {
        const nextIndex = (pageIndex + 1) % pages.length;
        const currentImg = pages[pageIndex].imageUrl;
        const nextImg = pages[nextIndex].imageUrl;

        // 准备翻页层
        if (flipPage && flipImage) {
            // 设置翻页层的当前图片
            flipImage.setAttribute('href', nextImg);

            // 重置翻页层位置（从右侧开始）
            flipPage.style.display = 'block';
            flipPage.style.transition = 'none';
            flipPage.style.transformOrigin = 'left center';
            // 使用 path 变形或者简单的 scaleX 模拟翻页
            // 这里用更精细的 SVG 变换
            flipPage.style.transform = 'rotateY(0deg)';

            // 强制重绘
            void flipPage.offsetWidth;

            // 执行翻页动画 (从右向左翻)
            flipPage.style.transition = 'transform 0.9s cubic-bezier(0.645, 0.045, 0.355, 1)';
            flipPage.style.transform = 'rotateY(-178deg)'; // 翻过去

            // 动画结束后更新底层图片
            setTimeout(() => {
                if (pageContent) pageContent.setAttribute('href', nextImg);
                flipPage.style.display = 'none'; // 隐藏翻页层
                pageIndex = nextIndex;
            }, 900); // 与 transition 时间一致
        }
    };

    // 首次延迟后开始翻页
    window.miniBookTimeout = setTimeout(() => {
        doFlip();
        window.miniBookIntervals[bookId] = setInterval(doFlip, 2500); // 放慢速度：2.5秒翻一次
    }, 1000);
};

/**
 * 停止微型书预览
 */
window.stopMiniBookPreview = function (bookId) {
    const svgContainer = document.getElementById(bookId);
    if (!svgContainer) return;

    const coverGroup = svgContainer.querySelector('.svg-cover-group');
    const flipPage = svgContainer.querySelector('.svg-flip-page');

    // 合上封面
    if (coverGroup) {
        coverGroup.style.transform = 'rotateY(0deg)';
    }

    // 隐藏翻页层
    if (flipPage) {
        flipPage.style.display = 'none';
    }

    // 清除定时器
    if (window.miniBookIntervals?.[bookId]) {
        clearInterval(window.miniBookIntervals[bookId]);
        delete window.miniBookIntervals[bookId];
    }
    if (window.miniBookTimeout) clearTimeout(window.miniBookTimeout);
};

