// ==================== 📱 移动端UI优化 ====================

/**
 * 📱 初始化移动端UI（悬浮球鼠标 + 底部工具栏）
 */
function initMobileUI() {
    // 仅在小屏真触摸设备启用（避免桌面端误触发出现悬浮球但无法操作）
    const isSmallScreen = (() => {
        try {
            return !!(window.matchMedia && window.matchMedia('(max-width: 900px)').matches);
        } catch (e) {
            return window.innerWidth <= 900;
        }
    })();
    const isCoarse = (() => {
        try {
            return !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches);
        } catch (e) {
            return true;
        }
    })();
    const isTouch = (navigator.maxTouchPoints > 0) || ('ontouchstart' in window);
    if (!isSmallScreen || !isTouch) return;

    console.log('📱 初始化移动端UI...');

    createSunflowerMouseRemote();

    // 创建底部工具栏
    createMobileToolbar();
}

function createSunflowerMouseRemote() {
    if (document.getElementById('sunflowerMouseRemote')) return;

    try { document.getElementById('floatingMouseBall')?.remove(); } catch (e) { }
    try { document.getElementById('floatingMousePanel')?.remove(); } catch (e) { }
    try { document.getElementById('virtualMouseCursor')?.remove(); } catch (e) { }

    const cursor = document.createElement('div');
    cursor.id = 'virtualMouseArrowCursor';
    cursor.style.cssText = `
        position: fixed;
        left: 50vw;
        top: 50vh;
        width: 0;
        height: 0;
        border-top: 10px solid transparent;
        border-bottom: 10px solid transparent;
        border-left: 16px solid rgba(255,255,255,0.95);
        filter: drop-shadow(0 4px 12px rgba(0,0,0,0.6));
        z-index: 10079;
        pointer-events: none;
        transform: translateZ(0);
        opacity: 0;
        transition: opacity 120ms ease;
    `;
    document.body.appendChild(cursor);

    const remote = document.createElement('div');
    remote.id = 'sunflowerMouseRemote';
    remote.style.cssText = `
        position: fixed;
        left: 0;
        top: 0;
        width: 152px;
        height: 176px;
        z-index: 10080;
        pointer-events: auto;
        touch-action: none;
        user-select: none;
        -webkit-user-select: none;
        display: grid;
        grid-template-columns: 1fr 84px 1fr;
        grid-template-rows: 40px 84px 40px;
        gap: 8px;
        align-items: center;
        justify-items: center;
    `;

    const btnTop = document.createElement('button');
    btnTop.type = 'button';
    btnTop.setAttribute('data-act', 'drag');
    btnTop.style.cssText = `
        width: 44px;
        height: 44px;
        border-radius: 50%;
        border: 2px solid rgba(0,0,0,0.22);
        background: rgba(255,255,255,0.72);
        backdrop-filter: blur(6px);
        -webkit-backdrop-filter: blur(6px);
        box-shadow: 0 10px 22px rgba(0,0,0,0.18);
        font-weight: 800;
        color: rgba(0,0,0,0.8);
        cursor: pointer;
    `;
    btnTop.textContent = '⤓';

    const btnLeft = document.createElement('button');
    btnLeft.type = 'button';
    btnLeft.setAttribute('data-act', 'left');
    btnLeft.style.cssText = `
        width: 54px;
        height: 92px;
        border-radius: 999px;
        border: 2px solid rgba(0,0,0,0.22);
        background: rgba(255,255,255,0.72);
        backdrop-filter: blur(6px);
        -webkit-backdrop-filter: blur(6px);
        box-shadow: 0 10px 22px rgba(0,0,0,0.18);
        cursor: pointer;
    `;

    const btnRight = document.createElement('button');
    btnRight.type = 'button';
    btnRight.setAttribute('data-act', 'right');
    btnRight.style.cssText = btnLeft.style.cssText;

    const trackpad = document.createElement('div');
    trackpad.id = 'sunflowerTrackpad';
    trackpad.style.cssText = `
        width: 92px;
        height: 92px;
        border-radius: 50%;
        border: 2px solid rgba(0,0,0,0.22);
        background: rgba(255,255,255,0.66);
        backdrop-filter: blur(6px);
        -webkit-backdrop-filter: blur(6px);
        box-shadow: 0 10px 22px rgba(0,0,0,0.18);
        cursor: grab;
        touch-action: none;
    `;

    const btnBottom = document.createElement('button');
    btnBottom.type = 'button';
    btnBottom.setAttribute('data-act', 'scroll');
    btnBottom.style.cssText = btnTop.style.cssText;
    btnBottom.textContent = '≡';

    const btnToggle = document.createElement('button');
    btnToggle.type = 'button';
    btnToggle.setAttribute('data-act', 'toggle');
    btnToggle.style.cssText = `
        width: 34px;
        height: 34px;
        border-radius: 50%;
        border: 1px solid rgba(0,0,0,0.18);
        background: rgba(255,255,255,0.72);
        backdrop-filter: blur(6px);
        -webkit-backdrop-filter: blur(6px);
        box-shadow: 0 10px 22px rgba(0,0,0,0.14);
        cursor: pointer;
        font-weight: 800;
        color: rgba(0,0,0,0.72);
        touch-action: none;
    `;
    btnToggle.textContent = '🖱️';

    remote.appendChild(btnToggle);
    remote.appendChild(btnTop);
    remote.appendChild(document.createElement('div'));
    remote.appendChild(btnLeft);
    remote.appendChild(trackpad);
    remote.appendChild(btnRight);
    remote.appendChild(document.createElement('div'));
    remote.appendChild(btnBottom);
    remote.appendChild(document.createElement('div'));
    document.body.appendChild(remote);

    let remoteCollapsed = true;
    let remoteX = 0;
    let remoteY = 0;

    const REMOTE_COLLAPSED_SIZE = 52;
    const REMOTE_EXPANDED_W = 152;
    const REMOTE_EXPANDED_H = 176;
    const remoteChildren = { btnToggle, btnTop, btnLeft, btnRight, btnBottom, trackpad };

    function clamp(n, min, max) {
        return Math.max(min, Math.min(max, n));
    }

    function loadRemotePos() {
        try {
            const raw = localStorage.getItem('sunflower_remote_pos');
            if (!raw) return false;
            const obj = JSON.parse(raw);
            if (!obj || typeof obj !== 'object') return false;
            const x = Number(obj.x);
            const y = Number(obj.y);
            if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
            remoteX = x;
            remoteY = y;
            return true;
        } catch (e) {
            return false;
        }
    }

    function saveRemotePos() {
        try {
            localStorage.setItem('sunflower_remote_pos', JSON.stringify({ x: remoteX, y: remoteY }));
        } catch (e) { }
    }

    function applyRemotePos() {
        const w = remoteCollapsed ? REMOTE_COLLAPSED_SIZE : REMOTE_EXPANDED_W;
        const h = remoteCollapsed ? REMOTE_COLLAPSED_SIZE : REMOTE_EXPANDED_H;
        remoteX = clamp(remoteX, 8, window.innerWidth - w - 8);
        remoteY = clamp(remoteY, 8, window.innerHeight - h - 8);
        remote.style.left = remoteX + 'px';
        remote.style.top = remoteY + 'px';
    }

    function applyRemoteLayout() {
        if (remoteCollapsed) {
            remote.style.width = REMOTE_COLLAPSED_SIZE + 'px';
            remote.style.height = REMOTE_COLLAPSED_SIZE + 'px';
            remote.style.gridTemplateColumns = '1fr';
            remote.style.gridTemplateRows = '1fr';
            remote.style.gap = '0';
            remoteChildren.btnTop.style.display = 'none';
            remoteChildren.btnLeft.style.display = 'none';
            remoteChildren.btnRight.style.display = 'none';
            remoteChildren.btnBottom.style.display = 'none';
            remoteChildren.trackpad.style.display = 'none';
            remoteChildren.btnToggle.style.width = '52px';
            remoteChildren.btnToggle.style.height = '52px';
            remoteChildren.btnToggle.style.borderRadius = '50%';
            remoteChildren.btnToggle.textContent = '🖱️';
        } else {
            remote.style.width = REMOTE_EXPANDED_W + 'px';
            remote.style.height = REMOTE_EXPANDED_H + 'px';
            remote.style.gridTemplateColumns = '1fr 84px 1fr';
            remote.style.gridTemplateRows = '40px 84px 40px';
            remote.style.gap = '8px';
            remoteChildren.btnTop.style.display = '';
            remoteChildren.btnLeft.style.display = '';
            remoteChildren.btnRight.style.display = '';
            remoteChildren.btnBottom.style.display = '';
            remoteChildren.trackpad.style.display = '';
            remoteChildren.btnToggle.style.width = '34px';
            remoteChildren.btnToggle.style.height = '34px';
            remoteChildren.btnToggle.style.borderRadius = '50%';
            remoteChildren.btnToggle.textContent = '×';
        }
        applyRemotePos();
    }

    (function initRemotePos() {
        const ok = loadRemotePos();
        if (!ok) {
            remoteX = Math.max(8, window.innerWidth - REMOTE_COLLAPSED_SIZE - 12);
            remoteY = Math.max(8, window.innerHeight - 220);
        }
        applyRemoteLayout();
        try {
            window.addEventListener('resize', () => {
                applyRemotePos();
                saveRemotePos();
            });
        } catch (e) { }
    })();

    let cursorX = Math.round(window.innerWidth / 2);
    let cursorY = Math.round(window.innerHeight / 2);
    let dragLocked = false;
    let scrollMode = false;
    let dragTarget = null;
    let lastTapAt = 0;
    let lastTapX = 0;
    let lastTapY = 0;
    let _lastHoveredEl = null;
    let hideCursorTimer = null;
    const clickMoveThreshold = 10;
    const sensitivity = 1.1;

    function showCursor() {
        cursor.style.opacity = '1';
        try { clearTimeout(hideCursorTimer); } catch (e) { }
        hideCursorTimer = setTimeout(() => {
            try { cursor.style.opacity = '0'; } catch (e) { }
        }, 1200);
    }

    function setCursorPos(x, y) {
        cursorX = Math.max(2, Math.min(window.innerWidth - 2, Math.round(x)));
        cursorY = Math.max(2, Math.min(window.innerHeight - 2, Math.round(y)));
        cursor.style.left = cursorX + 'px';
        cursor.style.top = cursorY + 'px';
        showCursor();
        triggerHover(cursorX, cursorY);
    }

    function elementFromCursor() {
        const prev = cursor.style.pointerEvents;
        cursor.style.pointerEvents = 'none';
        remote.style.pointerEvents = 'none';
        const el = document.elementFromPoint(cursorX, cursorY);
        remote.style.pointerEvents = 'auto';
        cursor.style.pointerEvents = prev || 'none';
        return el;
    }

    function findScrollable(el) {
        let cur = el;
        for (let i = 0; i < 10 && cur; i++) {
            if (cur === document.body || cur === document.documentElement) break;
            try {
                const style = window.getComputedStyle(cur);
                const oy = style && style.overflowY;
                const scrollable = (oy === 'auto' || oy === 'scroll') && (cur.scrollHeight > cur.clientHeight + 1);
                if (scrollable) return cur;
            } catch (e) { }
            cur = cur.parentElement;
        }
        return null;
    }

    function dispatchMouse(type, opts = {}) {
        try {
            const evt = new MouseEvent(type, {
                bubbles: true,
                cancelable: true,
                clientX: cursorX,
                clientY: cursorY,
                ...opts
            });
            (dragTarget || document).dispatchEvent(evt);
        } catch (e) { }
    }

    function clickAtCursor() {
        const el = elementFromCursor();
        if (!el) return;
        if (el === document.body || el === document.documentElement) return;
        try { el.click(); } catch (e) { }
    }

    function dblClickAtCursor() {
        const el = elementFromCursor();
        if (!el) return;
        try {
            el.dispatchEvent(new MouseEvent('dblclick', { bubbles: true, cancelable: true, clientX: cursorX, clientY: cursorY }));
        } catch (e) { }
    }

    function rightClickAtCursor() {
        const el = elementFromCursor();
        if (!el) return;
        try {
            el.dispatchEvent(new MouseEvent('contextmenu', { bubbles: true, cancelable: true, clientX: cursorX, clientY: cursorY, button: 2, buttons: 2 }));
        } catch (e) { }
    }

    function setDragLocked(enabled) {
        dragLocked = !!enabled;
        btnTop.style.background = dragLocked ? 'rgba(255, 215, 0, 0.42)' : 'rgba(255,255,255,0.72)';
        btnTop.style.borderColor = dragLocked ? 'rgba(255, 215, 0, 0.55)' : 'rgba(0,0,0,0.22)';
        try {
            if (dragLocked) {
                dragTarget = elementFromCursor();
                dispatchMouse('mousedown', { button: 0, buttons: 1 });
            } else {
                dispatchMouse('mouseup', { button: 0, buttons: 0 });
                dragTarget = null;
            }
        } catch (e) { }
    }

    function setScrollMode(enabled) {
        scrollMode = !!enabled;
        btnBottom.style.background = scrollMode ? 'rgba(255, 215, 0, 0.42)' : 'rgba(255,255,255,0.72)';
        btnBottom.style.borderColor = scrollMode ? 'rgba(255, 215, 0, 0.55)' : 'rgba(0,0,0,0.22)';
    }

    function triggerHover(x, y) {
        const prevRemote = remote.style.pointerEvents;
        const prevCursor = cursor.style.pointerEvents;
        remote.style.pointerEvents = 'none';
        cursor.style.pointerEvents = 'none';
        const el = document.elementFromPoint(x, y);
        remote.style.pointerEvents = prevRemote || 'auto';
        cursor.style.pointerEvents = prevCursor || 'none';
        if (!el) return;

        const hoverable = el.closest('.result-card, .banana-node, .menu-item, .btn-primary, .btn-secondary, button, a, [role="button"], .idea-item, .task-item, .task-item-actions, .tab-btn, .node-header, .node-title, .node-toolbar-btn');
        if (hoverable !== _lastHoveredEl) {
            if (_lastHoveredEl) _lastHoveredEl.classList.remove('virtual-hovered');
            if (hoverable) hoverable.classList.add('virtual-hovered');
            _lastHoveredEl = hoverable;
        }
    }

    setCursorPos(cursorX, cursorY);

    const onButtonDown = (e) => {
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        const act = e.currentTarget?.getAttribute('data-act');
        if (act === 'left') {
            clickAtCursor();
        } else if (act === 'right') {
            rightClickAtCursor();
        } else if (act === 'drag') {
            setDragLocked(!dragLocked);
        } else if (act === 'scroll') {
            setScrollMode(!scrollMode);
        } else if (act === 'toggle') {
            remoteCollapsed = !remoteCollapsed;
            applyRemoteLayout();
            saveRemotePos();
        }
    };
    btnLeft.addEventListener('touchstart', onButtonDown, { passive: false });
    btnRight.addEventListener('touchstart', onButtonDown, { passive: false });
    btnTop.addEventListener('touchstart', onButtonDown, { passive: false });
    btnBottom.addEventListener('touchstart', onButtonDown, { passive: false });
    btnToggle.addEventListener('touchstart', onButtonDown, { passive: false });

    btnLeft.addEventListener('click', onButtonDown, { passive: false });
    btnRight.addEventListener('click', onButtonDown, { passive: false });
    btnTop.addEventListener('click', onButtonDown, { passive: false });
    btnBottom.addEventListener('click', onButtonDown, { passive: false });
    btnToggle.addEventListener('click', onButtonDown, { passive: false });

    // 仅允许拖动按钮区域移动遥控器，避免误操作挡住业务UI
    let _dragRemoteActive = false;
    let _dragRemoteMoved = false;
    let _dragStartX = 0;
    let _dragStartY = 0;
    let _dragStartRemoteX = 0;
    let _dragStartRemoteY = 0;

    const onRemoteDragStart = (clientX, clientY) => {
        _dragRemoteActive = true;
        _dragRemoteMoved = false;
        _dragStartX = clientX;
        _dragStartY = clientY;
        _dragStartRemoteX = remoteX;
        _dragStartRemoteY = remoteY;
    };
    const onRemoteDragMove = (clientX, clientY) => {
        if (!_dragRemoteActive) return;
        const dx = clientX - _dragStartX;
        const dy = clientY - _dragStartY;
        if (Math.hypot(dx, dy) > 6) _dragRemoteMoved = true;
        remoteX = _dragStartRemoteX + dx;
        remoteY = _dragStartRemoteY + dy;
        applyRemotePos();
    };
    const onRemoteDragEnd = () => {
        if (!_dragRemoteActive) return;
        _dragRemoteActive = false;
        if (_dragRemoteMoved) saveRemotePos();
    };

    btnToggle.addEventListener('touchstart', (e) => {
        const t = e.touches && e.touches[0];
        if (!t) return;
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        onRemoteDragStart(t.clientX, t.clientY);
    }, { passive: false });
    btnToggle.addEventListener('touchmove', (e) => {
        const t = e.touches && e.touches[0];
        if (!t) return;
        if (!_dragRemoteActive) return;
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        onRemoteDragMove(t.clientX, t.clientY);
    }, { passive: false });
    btnToggle.addEventListener('touchend', (e) => {
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        onRemoteDragEnd();
    }, { passive: false });

    btnToggle.addEventListener('mousedown', (e) => {
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        onRemoteDragStart(e.clientX, e.clientY);
        const onMove = (ev) => {
            try { ev.preventDefault(); ev.stopPropagation(); } catch (err2) { }
            onRemoteDragMove(ev.clientX, ev.clientY);
        };
        const onUp = (ev) => {
            try { ev.preventDefault(); ev.stopPropagation(); } catch (err2) { }
            document.removeEventListener('mousemove', onMove, true);
            document.removeEventListener('mouseup', onUp, true);
            onRemoteDragEnd();
        };
        document.addEventListener('mousemove', onMove, true);
        document.addEventListener('mouseup', onUp, true);
    }, true);

    let tracking = false;
    let startX = 0;
    let startY = 0;
    let moved = 0;

    const onPadStart = (e) => {
        const t = e.touches && e.touches[0];
        if (!t) return;
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }

        tracking = true;
        startX = t.clientX;
        startY = t.clientY;
        moved = 0;

        const now = Date.now();
        const tapDist = Math.hypot(t.clientX - lastTapX, t.clientY - lastTapY);
        const isDoubleTap = (now - lastTapAt) <= 280 && tapDist <= 24;
        lastTapAt = now;
        lastTapX = t.clientX;
        lastTapY = t.clientY;
        if (isDoubleTap) {
            dblClickAtCursor();
        }
    };

    const onPadMove = (e) => {
        const t = e.touches && e.touches[0];
        if (!t) return;
        if (!tracking) return;
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }

        const dx = (t.clientX - startX) * sensitivity;
        const dy = (t.clientY - startY) * sensitivity;
        moved = Math.hypot(dx, dy);

        startX = t.clientX;
        startY = t.clientY;

        if (scrollMode) {
            const baseEl = elementFromCursor();
            const st = findScrollable(baseEl);
            if (st) {
                try { st.scrollTop -= dy; } catch (e2) { }
            } else {
                try { window.scrollBy(0, -dy); } catch (e2) { }
            }
            showCursor();
            return;
        }

        setCursorPos(cursorX + dx, cursorY + dy);
        if (dragLocked) {
            if (!dragTarget) dragTarget = elementFromCursor();
            dispatchMouse('mousemove', { buttons: 1 });
        }
    };

    const onPadEnd = (e) => {
        if (!tracking) return;
        tracking = false;
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        if (moved <= clickMoveThreshold) {
            clickAtCursor();
        }
    };

    trackpad.addEventListener('touchstart', onPadStart, { passive: false });
    trackpad.addEventListener('touchmove', onPadMove, { passive: false });
    trackpad.addEventListener('touchend', onPadEnd, { passive: false });

    trackpad.addEventListener('mousedown', (e) => {
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        tracking = true;
        startX = e.clientX;
        startY = e.clientY;
        moved = 0;
        showCursor();
        const onMove = (ev) => {
            if (!tracking) return;
            try { ev.preventDefault(); ev.stopPropagation(); } catch (err2) { }
            const dx = (ev.clientX - startX) * sensitivity;
            const dy = (ev.clientY - startY) * sensitivity;
            moved = Math.hypot(dx, dy);
            startX = ev.clientX;
            startY = ev.clientY;
            if (scrollMode) {
                const baseEl = elementFromCursor();
                const st = findScrollable(baseEl);
                if (st) {
                    try { st.scrollTop -= dy; } catch (e2) { }
                } else {
                    try { window.scrollBy(0, -dy); } catch (e2) { }
                }
                showCursor();
                return;
            }
            setCursorPos(cursorX + dx, cursorY + dy);
            if (dragLocked) {
                if (!dragTarget) dragTarget = elementFromCursor();
                dispatchMouse('mousemove', { buttons: 1 });
            }
        };
        const onUp = (ev) => {
            tracking = false;
            try { ev.preventDefault(); ev.stopPropagation(); } catch (err2) { }
            try {
                document.removeEventListener('mousemove', onMove, true);
                document.removeEventListener('mouseup', onUp, true);
            } catch (e2) { }
            if (moved <= clickMoveThreshold) clickAtCursor();
        };
        document.addEventListener('mousemove', onMove, true);
        document.addEventListener('mouseup', onUp, true);
    }, true);

    trackpad.addEventListener('contextmenu', (e) => {
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        rightClickAtCursor();
    }, true);

    window.__rrMobileMouse = window.__rrMobileMouse || {};
    window.__rrMobileMouse.showRemote = () => { try { remote.style.display = 'grid'; } catch (e) { } };
}

/**
 * 📱 创建悬浮球鼠标
 * 拖动悬浮球可以移动虚拟鼠标指针，触发hover效果，点击执行点击
 */
function createFloatingMouse() {
    if (document.getElementById('floatingMouseBall')) return;

    // 🔧 悬浮球尺寸设置（支持3档：小/中/大）- 提前读取
    const ballSizes = [40, 56, 72];
    const cursorSizes = [10, 14, 18];
    let sizeIndex = 1; // 默认中等
    try {
        const saved = localStorage.getItem('rr_floating_mouse_size');
        if (saved !== null) sizeIndex = Math.min(2, Math.max(0, parseInt(saved) || 1));
    } catch (e) { }
    let initBallSize = ballSizes[sizeIndex];
    let initCursorSize = cursorSizes[sizeIndex];

    // 创建悬浮球
    const ball = document.createElement('div');
    ball.id = 'floatingMouseBall';
    ball.className = 'floating-mouse-ball';
    ball.innerHTML = '🖱️';
    ball.style.cssText = `
        position: fixed;
        bottom: 150px;
        right: 20px;
        width: ${initBallSize}px;
        height: ${initBallSize}px;
        border-radius: 50%;
        background: linear-gradient(135deg, #ffd700 0%, #ff8c00 100%);
        border: 3px solid rgba(255,255,255,0.5);
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: ${initBallSize * 0.43}px;
        z-index: 10080;
        box-shadow: 0 4px 20px rgba(255,215,0,0.5);
        cursor: grab;
        touch-action: none;
        user-select: none;
        -webkit-user-select: none;
    `;

    document.body.appendChild(ball);

    const cursor = document.createElement('div');
    cursor.id = 'virtualMouseCursor';
    cursor.style.cssText = `
        position: fixed;
        left: 50vw;
        top: 50vh;
        width: ${initCursorSize}px;
        height: ${initCursorSize}px;
        margin-left: ${-initCursorSize / 2}px;
        margin-top: ${-initCursorSize / 2}px;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.95);
        border: 2px solid rgba(0,0,0,0.55);
        box-shadow: 0 6px 18px rgba(0,0,0,0.5);
        z-index: 10079;
        pointer-events: none;
        transform: translateZ(0);
        opacity: 0;
        transition: opacity 120ms ease;
    `;
    document.body.appendChild(cursor);

    const panel = document.createElement('div');
    panel.id = 'floatingMousePanel';
    panel.style.cssText = `
        position: fixed;
        left: 0;
        top: 0;
        padding: 8px;
        border-radius: 14px;
        background: rgba(17, 24, 39, 0.92);
        border: 1px solid rgba(255, 215, 0, 0.25);
        box-shadow: 0 10px 28px rgba(0,0,0,0.35);
        z-index: 10081;
        display: none;
        gap: 8px;
        align-items: center;
        user-select: none;
        -webkit-user-select: none;
        touch-action: none;
        transform: translateZ(0);
    `;
    panel.innerHTML = `
        <button data-act="l" style="width:40px;height:34px;border-radius:10px;border:1px solid rgba(255,255,255,0.18);background:rgba(255,255,255,0.08);color:#fff;font-weight:700;">L</button>
        <button data-act="r" style="width:40px;height:34px;border-radius:10px;border:1px solid rgba(255,255,255,0.18);background:rgba(255,255,255,0.08);color:#fff;font-weight:700;">R</button>
        <button data-act="d" style="width:54px;height:34px;border-radius:10px;border:1px solid rgba(255,255,255,0.18);background:rgba(255,255,255,0.08);color:#fff;font-weight:700;">拖拽</button>
        <button data-act="s" style="width:54px;height:34px;border-radius:10px;border:1px solid rgba(255,255,255,0.18);background:rgba(255,255,255,0.08);color:#fff;font-weight:700;">滚动</button>
        <button data-act="size" style="width:40px;height:34px;border-radius:10px;border:1px solid rgba(255,255,255,0.18);background:rgba(255,255,255,0.08);color:#fff;font-weight:700;" title="切换尺寸">📏</button>
        <button data-act="x" style="width:40px;height:34px;border-radius:10px;border:1px solid rgba(255,255,255,0.18);background:rgba(255,255,255,0.08);color:#fff;font-weight:700;">✕</button>
    `;
    document.body.appendChild(panel);

    let ballSize = initBallSize;
    const initRight = 20;
    const initBottom = 150;
    let ballX = Math.max(0, Math.min(window.innerWidth - ballSize, window.innerWidth - initRight - ballSize));
    let ballY = Math.max(0, Math.min(window.innerHeight - ballSize, window.innerHeight - initBottom - ballSize));
    ball.style.left = ballX + 'px';
    ball.style.top = ballY + 'px';
    ball.style.right = 'auto';
    ball.style.bottom = 'auto';

    let isDragging = false;
    let dragStartX = 0;
    let dragStartY = 0;
    let startBallX = 0;
    let startBallY = 0;
    let totalMove = 0;
    let _lastHoveredEl = null;
    const clickMoveThreshold = 10;
    const rightClickThreshold = 10;
    const longPressMs = 420;
    let longPressTimer = null;
    let longPressFired = false;
    let dragHoldActive = false;
    let dragTarget = null;
    let twoFingerScroll = false;
    let lastScrollY = 0;
    let scrollTarget = null;
    let dragLocked = false;
    let scrollMode = false;
    let lastTapAt = 0;
    let lastTapX = 0;
    let lastTapY = 0;
    let panelAutoHideTimer = null;

    function showCursor() {
        cursor.style.opacity = '1';
    }

    function hideCursorSoon() {
        try {
            clearTimeout(panelAutoHideTimer);
        } catch (e) { }
        panelAutoHideTimer = setTimeout(() => {
            try { cursor.style.opacity = '0'; } catch (e) { }
        }, 900);
    }

    function setCursorAt(x, y) {
        cursor.style.left = x + 'px';
        cursor.style.top = y + 'px';
        showCursor();
    }

    function updatePanelPosition() {
        const c = getBallCenter();
        const w = 40 + 40 + 54 + 54 + 40 + 8 * 6;
        const h = 34 + 16;
        const left = Math.max(10, Math.min(window.innerWidth - w - 10, c.x - w / 2));
        const top = Math.max(10, Math.min(window.innerHeight - h - 10, c.y - ballSize / 2 - h - 10));
        panel.style.left = left + 'px';
        panel.style.top = top + 'px';
    }

    function openPanel() {
        updatePanelPosition();
        panel.style.display = 'flex';
        try { clearTimeout(panelAutoHideTimer); } catch (e) { }
        panelAutoHideTimer = setTimeout(() => {
            try { panel.style.display = 'none'; } catch (e) { }
        }, 2600);
    }

    function closePanel() {
        panel.style.display = 'none';
    }

    function getBallCenter() {
        return {
            x: Math.round(ballX + ballSize / 2),
            y: Math.round(ballY + ballSize / 2)
        };
    }

    function elementFromBallCenter() {
        const c = getBallCenter();
        const prev = ball.style.pointerEvents;
        ball.style.pointerEvents = 'none';
        const el = document.elementFromPoint(c.x, c.y);
        ball.style.pointerEvents = prev || 'auto';
        return el;
    }

    function clickAtBallCenter() {
        const targetEl = elementFromBallCenter();
        if (!targetEl) return;
        if (targetEl === document.body || targetEl === document.documentElement) return;
        try { targetEl.click(); } catch (e) { }
    }

    function dblClickAtBallCenter() {
        const c = getBallCenter();
        const targetEl = elementFromBallCenter();
        if (!targetEl) return;
        try {
            targetEl.dispatchEvent(new MouseEvent('dblclick', { bubbles: true, cancelable: true, clientX: c.x, clientY: c.y }));
        } catch (e) { }
    }

    function rightClickAtBallCenter() {
        const c = getBallCenter();
        const targetEl = elementFromBallCenter();
        if (!targetEl) return;
        try {
            const evt = new MouseEvent('contextmenu', {
                bubbles: true,
                cancelable: true,
                clientX: c.x,
                clientY: c.y,
                button: 2,
                buttons: 2
            });
            targetEl.dispatchEvent(evt);
        } catch (e) { }
    }

    function findScrollable(el) {
        let cur = el;
        for (let i = 0; i < 10 && cur; i++) {
            if (cur === document.body || cur === document.documentElement) break;
            try {
                const style = window.getComputedStyle(cur);
                const oy = style && style.overflowY;
                const scrollable = (oy === 'auto' || oy === 'scroll') && (cur.scrollHeight > cur.clientHeight + 1);
                if (scrollable) return cur;
            } catch (e) { }
            cur = cur.parentElement;
        }
        return null;
    }

    function dispatchMouse(type, x, y, opts = {}) {
        try {
            const evt = new MouseEvent(type, {
                bubbles: true,
                cancelable: true,
                clientX: x,
                clientY: y,
                ...opts
            });
            const target = dragTarget || document;
            target.dispatchEvent(evt);
        } catch (e) { }
    }

    function setDragLocked(enabled) {
        dragLocked = !!enabled;
        try {
            const btn = panel.querySelector('button[data-act="d"]');
            if (btn) {
                btn.style.background = dragLocked ? 'rgba(255, 215, 0, 0.25)' : 'rgba(255,255,255,0.08)';
                btn.style.borderColor = dragLocked ? 'rgba(255, 215, 0, 0.45)' : 'rgba(255,255,255,0.18)';
            }
        } catch (e) { }

        const c = getBallCenter();
        try {
            if (dragLocked) {
                dragTarget = elementFromBallCenter();
                dispatchMouse('mousedown', c.x, c.y, { button: 0, buttons: 1 });
            } else {
                dispatchMouse('mouseup', c.x, c.y, { button: 0, buttons: 0 });
                dragTarget = null;
            }
        } catch (e) { }
    }

    function setScrollMode(enabled) {
        scrollMode = !!enabled;
        try {
            const btn = panel.querySelector('button[data-act="s"]');
            if (btn) {
                btn.style.background = scrollMode ? 'rgba(255, 215, 0, 0.25)' : 'rgba(255,255,255,0.08)';
                btn.style.borderColor = scrollMode ? 'rgba(255, 215, 0, 0.45)' : 'rgba(255,255,255,0.18)';
            }
        } catch (e) { }
    }

    // 🔧 切换悬浮球和光标尺寸
    function toggleSize() {
        sizeIndex = (sizeIndex + 1) % 3;
        ballSize = ballSizes[sizeIndex];
        const cursorSize = cursorSizes[sizeIndex];

        // 更新悬浮球尺寸
        ball.style.width = ballSize + 'px';
        ball.style.height = ballSize + 'px';
        ball.style.fontSize = (ballSize * 0.43) + 'px';

        // 更新光标尺寸
        cursor.style.width = cursorSize + 'px';
        cursor.style.height = cursorSize + 'px';
        cursor.style.marginLeft = (-cursorSize / 2) + 'px';
        cursor.style.marginTop = (-cursorSize / 2) + 'px';

        // 保存设置
        try { localStorage.setItem('rr_floating_mouse_size', String(sizeIndex)); } catch (e) { }

        const sizeNames = ['小', '中', '大'];
        toast(`🖱️ 鼠标尺寸：${sizeNames[sizeIndex]}`, 'info', 1200);
    }

    // 🔧 L按钮（左键）的触摸拖拽状态
    let lBtnDragging = false;
    let lBtnStartX = 0;
    let lBtnStartY = 0;
    let lBtnMoved = false;
    let lBtnTarget = null;
    let lBtnMouseDown = false;

    // L按钮触摸开始 - 模拟鼠标按下
    function onLBtnTouchStart(e) {
        if (!e.touches || !e.touches[0]) return;
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }

        lBtnDragging = true;
        lBtnMoved = false;
        lBtnStartX = e.touches[0].clientX;
        lBtnStartY = e.touches[0].clientY;

        // 立即触发 mousedown
        const c = getBallCenter();
        lBtnTarget = elementFromBallCenter();
        dispatchMouse('mousedown', c.x, c.y, { button: 0, buttons: 1 });
        lBtnMouseDown = true;

        // 高亮L按钮
        const btn = panel.querySelector('button[data-act="l"]');
        if (btn) {
            btn.style.background = 'rgba(255, 215, 0, 0.35)';
            btn.style.borderColor = 'rgba(255, 215, 0, 0.55)';
        }

        document.addEventListener('touchmove', onLBtnTouchMove, { passive: false });
        document.addEventListener('touchend', onLBtnTouchEnd, { passive: false });
    }

    // L按钮触摸移动 - 拖动悬浮球并模拟鼠标拖拽
    function onLBtnTouchMove(e) {
        if (!lBtnDragging || !e.touches || !e.touches[0]) return;
        try { e.preventDefault(); } catch (err) { }

        const t = e.touches[0];
        const dx = t.clientX - lBtnStartX;
        const dy = t.clientY - lBtnStartY;
        const dist = Math.hypot(dx, dy);

        if (dist > 5) lBtnMoved = true;

        // 移动悬浮球
        ballX = Math.max(0, Math.min(window.innerWidth - ballSize, ballX + (t.clientX - lBtnStartX)));
        ballY = Math.max(0, Math.min(window.innerHeight - ballSize, ballY + (t.clientY - lBtnStartY)));
        ball.style.left = ballX + 'px';
        ball.style.top = ballY + 'px';
        updatePanelPosition();

        lBtnStartX = t.clientX;
        lBtnStartY = t.clientY;

        // 触发 mousemove（拖拽中）
        const c = getBallCenter();
        triggerHover(c.x, c.y);
        setCursorAt(c.x, c.y);
        dispatchMouse('mousemove', c.x, c.y, { buttons: 1 });
    }

    // L按钮触摸结束 - 模拟鼠标释放
    function onLBtnTouchEnd(e) {
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }

        document.removeEventListener('touchmove', onLBtnTouchMove);
        document.removeEventListener('touchend', onLBtnTouchEnd);

        const c = getBallCenter();

        // 触发 mouseup
        if (lBtnMouseDown) {
            dispatchMouse('mouseup', c.x, c.y, { button: 0, buttons: 0 });
            lBtnMouseDown = false;
        }

        // 如果没有移动，额外触发 click
        if (!lBtnMoved) {
            try {
                const targetEl = elementFromBallCenter();
                if (targetEl && targetEl !== document.body && targetEl !== document.documentElement) {
                    targetEl.click();
                }
            } catch (e) { }
        }

        // 恢复L按钮样式
        const btn = panel.querySelector('button[data-act="l"]');
        if (btn) {
            btn.style.background = 'rgba(255,255,255,0.08)';
            btn.style.borderColor = 'rgba(255,255,255,0.18)';
        }

        lBtnDragging = false;
        lBtnTarget = null;
    }

    // 为L按钮添加触摸事件
    const lBtn = panel.querySelector('button[data-act="l"]');
    if (lBtn) {
        lBtn.addEventListener('touchstart', onLBtnTouchStart, { passive: false });
    }

    // 🔧 面板按钮的通用处理函数
    function handlePanelButtonAction(act) {
        if (act === 'l') return; // L按钮由触摸事件单独处理
        if (act === 'r') {
            rightClickAtBallCenter();
        } else if (act === 'd') {
            setDragLocked(!dragLocked);
        } else if (act === 's') {
            setScrollMode(!scrollMode);
        } else if (act === 'size') {
            toggleSize();
        } else if (act === 'x') {
            closePanel();
        }
    }

    // 🔧 为所有按钮添加 touchend 事件（移动端更可靠）
    panel.querySelectorAll('button[data-act]').forEach(btn => {
        const act = btn.getAttribute('data-act');
        if (act === 'l') return; // L按钮已单独处理

        let touchStarted = false;
        btn.addEventListener('touchstart', (e) => {
            touchStarted = true;
            try { e.stopPropagation(); } catch (err) { }
        }, { passive: false });

        btn.addEventListener('touchend', (e) => {
            if (!touchStarted) return;
            touchStarted = false;
            try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
            handlePanelButtonAction(act);
        }, { passive: false });
    });

    // 桌面端仍使用click事件
    panel.addEventListener('click', (e) => {
        const btn = e.target && e.target.closest ? e.target.closest('button[data-act]') : null;
        if (!btn) return;
        const act = btn.getAttribute('data-act');
        if (act === 'l') return;
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        handlePanelButtonAction(act);
    }, { passive: false });

    // 🔧 无感切换模式 - 像真实鼠标一样操作
    // 拖动悬浮球 = 移动光标
    // 轻点（不移动）= 左键点击
    // 长按后拖动 = 拖拽目标元素
    // 双击 = 双击 + 打开设置面板
    // 双指滑动 = 滚动页面

    const onBallTouchStart = (e) => {
        if (!e.touches || !e.touches[0]) return;
        try { e.preventDefault(); } catch (err) { }

        clearTimeout(longPressTimer);
        longPressTimer = null;
        longPressFired = false;
        dragHoldActive = false;
        dragTarget = null;
        twoFingerScroll = false;
        scrollTarget = null;
        totalMove = 0;

        const now = Date.now();
        const tapX = e.touches[0].clientX;
        const tapY = e.touches[0].clientY;
        const tapDist = Math.hypot(tapX - lastTapX, tapY - lastTapY);
        const isDoubleTap = (now - lastTapAt) <= 280 && tapDist <= 22;
        lastTapAt = now;
        lastTapX = tapX;
        lastTapY = tapY;

        // 双击：触发双击事件 + 打开设置面板
        if (isDoubleTap) {
            dblClickAtBallCenter();
            openPanel();
            cleanupDrag();
            return;
        }

        // 双指：滚动模式
        if (e.touches.length >= 2) {
            twoFingerScroll = true;
            const c = getBallCenter();
            const baseEl = elementFromBallCenter();
            scrollTarget = findScrollable(baseEl) || null;
            lastScrollY = (e.touches[0].clientY + e.touches[1].clientY) / 2;
            triggerHover(c.x, c.y);
        } else {
            // 单指：开始拖动
            isDragging = true;
            const t = e.touches[0];
            dragStartX = t.clientX;
            dragStartY = t.clientY;
            startBallX = ballX;
            startBallY = ballY;
            ball.style.transform = 'scale(1.06)';

            // 长按检测：用于触发拖拽模式
            longPressTimer = setTimeout(() => {
                if (!isDragging) return;
                // 长按且未移动太多 = 准备拖拽目标
                if (totalMove <= rightClickThreshold) {
                    longPressFired = true;
                    // 震动反馈（如果支持）
                    try { navigator.vibrate && navigator.vibrate(30); } catch (e) { }
                    // 视觉反馈
                    ball.style.boxShadow = '0 4px 30px rgba(255,100,100,0.7)';
                }
            }, longPressMs);
        }

        document.addEventListener('touchmove', onDocTouchMove, { passive: false });
        document.addEventListener('touchend', onDocTouchEnd, { passive: false });
    };

    const onDocTouchMove = (e) => {
        if (!e.touches || !e.touches[0]) return;
        try { e.preventDefault(); } catch (err) { }

        // 🔧 双指滚动
        if (twoFingerScroll && e.touches.length >= 2) {
            const y = (e.touches[0].clientY + e.touches[1].clientY) / 2;
            const dy = y - lastScrollY;
            lastScrollY = y;
            if (scrollTarget) {
                try { scrollTarget.scrollTop -= dy; } catch (e) { }
            } else {
                try { window.scrollBy(0, -dy); } catch (e) { }
            }
            const c = getBallCenter();
            triggerHover(c.x, c.y);
            return;
        }

        if (!isDragging) return;

        const t = e.touches[0];
        const dx = t.clientX - dragStartX;
        const dy = t.clientY - dragStartY;
        totalMove = Math.hypot(dx, dy);

        // 🔧 移动悬浮球（同时移动X和Y）
        const newBallX = Math.max(0, Math.min(window.innerWidth - ballSize, Math.round(startBallX + dx)));
        const newBallY = Math.max(0, Math.min(window.innerHeight - ballSize, Math.round(startBallY + dy)));
        ballX = newBallX;
        ballY = newBallY;
        ball.style.left = newBallX + 'px';
        ball.style.top = newBallY + 'px';
        updatePanelPosition();

        const c = getBallCenter();
        triggerHover(c.x, c.y);
        setCursorAt(c.x, c.y);

        // 🔧 长按后移动 = 拖拽目标元素
        if (longPressFired && !dragHoldActive && totalMove > 5) {
            dragHoldActive = true;
            dragTarget = elementFromBallCenter();
            dispatchMouse('mousedown', c.x, c.y, { button: 0, buttons: 1 });
        }

        // 拖拽中：持续触发mousemove
        if (dragHoldActive) {
            dispatchMouse('mousemove', c.x, c.y, { buttons: 1 });
        }
    };

    const onDocTouchEnd = (e) => {
        clearTimeout(longPressTimer);
        longPressTimer = null;

        const c = getBallCenter();

        // 双指滚动结束
        if (twoFingerScroll) {
            cleanupDrag();
            return;
        }

        if (!isDragging) {
            cleanupDrag();
            return;
        }

        // 拖拽结束：触发mouseup
        if (dragHoldActive) {
            dispatchMouse('mouseup', c.x, c.y, { button: 0, buttons: 0 });
            cleanupDrag();
            return;
        }

        // 长按但未拖动：触发右键菜单
        if (longPressFired && totalMove <= rightClickThreshold) {
            rightClickAtBallCenter();
            cleanupDrag();
            return;
        }

        // 轻点（移动距离小）：触发左键点击
        if (totalMove <= clickMoveThreshold) {
            clickAtBallCenter();
        }

        cleanupDrag();
    };

    function cleanupDrag() {
        isDragging = false;
        twoFingerScroll = false;
        dragHoldActive = false;
        longPressFired = false;
        dragTarget = null;
        ball.style.transform = 'scale(1)';
        ball.style.boxShadow = '0 4px 20px rgba(255,215,0,0.5)';
        hideCursorSoon();
        try {
            document.removeEventListener('touchmove', onDocTouchMove);
            document.removeEventListener('touchend', onDocTouchEnd);
        } catch (e) { }
    }

    ball.addEventListener('touchstart', onBallTouchStart, { passive: false });

    // 桌面/DevTools 兼容：允许用鼠标拖动悬浮球（否则在电脑手机模拟器里会觉得“球固定不动”）
    let mouseDragging = false;
    let mouseStartX = 0;
    let mouseStartY = 0;
    let mouseBallStartX = 0;
    let mouseBallStartY = 0;
    let mouseTotalMove = 0;

    const onBallMouseDown = (e) => {
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        mouseDragging = true;
        mouseStartX = e.clientX;
        mouseStartY = e.clientY;
        mouseBallStartX = ballX;
        mouseBallStartY = ballY;
        mouseTotalMove = 0;
        ball.style.transform = 'scale(1.06)';
        document.addEventListener('mousemove', onDocMouseMove, true);
        document.addEventListener('mouseup', onDocMouseUp, true);
    };

    const onDocMouseMove = (e) => {
        if (!mouseDragging) return;
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        const dx = e.clientX - mouseStartX;
        const dy = e.clientY - mouseStartY;
        mouseTotalMove = Math.hypot(dx, dy);
        if (scrollMode) {
            const c = getBallCenter();
            const baseEl = elementFromBallCenter();
            const st = findScrollable(baseEl);
            if (st) {
                try { st.scrollTop -= dy; } catch (e2) { }
            } else {
                try { window.scrollBy(0, -dy); } catch (e2) { }
            }
            mouseStartX = e.clientX;
            mouseStartY = e.clientY;
            triggerHover(c.x, c.y);
            setCursorAt(c.x, c.y);
            return;
        }
        ballX = Math.max(0, Math.min(window.innerWidth - ballSize, Math.round(mouseBallStartX + dx)));
        ballY = Math.max(0, Math.min(window.innerHeight - ballSize, Math.round(mouseBallStartY + dy)));
        ball.style.left = ballX + 'px';
        ball.style.top = ballY + 'px';
        const c = getBallCenter();
        triggerHover(c.x, c.y);
        setCursorAt(c.x, c.y);
        updatePanelPosition();
        if (dragLocked) {
            if (!dragTarget) dragTarget = elementFromBallCenter();
            dispatchMouse('mousemove', c.x, c.y, { buttons: 1 });
        }
    };

    const onDocMouseUp = (e) => {
        if (!mouseDragging) return;
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        mouseDragging = false;
        ball.style.transform = 'scale(1)';
        try {
            document.removeEventListener('mousemove', onDocMouseMove, true);
            document.removeEventListener('mouseup', onDocMouseUp, true);
        } catch (err) { }
        if (mouseTotalMove <= clickMoveThreshold) {
            clickAtBallCenter();
        }
        hideCursorSoon();
    };

    ball.addEventListener('mousedown', onBallMouseDown, true);
    ball.addEventListener('contextmenu', (e) => {
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        rightClickAtBallCenter();
    }, true);

    ball.addEventListener('dblclick', (e) => {
        try { e.preventDefault(); e.stopPropagation(); } catch (err) { }
        openPanel();
    }, true);

    // 触发hover效果
    function triggerHover(x, y) {
        const prev = ball.style.pointerEvents;
        ball.style.pointerEvents = 'none';
        const el = document.elementFromPoint(x, y);
        ball.style.pointerEvents = prev || 'auto';
        if (!el) return;

        const hoverable = el.closest('.result-card, .banana-node, .menu-item, .btn-primary, .btn-secondary, button, a, [role="button"], .idea-item, .task-item, .task-item-actions, .tab-btn, .node-header, .node-title, .node-toolbar-btn');

        if (hoverable !== _lastHoveredEl) {
            if (_lastHoveredEl) {
                _lastHoveredEl.classList.remove('virtual-hovered');
            }
            if (hoverable) {
                hoverable.classList.add('virtual-hovered');
            }
            _lastHoveredEl = hoverable;
        }
    }

    function clearHover() {
        if (_lastHoveredEl) {
            _lastHoveredEl.classList.remove('virtual-hovered');
            _lastHoveredEl = null;
        }
        document.querySelectorAll('.virtual-hovered').forEach(el => {
            el.classList.remove('virtual-hovered');
        });
    }
}

/**
 * 📱 创建底部工具栏
 */
function createMobileToolbar() {
    if (document.getElementById('mobileToolbar')) return;

    const toolbar = document.createElement('div');
    toolbar.id = 'mobileToolbar';
    toolbar.className = 'mobile-toolbar';

    toolbar.innerHTML = `
        <button class="mobile-toolbar-btn" onclick="toggleMobileSidebar()" title="菜单">☰</button>
        <button class="mobile-toolbar-btn" onclick="showNodeMenu(event)" title="添加节点">➕</button>
        <button class="mobile-toolbar-btn" onclick="document.getElementById('quickIdeaInput')?.focus()" title="快速创作">✨</button>
        <button class="mobile-toolbar-btn" onclick="zoomToFit()" title="适应画布">🔍</button>
        <button class="mobile-toolbar-btn" onclick="openSettingsModal()" title="设置">⚙️</button>
    `;

    document.body.appendChild(toolbar);
}

/**
 * 📱 显示节点添加菜单（移动端）
 */
window.showNodeMenu = function (e) {
    // 使用现有的右键菜单逻辑
    const canvas = document.getElementById('taskCanvas');
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const screenX = rect.left + rect.width / 2;
    const screenY = rect.top + rect.height / 2;

    if (typeof showContextMenu === 'function') {
        showContextMenu(screenX, screenY);
    }
};

// ==================== 🎬 智能任务调度器集成 ====================
/**
 * 注册任务处理器到 TaskOrchestrator
 * 使新模块与现有系统无缝集成
 */
(function initTaskOrchestrator() {
    // 等待 TaskOrchestrator 加载
    if (typeof TaskOrchestrator === 'undefined') {
        console.log('⏳ [集成] 等待 TaskOrchestrator 加载...');
        setTimeout(initTaskOrchestrator, 100);
        return;
    }

    console.log('🔗 [集成] 开始注册任务处理器...');

    // 📝 文本生成处理器
    TaskOrchestrator.registerHandler('text_story', async (task) => {
        const { prompt, settings } = task.payload;
        return await callScriptGenerator({ settings }, prompt);
    });

    TaskOrchestrator.registerHandler('text_character', async (task) => {
        const { prompt, settings } = task.payload;
        return await callScriptGenerator({ settings }, prompt);
    });

    TaskOrchestrator.registerHandler('text_scene', async (task) => {
        const { prompt, settings } = task.payload;
        return await callScriptGenerator({ settings }, prompt);
    });

    // 🖼️ 图像生成处理器
    TaskOrchestrator.registerHandler('image_character', async (task) => {
        const { prompt, aspectRatio, model, useModelScope, useBestModel } = task.payload;
        if (useModelScope) {
            return await callModelScopeImageAPI(prompt, { aspectRatio });
        } else {
            return await callBanana2ImageAPI(prompt, { aspectRatio, model: model || 'nano-banana-2-4k' });
        }
    });

    TaskOrchestrator.registerHandler('image_scene', async (task) => {
        const { prompt, aspectRatio, model } = task.payload;
        return await callBanana2ImageAPI(prompt, { aspectRatio, model: model || 'nano-banana-2' });
    });

    // 🎬 视频生成处理器
    TaskOrchestrator.registerHandler('video_sora2', async (task) => {
        const { prompt, model, aspectRatio, duration, imageUrl, hd } = task.payload;
        if (imageUrl) {
            return await callSora2ImageToVideoAPI(prompt, imageUrl, { model, aspectRatio, duration, hd });
        } else {
            return await callSora2TextToVideoAPI(prompt, { model, aspectRatio, duration, hd });
        }
    });

    // 🔗 工作流处理器（父任务）
    TaskOrchestrator.registerHandler('workflow', async (task) => {
        // 工作流本身不执行，只等待子任务完成
        return { status: 'workflow_started', name: task.payload.name };
    });

    // 📊 监听任务事件，更新 UI
    TaskOrchestrator.on('taskStarted', (task) => {
        updateSmartProgress();
        if (task.type !== 'workflow') {
            addCineStepResult(`⏳ ${getTaskTypeLabel(task.type)}...`, 'running');
        }
    });

    TaskOrchestrator.on('taskCompleted', (task) => {
        updateSmartProgress();
        if (task.type !== 'workflow') {
            addCineStepResult(`✅ ${getTaskTypeLabel(task.type)} 完成`, 'success');
        }
    });

    TaskOrchestrator.on('taskFailed', (task) => {
        updateSmartProgress();
        if (task.type !== 'workflow') {
            addCineStepResult(`❌ ${getTaskTypeLabel(task.type)} 失败: ${task.error?.substring(0, 50) || '未知错误'}`, 'error');
        }
    });

    TaskOrchestrator.on('workflowCompleted', (workflow) => {
        console.log(`🎉 [工作流完成] ${workflow.payload.name}`);
        updateSmartProgress();
    });

    console.log('✅ [集成] 任务处理器注册完成');
})();

/**
 * 获取任务类型的中文标签
 */
function getTaskTypeLabel(type) {
    const labels = {
        'text_story': '📝 故事生成',
        'text_character': '👤 角色描述',
        'text_scene': '🎬 分镜脚本',
        'image_character': '🎨 角色图像',
        'image_scene': '🖼️ 分镜图像',
        'video_sora2': '🎬 视频生成',
        'workflow': '📋 工作流'
    };
    return labels[type] || type;
}

/**
 * 🔄 更新智能进度显示
 * 显示预估剩余时间和详细状态
 */
function updateSmartProgress() {
    if (typeof TaskOrchestrator === 'undefined') return;

    const status = TaskOrchestrator.getStatus();
    const progress = TaskOrchestrator.getProgress();

    // 更新进度条（如果存在）
    const progressBar = document.querySelector('.smart-progress-bar');
    if (progressBar) {
        progressBar.style.width = `${progress}%`;
    }

    // 更新预估时间显示
    const etaEl = document.getElementById('smartETA');
    if (etaEl && status.estimatedTimeRemaining > 0) {
        etaEl.textContent = `⏱️ 预计剩余: ${status.estimatedTimeFormatted}`;
        etaEl.style.display = 'block';
    } else if (etaEl) {
        etaEl.style.display = 'none';
    }

    // 更新状态文字
    const statusEl = document.getElementById('cineStatus');
    if (statusEl && status.running > 0) {
        statusEl.textContent = `正在处理 ${status.running} 个任务，等待 ${status.pending} 个...`;
    }

    // 更新任务计数（如果存在）
    const countEl = document.getElementById('taskQueueCount');
    if (countEl) {
        countEl.textContent = `${status.completed}/${status.total}`;
    }
}

/**
 * 🛡️ 弹性 API 网关集成
 * 提供统一的 API 调用入口（可选使用）
 */
window.SmartAPI = {
    /**
     * 智能图像生成（自动选择最优节点）
     */
    async generateImage(options) {
        if (typeof ResilientAPIGateway === 'undefined') {
            // 降级到原有方法
            const { prompt, aspectRatio, model, preferFree } = options;
            if (preferFree) {
                return await callModelScopeImageAPI(prompt, { aspectRatio });
            } else {
                return await callBanana2ImageAPI(prompt, { aspectRatio, model });
            }
        }
        return await ResilientAPIGateway.callImageAPI(options);
    },

    /**
     * 智能文本生成（自动选择最优节点）
     */
    async generateText(options) {
        if (typeof ResilientAPIGateway === 'undefined') {
            const { prompt, settings } = options;
            return await callScriptGenerator({ settings }, prompt);
        }
        return await ResilientAPIGateway.callTextAPI(options);
    },

    /**
     * 智能视频生成（自动选择最优节点）
     */
    async generateVideo(options) {
        if (typeof ResilientAPIGateway === 'undefined') {
            const { prompt, model, aspectRatio, duration, imageUrl, hd } = options;
            if (imageUrl) {
                return await callSora2ImageToVideoAPI(prompt, imageUrl, { model, aspectRatio, duration, hd });
            } else {
                return await callSora2TextToVideoAPI(prompt, { model, aspectRatio, duration, hd });
            }
        }
        return await ResilientAPIGateway.callVideoAPI(options);
    },

    /**
     * 获取 API 状态
     */
    getStatus() {
        if (typeof ResilientAPIGateway === 'undefined') {
            return { available: true, message: '使用原生 API' };
        }
        return ResilientAPIGateway.getStatus();
    },

    /**
     * 获取成本预估
     */
    estimateCost(usage) {
        if (typeof ResilientAPIGateway === 'undefined') {
            return { totalCost: 0, message: '无法预估' };
        }
        return ResilientAPIGateway.estimateCost(usage);
    }
};

console.log('🎬 [SmartAPI] 智能 API 接口已就绪');

